(11001, '2 Chronicles 27:7', '2 Chronicles', 27, 7, '&nbsp;د يوتام د بادشاهۍ نورې واقعې، د هغۀ جنګونه او د هغۀ نور کارونه، دا هر څۀ د اِسرائيل او د يهوداه په تاريخ کښې ليکلے شوى دى.', NULL, '&nbsp;د يوتام د بادشاهۍ نورې واقعې، د هغۀ جنګونه او د هغۀ نور کارونه، دا هر څۀ د اِسرائيل او د يهوداه په تاريخ کښې ليکلے شوى دى.', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles027_verse_007.mp3', NULL, 1761760676, 1761760676),
(11002, '2 Chronicles 27:8', '2 Chronicles', 27, 8, '&nbsp;يوتام د پينځويشتو کالو وو چې هغه بادشاه شو او هغۀ په يروشلم باندې شپاړس کاله بادشاهى وکړه.', NULL, '&nbsp;يوتام د پينځويشتو کالو وو چې هغه بادشاه شو او هغۀ په يروشلم باندې شپاړس کاله بادشاهى وکړه.', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles027_verse_008.mp3', NULL, 1761760676, 1761760676),
(11003, '2 Chronicles 27:9', '2 Chronicles', 27, 9, '&nbsp;يوتام مړ شو او د داؤد په ښار کښې ښخ شو او د هغۀ زوئ احاز د هغۀ نه پس بادشاه جوړ شو.', NULL, '&nbsp;يوتام مړ شو او د داؤد په ښار کښې ښخ شو او د هغۀ زوئ احاز د هغۀ نه پس بادشاه جوړ شو.', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles027_verse_009.mp3', NULL, 1761760676, 1761760676),
(11004, '2 Chronicles 28:1', '2 Chronicles', 28, 1, '&nbsp;احاز د شلو کالو په عُمر کښې بادشاه شو او هغۀ په يروشلم باندې شپاړس کاله بادشاهى وکړه. هغه د خپل پلار نيکۀ داؤد په شان نۀ وو، او په ځائ د هغې يې هغه کار کولو چې په څۀ مالِک خُدائ ناراضه کېدو.', NULL, '&nbsp;احاز د شلو کالو په عُمر کښې بادشاه شو او هغۀ په يروشلم باندې شپاړس کاله بادشاهى وکړه. هغه د خپل پلار نيکۀ داؤد په شان نۀ وو، او په ځائ د هغې يې هغه کار کولو چې په څۀ مالِک خُدائ ناراضه کېدو.', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles028_verse_001.mp3', NULL, 1761760676, 1761760676),
(11005, '2 Chronicles 28:2', '2 Chronicles', 28, 2, '&nbsp;او د اِسرائيل د بادشاهانو په نقش قدم باندې روان وو. هغۀ د بعل د اوسپنې بُتان جوړ کړى وُو،', NULL, '&nbsp;او د اِسرائيل د بادشاهانو په نقش قدم باندې روان وو. هغۀ د بعل د اوسپنې بُتان جوړ کړى وُو،', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles028_verse_002.mp3', NULL, 1761760676, 1761760676),
(11006, '2 Chronicles 28:3', '2 Chronicles', 28, 3, '&nbsp;د هنوم په وادۍ کښې يې خوشبويۍ سوزولې او تر دې پورې چې خپل زامن يې هم بُتانو ته د سوزېدونکې نذرانو په توګه قربانى کړل. د هغه خلقو د حرامو رِواجونو نقل يې کولو چې کله بنى اِسرائيليان مخ په وړاندې تلل نو مالِک خُدائ هغه د غېرو قومونو خلق د هغه مُلک نه شړلى وُو.', NULL, '&nbsp;د هنوم په وادۍ کښې يې خوشبويۍ سوزولې او تر دې پورې چې خپل زامن يې هم بُتانو ته د سوزېدونکې نذرانو په توګه قربانى کړل. د هغه خلقو د حرامو رِواجونو نقل يې کولو چې کله بنى اِسرائيليان مخ په وړاندې تلل نو مالِک خُدائ هغه د غېرو قومونو خلق د هغه مُلک نه شړلى وُو.', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles028_verse_003.mp3', NULL, 1761760676, 1761760676),
(11007, '2 Chronicles 28:4', '2 Chronicles', 28, 4, '&nbsp;په علاقائى عبادتخانو کښې، په غرونو، او د سورى د هرې ونې لاندې به احاز قربانۍ پېش کولې او خوشبويۍ يې سوزولې.', NULL, '&nbsp;په علاقائى عبادتخانو کښې، په غرونو، او د سورى د هرې ونې لاندې به احاز قربانۍ پېش کولې او خوشبويۍ يې سوزولې.', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles028_verse_004.mp3', NULL, 1761760676, 1761760676),
(11008, '2 Chronicles 28:7', '2 Chronicles', 28, 7, '&nbsp;يو اِسرائيلى فوجى چې نوم يې زِکرى وو هغۀ د احاز بادشاه زوئ معسياه، د محل مشر عزريقام او القنه ووژل. القنه په بادشاه پسې دوېم سړے وو.', NULL, '&nbsp;يو اِسرائيلى فوجى چې نوم يې زِکرى وو هغۀ د احاز بادشاه زوئ معسياه، د محل مشر عزريقام او القنه ووژل. القنه په بادشاه پسې دوېم سړے وو.', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles028_verse_007.mp3', NULL, 1761760676, 1761760676),
(11009, '2 Chronicles 28:8', '2 Chronicles', 28, 8, '&nbsp;اګر چې د يهوداه خلق د هغوئ خپل رشته‌دار هم وُو، خو د اِسرائيل لښکر دوه لاکه ښځې او ماشومان قېديان کړل او د ډېر زيات مالِ غنيمت سره يې سامريه ته بوتلل.', NULL, '&nbsp;اګر چې د يهوداه خلق د هغوئ خپل رشته‌دار هم وُو، خو د اِسرائيل لښکر دوه لاکه ښځې او ماشومان قېديان کړل او د ډېر زيات مالِ غنيمت سره يې سامريه ته بوتلل.', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles028_verse_008.mp3', NULL, 1761760676, 1761760676),
(11010, '2 Chronicles 28:9', '2 Chronicles', 28, 9, '&nbsp;د مالِک خُدائ يو پېغمبر چې نوم يې عوبېد وو، هغه د سامريه په ښار کښې اوسېدو. کله چې د اِسرائيل لښکر د يهوداه د قېديانو سره واپس راروان وو نو چې هغوئ ښار ته په ننوتلو وُو نو عوبيد هغوئ له د مِلاوېدو دپاره ور ووتلو او عوبيد ورته ووئيل، ”مالِک خُدائ ستاسو د پلار نيکۀ خُدائ پاک د يهوداه خلقو ته غصه وو او ستاسو په ذريعه يې هغوئ له شکست ورکړو، خو چې تاسو هغوئ څومره په بې‌رحمۍ سره حلال کړى دى نو خُدائ پاک د هغې نه خبر شوے دے.', NULL, '&nbsp;د مالِک خُدائ يو پېغمبر چې نوم يې عوبېد وو، هغه د سامريه په ښار کښې اوسېدو. کله چې د اِسرائيل لښکر د يهوداه د قېديانو سره واپس راروان وو نو چې هغوئ ښار ته په ننوتلو وُو نو عوبيد هغوئ له د مِلاوېدو دپاره ور ووتلو او عوبيد ورته ووئيل، ”مالِک خُدائ ستاسو د پلار نيکۀ خُدائ پاک د يهوداه خلقو ته غصه وو او ستاسو په ذريعه يې هغوئ له شکست ورکړو، خو چې تاسو هغوئ څومره په بې‌رحمۍ سره حلال کړى دى نو خُدائ پاک د هغې نه خبر شوے دے.', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles028_verse_009.mp3', NULL, 1761760676, 1761760676),
(11011, '2 Chronicles 28:10', '2 Chronicles', 28, 10, '&nbsp;او اوس ستاسو اراده دا ده چې د يروشلم او يهوداه سړى او ښځې خپل غلامان او وينځې جوړې کړئ. ولې تاسو ته پته نشته څۀ چې تاسو د مالِک خُدائ د خپل خُدائ پاک خِلاف ګناهونه هم کړې دى؟', NULL, '&nbsp;او اوس ستاسو اراده دا ده چې د يروشلم او يهوداه سړى او ښځې خپل غلامان او وينځې جوړې کړئ. ولې تاسو ته پته نشته څۀ چې تاسو د مالِک خُدائ د خپل خُدائ پاک خِلاف ګناهونه هم کړې دى؟', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles028_verse_010.mp3', NULL, 1761760676, 1761760676),
(11012, '2 Chronicles 28:11', '2 Chronicles', 28, 11, '&nbsp;زما دا خبره واورئ. دا قېديان ستاسو وروڼه او خوېندې دى. هغوئ پرېږدئ چې لاړ شى، ګنې مالِک خُدائ به په غصه کښې تاسو له سزا درکړى.“', NULL, '&nbsp;زما دا خبره واورئ. دا قېديان ستاسو وروڼه او خوېندې دى. هغوئ پرېږدئ چې لاړ شى، ګنې مالِک خُدائ به په غصه کښې تاسو له سزا درکړى.“', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles028_verse_011.mp3', NULL, 1761760676, 1761760676),
(11013, '2 Chronicles 28:12', '2 Chronicles', 28, 12, '&nbsp;د اِفرائيم د قبيلې څلورو مشرانو سړو، د يهوحنان زوئ عزرياه، د مسلموت زوئ برکياه، د سلوم زوئ يحزقياه او د خدلى زوئ عماسا هم د فوجى کاروائۍ مخالفت وکړو.', NULL, '&nbsp;د اِفرائيم د قبيلې څلورو مشرانو سړو، د يهوحنان زوئ عزرياه، د مسلموت زوئ برکياه، د سلوم زوئ يحزقياه او د خدلى زوئ عماسا هم د فوجى کاروائۍ مخالفت وکړو.', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles028_verse_012.mp3', NULL, 1761760676, 1761760676),
(11014, '2 Chronicles 28:13', '2 Chronicles', 28, 13, '&nbsp;هغوئ ووئيل، ”دا قېديان دلته مۀ راولئ. مونږ د مالِک خُدائ خِلاف لويه ګناه کړې ده او هغه مو دومره غصه کړے دے چې مونږ له به سزا راکړى. اوس تۀ داسې نور هم څۀ کول غواړې چې په هغې باندې زمونږ جرم زيات شى.“', NULL, '&nbsp;هغوئ ووئيل، ”دا قېديان دلته مۀ راولئ. مونږ د مالِک خُدائ خِلاف لويه ګناه کړې ده او هغه مو دومره غصه کړے دے چې مونږ له به سزا راکړى. اوس تۀ داسې نور هم څۀ کول غواړې چې په هغې باندې زمونږ جرم زيات شى.“', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles028_verse_013.mp3', NULL, 1761760676, 1761760676),
(11015, '2 Chronicles 28:14', '2 Chronicles', 28, 14, '&nbsp;نو بيا فوجيانو قېديان او مالِ غنيمت هغه خلقو او د هغوئ مشرانو ته حواله کړو،', NULL, '&nbsp;نو بيا فوجيانو قېديان او مالِ غنيمت هغه خلقو او د هغوئ مشرانو ته حواله کړو،', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles028_verse_014.mp3', NULL, 1761760676, 1761760676),
(11016, '2 Chronicles 28:15', '2 Chronicles', 28, 15, '&nbsp;او هغه څلور سړى د دې دپاره مقرر کړے شول چې قېديانو له د هغه نيولے شوى مالِ غنيمت نه جامې ورکړى. هغوئ ورله د اغوستلو دپاره څپلۍ او جامې ورکړې، د خوراک څښاک ښۀ ډېر څيزونه يې ورکړل او د هغوئ په زخمونو يې د زيتُونو تېل واچول. هغه کسان چې کوم ډېر کمزورى وُو او تلے نۀ شو نو هغوئ يې په خرونو کښېنول او ټول قېديان په يريحو کښې د يهوداه علاقې ته بوتلے شول، کوم چې د کجورو د ونو ښار دے. بيا د اِسرائيل خلق خپل کور سامريه ته راواپس شول.', NULL, '&nbsp;او هغه څلور سړى د دې دپاره مقرر کړے شول چې قېديانو له د هغه نيولے شوى مالِ غنيمت نه جامې ورکړى. هغوئ ورله د اغوستلو دپاره څپلۍ او جامې ورکړې، د خوراک څښاک ښۀ ډېر څيزونه يې ورکړل او د هغوئ په زخمونو يې د زيتُونو تېل واچول. هغه کسان چې کوم ډېر کمزورى وُو او تلے نۀ شو نو هغوئ يې په خرونو کښېنول او ټول قېديان په يريحو کښې د يهوداه علاقې ته بوتلے شول، کوم چې د کجورو د ونو ښار دے. بيا د اِسرائيل خلق خپل کور سامريه ته راواپس شول.', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles028_verse_015.mp3', NULL, 1761760676, 1761760676),
(11017, '2 Chronicles 28:18', '2 Chronicles', 28, 18, '&nbsp;په هغه وخت کښې فلستيانو د نمرپرېواتۀ په طرف د غرونو په لمن کښې او په جنوبى يهوداه کښې په ښارونو باندې حملې کولې. هغوئ د بيت‌شمس، ايالون، جديروت، شوکو، تمنت او جِمسو ښارونه او ورسره خواوشا علاقو کښې کلى هم قبضه کړل او هلته پاخۀ دېره شول.', NULL, '&nbsp;په هغه وخت کښې فلستيانو د نمرپرېواتۀ په طرف د غرونو په لمن کښې او په جنوبى يهوداه کښې په ښارونو باندې حملې کولې. هغوئ د بيت‌شمس، ايالون، جديروت، شوکو، تمنت او جِمسو ښارونه او ورسره خواوشا علاقو کښې کلى هم قبضه کړل او هلته پاخۀ دېره شول.', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles028_verse_018.mp3', NULL, 1761760676, 1761760676),
(11018, '2 Chronicles 28:19', '2 Chronicles', 28, 19, '&nbsp;احاز بادشاه خپل خلق د بدعملۍ په لار روان کړى وُو او د مالِک خُدائ نافرمانى يې کړې وه نو په دې وجه مالِک خُدائ په يهوداه باندې افتونه راوستل.', NULL, '&nbsp;احاز بادشاه خپل خلق د بدعملۍ په لار روان کړى وُو او د مالِک خُدائ نافرمانى يې کړې وه نو په دې وجه مالِک خُدائ په يهوداه باندې افتونه راوستل.', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles028_verse_019.mp3', NULL, 1761760676, 1761760676),
(11019, '2 Chronicles 28:20', '2 Chronicles', 28, 20, '&nbsp;د اسور بادشاه د احاز د مدد په ځائ د هغۀ مخالفت وکړو او هغه يې د تکليف سره مخ کړو.', NULL, '&nbsp;د اسور بادشاه د احاز د مدد په ځائ د هغۀ مخالفت وکړو او هغه يې د تکليف سره مخ کړو.', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles028_verse_020.mp3', NULL, 1761760676, 1761760676),
(11020, '2 Chronicles 28:21', '2 Chronicles', 28, 21, '&nbsp;نو احاز د مالِک خُدائ د کور، محل او د خلقو د مشرانو د کورونو نه يې سرۀ زر واخستل او د اسور بادشاه له يې ورکړل، خو په دې هم کار ونۀ شو.', NULL, '&nbsp;نو احاز د مالِک خُدائ د کور، محل او د خلقو د مشرانو د کورونو نه يې سرۀ زر واخستل او د اسور بادشاه له يې ورکړل، خو په دې هم کار ونۀ شو.', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles028_verse_021.mp3', NULL, 1761760676, 1761760676),
(11021, '2 Chronicles 28:22', '2 Chronicles', 28, 22, '&nbsp;کله چې مصيبتونه ډېر سخت وُو، نو هغه سړى يعنې احاز د مالِک خُدائ خِلاف د مخکښې نه زياته ګناه وکړه.', NULL, '&nbsp;کله چې مصيبتونه ډېر سخت وُو، نو هغه سړى يعنې احاز د مالِک خُدائ خِلاف د مخکښې نه زياته ګناه وکړه.', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles028_verse_022.mp3', NULL, 1761760676, 1761760676),
(11022, '2 Chronicles 28:23', '2 Chronicles', 28, 23, '&nbsp;هغۀ د دمشق معبودانو ته قربانۍ پېش کړې، چا چې هغۀ له شکست ورکړے وو. هغۀ ووئيل، ”د شام معبودانو د خپلو بادشاهانو مدد وکړو، نو کۀ زۀ هغوئ ته قربانۍ پېش کړم، نو کېدے شى چې زما هم مدد وکړى.“ نو په دې وجه په هغۀ او د هغۀ په قوم باندې تباهى راغله.', NULL, '&nbsp;هغۀ د دمشق معبودانو ته قربانۍ پېش کړې، چا چې هغۀ له شکست ورکړے وو. هغۀ ووئيل، ”د شام معبودانو د خپلو بادشاهانو مدد وکړو، نو کۀ زۀ هغوئ ته قربانۍ پېش کړم، نو کېدے شى چې زما هم مدد وکړى.“ نو په دې وجه په هغۀ او د هغۀ په قوم باندې تباهى راغله.', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles028_verse_023.mp3', NULL, 1761760676, 1761760676),
(11023, '2 Chronicles 28:24', '2 Chronicles', 28, 24, '&nbsp;د دې نه علاوه، هغۀ د خُدائ پاک د کور ټول سامان هم واخستلو او ټوټې ټوټې يې کړو. هغۀ د مالِک خُدائ د کور دروازې بندې کړې او د يروشلم په هر ځائ کښې يې قربان‌ګاه جوړې کړې.', NULL, '&nbsp;د دې نه علاوه، هغۀ د خُدائ پاک د کور ټول سامان هم واخستلو او ټوټې ټوټې يې کړو. هغۀ د مالِک خُدائ د کور دروازې بندې کړې او د يروشلم په هر ځائ کښې يې قربان‌ګاه جوړې کړې.', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles028_verse_024.mp3', NULL, 1761760676, 1761760676),
(11024, '2 Chronicles 28:25', '2 Chronicles', 28, 25, '&nbsp;هغۀ د يهوداه په هر يو ښار کښې علاقائى عبادتخانې جوړې کړې، چرته چې به پردو خُدايانو ته خوشبويۍ سوزولے شوې. نو په دې وجه هغۀ مالِک خُدائ د خپل پلار نيکۀ خُدائ پاک په قهر کړو.', NULL, '&nbsp;هغۀ د يهوداه په هر يو ښار کښې علاقائى عبادتخانې جوړې کړې، چرته چې به پردو خُدايانو ته خوشبويۍ سوزولے شوې. نو په دې وجه هغۀ مالِک خُدائ د خپل پلار نيکۀ خُدائ پاک په قهر کړو.', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles028_verse_025.mp3', NULL, 1761760676, 1761760676),
(11025, '2 Chronicles 28:26', '2 Chronicles', 28, 26, '&nbsp;د شروع نه واخله تر آخره پورې د هغۀ د بادشاهۍ ټولې واقعې د يهوداه او د اِسرائيل په تاريخ کښې ليکلے شوى دى.', NULL, '&nbsp;د شروع نه واخله تر آخره پورې د هغۀ د بادشاهۍ ټولې واقعې د يهوداه او د اِسرائيل په تاريخ کښې ليکلے شوى دى.', 'NT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761760676, 1761760676),
(11026, '2 Chronicles 28:27', '2 Chronicles', 28, 27, '&nbsp;احاز بادشاه مړ شو او په يروشلم کښې ښخ شو، خو په شاهى اديره کښې ښخ نۀ شو. د هغۀ زوئ حزقياه د هغۀ نه پس بادشاه جوړ شو.', NULL, '&nbsp;احاز بادشاه مړ شو او په يروشلم کښې ښخ شو، خو په شاهى اديره کښې ښخ نۀ شو. د هغۀ زوئ حزقياه د هغۀ نه پس بادشاه جوړ شو.', 'NT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761760676, 1761760676),
(11027, '2 Chronicles 29:1', '2 Chronicles', 29, 1, '&nbsp;حزقياه د پينځويشتو کالو په عُمر کښې د يهوداه بادشاه شو او يو کم دېرش کاله يې په يروشلم باندې بادشاهى وکړه. د هغۀ مور ابياه د زکرياه لور وه.', NULL, '&nbsp;حزقياه د پينځويشتو کالو په عُمر کښې د يهوداه بادشاه شو او يو کم دېرش کاله يې په يروشلم باندې بادشاهى وکړه. د هغۀ مور ابياه د زکرياه لور وه.', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles029_verse_001.mp3', NULL, 1761760676, 1761760676),
(11028, '2 Chronicles 29:2', '2 Chronicles', 29, 2, '&nbsp;هغۀ د خپل پلار نيکۀ داؤد په نقشِ قدم باندې روان وو او هغه کار يې کولو چې مالِک خُدائ ورباندې رضا کېدو.', NULL, '&nbsp;هغۀ د خپل پلار نيکۀ داؤد په نقشِ قدم باندې روان وو او هغه کار يې کولو چې مالِک خُدائ ورباندې رضا کېدو.', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles029_verse_002.mp3', NULL, 1761760676, 1761760676),
(11029, '2 Chronicles 29:3', '2 Chronicles', 29, 3, '&nbsp;د حزقياه د بادشاهۍ د اول کال په وړومبۍ مياشت، هغۀ د مالِک خُدائ د کور دروازې کولاو کړې او مرمت يې کړې.', NULL, '&nbsp;د حزقياه د بادشاهۍ د اول کال په وړومبۍ مياشت، هغۀ د مالِک خُدائ د کور دروازې کولاو کړې او مرمت يې کړې.', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles029_verse_003.mp3', NULL, 1761760676, 1761760676),
(11030, '2 Chronicles 29:4', '2 Chronicles', 29, 4, '&nbsp;هغۀ د مالِک خُدائ د کور نمرخاتۀ طرف ته دربار کښې اِمامان او ليويانو راغونډ کړل', NULL, '&nbsp;هغۀ د مالِک خُدائ د کور نمرخاتۀ طرف ته دربار کښې اِمامان او ليويانو راغونډ کړل', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles029_verse_004.mp3', NULL, 1761760676, 1761760676),
(11031, '2 Chronicles 29:5', '2 Chronicles', 29, 5, '&nbsp;او هلته يې ورته خبرې وکړې. هغۀ وفرمائيل، ”ليويانو تاسو به خپل ځانونه وقف کړئ او د مالِک خُدائ کور به پاک کړئ کوم چې ستاسو د پلار نيکۀ خُدائ پاک دے. د مقدس ځائ نه ټول ناپاکه څيزونه لرې کړئ.', NULL, '&nbsp;او هلته يې ورته خبرې وکړې. هغۀ وفرمائيل، ”ليويانو تاسو به خپل ځانونه وقف کړئ او د مالِک خُدائ کور به پاک کړئ کوم چې ستاسو د پلار نيکۀ خُدائ پاک دے. د مقدس ځائ نه ټول ناپاکه څيزونه لرې کړئ.', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles029_verse_005.mp3', NULL, 1761760676, 1761760676),
(11032, '2 Chronicles 29:6', '2 Chronicles', 29, 6, '&nbsp;زمونږ پلار نيکۀ د مالِک خُدائ زمونږ د خُدائ پاک نافرمانه وُو او هغه کار يې کولو چې په څۀ باندې هغه ناراضه کېدو. هغوئ مالِک خُدائ او د هغۀ کور پرېښودو او هغۀ ته يې شا وګرځوله.', NULL, '&nbsp;زمونږ پلار نيکۀ د مالِک خُدائ زمونږ د خُدائ پاک نافرمانه وُو او هغه کار يې کولو چې په څۀ باندې هغه ناراضه کېدو. هغوئ مالِک خُدائ او د هغۀ کور پرېښودو او هغۀ ته يې شا وګرځوله.', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles029_verse_006.mp3', NULL, 1761760676, 1761760676),
(11033, '2 Chronicles 29:7', '2 Chronicles', 29, 7, '&nbsp;هغوئ د ننوتو د کوټې دروازې بندې کړې، ډيوې يې پرېښودې چې مړې شى او خوشبوئى يې نۀ سوزوله او نۀ يې د بنى اِسرائيلو د خُدائ پاک په مقدس ځائ کښې سوزېدونکې نذرانې پېش کړې.', NULL, '&nbsp;هغوئ د ننوتو د کوټې دروازې بندې کړې، ډيوې يې پرېښودې چې مړې شى او خوشبوئى يې نۀ سوزوله او نۀ يې د بنى اِسرائيلو د خُدائ پاک په مقدس ځائ کښې سوزېدونکې نذرانې پېش کړې.', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles029_verse_007.mp3', NULL, 1761760676, 1761760676),
(11034, '2 Chronicles 29:8', '2 Chronicles', 29, 8, '&nbsp;نو په دې وجه مالِک خُدائ يهوداه او يروشلم ته غصه دے او چې هغۀ څۀ کړى دى په هغې باندې هر يو کس حېران دے او يرېدلے دے او سپک يې ګڼى. او تاسو ته د دې ډېره ښۀ پته ده.', NULL, '&nbsp;نو په دې وجه مالِک خُدائ يهوداه او يروشلم ته غصه دے او چې هغۀ څۀ کړى دى په هغې باندې هر يو کس حېران دے او يرېدلے دے او سپک يې ګڼى. او تاسو ته د دې ډېره ښۀ پته ده.', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles029_verse_008.mp3', NULL, 1761760676, 1761760676),
(11035, '2 Chronicles 29:9', '2 Chronicles', 29, 9, '&nbsp;زمونږ پلار نيکۀ په جنګ کښې وژلے شوى وُو او زمونږ ښځې او بچى قېديان بوتلے شوى دى.', NULL, '&nbsp;زمونږ پلار نيکۀ په جنګ کښې وژلے شوى وُو او زمونږ ښځې او بچى قېديان بوتلے شوى دى.', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles029_verse_009.mp3', NULL, 1761760676, 1761760676),
(11036, '2 Chronicles 29:10', '2 Chronicles', 29, 10, '&nbsp;اوس ما دا فېصله کړې ده چې د مالِک خُدائ د بنى اِسرائيلو د خُدائ پاک سره يو لوظ وکړم، نو هغه به نور مونږ ته غصه نۀ وى.', NULL, '&nbsp;اوس ما دا فېصله کړې ده چې د مالِک خُدائ د بنى اِسرائيلو د خُدائ پاک سره يو لوظ وکړم، نو هغه به نور مونږ ته غصه نۀ وى.', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles029_verse_010.mp3', NULL, 1761760676, 1761760676),
(11037, '2 Chronicles 29:11', '2 Chronicles', 29, 11, '&nbsp;زما زامنو وخت مۀ ضائع کوئ. تاسو هغه څوک يئ چې مالِک خُدائ د دې دپاره خوښ کړى يئ چې هغۀ ته خوشبوئى وسوزوئ او د هغۀ په عبادت کښې د خلقو مشرى وکړئ.“', NULL, '&nbsp;زما زامنو وخت مۀ ضائع کوئ. تاسو هغه څوک يئ چې مالِک خُدائ د دې دپاره خوښ کړى يئ چې هغۀ ته خوشبوئى وسوزوئ او د هغۀ په عبادت کښې د خلقو مشرى وکړئ.“', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles029_verse_011.mp3', NULL, 1761760676, 1761760676),
(11038, '2 Chronicles 29:15', '2 Chronicles', 29, 15, '&nbsp;دې سړو خپل ليويان راغونډ کړل او هغوئ ټولو خپل ځانونه پاک کړل. بيا هغوئ د مالِک خُدائ د کور پاکول شروع کړل، هم هغه شان چې څنګه بادشاه حُکم کړے وو. هغوئ په خپل کار کښې د مالِک خُدائ د اصُولو منلو خيال ساتلو.', NULL, '&nbsp;دې سړو خپل ليويان راغونډ کړل او هغوئ ټولو خپل ځانونه پاک کړل. بيا هغوئ د مالِک خُدائ د کور پاکول شروع کړل، هم هغه شان چې څنګه بادشاه حُکم کړے وو. هغوئ په خپل کار کښې د مالِک خُدائ د اصُولو منلو خيال ساتلو.', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles029_verse_015.mp3', NULL, 1761760676, 1761760676),
(11039, '2 Chronicles 29:16', '2 Chronicles', 29, 16, '&nbsp;د مالِک خُدائ د کور مقدس کولو دپاره اِمامان دننه لاړل او هغوئ د مالِک خُدائ د کور دربار ته هغه هر څۀ راوويستل کوم چې ناپاک وُو. ليويانو هغه هر څۀ د ښار نه بهر د قِدرون وادۍ ته يوړل.', NULL, '&nbsp;د مالِک خُدائ د کور مقدس کولو دپاره اِمامان دننه لاړل او هغوئ د مالِک خُدائ د کور دربار ته هغه هر څۀ راوويستل کوم چې ناپاک وُو. ليويانو هغه هر څۀ د ښار نه بهر د قِدرون وادۍ ته يوړل.', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles029_verse_016.mp3', NULL, 1761760676, 1761760676),
(11040, '2 Chronicles 29:17', '2 Chronicles', 29, 17, '&nbsp;نو هغوئ د اولې مياشتې په وړومبۍ ورځ مقدس کول شروع کړل، نو هم د دې مياشتې په اتمه ورځ هغوئ د مالِک خُدائ د کور د ننوتلو دروازې پورې ورسېدل. بيا هغوئ په اتۀ نورو ورځو کښې د مالِک خُدائ کور پاک کړو او د وړومبۍ مياشتې په شپاړسمه ورځ يې ټول کار ختم کړو.', NULL, '&nbsp;نو هغوئ د اولې مياشتې په وړومبۍ ورځ مقدس کول شروع کړل، نو هم د دې مياشتې په اتمه ورځ هغوئ د مالِک خُدائ د کور د ننوتلو دروازې پورې ورسېدل. بيا هغوئ په اتۀ نورو ورځو کښې د مالِک خُدائ کور پاک کړو او د وړومبۍ مياشتې په شپاړسمه ورځ يې ټول کار ختم کړو.', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles029_verse_017.mp3', NULL, 1761760676, 1761760676),
(11041, '2 Chronicles 29:18', '2 Chronicles', 29, 18, '&nbsp;ليويان لاړل او حزقياه بادشاه ته يې دا خبرې وکړې، ”مونږ د مالِک خُدائ د کور د پاکوالى ټول رسم پوره کړے دے، چې په هغې کښې د سوزېدونکې نذرانو قربان‌ګاه، د مقدسې روټۍ مېز او د هغې ټول سامان هم شامل دے.', NULL, '&nbsp;ليويان لاړل او حزقياه بادشاه ته يې دا خبرې وکړې، ”مونږ د مالِک خُدائ د کور د پاکوالى ټول رسم پوره کړے دے، چې په هغې کښې د سوزېدونکې نذرانو قربان‌ګاه، د مقدسې روټۍ مېز او د هغې ټول سامان هم شامل دے.', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles029_verse_018.mp3', NULL, 1761760676, 1761760676),
(11042, '2 Chronicles 29:19', '2 Chronicles', 29, 19, '&nbsp;مونږ هغه ټول سامان هم واپس راوړے دے چې کوم احاز بادشاه د خپلې بادشاهۍ په وخت کښې اوړے وو چې کله هغه د خُدائ پاک نافرمانه وو او مونږ دا بيا وقف کړے دے. دا هر څۀ د مالِک خُدائ د قربان‌ګاه په مخکښې دى.“', NULL, '&nbsp;مونږ هغه ټول سامان هم واپس راوړے دے چې کوم احاز بادشاه د خپلې بادشاهۍ په وخت کښې اوړے وو چې کله هغه د خُدائ پاک نافرمانه وو او مونږ دا بيا وقف کړے دے. دا هر څۀ د مالِک خُدائ د قربان‌ګاه په مخکښې دى.“', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles029_verse_019.mp3', NULL, 1761760676, 1761760676),
(11043, '2 Chronicles 29:20', '2 Chronicles', 29, 20, '&nbsp;نو حزقياه سحر وختى د ښار مشران سړى راغونډ کړل او هغوئ په يو ځائ د مالِک خُدائ کور ته لاړل.', NULL, '&nbsp;نو حزقياه سحر وختى د ښار مشران سړى راغونډ کړل او هغوئ په يو ځائ د مالِک خُدائ کور ته لاړل.', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles029_verse_020.mp3', NULL, 1761760676, 1761760676),
(11044, '2 Chronicles 29:21', '2 Chronicles', 29, 21, '&nbsp;د شاهى خاندان او د يهوداه د خلقو د ګناه د کفارې دپاره او د مالِک خُدائ د کور د پاکولو دپاره، هغوئ اووۀ غوَيى، اووۀ ګډان، اووۀ ګډُورى او اووۀ چېلى د يوې نذرانې په توګه بوتلل. بادشاه د هارون د اولاد اِمامانو ته ووئيل چې هغه ځناور په قربان‌ګاه باندې قربانى کړئ.', NULL, '&nbsp;د شاهى خاندان او د يهوداه د خلقو د ګناه د کفارې دپاره او د مالِک خُدائ د کور د پاکولو دپاره، هغوئ اووۀ غوَيى، اووۀ ګډان، اووۀ ګډُورى او اووۀ چېلى د يوې نذرانې په توګه بوتلل. بادشاه د هارون د اولاد اِمامانو ته ووئيل چې هغه ځناور په قربان‌ګاه باندې قربانى کړئ.', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles029_verse_021.mp3', NULL, 1761760676, 1761760676),
(11045, '2 Chronicles 29:22', '2 Chronicles', 29, 22, '&nbsp;اِمامانو اول غوَيان حلال کړل، بيا يې ګډان او بيا يې ګډُورى حلال کړل او د هرې قربانۍ وينه يې په قربان‌ګاه باندې وشيندله.', NULL, '&nbsp;اِمامانو اول غوَيان حلال کړل، بيا يې ګډان او بيا يې ګډُورى حلال کړل او د هرې قربانۍ وينه يې په قربان‌ګاه باندې وشيندله.', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles029_verse_022.mp3', NULL, 1761760676, 1761760676),
(11046, '2 Chronicles 29:23', '2 Chronicles', 29, 23, '&nbsp;په آخر کښې هغوئ بادشاه او نورو عبادت کوونکو له چېلى راوستل، چې هغوئ خپل لاسونه په دې چېلو باندې کېښودل.', NULL, '&nbsp;په آخر کښې هغوئ بادشاه او نورو عبادت کوونکو له چېلى راوستل، چې هغوئ خپل لاسونه په دې چېلو باندې کېښودل.', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles029_verse_023.mp3', NULL, 1761760676, 1761760676),
(11047, '2 Chronicles 29:24', '2 Chronicles', 29, 24, '&nbsp;اِمامانو بيا چېلى حلال کړل او د دې وينه يې په قربان‌ګاه توئ کړه چې دا د ټولو خلقو د ګناه د کفارې نذرانه شى، ځکه چې بادشاه حُکم کړے وو چې د ټول اِسرائيل دپاره سوزېدونکې نذرانې او د ګناه نذرانې پېش شى.', NULL, '&nbsp;اِمامانو بيا چېلى حلال کړل او د دې وينه يې په قربان‌ګاه توئ کړه چې دا د ټولو خلقو د ګناه د کفارې نذرانه شى، ځکه چې بادشاه حُکم کړے وو چې د ټول اِسرائيل دپاره سوزېدونکې نذرانې او د ګناه نذرانې پېش شى.', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles029_verse_024.mp3', NULL, 1761760676, 1761760676),
(11048, '2 Chronicles 29:25', '2 Chronicles', 29, 25, '&nbsp;بادشاه په هغه اصُولو باندې عمل وکړو چې کوم مالِک خُدائ د بادشاه پېغمبر جاد او د ناتن پېغمبر په ذريعه داؤد بادشاه ته ښودلى وُو، هغۀ د مالِک خُدائ په کور کښې د ربابونو او چمټو سره ليويان مقرر کړل،', NULL, '&nbsp;بادشاه په هغه اصُولو باندې عمل وکړو چې کوم مالِک خُدائ د بادشاه پېغمبر جاد او د ناتن پېغمبر په ذريعه داؤد بادشاه ته ښودلى وُو، هغۀ د مالِک خُدائ په کور کښې د ربابونو او چمټو سره ليويان مقرر کړل،', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles029_verse_025.mp3', NULL, 1761760676, 1761760676),
(11049, '2 Chronicles 29:26', '2 Chronicles', 29, 26, '&nbsp;دا د موسيقۍ هم هغه شان څيزونه وُو چې څنګه داؤد بادشاه استعمال کړى وُو. هلته اِمامان هم د بيګلو سره ولاړ وُو.', NULL, '&nbsp;دا د موسيقۍ هم هغه شان څيزونه وُو چې څنګه داؤد بادشاه استعمال کړى وُو. هلته اِمامان هم د بيګلو سره ولاړ وُو.', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles029_verse_026.mp3', NULL, 1761760676, 1761760676),
(11050, '2 Chronicles 29:27', '2 Chronicles', 29, 27, '&nbsp;حزقياه حُکم وکړو چې سوزېدونکې نذرانه دې پېش کړے شى، او چې څنګه د نذرانې پېش کېدل شروع شول، نو خلقو د مالِک خُدائ ثناء صِفت وئيل شروع کړل او موسيقارانو د بيګلو او نورو څيزونو غږول شروع کړل.', NULL, '&nbsp;حزقياه حُکم وکړو چې سوزېدونکې نذرانه دې پېش کړے شى، او چې څنګه د نذرانې پېش کېدل شروع شول، نو خلقو د مالِک خُدائ ثناء صِفت وئيل شروع کړل او موسيقارانو د بيګلو او نورو څيزونو غږول شروع کړل.', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles029_verse_027.mp3', NULL, 1761760676, 1761760676),
(11051, '2 Chronicles 29:28', '2 Chronicles', 29, 28, '&nbsp;هلته چې هر څوک هم وو نو هغوئ په عبادت کښې شريک شُو او ثناء صِفت وکړو او نوره موسيقى تر هغه وخت پورې جارى وه چې ټولې نذرانې وسوزولے شوې.', NULL, '&nbsp;هلته چې هر څوک هم وو نو هغوئ په عبادت کښې شريک شُو او ثناء صِفت وکړو او نوره موسيقى تر هغه وخت پورې جارى وه چې ټولې نذرانې وسوزولے شوې.', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles029_verse_028.mp3', NULL, 1761760676, 1761760676),
(11052, '2 Chronicles 29:29', '2 Chronicles', 29, 29, '&nbsp;بيا حزقياه بادشاه او ټول خلق ټيټ شول او د خُدائ پاک عبادت يې وکړو.', NULL, '&nbsp;بيا حزقياه بادشاه او ټول خلق ټيټ شول او د خُدائ پاک عبادت يې وکړو.', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles029_verse_029.mp3', NULL, 1761760676, 1761760676),
(11053, '2 Chronicles 29:30', '2 Chronicles', 29, 30, '&nbsp;بادشاه د قوم مشرانو ليويانو ته وفرمائيل چې د مالِک خُدائ د ثناء صِفت هغه سندرې ووايئ کومې چې د داؤد او د آسف پېغمبر په ذريعه ليکلے شوې وې. نو هر يو د لوئې خوشحالۍ سره او سندرې ووئيلې هغوئ د خُدائ پاک په وړاندې په زنګنونو او ټيټ شول او د هغۀ عبادت يې وکړو.', NULL, '&nbsp;بادشاه د قوم مشرانو ليويانو ته وفرمائيل چې د مالِک خُدائ د ثناء صِفت هغه سندرې ووايئ کومې چې د داؤد او د آسف پېغمبر په ذريعه ليکلے شوې وې. نو هر يو د لوئې خوشحالۍ سره او سندرې ووئيلې هغوئ د خُدائ پاک په وړاندې په زنګنونو او ټيټ شول او د هغۀ عبادت يې وکړو.', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles029_verse_030.mp3', NULL, 1761760676, 1761760676),
(11054, '2 Chronicles 29:31', '2 Chronicles', 29, 31, '&nbsp;حزقياه خلقو ته وفرمائيل، ”اوس چې تاسو پاک شوئ، نو د مالِک خُدائ کور ته قربانۍ او د شکرانې نذرانې راوړئ.“ نو خلقو خپلې قربانۍ او د شکرانې نذرانې راوړې او چا چې غوښتل نو هغوئ سوزېدونکې نذرانې هم راوړې.', NULL, '&nbsp;حزقياه خلقو ته وفرمائيل، ”اوس چې تاسو پاک شوئ، نو د مالِک خُدائ کور ته قربانۍ او د شکرانې نذرانې راوړئ.“ نو خلقو خپلې قربانۍ او د شکرانې نذرانې راوړې او چا چې غوښتل نو هغوئ سوزېدونکې نذرانې هم راوړې.', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles029_verse_031.mp3', NULL, 1761760676, 1761760676),
(11055, '2 Chronicles 29:32', '2 Chronicles', 29, 32, '&nbsp;هغوئ مالِک خُدائ ته د سوزېدونکې نذرانې په توګه اويا غوَيى، سل ګډان او دوه سوه ګډُورى راوستل،', NULL, '&nbsp;هغوئ مالِک خُدائ ته د سوزېدونکې نذرانې په توګه اويا غوَيى، سل ګډان او دوه سوه ګډُورى راوستل،', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles029_verse_032.mp3', NULL, 1761760676, 1761760676),
(11056, '2 Chronicles 29:33', '2 Chronicles', 29, 33, '&nbsp;هغوئ شپږ سوه غوَيى او درې زره ګډان هم راوستل چې د خلقو د خوړلو دپاره قربانى شى.', NULL, '&nbsp;هغوئ شپږ سوه غوَيى او درې زره ګډان هم راوستل چې د خلقو د خوړلو دپاره قربانى شى.', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles029_verse_033.mp3', NULL, 1761760676, 1761760676),
(11057, '2 Chronicles 29:34', '2 Chronicles', 29, 34, '&nbsp;خو اِمامان دومره لږ وُو چې دا ټول ځناور يې نۀ شول حلالولے، نو ليويانو د کار د ختمېدو پورې د هغوئ مدد کولو تر هغه وخته پورې چې نورو اِمامانو ځانونه پاک کړل. ليويانو د ځان په پاک ساتلو کښې د اِمامانو نه زيات خيال ساتلو.', NULL, '&nbsp;خو اِمامان دومره لږ وُو چې دا ټول ځناور يې نۀ شول حلالولے، نو ليويانو د کار د ختمېدو پورې د هغوئ مدد کولو تر هغه وخته پورې چې نورو اِمامانو ځانونه پاک کړل. ليويانو د ځان په پاک ساتلو کښې د اِمامانو نه زيات خيال ساتلو.', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles029_verse_034.mp3', NULL, 1761760676, 1761760676),
(11058, '2 Chronicles 29:35', '2 Chronicles', 29, 35, '&nbsp;د پوره سوزېدونکو نذرانو د پېش کېدو نه علاوه، اِمامان د هغه وازګې د سوزولو هم ذمه وار وُو کومه چې د هغه نذرانو نه پېش کړے شوې وه چې خلقو خوړلې وه او هغوئ د هغه ميو د تويولو هم ذمه وار وُو چې د سوزېدونکې نذرانو سره پېش کړے شوى وُو. نو داسې د مالِک خُدائ په کور کښې عبادت بيا شروع شو.', NULL, '&nbsp;د پوره سوزېدونکو نذرانو د پېش کېدو نه علاوه، اِمامان د هغه وازګې د سوزولو هم ذمه وار وُو کومه چې د هغه نذرانو نه پېش کړے شوې وه چې خلقو خوړلې وه او هغوئ د هغه ميو د تويولو هم ذمه وار وُو چې د سوزېدونکې نذرانو سره پېش کړے شوى وُو. نو داسې د مالِک خُدائ په کور کښې عبادت بيا شروع شو.', 'NT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761760676, 1761760676),
(11059, '2 Chronicles 29:36', '2 Chronicles', 29, 36, '&nbsp;حزقياه بادشاه او خلق خوشحاله وُو، ځکه چې خُدائ پاک د هغوئ مدد کړے وو چې هر څۀ زر زر وشى.', NULL, '&nbsp;حزقياه بادشاه او خلق خوشحاله وُو، ځکه چې خُدائ پاک د هغوئ مدد کړے وو چې هر څۀ زر زر وشى.', 'NT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761760676, 1761760676),
(11060, '2 Chronicles 30:4', '2 Chronicles', 30, 4, '&nbsp;نو دا خبره بادشاه او نورو خلقو ته ښۀ ښکاره شوه،', NULL, '&nbsp;نو دا خبره بادشاه او نورو خلقو ته ښۀ ښکاره شوه،', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles030_verse_004.mp3', NULL, 1761760676, 1761760676),
(11061, '2 Chronicles 30:5', '2 Chronicles', 30, 5, '&nbsp;نو هغوئ په شمال کښې د دان نه واخله په جنوب کښې د بيرسبع پورې ټول اِسرائيل له دعوت ورکړو، چې په يروشلم کښې په دومره لوئ شمېر کښې راغونډ شى چې مخکښې نۀ وى راغونډ شوى او د قانون په مطابق د فسحې اختر وکړى.', NULL, '&nbsp;نو هغوئ په شمال کښې د دان نه واخله په جنوب کښې د بيرسبع پورې ټول اِسرائيل له دعوت ورکړو، چې په يروشلم کښې په دومره لوئ شمېر کښې راغونډ شى چې مخکښې نۀ وى راغونډ شوى او د قانون په مطابق د فسحې اختر وکړى.', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles030_verse_005.mp3', NULL, 1761760676, 1761760676),
(11062, '2 Chronicles 30:6', '2 Chronicles', 30, 6, '&nbsp;نو پېغام وړُونکى د بادشاه او د هغۀ د آفسرانو په حُکم د دې دعوت سره ټول يهوداه او اِسرائيل ته لاړل، ”اے بنى اِسرائيلو، تاسو د اسور بادشاهانو نه بچ شوى يئ چې کله هغوئ مُلک قبضه کړے وو. نو اوس مالِک خُدائ ته راوګرځئ، کوم چې د اِبراهيم، اِسحاق او يعقوب خُدائ پاک دے او هغه به تاسو ته راوګرځى.', NULL, '&nbsp;نو پېغام وړُونکى د بادشاه او د هغۀ د آفسرانو په حُکم د دې دعوت سره ټول يهوداه او اِسرائيل ته لاړل، ”اے بنى اِسرائيلو، تاسو د اسور بادشاهانو نه بچ شوى يئ چې کله هغوئ مُلک قبضه کړے وو. نو اوس مالِک خُدائ ته راوګرځئ، کوم چې د اِبراهيم، اِسحاق او يعقوب خُدائ پاک دے او هغه به تاسو ته راوګرځى.', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles030_verse_006.mp3', NULL, 1761760676, 1761760676),
(11063, '2 Chronicles 30:7', '2 Chronicles', 30, 7, '&nbsp;د خپل پلار نيکۀ او د خپلوانو په شان مۀ جوړېږئ څوک چې د مالِک خُدائ د هغوئ د خُدائ پاک وفادار نۀ وُو. لکه څنګه چې تاسو ته پته ده چې هغوئ له يې سخته سزا ورکړه.', NULL, '&nbsp;د خپل پلار نيکۀ او د خپلوانو په شان مۀ جوړېږئ څوک چې د مالِک خُدائ د هغوئ د خُدائ پاک وفادار نۀ وُو. لکه څنګه چې تاسو ته پته ده چې هغوئ له يې سخته سزا ورکړه.', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles030_verse_007.mp3', NULL, 1761760676, 1761760676),
(11064, '2 Chronicles 30:8', '2 Chronicles', 30, 8, '&nbsp;د هغوئ په شان ضدى مۀ جوړېږئ، خو د مالِک خُدائ تابعدارى کوئ. په يروشلم کښې د مالِک خُدائ کور ته راځئ، کوم چې مالِک خُدائ ستاسو خُدائ پاک د همېشه دپاره مقدس کړے دے او د هغۀ عبادت کوئ نو داسې به د هغۀ د سخت قهر نه خلاص شئ.', NULL, '&nbsp;د هغوئ په شان ضدى مۀ جوړېږئ، خو د مالِک خُدائ تابعدارى کوئ. په يروشلم کښې د مالِک خُدائ کور ته راځئ، کوم چې مالِک خُدائ ستاسو خُدائ پاک د همېشه دپاره مقدس کړے دے او د هغۀ عبادت کوئ نو داسې به د هغۀ د سخت قهر نه خلاص شئ.', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles030_verse_008.mp3', NULL, 1761760676, 1761760676),
(11065, '2 Chronicles 30:9', '2 Chronicles', 30, 9, '&nbsp;کۀ تاسو مالِک خُدائ ته راوګرځئ، نو چا چې ستاسو خپلوان اغوا کړى دى نو هغوئ به ستاسو په خپلوانو باندې رحم وکړى او هغوئ به خپلو کورونو ته بيا راولى. مالِک خُدائ، خُدائ پاک رحمان او رحيم دے او کۀ تاسو هغۀ ته راوګرځئ، نو هغه به تاسو قبول کړى.“', NULL, '&nbsp;کۀ تاسو مالِک خُدائ ته راوګرځئ، نو چا چې ستاسو خپلوان اغوا کړى دى نو هغوئ به ستاسو په خپلوانو باندې رحم وکړى او هغوئ به خپلو کورونو ته بيا راولى. مالِک خُدائ، خُدائ پاک رحمان او رحيم دے او کۀ تاسو هغۀ ته راوګرځئ، نو هغه به تاسو قبول کړى.“', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles030_verse_009.mp3', NULL, 1761760676, 1761760676),
(11066, '2 Chronicles 30:10', '2 Chronicles', 30, 10, '&nbsp;پېغام‌وړونکى په شمال کښې د زبولون قبيلې پورې د اِفرائيم او منسى قبيلو په علاقې کښې هر يو ښار ته لاړل، خو خلقو په هغوئ پورې خندل او ټوقې يې ورپورې کولې.', NULL, '&nbsp;پېغام‌وړونکى په شمال کښې د زبولون قبيلې پورې د اِفرائيم او منسى قبيلو په علاقې کښې هر يو ښار ته لاړل، خو خلقو په هغوئ پورې خندل او ټوقې يې ورپورې کولې.', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles030_verse_010.mp3', NULL, 1761760676, 1761760676),
(11067, '2 Chronicles 30:11', '2 Chronicles', 30, 11, '&nbsp;خو بيا هم د آشر، منسى او د زبولون قبيلو څۀ خلقو عاجزى ښکاره کړه او يروشلم ته لاړل.', NULL, '&nbsp;خو بيا هم د آشر، منسى او د زبولون قبيلو څۀ خلقو عاجزى ښکاره کړه او يروشلم ته لاړل.', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles030_verse_011.mp3', NULL, 1761760676, 1761760676),
(11068, '2 Chronicles 30:12', '2 Chronicles', 30, 12, '&nbsp;خُدائ پاک د يهوداه خلق هم د دې دپاره متحد کړل چې د هغۀ په مرضۍ باندې روان شى او د بادشاه او د هغۀ د آفسرانو حُکمونه ومنى.', NULL, '&nbsp;خُدائ پاک د يهوداه خلق هم د دې دپاره متحد کړل چې د هغۀ په مرضۍ باندې روان شى او د بادشاه او د هغۀ د آفسرانو حُکمونه ومنى.', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles030_verse_012.mp3', NULL, 1761760676, 1761760676),
(11069, '2 Chronicles 30:13', '2 Chronicles', 30, 13, '&nbsp;په دوېمه مياشت کښې د خلقو يو لوئ شمېر په يروشلم کښې راغونډ شو چې د پتيرې روټۍ اختر وکړى.', NULL, '&nbsp;په دوېمه مياشت کښې د خلقو يو لوئ شمېر په يروشلم کښې راغونډ شو چې د پتيرې روټۍ اختر وکړى.', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles030_verse_013.mp3', NULL, 1761760676, 1761760676),
(11070, '2 Chronicles 30:14', '2 Chronicles', 30, 14, '&nbsp;هغوئ هغه ټولې قربان‌ګاه واخستلې کومې چې په يروشلم کښې د نذرانو د پېش کولو او د خوشبويۍ د سوزولو دپاره استعمالېدلې او د قِدرون په وادۍ کښې يې وغورزولې.', NULL, '&nbsp;هغوئ هغه ټولې قربان‌ګاه واخستلې کومې چې په يروشلم کښې د نذرانو د پېش کولو او د خوشبويۍ د سوزولو دپاره استعمالېدلې او د قِدرون په وادۍ کښې يې وغورزولې.', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles030_verse_014.mp3', NULL, 1761760676, 1761760676),
(11071, '2 Chronicles 30:15', '2 Chronicles', 30, 15, '&nbsp;او د هغه مياشتې په څوارلسمه ورځ هغوئ د فسحې اختر د قربانۍ دپاره ګډُورى حلال کړل. کوم اِمامان او ليويان چې پاک نۀ وُو نو هغوئ دومره وشرمېدل چې خپل ځانونه يې مالِک خُدائ ته وقف کړل، نو داسې هغوئ د مالِک خُدائ په کور کښې سوزېدونکې نذرانې پېش کولے شوې.', NULL, '&nbsp;او د هغه مياشتې په څوارلسمه ورځ هغوئ د فسحې اختر د قربانۍ دپاره ګډُورى حلال کړل. کوم اِمامان او ليويان چې پاک نۀ وُو نو هغوئ دومره وشرمېدل چې خپل ځانونه يې مالِک خُدائ ته وقف کړل، نو داسې هغوئ د مالِک خُدائ په کور کښې سوزېدونکې نذرانې پېش کولے شوې.', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles030_verse_015.mp3', NULL, 1761760676, 1761760676),
(11072, '2 Chronicles 30:16', '2 Chronicles', 30, 16, '&nbsp;هغوئ د خُدائ پاک د خِدمتګار موسىٰ د شريعت په مطابق د مالِک خُدائ په کور کښې په خپلو ځايونو باندې ودرېدل. ليويانو د قربانۍ وينه اِمامانو له ورکړه، چې هغوئ دا په قربان‌ګاه باندې وشيندله.', NULL, '&nbsp;هغوئ د خُدائ پاک د خِدمتګار موسىٰ د شريعت په مطابق د مالِک خُدائ په کور کښې په خپلو ځايونو باندې ودرېدل. ليويانو د قربانۍ وينه اِمامانو له ورکړه، چې هغوئ دا په قربان‌ګاه باندې وشيندله.', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles030_verse_016.mp3', NULL, 1761760676, 1761760676),
(11073, '2 Chronicles 30:17', '2 Chronicles', 30, 17, '&nbsp;په دغه مجمه کښې ډېر خلق په اودس کښې نۀ وُو، نو په دې وجه هغوئ د فسحې اختر ګډُورى نۀ شُو حلالولے، نو ليويانو د هغوئ دپاره حلال کړل او هغه ګډُورى يې مالِک خُدائ ته وقف کړل.', NULL, '&nbsp;په دغه مجمه کښې ډېر خلق په اودس کښې نۀ وُو، نو په دې وجه هغوئ د فسحې اختر ګډُورى نۀ شُو حلالولے، نو ليويانو د هغوئ دپاره حلال کړل او هغه ګډُورى يې مالِک خُدائ ته وقف کړل.', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles030_verse_017.mp3', NULL, 1761760676, 1761760676),
(11074, '2 Chronicles 30:18', '2 Chronicles', 30, 18, '&nbsp;د دې نه علاوه، هغه ډېر کسان کوم چې د اِفرائيم، منسى، يساکار او زبولون د قبيلو نه راغلى وُو نو هغوئ د پاکوالى رسم نۀ وو ادا کړے، نو هغوئ په غلطه طريقه باندې د فسحې اختر کولو. حزقياه بادشاه د هغوئ دپاره دا دُعا وکړه،', NULL, '&nbsp;د دې نه علاوه، هغه ډېر کسان کوم چې د اِفرائيم، منسى، يساکار او زبولون د قبيلو نه راغلى وُو نو هغوئ د پاکوالى رسم نۀ وو ادا کړے، نو هغوئ په غلطه طريقه باندې د فسحې اختر کولو. حزقياه بادشاه د هغوئ دپاره دا دُعا وکړه،', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles030_verse_018.mp3', NULL, 1761760676, 1761760676),
(11075, '2 Chronicles 30:19', '2 Chronicles', 30, 19, '&nbsp;”اے مالِکه خُدايه، زمونږ د پلار نيکۀ خُدايه پاکه. د خپل رحم په وجه هغه کسان معاف کړه چې هغوئ د زړۀ د اخلاصه ستا عبادت کوى، اګر چې هغوئ پاک هم نۀ دى.“', NULL, '&nbsp;”اے مالِکه خُدايه، زمونږ د پلار نيکۀ خُدايه پاکه. د خپل رحم په وجه هغه کسان معاف کړه چې هغوئ د زړۀ د اخلاصه ستا عبادت کوى، اګر چې هغوئ پاک هم نۀ دى.“', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles030_verse_019.mp3', NULL, 1761760676, 1761760676),
(11076, '2 Chronicles 30:20', '2 Chronicles', 30, 20, '&nbsp;مالِک خُدائ د حزقياه دُعا واورېدله، هغۀ هغه خلق معاف کړل او هغوئ ته يې څۀ نقصان ونۀ رسولو.', NULL, '&nbsp;مالِک خُدائ د حزقياه دُعا واورېدله، هغۀ هغه خلق معاف کړل او هغوئ ته يې څۀ نقصان ونۀ رسولو.', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles030_verse_020.mp3', NULL, 1761760676, 1761760676),
(11077, '2 Chronicles 30:21', '2 Chronicles', 30, 21, '&nbsp;کوم خلق چې په يروشلم کښې راغونډ شوى وُو نو هغوئ د لوئې خوشحالۍ سره اووۀ ورځې د پتيرې روټۍ اختر کولو او ليويانو او اِمامانو هره ورځ د جذبې سره د مالِک خُدائ ثناء صِفت کولو.', NULL, '&nbsp;کوم خلق چې په يروشلم کښې راغونډ شوى وُو نو هغوئ د لوئې خوشحالۍ سره اووۀ ورځې د پتيرې روټۍ اختر کولو او ليويانو او اِمامانو هره ورځ د جذبې سره د مالِک خُدائ ثناء صِفت کولو.', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles030_verse_021.mp3', NULL, 1761760676, 1761760676),
(11078, '2 Chronicles 30:22', '2 Chronicles', 30, 22, '&nbsp;حزقياه د ليويانو دا صِفت وکړو ځکه چې هغوئ د مالِک خُدائ په عبادت کښې تکړه وُو. دوېم ځل خوشحالى کول د هغه اوو ورځو نه پس په کومو کښې چې هغوئ د مالِک خُدائ په ثناء صِفت کښې قربانۍ پېش کړې وې، چې کوم د هغوئ د پلار نيکۀ خُدائ پاک دے،', NULL, '&nbsp;حزقياه د ليويانو دا صِفت وکړو ځکه چې هغوئ د مالِک خُدائ په عبادت کښې تکړه وُو.
</p><h3 class="sectiontitle">دوېم ځل خوشحالى کول</h3>
<p>د هغه اوو ورځو نه پس په کومو کښې چې هغوئ د مالِک خُدائ په ثناء صِفت کښې قربانۍ پېش کړې وې، چې کوم د هغوئ د پلار نيکۀ خُدائ پاک دے،', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles030_verse_022.mp3', NULL, 1761760676, 1761760676),
(11079, '2 Chronicles 30:23', '2 Chronicles', 30, 23, '&nbsp;هغوئ ټولو دا فېصله وکړه چې اووۀ ورځې به نور اختر کوى. نو هغوئ د خوشحالۍ سره اختر وکړو.', NULL, '&nbsp;هغوئ ټولو دا فېصله وکړه چې اووۀ ورځې به نور اختر کوى. نو هغوئ د خوشحالۍ سره اختر وکړو.', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles030_verse_023.mp3', NULL, 1761760676, 1761760676),
(11080, '2 Chronicles 30:24', '2 Chronicles', 30, 24, '&nbsp;حزقياه بادشاه يو زر غوَيى او اووۀ زره ګډان خلقو له ورکړل چې حلال يې کړى او وې خورى او آفسرانو هغوئ له يو زر نور غوَيى او لس زره ګډان ورکړل. نو داسې د ډېرو اِمامانو د پاکوالى رسم ادا شو.', NULL, '&nbsp;حزقياه بادشاه يو زر غوَيى او اووۀ زره ګډان خلقو له ورکړل چې حلال يې کړى او وې خورى او آفسرانو هغوئ له يو زر نور غوَيى او لس زره ګډان ورکړل. نو داسې د ډېرو اِمامانو د پاکوالى رسم ادا شو.', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles030_verse_024.mp3', NULL, 1761760676, 1761760676),
(11081, '2 Chronicles 30:25', '2 Chronicles', 30, 25, '&nbsp;نو دا ټول خوشحاله وُو، د يهوداه خلق، اِمامان، ليويان، هغه خلق چې کوم د شمالى طرف نه راغلى وُو او هغه مسافر کوم چې په اِسرائيل او يهوداه کښې پاخۀ دېره شوى وُو.', NULL, '&nbsp;نو دا ټول خوشحاله وُو، د يهوداه خلق، اِمامان، ليويان، هغه خلق چې کوم د شمالى طرف نه راغلى وُو او هغه مسافر کوم چې په اِسرائيل او يهوداه کښې پاخۀ دېره شوى وُو.', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles030_verse_025.mp3', NULL, 1761760676, 1761760676),
(11082, '2 Chronicles 30:26', '2 Chronicles', 30, 26, '&nbsp;د يروشلم ښار د خوشحالۍ نه ډک وو، ځکه چې د داؤد زوئ سليمان د وخت نه پس هيڅکله هم داسې نۀ وُو شوى.', NULL, '&nbsp;د يروشلم ښار د خوشحالۍ نه ډک وو، ځکه چې د داؤد زوئ سليمان د وخت نه پس هيڅکله هم داسې نۀ وُو شوى.', 'NT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761760676, 1761760676),
(11083, '2 Chronicles 30:27', '2 Chronicles', 30, 27, '&nbsp;اِمامانو او ليويانو د خلقو دپاره د مالِک خُدائ برکت وغوښتلو. خُدائ پاک په آسمان کښې په خپل کور کښې د هغوئ دُعاګانې واورېدلې او قبولې يې کړې.', NULL, '&nbsp;اِمامانو او ليويانو د خلقو دپاره د مالِک خُدائ برکت وغوښتلو. خُدائ پاک په آسمان کښې په خپل کور کښې د هغوئ دُعاګانې واورېدلې او قبولې يې کړې.', 'NT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761760676, 1761760676),
(11084, '2 Chronicles 31:1', '2 Chronicles', 31, 1, '&nbsp;د اختر د ختمېدو نه پس، ټول اِسرائيليان د يهوداه هر يو ښار ته لاړل، او د کاڼو ستنې يې ماتې کړې، د اشيرې بُت نښې يې راوغورزولې او قربان‌ګاه او علاقائى عبادتخانې يې تباه کړې. هغوئ په باقى ټوله يهوداه کښې، د بنيامين، اِفرائيم او منسى په علاقو کښې هم دغه شان وکړل، بيا هغوئ ټول کورونو ته راواپس شول.', NULL, '&nbsp;د اختر د ختمېدو نه پس، ټول اِسرائيليان د يهوداه هر يو ښار ته لاړل، او د کاڼو ستنې يې ماتې کړې، د اشيرې بُت نښې يې راوغورزولې او قربان‌ګاه او علاقائى عبادتخانې يې تباه کړې. هغوئ په باقى ټوله يهوداه کښې، د بنيامين، اِفرائيم او منسى په علاقو کښې هم دغه شان وکړل، بيا هغوئ ټول کورونو ته راواپس شول.', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles031_verse_001.mp3', NULL, 1761760676, 1761760676),
(11085, '2 Chronicles 31:2', '2 Chronicles', 31, 2, '&nbsp;حزقياه بادشاه د اِمامانو او ليويانو تنظيم هم بيا جوړ کړو، چې د هغې لاندې هر يو خپلې خاص ذمه وارۍ لرلې. په دې کښې د سوزېدونکو نذرانو او د سلامتۍ د نذرانو پېش کول، او د مالِک خُدائ د کور په دروازو کښې ثناء صِفت کول او شُکر ادا کول هم شامل وُو.', NULL, '&nbsp;حزقياه بادشاه د اِمامانو او ليويانو تنظيم هم بيا جوړ کړو، چې د هغې لاندې هر يو خپلې خاص ذمه وارۍ لرلې. په دې کښې د سوزېدونکو نذرانو او د سلامتۍ د نذرانو پېش کول، او د مالِک خُدائ د کور په دروازو کښې ثناء صِفت کول او شُکر ادا کول هم شامل وُو.', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles031_verse_002.mp3', NULL, 1761760676, 1761760676),
(11086, '2 Chronicles 31:3', '2 Chronicles', 31, 3, '&nbsp;هر سحر او هر ماښام به هغۀ د خپلو رَمو او څاروو نه د سوزېدونکې نذرانو دپاره ځناور ورکول او دا ځناور به د سبت په ورځ، د نوې مياشتې په اختر کښې او چې په نورو اخترونو کښې پېش کېدل، کوم چې د مالِک خُدائ په قانون کښې ليکلے شوى وُو.', NULL, '&nbsp;هر سحر او هر ماښام به هغۀ د خپلو رَمو او څاروو نه د سوزېدونکې نذرانو دپاره ځناور ورکول او دا ځناور به د سبت په ورځ، د نوې مياشتې په اختر کښې او چې په نورو اخترونو کښې پېش کېدل، کوم چې د مالِک خُدائ په قانون کښې ليکلے شوى وُو.', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles031_verse_003.mp3', NULL, 1761760676, 1761760676),
(11087, '2 Chronicles 31:4', '2 Chronicles', 31, 4, '&nbsp;د دې نه علاوه، بادشاه د يروشلم خلقو ته وفرمائيل چې هغه نذرانې راوړى چې دا اِمامانو او ليويانو حق جوړېدو، نو چې داسې هغوئ هر وخت د مالِک خُدائ قانون ته وقف وى.', NULL, '&nbsp;د دې نه علاوه، بادشاه د يروشلم خلقو ته وفرمائيل چې هغه نذرانې راوړى چې دا اِمامانو او ليويانو حق جوړېدو، نو چې داسې هغوئ هر وخت د مالِک خُدائ قانون ته وقف وى.', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles031_verse_004.mp3', NULL, 1761760676, 1761760676),
(11088, '2 Chronicles 31:5', '2 Chronicles', 31, 5, '&nbsp;چې اِسرائيليانو څنګه دا حُکم واورېدو نو هغوئ د خپلو وړومبو غلو، ميو، د زيتُونو تېلو، شاتو او د نور پېداوار تُحفې راوړې او چې هغوئ څۀ هم لرل د هغې لسمه برخه يې هم راوړه.', NULL, '&nbsp;چې اِسرائيليانو څنګه دا حُکم واورېدو نو هغوئ د خپلو وړومبو غلو، ميو، د زيتُونو تېلو، شاتو او د نور پېداوار تُحفې راوړې او چې هغوئ څۀ هم لرل د هغې لسمه برخه يې هم راوړه.', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles031_verse_005.mp3', NULL, 1761760676, 1761760676),
(11089, '2 Chronicles 31:6', '2 Chronicles', 31, 6, '&nbsp;کوم خلق چې د يهوداه په ښارونو کښې اوسېدل نو هغوئ ټولو د خپلو څاروو او ګډو، لسمه حِصه راوړه او هغوئ ډېرې زياتې تُحفې هم راوړې، چې هغه يې مالِک خُدائ خپل خُدائ پاک ته وقف کړې.', NULL, '&nbsp;کوم خلق چې د يهوداه په ښارونو کښې اوسېدل نو هغوئ ټولو د خپلو څاروو او ګډو، لسمه حِصه راوړه او هغوئ ډېرې زياتې تُحفې هم راوړې، چې هغه يې مالِک خُدائ خپل خُدائ پاک ته وقف کړې.', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles031_verse_006.mp3', NULL, 1761760676, 1761760676),
(11090, '2 Chronicles 31:7', '2 Chronicles', 31, 7, '&nbsp;په درېمه مياشت کښې د تُحفو راتلل شروع شول او تر ورپسې څلورو مياشتو پورې د دې نه ډېرى جوړېدل شروع وُو.', NULL, '&nbsp;په درېمه مياشت کښې د تُحفو راتلل شروع شول او تر ورپسې څلورو مياشتو پورې د دې نه ډېرى جوړېدل شروع وُو.', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles031_verse_007.mp3', NULL, 1761760676, 1761760676),
(11091, '2 Chronicles 31:8', '2 Chronicles', 31, 8, '&nbsp;کله چې حزقياه بادشاه او د هغۀ آفسران راغلل او دا لوئ ډېرى يې وليدل، نو هغوئ د مالِک خُدائ ثناء صِفت وکړو او د خپلو اِسرائيليانو صِفت يې هم وکړو.', NULL, '&nbsp;کله چې حزقياه بادشاه او د هغۀ آفسران راغلل او دا لوئ ډېرى يې وليدل، نو هغوئ د مالِک خُدائ ثناء صِفت وکړو او د خپلو اِسرائيليانو صِفت يې هم وکړو.', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles031_verse_008.mp3', NULL, 1761760676, 1761760676),
(11092, '2 Chronicles 31:9', '2 Chronicles', 31, 9, '&nbsp;بادشاه د اِمامانو او ليويانو سره د دې تُحفو په حقله خبره وکړه،', NULL, '&nbsp;بادشاه د اِمامانو او ليويانو سره د دې تُحفو په حقله خبره وکړه،', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles031_verse_009.mp3', NULL, 1761760676, 1761760676),
(11093, '2 Chronicles 31:10', '2 Chronicles', 31, 10, '&nbsp;او د صدوق د اولاد يو کس، مشر اِمام عزرياه هغۀ ته ووئيل، ”خلقو خپلې تُحفې د مالِک خُدائ کور ته راوړل شروع کړى دى، نو په دې وجه دا د خوراک دپاره کافى دى او د دې نه علاوه دا ډېر زيات هم دى. دا هر څۀ مونږ سره ځکه زيات پاتې شوى دى چې مالِک خُدائ خپلو خلقو له برکت ورکړے دے.“', NULL, '&nbsp;او د صدوق د اولاد يو کس، مشر اِمام عزرياه هغۀ ته ووئيل، ”خلقو خپلې تُحفې د مالِک خُدائ کور ته راوړل شروع کړى دى، نو په دې وجه دا د خوراک دپاره کافى دى او د دې نه علاوه دا ډېر زيات هم دى. دا هر څۀ مونږ سره ځکه زيات پاتې شوى دى چې مالِک خُدائ خپلو خلقو له برکت ورکړے دے.“', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles031_verse_010.mp3', NULL, 1761760676, 1761760676),
(11094, '2 Chronicles 31:11', '2 Chronicles', 31, 11, '&nbsp;د بادشاه په حُکم هغوئ د مالِک خُدائ په کور کښې ګودامونه جوړ کړل', NULL, '&nbsp;د بادشاه په حُکم هغوئ د مالِک خُدائ په کور کښې ګودامونه جوړ کړل', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles031_verse_011.mp3', NULL, 1761760676, 1761760676),
(11095, '2 Chronicles 31:12', '2 Chronicles', 31, 12, '&nbsp;او ټولې تُحفې او لسمې حِصې يې د امانت په توګه کېښودې. هغوئ يو ليوى مشر مقرر کړو چې نوم يې کنعنياه وو او د هغۀ ورور سِمعى يې د هغۀ مددګار جوړ کړو.', NULL, '&nbsp;او ټولې تُحفې او لسمې حِصې يې د امانت په توګه کېښودې. هغوئ يو ليوى مشر مقرر کړو چې نوم يې کنعنياه وو او د هغۀ ورور سِمعى يې د هغۀ مددګار جوړ کړو.', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles031_verse_012.mp3', NULL, 1761760676, 1761760676),
(11096, '2 Chronicles 31:13', '2 Chronicles', 31, 13, '&nbsp;دې لسو ليويانو ته د هغوئ د اختيار لاندې کار کول حواله شوے وو: يحى‌ايل، عززياه، نحت، عساهيل، يريموت، يوزبد، اِلى‌ايل، اِسماکياه، محت، او بناياه. دا هر څۀ د حزقياه بادشاه او د مشر اِمام عزرياه د اختيار لاندې شوى وُو.', NULL, '&nbsp;دې لسو ليويانو ته د هغوئ د اختيار لاندې کار کول حواله شوے وو: يحى‌ايل، عززياه، نحت، عساهيل، يريموت، يوزبد، اِلى‌ايل، اِسماکياه، محت، او بناياه. دا هر څۀ د حزقياه بادشاه او د مشر اِمام عزرياه د اختيار لاندې شوى وُو.', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles031_verse_013.mp3', NULL, 1761760676, 1761760676),
(11097, '2 Chronicles 31:14', '2 Chronicles', 31, 14, '&nbsp;يو ليوى، د يمنه زوئ قورې څوک چې د مالِک خُدائ د کور د نمرخاتۀ طرف ته دروازې مشر څوکيدار وو، هغه د هغه تُحفو د وصولولو او د تقسيمولو مشر وو چې کومې مالِک خُدائ ته پېش کېدلې.', NULL, '&nbsp;يو ليوى، د يمنه زوئ قورې څوک چې د مالِک خُدائ د کور د نمرخاتۀ طرف ته دروازې مشر څوکيدار وو، هغه د هغه تُحفو د وصولولو او د تقسيمولو مشر وو چې کومې مالِک خُدائ ته پېش کېدلې.', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles031_verse_014.mp3', NULL, 1761760676, 1761760676),
(11098, '2 Chronicles 31:15', '2 Chronicles', 31, 15, '&nbsp;په هغه نورو ښارونو کښې چې چرته اِمامان اوسېدل، په دې کار کښې په وفادارۍ سره دې ليويانو د هغۀ مدد کولو: عدن، مينامين، يشوَع، سمعياه، امرياه او سکانياه. هغوئ په خپلو ليويانو باندې خوراک په وړو او غټو يو شان تقسيمولو هم هغه شان چې څنګه د هغوئ ذمه وارى وه،', NULL, '&nbsp;په هغه نورو ښارونو کښې چې چرته اِمامان اوسېدل، په دې کار کښې په وفادارۍ سره دې ليويانو د هغۀ مدد کولو: عدن، مينامين، يشوَع، سمعياه، امرياه او سکانياه. هغوئ په خپلو ليويانو باندې خوراک په وړو او غټو يو شان تقسيمولو هم هغه شان چې څنګه د هغوئ ذمه وارى وه،', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles031_verse_015.mp3', NULL, 1761760676, 1761760676),
(11099, '2 Chronicles 31:16', '2 Chronicles', 31, 16, '&nbsp;خو دا تقسيم د ډلو په مطابق نۀ وو. هغوئ هغه ټولو سړو له يوه برخه ورکوله چې د هغوئ عُمر درې کاله يا د دې نه زيات وو د کومو چې د خپلو عُهدو په مطابق د مالِک خُدائ په کور کښې د هرې ورځې ذمه وارۍ لرلې.', NULL, '&nbsp;خو دا تقسيم د ډلو په مطابق نۀ وو. هغوئ هغه ټولو سړو له يوه برخه ورکوله چې د هغوئ عُمر درې کاله يا د دې نه زيات وو د کومو چې د خپلو عُهدو په مطابق د مالِک خُدائ په کور کښې د هرې ورځې ذمه وارۍ لرلې.', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles031_verse_016.mp3', NULL, 1761760676, 1761760676),
(11100, '2 Chronicles 31:17', '2 Chronicles', 31, 17, '&nbsp;اِمامانو ته د ډلو په مطابق ذمه وارۍ حواله شوې وې او هغه ليويانو ته د کار د ډلو په مطابق ذمه وارۍ حواله شوې وې چې د هغوئ عُمر شل کاله يا د دې نه زيات وو.', NULL, '&nbsp;اِمامانو ته د ډلو په مطابق ذمه وارۍ حواله شوې وې او هغه ليويانو ته د کار د ډلو په مطابق ذمه وارۍ حواله شوې وې چې د هغوئ عُمر شل کاله يا د دې نه زيات وو.', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles031_verse_017.mp3', NULL, 1761760676, 1761760676),
(11101, '2 Chronicles 31:18', '2 Chronicles', 31, 18, '&nbsp;د خپلو ښځو، بچو او خپلو نورو کشرانو سره د هغوئ ټولو نومونه ليکلے شوى وُو، ځکه چې هغوئ ته وئيلى شوى وُو چې هغوئ دې د خپلو مقدسو ذمه وارو ادا کولو دپاره هر وخت تيار اوسيږى.', NULL, '&nbsp;د خپلو ښځو، بچو او خپلو نورو کشرانو سره د هغوئ ټولو نومونه ليکلے شوى وُو، ځکه چې هغوئ ته وئيلى شوى وُو چې هغوئ دې د خپلو مقدسو ذمه وارو ادا کولو دپاره هر وخت تيار اوسيږى.', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles031_verse_018.mp3', NULL, 1761760676, 1761760676),
(11102, '2 Chronicles 31:19', '2 Chronicles', 31, 19, '&nbsp;کوم اِمامان چې په هغه ښارونو کښې اوسېدل چې د هارون اولاد ته حواله شوى وُو، يا چې د څرن په هغه زمکو کښې اوسېدل چې د دې ښارونو وې، نو هلته يو څو ذمه وار سړى داسې وُو چې هغوئ به د اِمامانو په کورَنو کښې په ټولو ناريناؤ باندې خوراک تقسيمولو او په هغه هر چا باندې يې هم خوراک تقسيمولو چې د چا نومونه د ليويانو په ډلو کښې ليکلے شوى وُو.', NULL, '&nbsp;کوم اِمامان چې په هغه ښارونو کښې اوسېدل چې د هارون اولاد ته حواله شوى وُو، يا چې د څرن په هغه زمکو کښې اوسېدل چې د دې ښارونو وې، نو هلته يو څو ذمه وار سړى داسې وُو چې هغوئ به د اِمامانو په کورَنو کښې په ټولو ناريناؤ باندې خوراک تقسيمولو او په هغه هر چا باندې يې هم خوراک تقسيمولو چې د چا نومونه د ليويانو په ډلو کښې ليکلے شوى وُو.', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles031_verse_019.mp3', NULL, 1761760676, 1761760676),
(11103, '2 Chronicles 31:20', '2 Chronicles', 31, 20, '&nbsp;په ټوله يهوداه کښې، حزقياه بادشاه هغه څۀ کول چې څۀ صحيح وُو او چې په څۀ باندې مالِک خُدائ د هغۀ خُدائ پاک رضا کېدو.', NULL, '&nbsp;په ټوله يهوداه کښې، حزقياه بادشاه هغه څۀ کول چې څۀ صحيح وُو او چې په څۀ باندې مالِک خُدائ د هغۀ خُدائ پاک رضا کېدو.', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles031_verse_020.mp3', NULL, 1761760676, 1761760676),
(11104, '2 Chronicles 31:21', '2 Chronicles', 31, 21, '&nbsp;هغۀ د مالِک خُدائ د کور دپاره او د شريعت منلو دپاره چې هر څۀ هم کړى وُو، دا يې د زړۀ د اخلاصه کړى وُو او د خُدائ پاک طلبګار وو نو په دې وجه هغه کامياب وو.', NULL, '&nbsp;هغۀ د مالِک خُدائ د کور دپاره او د شريعت منلو دپاره چې هر څۀ هم کړى وُو، دا يې د زړۀ د اخلاصه کړى وُو او د خُدائ پاک طلبګار وو نو په دې وجه هغه کامياب وو.', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles031_verse_021.mp3', NULL, 1761760676, 1761760676),
(11105, '2 Chronicles 32:1', '2 Chronicles', 32, 1, '&nbsp;د دې واقعو نه پس، چې په کومو کښې حزقياه بادشاه په وفادارۍ سره د مالِک خُدائ خِدمت کړے وو، د اسور بادشاه سينحرب په يهوداه حمله وکړه. هغۀ د پَخو دېوالونو ښارونه محاصره کړل او خپل لښکر له يې حُکم ورکړو چې دېوالونه راوغورزوى.', NULL, '&nbsp;د دې واقعو نه پس، چې په کومو کښې حزقياه بادشاه په وفادارۍ سره د مالِک خُدائ خِدمت کړے وو، د اسور بادشاه سينحرب په يهوداه حمله وکړه. هغۀ د پَخو دېوالونو ښارونه محاصره کړل او خپل لښکر له يې حُکم ورکړو چې دېوالونه راوغورزوى.', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles032_verse_001.mp3', NULL, 1761760676, 1761760676),
(11106, '2 Chronicles 32:2', '2 Chronicles', 32, 2, '&nbsp;کله چې حزقياه ته پته ولګېده چې سينحرب په يروشلم د حملې کولو اراده لرى،', NULL, '&nbsp;کله چې حزقياه ته پته ولګېده چې سينحرب په يروشلم د حملې کولو اراده لرى،', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles032_verse_002.mp3', NULL, 1761760676, 1761760676),
(11107, '2 Chronicles 32:5', '2 Chronicles', 32, 5, '&nbsp;بادشاه د ښار دِفاع داسې مضبوطه کړه چې د دې دېوال يې مرمت کړل، په دې باندې يې برجونه جوړ کړل او بهرنى دېوال يې ورله جوړ کړو. د دې نه علاوه، هغۀ د دِفاع هغه ځايونه هم مرمت کړل چې په هغه زمکه باندې جوړ وُو چې د يروشلم د زړې برخې نمرخاتۀ طرف ته ډک کړے شوى وُو. هغۀ ډېره زياته وسله او ډالونه جوړ کړل.', NULL, '&nbsp;بادشاه د ښار دِفاع داسې مضبوطه کړه چې د دې دېوال يې مرمت کړل، په دې باندې يې برجونه جوړ کړل او بهرنى دېوال يې ورله جوړ کړو. د دې نه علاوه، هغۀ د دِفاع هغه ځايونه هم مرمت کړل چې په هغه زمکه باندې جوړ وُو چې د يروشلم د زړې برخې نمرخاتۀ طرف ته ډک کړے شوى وُو. هغۀ ډېره زياته وسله او ډالونه جوړ کړل.', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles032_verse_005.mp3', NULL, 1761760676, 1761760676),
(11108, '2 Chronicles 32:6', '2 Chronicles', 32, 6, '&nbsp;هغۀ په خلقو باندې فوجى آفسران مقرر کړل او هغوئ له يې حُکم ورکړو چې د ښار د دروازې سره په کولاو ځائ کښې راغونډ شئ. هغۀ ورته ووئيل،', NULL, '&nbsp;هغۀ په خلقو باندې فوجى آفسران مقرر کړل او هغوئ له يې حُکم ورکړو چې د ښار د دروازې سره په کولاو ځائ کښې راغونډ شئ. هغۀ ورته ووئيل،', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles032_verse_006.mp3', NULL, 1761760676, 1761760676),
(11109, '2 Chronicles 32:7', '2 Chronicles', 32, 7, '&nbsp;”تکړه شئ او حوصله مضبوطه کړئ او د اسور بادشاه نه او د هغه لښکر نه مۀ يرېږئ چې هغۀ راروان کړے دے. کوم ذات چې زمونږ مل دے نو هغه د هغۀ نه زيات طاقتور دے.', NULL, '&nbsp;”تکړه شئ او حوصله مضبوطه کړئ او د اسور بادشاه نه او د هغه لښکر نه مۀ يرېږئ چې هغۀ راروان کړے دے. کوم ذات چې زمونږ مل دے نو هغه د هغۀ نه زيات طاقتور دے.', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles032_verse_007.mp3', NULL, 1761760676, 1761760676),
(11110, '2 Chronicles 32:8', '2 Chronicles', 32, 8, '&nbsp;د هغۀ سره انسانى طاقت دے، خو مونږ سره د مالِک خُدائ زمونږ خُدائ پاک شته چې زمونږ مدد وکړى او زمونږ جنګونه وکړى.“ د خلقو د خپل بادشاه په دې خبره باندې حوصله مضبوطه شوه.', NULL, '&nbsp;د هغۀ سره انسانى طاقت دے، خو مونږ سره د مالِک خُدائ زمونږ خُدائ پاک شته چې زمونږ مدد وکړى او زمونږ جنګونه وکړى.“ د خلقو د خپل بادشاه په دې خبره باندې حوصله مضبوطه شوه.', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles032_verse_008.mp3', NULL, 1761760676, 1761760676),
(11111, '2 Chronicles 32:9', '2 Chronicles', 32, 9, '&nbsp;څۀ موده وروستو، کله چې سينحرب او د هغۀ لښکر تر اوسه پورې په لکيس کښې وو، نو هغۀ حزقياه او د يهوداه هغه خلقو ته چې د هغۀ سره په يروشلم کښې وُو دا پېغام ورولېږلو،', NULL, '&nbsp;څۀ موده وروستو، کله چې سينحرب او د هغۀ لښکر تر اوسه پورې په لکيس کښې وو، نو هغۀ حزقياه او د يهوداه هغه خلقو ته چې د هغۀ سره په يروشلم کښې وُو دا پېغام ورولېږلو،', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles032_verse_009.mp3', NULL, 1761760676, 1761760676),
(11112, '2 Chronicles 32:10', '2 Chronicles', 32, 10, '&nbsp;”زۀ د اسور بادشاه سينحرب دا وايم چې ستاسو په زړۀ کښې څۀ دى چې تاسو به د يروشلم محاصرې ته ټينګ شئ؟', NULL, '&nbsp;”زۀ د اسور بادشاه سينحرب دا وايم چې ستاسو په زړۀ کښې څۀ دى چې تاسو به د يروشلم محاصرې ته ټينګ شئ؟', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles032_verse_010.mp3', NULL, 1761760676, 1761760676),
(11113, '2 Chronicles 32:11', '2 Chronicles', 32, 11, '&nbsp;حزقياه تاسو ته وائى چې مالِک خُدائ ستاسو خُدائ پاک به تاسو زمونږ د طاقت نه بچ کړى، خو حزقياه تاسو دوکه کوى او دې ته به مو جوړوى چې د لوږې او تندې نه مړۀ شئ.', NULL, '&nbsp;حزقياه تاسو ته وائى چې مالِک خُدائ ستاسو خُدائ پاک به تاسو زمونږ د طاقت نه بچ کړى، خو حزقياه تاسو دوکه کوى او دې ته به مو جوړوى چې د لوږې او تندې نه مړۀ شئ.', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles032_verse_011.mp3', NULL, 1761760676, 1761760676),
(11114, '2 Chronicles 32:12', '2 Chronicles', 32, 12, '&nbsp;دا هغه کس دے چا چې د مالِک خُدائ علاقائى عبادتخانې او قربان‌ګاه تباه کړى دى او بيا يې د يهوداه او يروشلم خلقو ته ووئيل چې صِرف په يوه قربان‌ګاه باندې عبادت وکړئ او خوشبويۍ سوزوئ.', NULL, '&nbsp;دا هغه کس دے چا چې د مالِک خُدائ علاقائى عبادتخانې او قربان‌ګاه تباه کړى دى او بيا يې د يهوداه او يروشلم خلقو ته ووئيل چې صِرف په يوه قربان‌ګاه باندې عبادت وکړئ او خوشبويۍ سوزوئ.', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles032_verse_012.mp3', NULL, 1761760676, 1761760676),
(11115, '2 Chronicles 32:13', '2 Chronicles', 32, 13, '&nbsp;تاسو ته پته نشته څۀ چې ما او زما پلار نيکۀ د نورو قومونو په خلقو باندې څۀ کړى دى؟ د بل يو قوم معبودانو خپل خلق د اسور بادشاه نه بچ کړى دى څۀ؟', NULL, '&nbsp;تاسو ته پته نشته څۀ چې ما او زما پلار نيکۀ د نورو قومونو په خلقو باندې څۀ کړى دى؟ د بل يو قوم معبودانو خپل خلق د اسور بادشاه نه بچ کړى دى څۀ؟', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles032_verse_013.mp3', NULL, 1761760676, 1761760676),
(11116, '2 Chronicles 32:14', '2 Chronicles', 32, 14, '&nbsp;د هغه ټولو مُلکونو يو خُدائ کله هم خپل مُلک زمونږ نه بچ کړے دے څۀ؟ نو بيا تاسو ولې وايئ چې ستاسو خُدائ تاسو بچ کولے شى؟', NULL, '&nbsp;د هغه ټولو مُلکونو يو خُدائ کله هم خپل مُلک زمونږ نه بچ کړے دے څۀ؟ نو بيا تاسو ولې وايئ چې ستاسو خُدائ تاسو بچ کولے شى؟', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles032_verse_014.mp3', NULL, 1761760676, 1761760676),
(11117, '2 Chronicles 32:15', '2 Chronicles', 32, 15, '&nbsp;نو حزقياه دې ته مۀ پرېږدئ چې دوکه مو کړى يا چې په داسې غلطه لار مو بوځى. په هغۀ باندې اعتبار مۀ کوئ. د يو قوم خُدائ هم خپل خلق د اسور د يو بادشاه نه نۀ دى بچ کړى. نو بې‌شکه ستاسو دا خُدائ هم تاسو نۀ شى بچ کولے.“', NULL, '&nbsp;نو حزقياه دې ته مۀ پرېږدئ چې دوکه مو کړى يا چې په داسې غلطه لار مو بوځى. په هغۀ باندې اعتبار مۀ کوئ. د يو قوم خُدائ هم خپل خلق د اسور د يو بادشاه نه نۀ دى بچ کړى. نو بې‌شکه ستاسو دا خُدائ هم تاسو نۀ شى بچ کولے.“', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles032_verse_015.mp3', NULL, 1761760676, 1761760676),
(11118, '2 Chronicles 32:16', '2 Chronicles', 32, 16, '&nbsp;د اسور آفسرانو د مالِک خُدائ، خُدائ پاک او د مالِک خُدائ خِدمت کوونکى حزقياه په حقله د دې نه هم زيات بدرد ووئيل.', NULL, '&nbsp;د اسور آفسرانو د مالِک خُدائ، خُدائ پاک او د مالِک خُدائ خِدمت کوونکى حزقياه په حقله د دې نه هم زيات بدرد ووئيل.', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles032_verse_016.mp3', NULL, 1761760676, 1761760676),
(11119, '2 Chronicles 32:17', '2 Chronicles', 32, 17, '&nbsp;بادشاه چې کوم خط ليکلے وو دې خط په مالِک خُدائ د بنى اِسرائيلو په خُدائ پاک پورې ټوقې وکړې. په دې کښې ليکلى وُو، ”د قومونو خُدايانو خپل خلق زما د طاقت نه نۀ دى بچ کړى او نۀ به د حزقياه خُدائ خپل خلق زما نه بچ کړى.“', NULL, '&nbsp;بادشاه چې کوم خط ليکلے وو دې خط په مالِک خُدائ د بنى اِسرائيلو په خُدائ پاک پورې ټوقې وکړې. په دې کښې ليکلى وُو، ”د قومونو خُدايانو خپل خلق زما د طاقت نه نۀ دى بچ کړى او نۀ به د حزقياه خُدائ خپل خلق زما نه بچ کړى.“', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles032_verse_017.mp3', NULL, 1761760676, 1761760676),
(11120, '2 Chronicles 32:18', '2 Chronicles', 32, 18, '&nbsp;آفسرانو په عبرانۍ کښې د دې دپاره چغې ووهلې چې د يروشلم هغه خلق ويروى او بې‌حوصلې يې کړى کوم چې د ښار په دېوال باندې وُو، نو داسې د ښار قبضه کول به آسان شى.', NULL, '&nbsp;آفسرانو په عبرانۍ کښې د دې دپاره چغې ووهلې چې د يروشلم هغه خلق ويروى او بې‌حوصلې يې کړى کوم چې د ښار په دېوال باندې وُو، نو داسې د ښار قبضه کول به آسان شى.', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles032_verse_018.mp3', NULL, 1761760676, 1761760676),
(11121, '2 Chronicles 32:19', '2 Chronicles', 32, 19, '&nbsp;هغوئ د يروشلم د خُدائ پاک په حقله هم هغه شان خبرې وکړې چې د نورو خلقو د خُدايانو په حقله يې کولې، د هغه بُتانو چې د انسان لاسونو جوړ کړى وُو.', NULL, '&nbsp;هغوئ د يروشلم د خُدائ پاک په حقله هم هغه شان خبرې وکړې چې د نورو خلقو د خُدايانو په حقله يې کولې، د هغه بُتانو چې د انسان لاسونو جوړ کړى وُو.', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles032_verse_019.mp3', NULL, 1761760676, 1761760676),
(11122, '2 Chronicles 32:20', '2 Chronicles', 32, 20, '&nbsp;حزقياه بادشاه او د آموص زوئ يشعياه پېغمبر خُدائ پاک ته سوال وکړو او هغۀ ته يې د مدد دپاره فرياد وکړو.', NULL, '&nbsp;حزقياه بادشاه او د آموص زوئ يشعياه پېغمبر خُدائ پاک ته سوال وکړو او هغۀ ته يې د مدد دپاره فرياد وکړو.', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles032_verse_020.mp3', NULL, 1761760676, 1761760676),
(11123, '2 Chronicles 32:21', '2 Chronicles', 32, 21, '&nbsp;مالِک خُدائ يوه فرښته راولېږله چې هغې د اسور د لښکر فوجيان او آفسران ووژل. نو داسې بادشاه اسور ته واپس شرمېدلے لاړو. يوه ورځ چې کله هغه د خپل خُدائ په عبادتخانه کښې وو، نو د هغۀ يو څو زامنو هغه په تُورو باندې ووهلو او مړ يې کړو.', NULL, '&nbsp;مالِک خُدائ يوه فرښته راولېږله چې هغې د اسور د لښکر فوجيان او آفسران ووژل. نو داسې بادشاه اسور ته واپس شرمېدلے لاړو. يوه ورځ چې کله هغه د خپل خُدائ په عبادتخانه کښې وو، نو د هغۀ يو څو زامنو هغه په تُورو باندې ووهلو او مړ يې کړو.', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles032_verse_021.mp3', NULL, 1761760676, 1761760676),
(11124, '2 Chronicles 32:22', '2 Chronicles', 32, 22, '&nbsp;نو داسې مالِک خُدائ حزقياه بادشاه او د يروشلم خلق د اسور بادشاه سينحرب د زور نه او د هغوئ د نورو دشمنانو نه بچ کړل. او هغوئ د هر يو قوم سره په امن کښې ژوند تېرولو.', NULL, '&nbsp;نو داسې مالِک خُدائ حزقياه بادشاه او د يروشلم خلق د اسور بادشاه سينحرب د زور نه او د هغوئ د نورو دشمنانو نه بچ کړل. او هغوئ د هر يو قوم سره په امن کښې ژوند تېرولو.', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles032_verse_022.mp3', NULL, 1761760676, 1761760676),
(11125, '2 Chronicles 32:23', '2 Chronicles', 32, 23, '&nbsp;ډېر خلق يروشلم ته راتلل، چې مالِک خُدائ له يې نذرانې او حزقياه له يې تُحفې راوړې، نو د هغه وخت نه حزقياه د ټولو قومونو په نظر کښې عزتمند وو.', NULL, '&nbsp;ډېر خلق يروشلم ته راتلل، چې مالِک خُدائ له يې نذرانې او حزقياه له يې تُحفې راوړې، نو د هغه وخت نه حزقياه د ټولو قومونو په نظر کښې عزتمند وو.', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles032_verse_023.mp3', NULL, 1761760676, 1761760676),
(11126, '2 Chronicles 32:24', '2 Chronicles', 32, 24, '&nbsp;تقريباً هم هغه وخت حزقياه بادشاه بيمار شو او مرګ ته نزدې وو. هغۀ دُعا وکړه او مالِک خُدائ ورته يوه نښه وښودله چې هغه به روغ شى.', NULL, '&nbsp;تقريباً هم هغه وخت حزقياه بادشاه بيمار شو او مرګ ته نزدې وو. هغۀ دُعا وکړه او مالِک خُدائ ورته يوه نښه وښودله چې هغه به روغ شى.', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles032_verse_024.mp3', NULL, 1761760676, 1761760676),
(11127, '2 Chronicles 32:25', '2 Chronicles', 32, 25, '&nbsp;خو حزقياه ډېر زيات مغروره وو او د هغه څۀ شکريه يې ادا نۀ کړه چې مالِک خُدائ د هغۀ دپاره کړى وُو، نو په دې وجه د مالِک خُدائ غصه په هغۀ، په يهوداه او يروشلم نازله شوه.', NULL, '&nbsp;خو حزقياه ډېر زيات مغروره وو او د هغه څۀ شکريه يې ادا نۀ کړه چې مالِک خُدائ د هغۀ دپاره کړى وُو، نو په دې وجه د مالِک خُدائ غصه په هغۀ، په يهوداه او يروشلم نازله شوه.', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles032_verse_025.mp3', NULL, 1761760676, 1761760676),
(11128, '2 Chronicles 32:26', '2 Chronicles', 32, 26, '&nbsp;خو په آخر کښې حزقياه او د يروشلم خلقو خپل ځانونه عاجز کړل، نو ځکه مالِک خُدائ د حزقياه په ژوند کښې خلقو له سزا ورنۀ کړه.', NULL, '&nbsp;خو په آخر کښې حزقياه او د يروشلم خلقو خپل ځانونه عاجز کړل، نو ځکه مالِک خُدائ د حزقياه په ژوند کښې خلقو له سزا ورنۀ کړه.', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles032_verse_026.mp3', NULL, 1761760676, 1761760676),
(11129, '2 Chronicles 32:27', '2 Chronicles', 32, 27, '&nbsp;حزقياه بادشاه ډېر مالداره شو او هر چا به د هغۀ عزت کولو. هغۀ د خپلو سرو زرو، سپينو زرو، قيمتى کاڼو، مصالحو، ډالونو او د نورو قيمتى څيزونو دپاره ګودامونه جوړ کړى وُو.', NULL, '&nbsp;حزقياه بادشاه ډېر مالداره شو او هر چا به د هغۀ عزت کولو. هغۀ د خپلو سرو زرو، سپينو زرو، قيمتى کاڼو، مصالحو، ډالونو او د نورو قيمتى څيزونو دپاره ګودامونه جوړ کړى وُو.', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles032_verse_027.mp3', NULL, 1761760676, 1761760676),
(11130, '2 Chronicles 32:28', '2 Chronicles', 32, 28, '&nbsp;د دې نه علاوه، هغۀ د خپلې غلې، ميو، زيتُونو تېلو دپاره ګودامونه، د څاروو دپاره ديرې او د ګډو دپاره شپولونه جوړ کړى وُو.', NULL, '&nbsp;د دې نه علاوه، هغۀ د خپلې غلې، ميو، زيتُونو تېلو دپاره ګودامونه، د څاروو دپاره ديرې او د ګډو دپاره شپولونه جوړ کړى وُو.', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles032_verse_028.mp3', NULL, 1761760676, 1761760676),
(11131, '2 Chronicles 32:29', '2 Chronicles', 32, 29, '&nbsp;د دې هر څۀ نه علاوه، خُدائ پاک هغۀ له ګډې او څاروى ورکړى وُو او نور دولت يې دومره ډېر ورکړے وو چې هغۀ ډېر ښارونه جوړ کړل.', NULL, '&nbsp;د دې هر څۀ نه علاوه، خُدائ پاک هغۀ له ګډې او څاروى ورکړى وُو او نور دولت يې دومره ډېر ورکړے وو چې هغۀ ډېر ښارونه جوړ کړل.', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles032_verse_029.mp3', NULL, 1761760676, 1761760676),
(11132, '2 Chronicles 32:30', '2 Chronicles', 32, 30, '&nbsp;دا حزقياه بادشاه وو چې هغۀ د جيحون د چينو خولې بندې کړې او اوبو له يې يوه لار جوړه کړه چې اوبۀ د يو سورنګ په ذريعه د يروشلم په دېوالونو کښې دننه يو ځائ ته بهيږى. حزقياه چې هر کار کولو نو په هغې کښې کاميابېدو،', NULL, '&nbsp;دا حزقياه بادشاه وو چې هغۀ د جيحون د چينو خولې بندې کړې او اوبو له يې يوه لار جوړه کړه چې اوبۀ د يو سورنګ په ذريعه د يروشلم په دېوالونو کښې دننه يو ځائ ته بهيږى. حزقياه چې هر کار کولو نو په هغې کښې کاميابېدو،', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles032_verse_030.mp3', NULL, 1761760676, 1761760676),
(11133, '2 Chronicles 32:31', '2 Chronicles', 32, 31, '&nbsp;او چې کله د بابل سفير د هغه عجيبه واقعې د معلومولو دپاره راغلو چې کومه په هغه مُلک کښې شوې وه، نو خُدائ پاک حزقياه د دې دپاره يواځې پرېښودو چې د هغۀ نېت معلوم کړى.', NULL, '&nbsp;او چې کله د بابل سفير د هغه عجيبه واقعې د معلومولو دپاره راغلو چې کومه په هغه مُلک کښې شوې وه، نو خُدائ پاک حزقياه د دې دپاره يواځې پرېښودو چې د هغۀ نېت معلوم کړى.', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles032_verse_031.mp3', NULL, 1761760676, 1761760676),
(11134, '2 Chronicles 32:32', '2 Chronicles', 32, 32, '&nbsp;حزقياه بادشاه چې نور هر څۀ کړى وُو سره د هغۀ د نېکو عملونو، دا د آموص زوئ يشعياه پېغمبر په رويا کښې ليکلے شوى دى چې هغه د يهوداه او اِسرائيل د بادشاهانو د تاريخ يوه حِصه ده.', NULL, '&nbsp;حزقياه بادشاه چې نور هر څۀ کړى وُو سره د هغۀ د نېکو عملونو، دا د آموص زوئ يشعياه پېغمبر په رويا کښې ليکلے شوى دى چې هغه د يهوداه او اِسرائيل د بادشاهانو د تاريخ يوه حِصه ده.', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles032_verse_032.mp3', NULL, 1761760676, 1761760676),
(11135, '2 Chronicles 32:33', '2 Chronicles', 32, 33, '&nbsp;نو حزقياه مړ شو او هغه د شاهى اديرې په پاسنۍ حِصه کښې ښخ شو. د هغۀ په مرګ باندې د يهوداه او يروشلم ټولو خلقو هغۀ له يو لوئ عزت ورکړو. د هغۀ زوئ منسى د هغۀ نه پس بادشاه جوړ شو.', NULL, '&nbsp;نو حزقياه مړ شو او هغه د شاهى اديرې په پاسنۍ حِصه کښې ښخ شو. د هغۀ په مرګ باندې د يهوداه او يروشلم ټولو خلقو هغۀ له يو لوئ عزت ورکړو. د هغۀ زوئ منسى د هغۀ نه پس بادشاه جوړ شو.', 'NT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761760676, 1761760676),
(11136, '2 Chronicles 33:1', '2 Chronicles', 33, 1, '&nbsp;منسى دولس کلن وو چې هغه د يهوداه بادشاه جوړ شو او په يروشلم يې پينځۀ پنځوس کاله بادشاهى وکړه.', NULL, '&nbsp;منسى دولس کلن وو چې هغه د يهوداه بادشاه جوړ شو او په يروشلم يې پينځۀ پنځوس کاله بادشاهى وکړه.', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles033_verse_001.mp3', NULL, 1761760676, 1761760676),
(11137, '2 Chronicles 33:2', '2 Chronicles', 33, 2, '&nbsp;منسى د هغه قومونو هغه حرام کارونه کول کوم چې د مالِک خُدائ په نظر کښې بد وُو. دا هم هغه خلق وُو کوم چې مالِک خُدائ په هغه وخت کښې د هغه مُلک نه ويستلى وُو چې کله د هغۀ خلق مخ په وړاندې تلل.', NULL, '&nbsp;منسى د هغه قومونو هغه حرام کارونه کول کوم چې د مالِک خُدائ په نظر کښې بد وُو. دا هم هغه خلق وُو کوم چې مالِک خُدائ په هغه وخت کښې د هغه مُلک نه ويستلى وُو چې کله د هغۀ خلق مخ په وړاندې تلل.', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles033_verse_002.mp3', NULL, 1761760676, 1761760676),
(11138, '2 Chronicles 33:3', '2 Chronicles', 33, 3, '&nbsp;هغۀ علاقائى عبادتخانې بيا جوړې کړې چې کوم د هغۀ پلار حزقياه تباه کړى وُو. هغۀ د بعل د عبادت دپاره قربان‌ګاه جوړې کړې، د اشيرې بُت نښې يې جوړې کړې او د ستورو عبادت يې وکړو.', NULL, '&nbsp;هغۀ علاقائى عبادتخانې بيا جوړې کړې چې کوم د هغۀ پلار حزقياه تباه کړى وُو. هغۀ د بعل د عبادت دپاره قربان‌ګاه جوړې کړې، د اشيرې بُت نښې يې جوړې کړې او د ستورو عبادت يې وکړو.', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles033_verse_003.mp3', NULL, 1761760676, 1761760676),
(11139, '2 Chronicles 33:4', '2 Chronicles', 33, 4, '&nbsp;هغۀ د مالِک خُدائ په کور کښې د غېرو قومونو قربان‌ګاه جوړې کړې، د کوم ځائ په حقله چې مالِک خُدائ فرمائيلى وُو چې، ”زما نوم به په يروشلم کښې د همېشه دپاره پاتې شى.“', NULL, '&nbsp;هغۀ د مالِک خُدائ په کور کښې د غېرو قومونو قربان‌ګاه جوړې کړې، د کوم ځائ په حقله چې مالِک خُدائ فرمائيلى وُو چې، ”زما نوم به په يروشلم کښې د همېشه دپاره پاتې شى.“', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles033_verse_004.mp3', NULL, 1761760676, 1761760676),
(11140, '2 Chronicles 33:5', '2 Chronicles', 33, 5, '&nbsp;د مالِک خُدائ د کور په دوو دربارونو کښې هغۀ د ستورو د عبادت دپاره قربان‌ګاه جوړې کړې.', NULL, '&nbsp;د مالِک خُدائ د کور په دوو دربارونو کښې هغۀ د ستورو د عبادت دپاره قربان‌ګاه جوړې کړې.', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles033_verse_005.mp3', NULL, 1761760676, 1761760676),
(11141, '2 Chronicles 33:6', '2 Chronicles', 33, 6, '&nbsp;هغۀ د هنوم په وادۍ کښې خپل زامن د سوزېدونکې نذرانو په توګه قربانى کړل. هغۀ د غېبو کارونو او جادو نه کار اخستلو او قسمت ښودونکو او د فالګرو سره يې مشورې وکړې. هغۀ د مالِک خُدائ خِلاف لويه ګناه وکړه او د هغۀ غصه يې راوپاروله.', NULL, '&nbsp;هغۀ د هنوم په وادۍ کښې خپل زامن د سوزېدونکې نذرانو په توګه قربانى کړل. هغۀ د غېبو کارونو او جادو نه کار اخستلو او قسمت ښودونکو او د فالګرو سره يې مشورې وکړې. هغۀ د مالِک خُدائ خِلاف لويه ګناه وکړه او د هغۀ غصه يې راوپاروله.', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles033_verse_006.mp3', NULL, 1761760676, 1761760676),
(11142, '2 Chronicles 33:7', '2 Chronicles', 33, 7, '&nbsp;هغۀ چې کوم بُت جوړ کړے وو هغه يې واخستلو او د خُدائ پاک په کور کښې يې ودرولو چې د کوم په حقله خُدائ پاک داؤد او د هغۀ زوئ سليمان ته فرمائيلى وُو، ”په دې کور کښې او په يروشلم کښې به زۀ خپل نوم د همېشه دپاره وساتم کوم ښار چې ما د بنى اِسرائيلو د ټولو قبيلو نه خوښ کړے دے.', NULL, '&nbsp;هغۀ چې کوم بُت جوړ کړے وو هغه يې واخستلو او د خُدائ پاک په کور کښې يې ودرولو چې د کوم په حقله خُدائ پاک داؤد او د هغۀ زوئ سليمان ته فرمائيلى وُو، ”په دې کور کښې او په يروشلم کښې به زۀ خپل نوم د همېشه دپاره وساتم کوم ښار چې ما د بنى اِسرائيلو د ټولو قبيلو نه خوښ کړے دے.', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles033_verse_007.mp3', NULL, 1761760676, 1761760676),
(11143, '2 Chronicles 33:8', '2 Chronicles', 33, 8, '&nbsp;کۀ بنى اِسرائيليان زما ټول حُکمونه منى او هغه ټول قانون پوره کوى چې زما خِدمت کوونکى موسىٰ هغوئ له ورکړے دے، نو زۀ به هغوئ نۀ پرېږدم چې د هغه مُلک نه وويستلے شى چې کوم ما د هغوئ پلار نيکۀ له ورکړے دے.“', NULL, '&nbsp;کۀ بنى اِسرائيليان زما ټول حُکمونه منى او هغه ټول قانون پوره کوى چې زما خِدمت کوونکى موسىٰ هغوئ له ورکړے دے، نو زۀ به هغوئ نۀ پرېږدم چې د هغه مُلک نه وويستلے شى چې کوم ما د هغوئ پلار نيکۀ له ورکړے دے.“', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles033_verse_008.mp3', NULL, 1761760676, 1761760676),
(11144, '2 Chronicles 33:9', '2 Chronicles', 33, 9, '&nbsp;خو منسى د يهوداه او يروشلم خلق بې‌لارې کړل او هغوئ د هغه قومونو نه هم لوئې ګناهونه وکړل کوم چې مالِک خُدائ تباه کړى وُو کله چې بنى اِسرائيليان مخ په وړاندې تلل.', NULL, '&nbsp;خو منسى د يهوداه او يروشلم خلق بې‌لارې کړل او هغوئ د هغه قومونو نه هم لوئې ګناهونه وکړل کوم چې مالِک خُدائ تباه کړى وُو کله چې بنى اِسرائيليان مخ په وړاندې تلل.', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles033_verse_009.mp3', NULL, 1761760676, 1761760676),
(11145, '2 Chronicles 33:10', '2 Chronicles', 33, 10, '&nbsp;اګر چې مالِک خُدائ منسى او د هغۀ خلقو له خبردارے ورکړو، خو هغوئ به ورته غوږ نۀ نيولو.', NULL, '&nbsp;اګر چې مالِک خُدائ منسى او د هغۀ خلقو له خبردارے ورکړو، خو هغوئ به ورته غوږ نۀ نيولو.', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles033_verse_010.mp3', NULL, 1761760676, 1761760676),
(11146, '2 Chronicles 33:11', '2 Chronicles', 33, 11, '&nbsp;نو مالِک خُدائ د اسور فوجى مشران ولېږل چې په يهوداه باندې حمله وکړى. او هغوئ منسى ونيولو، کُنډې يې ورته واچولې او په زنځيرونو باندې يې وتړلو او بابل ته يې بوتلو.', NULL, '&nbsp;نو مالِک خُدائ د اسور فوجى مشران ولېږل چې په يهوداه باندې حمله وکړى. او هغوئ منسى ونيولو، کُنډې يې ورته واچولې او په زنځيرونو باندې يې وتړلو او بابل ته يې بوتلو.', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles033_verse_011.mp3', NULL, 1761760676, 1761760676),
(11147, '2 Chronicles 33:12', '2 Chronicles', 33, 12, '&nbsp;هغه د خپلو مصيبتونو په وجه عاجز شو او مالِک خُدائ، خُدائ پاک ته راوګرځېدو او هغۀ ته يې د مدد دپاره سوال وکړو.', NULL, '&nbsp;هغه د خپلو مصيبتونو په وجه عاجز شو او مالِک خُدائ، خُدائ پاک ته راوګرځېدو او هغۀ ته يې د مدد دپاره سوال وکړو.', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles033_verse_012.mp3', NULL, 1761760676, 1761760676),
(11148, '2 Chronicles 33:13', '2 Chronicles', 33, 13, '&nbsp;خُدائ پاک د منسى سوال واورېدو او قبول يې کړو او هغه يې ولېږلو چې يروشلم ته واپس لاړ شى او بيا حکومت وکړى. نو منسى ته پته ولګېده چې مالِک خُدائ په رښتيا خُدائ پاک دے.', NULL, '&nbsp;خُدائ پاک د منسى سوال واورېدو او قبول يې کړو او هغه يې ولېږلو چې يروشلم ته واپس لاړ شى او بيا حکومت وکړى. نو منسى ته پته ولګېده چې مالِک خُدائ په رښتيا خُدائ پاک دے.', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles033_verse_013.mp3', NULL, 1761760676, 1761760676),
(11149, '2 Chronicles 33:14', '2 Chronicles', 33, 14, '&nbsp;د دې نه پس، منسى د داؤد ښار د بهرنى دېوال اوچتوالے زيات کړو، د نمرپرېواتۀ په طرف په وادۍ کښې د جيحون د چشمې نه د کبانو دروازې پورې او هم دغه دېوال د عوفل د غر نه هم راتاو وو. هغۀ د يهوداه د پَخو دېوالونو په هر يو ښار کښې يو يو فوجى آفسر مقرر کړو.', NULL, '&nbsp;د دې نه پس، منسى د داؤد ښار د بهرنى دېوال اوچتوالے زيات کړو، د نمرپرېواتۀ په طرف په وادۍ کښې د جيحون د چشمې نه د کبانو دروازې پورې او هم دغه دېوال د عوفل د غر نه هم راتاو وو. هغۀ د يهوداه د پَخو دېوالونو په هر يو ښار کښې يو يو فوجى آفسر مقرر کړو.', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles033_verse_014.mp3', NULL, 1761760676, 1761760676),
(11150, '2 Chronicles 33:15', '2 Chronicles', 33, 15, '&nbsp;هغۀ د مالِک خُدائ د کور نه هغه پردى بُتان او نښې لرې کړې کومې چې هغۀ هلته اېښې وې او هغۀ د غېرو قومونو هغه قربان‌ګاه لرې کړې کومې چې د مالِک خُدائ د کور په غرۀ او په يروشلم کښې په نورو ځايونو کښې وې، هغۀ دا ټول څيزونه د ښار نه بهر يوړل او وې غورزول.', NULL, '&nbsp;هغۀ د مالِک خُدائ د کور نه هغه پردى بُتان او نښې لرې کړې کومې چې هغۀ هلته اېښې وې او هغۀ د غېرو قومونو هغه قربان‌ګاه لرې کړې کومې چې د مالِک خُدائ د کور په غرۀ او په يروشلم کښې په نورو ځايونو کښې وې، هغۀ دا ټول څيزونه د ښار نه بهر يوړل او وې غورزول.', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles033_verse_015.mp3', NULL, 1761760676, 1761760676),
(11151, '2 Chronicles 33:16', '2 Chronicles', 33, 16, '&nbsp;هغۀ هغه قربان‌ګاه هم مرمت کړه چرته چې د مالِک خُدائ عبادت کېدو او چې هغۀ ورباندې د سلامتۍ نذرانې او د شکرانې نذرانې پېش کولې. هغۀ د يهوداه ټولو خلقو له حُکم ورکړو چې د مالِک خُدائ د بنى اِسرائيلو د خُدائ پاک عبادت وکړى.', NULL, '&nbsp;هغۀ هغه قربان‌ګاه هم مرمت کړه چرته چې د مالِک خُدائ عبادت کېدو او چې هغۀ ورباندې د سلامتۍ نذرانې او د شکرانې نذرانې پېش کولې. هغۀ د يهوداه ټولو خلقو له حُکم ورکړو چې د مالِک خُدائ د بنى اِسرائيلو د خُدائ پاک عبادت وکړى.', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles033_verse_016.mp3', NULL, 1761760676, 1761760676),
(11152, '2 Chronicles 33:17', '2 Chronicles', 33, 17, '&nbsp;اګر چې خلقو په علاقائى عبادتخانو کښې هم قربانۍ پېش کولې، خو هغوئ دا صِرف مالِک خُدائ ته پېش کولې.', NULL, '&nbsp;اګر چې خلقو په علاقائى عبادتخانو کښې هم قربانۍ پېش کولې، خو هغوئ دا صِرف مالِک خُدائ ته پېش کولې.', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles033_verse_017.mp3', NULL, 1761760676, 1761760676),
(11153, '2 Chronicles 33:18', '2 Chronicles', 33, 18, '&nbsp;نور هر څۀ چې منسى کړى وُو، هغۀ چې خُدائ پاک ته کوم سوال کړے وو او د پېغمبرانو هغه پېغامونه چې هغوئ د مالِک خُدائ د بنى اِسرائيلو د خُدائ پاک په نوم د هغۀ سره خبرې وکړې، دا هر څۀ د اِسرائيل د بادشاهانو په تاريخ کښې ليکلے شوى دى.', NULL, '&nbsp;نور هر څۀ چې منسى کړى وُو، هغۀ چې خُدائ پاک ته کوم سوال کړے وو او د پېغمبرانو هغه پېغامونه چې هغوئ د مالِک خُدائ د بنى اِسرائيلو د خُدائ پاک په نوم د هغۀ سره خبرې وکړې، دا هر څۀ د اِسرائيل د بادشاهانو په تاريخ کښې ليکلے شوى دى.', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles033_verse_018.mp3', NULL, 1761760676, 1761760676),
(11154, '2 Chronicles 33:19', '2 Chronicles', 33, 19, '&nbsp;د بادشاه دُعا او د خُدائ پاک د دُعا قبلول او د هغۀ د توبې نه مخکښې د هغه ګناهونو حِساب کِتاب چې هغۀ کړى وُو، هغه بد عملونه چې هغۀ کړى وُو، علاقائى عبادتخانې او د اشيرې بُت کومې نښې چې هغۀ جوړې کړې وې او هغه بُتان چې هغۀ يې عبادت کولو، دا هر څۀ د پېغمبرانو په تاريخ کښې ليکلے شوى دى.', NULL, '&nbsp;د بادشاه دُعا او د خُدائ پاک د دُعا قبلول او د هغۀ د توبې نه مخکښې د هغه ګناهونو حِساب کِتاب چې هغۀ کړى وُو، هغه بد عملونه چې هغۀ کړى وُو، علاقائى عبادتخانې او د اشيرې بُت کومې نښې چې هغۀ جوړې کړې وې او هغه بُتان چې هغۀ يې عبادت کولو، دا هر څۀ د پېغمبرانو په تاريخ کښې ليکلے شوى دى.', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles033_verse_019.mp3', NULL, 1761760676, 1761760676),
(11155, '2 Chronicles 33:20', '2 Chronicles', 33, 20, '&nbsp;منسى مړ شو او په محل کښې ښخ شو او د هغۀ زوئ امون د هغۀ نه پس بادشاه جوړ شو.', NULL, '&nbsp;منسى مړ شو او په محل کښې ښخ شو او د هغۀ زوئ امون د هغۀ نه پس بادشاه جوړ شو.', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles033_verse_020.mp3', NULL, 1761760676, 1761760676),
(11156, '2 Chronicles 33:21', '2 Chronicles', 33, 21, '&nbsp;امون دوويشت کلن وو چې هغه د يهوداه بادشاه جوړ شو او هغۀ په يروشلم باندې دوه کاله حکومت وکړو.', NULL, '&nbsp;امون دوويشت کلن وو چې هغه د يهوداه بادشاه جوړ شو او هغۀ په يروشلم باندې دوه کاله حکومت وکړو.', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles033_verse_021.mp3', NULL, 1761760676, 1761760676),
(11157, '2 Chronicles 33:22', '2 Chronicles', 33, 22, '&nbsp;د خپل پلار منسى په شان هغۀ هم د مالِک خُدائ خِلاف ګناه وکړه او چې د هغۀ پلار د کومو بُتانو عبادت کړے وو نو هغۀ يې هم عبادت وکړو.', NULL, '&nbsp;د خپل پلار منسى په شان هغۀ هم د مالِک خُدائ خِلاف ګناه وکړه او چې د هغۀ پلار د کومو بُتانو عبادت کړے وو نو هغۀ يې هم عبادت وکړو.', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles033_verse_022.mp3', NULL, 1761760676, 1761760676),
(11158, '2 Chronicles 33:23', '2 Chronicles', 33, 23, '&nbsp;خو هغه د خپل پلار په شان عاجز نۀ شو او نۀ مالِک خُدائ ته راوګرځېدو، هغه د خپل پلار نه هم زيات ګناهګار شو.', NULL, '&nbsp;خو هغه د خپل پلار په شان عاجز نۀ شو او نۀ مالِک خُدائ ته راوګرځېدو، هغه د خپل پلار نه هم زيات ګناهګار شو.', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles033_verse_023.mp3', NULL, 1761760676, 1761760676),
(11159, '2 Chronicles 33:24', '2 Chronicles', 33, 24, '&nbsp;د امون آفسرانو د هغۀ خِلاف منصوبه جوړه کړه او په محل کښې يې ووژلو.', NULL, '&nbsp;د امون آفسرانو د هغۀ خِلاف منصوبه جوړه کړه او په محل کښې يې ووژلو.', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles033_verse_024.mp3', NULL, 1761760676, 1761760676),
(11160, '2 Chronicles 33:25', '2 Chronicles', 33, 25, '&nbsp;د يهوداه خلقو د امون قاتِلان ووژل او د هغۀ زوئ يوسياه يې بادشاه جوړ کړو.', NULL, '&nbsp;د يهوداه خلقو د امون قاتِلان ووژل او د هغۀ زوئ يوسياه يې بادشاه جوړ کړو.', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles033_verse_025.mp3', NULL, 1761760676, 1761760676),
(11161, '2 Chronicles 34:1', '2 Chronicles', 34, 1, '&nbsp;يوسياه اتۀ کلن وو چې هغه بادشاه جوړ شو او يو دېرش کاله يې په يروشلم بادشاهى وکړه.', NULL, '&nbsp;يوسياه اتۀ کلن وو چې هغه بادشاه جوړ شو او يو دېرش کاله يې په يروشلم بادشاهى وکړه.', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles034_verse_001.mp3', NULL, 1761760676, 1761760676),
(11162, '2 Chronicles 34:2', '2 Chronicles', 34, 2, '&nbsp;هغۀ هم هغه کار کولو چې په څۀ باندې مالِک خُدائ خوشحالېدو، هغه د خپل پلار نيکۀ داؤد په نقش قدم باندې روان وو او هغه د خُدائ پاک د قانون نه اخوا دېخوا نۀ اوړېدو.', NULL, '&nbsp;هغۀ هم هغه کار کولو چې په څۀ باندې مالِک خُدائ خوشحالېدو، هغه د خپل پلار نيکۀ داؤد په نقش قدم باندې روان وو او هغه د خُدائ پاک د قانون نه اخوا دېخوا نۀ اوړېدو.', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles034_verse_002.mp3', NULL, 1761760676, 1761760676),
(11163, '2 Chronicles 34:3', '2 Chronicles', 34, 3, '&nbsp;د يوسياه د بادشاهۍ په اتم کال، چې په کوم وخت کښې هغه لا وړوکے وو، نو هغۀ د خپل پلار نيکۀ داؤد خُدائ پاک عبادت شروع کړو. څلور کاله وروستو هغۀ علاقائى عبادتخانې، د اشيرې بُت نښې او د نورو ټولو بُتانو تباه کول شروع کړل.', NULL, '&nbsp;د يوسياه د بادشاهۍ په اتم کال، چې په کوم وخت کښې هغه لا وړوکے وو، نو هغۀ د خپل پلار نيکۀ داؤد خُدائ پاک عبادت شروع کړو. څلور کاله وروستو هغۀ علاقائى عبادتخانې، د اشيرې بُت نښې او د نورو ټولو بُتانو تباه کول شروع کړل.', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles034_verse_003.mp3', NULL, 1761760676, 1761760676),
(11164, '2 Chronicles 34:4', '2 Chronicles', 34, 4, '&nbsp;د هغۀ د ښودنې لاندې هغه قربان‌ګاه ټوټې ټوټې کړے شوه چرته چې د بعل عبادت کېدو او د دې سره نزدې د خوشبويۍ قربان‌ګاه راوغورزولے شوې. هغوئ د اشيرې بُتانو او د نورو ټولو بُتانو نه خاورې جوړې کړې او هغه خاورې يې د هغه خلقو په قبرونو باندې وشيندلې چا چې دې ته قربانۍ پېش کړې وې.', NULL, '&nbsp;د هغۀ د ښودنې لاندې هغه قربان‌ګاه ټوټې ټوټې کړے شوه چرته چې د بعل عبادت کېدو او د دې سره نزدې د خوشبويۍ قربان‌ګاه راوغورزولے شوې. هغوئ د اشيرې بُتانو او د نورو ټولو بُتانو نه خاورې جوړې کړې او هغه خاورې يې د هغه خلقو په قبرونو باندې وشيندلې چا چې دې ته قربانۍ پېش کړې وې.', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles034_verse_004.mp3', NULL, 1761760676, 1761760676),
(11165, '2 Chronicles 34:5', '2 Chronicles', 34, 5, '&nbsp;هغۀ د بُت پرستو اِمامانو هډُوکى په هغه قربان‌ګاه باندې وسوزول چرته چې هغوئ عبادت کړے وو. د دې هر څۀ کولو په وجه هغۀ يهوداه او يروشلم بيا پاک کړل.', NULL, '&nbsp;هغۀ د بُت پرستو اِمامانو هډُوکى په هغه قربان‌ګاه باندې وسوزول چرته چې هغوئ عبادت کړے وو. د دې هر څۀ کولو په وجه هغۀ يهوداه او يروشلم بيا پاک کړل.', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles034_verse_005.mp3', NULL, 1761760676, 1761760676),
(11166, '2 Chronicles 34:6', '2 Chronicles', 34, 6, '&nbsp;هغۀ په ښارونو کښې او د منسى، اِفرائيم او شمعون او په شمال کښې د نفتالى پورې هم دغه شان کار وکړو.', NULL, '&nbsp;هغۀ په ښارونو کښې او د منسى، اِفرائيم او شمعون او په شمال کښې د نفتالى پورې هم دغه شان کار وکړو.', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles034_verse_006.mp3', NULL, 1761760676, 1761760676),
(11167, '2 Chronicles 34:7', '2 Chronicles', 34, 7, '&nbsp;د شمالى بادشاهۍ په ټوله علاقه کښې هغۀ قربان‌ګاه او د اشيرې بُت نښې ټوټې ټوټې کړې او بُتان يې خاورې کړل او د خوشبويۍ ټولې قربان‌ګاه يې ټوټې ټوټې کړې. بيا هغه يروشلم ته راواپس شو.', NULL, '&nbsp;د شمالى بادشاهۍ په ټوله علاقه کښې هغۀ قربان‌ګاه او د اشيرې بُت نښې ټوټې ټوټې کړې او بُتان يې خاورې کړل او د خوشبويۍ ټولې قربان‌ګاه يې ټوټې ټوټې کړې. بيا هغه يروشلم ته راواپس شو.', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles034_verse_007.mp3', NULL, 1761760676, 1761760676),
(11168, '2 Chronicles 34:8', '2 Chronicles', 34, 8, '&nbsp;د هغۀ د بادشاهۍ په اتلسم کال، د هغې نه پس چې کله هغۀ د غېرو قومونو د عبادت نه مالِک خُدائ کور او هغه مُلک پاک کړے وو، نو يوسياه بادشاه دا درې سړى ولېږل چې د مالِک خُدائ، خُدائ پاک کور مرمت کړى، د اصلياه زوئ سافن، معسياه، چې د يروشلم حکمران وو او د يهوآخز زوئ يوآخ چې مشر آفسر وو.', NULL, '&nbsp;د هغۀ د بادشاهۍ په اتلسم کال، د هغې نه پس چې کله هغۀ د غېرو قومونو د عبادت نه مالِک خُدائ کور او هغه مُلک پاک کړے وو، نو يوسياه بادشاه دا درې سړى ولېږل چې د مالِک خُدائ، خُدائ پاک کور مرمت کړى، د اصلياه زوئ سافن، معسياه، چې د يروشلم حکمران وو او د يهوآخز زوئ يوآخ چې مشر آفسر وو.', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles034_verse_008.mp3', NULL, 1761760676, 1761760676),
(11169, '2 Chronicles 34:9', '2 Chronicles', 34, 9, '&nbsp;کومې پېسې چې ليوى خادمانو د مالِک خُدائ کور کښې راغونډې کړې وې هغه يې مشر اِمام خِلقياه له ورکړې. دا د اِفرائيم او منسى او د شمالى ټولې بادشاهۍ نه او د يهوداه، بنيامين او د يروشلم د خلقو نه راغونډې شوې وې.', NULL, '&nbsp;کومې پېسې چې ليوى خادمانو د مالِک خُدائ کور کښې راغونډې کړې وې هغه يې مشر اِمام خِلقياه له ورکړې. دا د اِفرائيم او منسى او د شمالى ټولې بادشاهۍ نه او د يهوداه، بنيامين او د يروشلم د خلقو نه راغونډې شوې وې.', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles034_verse_009.mp3', NULL, 1761760676, 1761760676),
(11170, '2 Chronicles 34:10', '2 Chronicles', 34, 10, '&nbsp;بيا دا پېسې هغه درېو سړو ته حواله شوې چې د مالِک خُدائ د کور د مرمت مشران وُو او هغوئ دا پېسې دې مزدورانو له ورکړې', NULL, '&nbsp;بيا دا پېسې هغه درېو سړو ته حواله شوې چې د مالِک خُدائ د کور د مرمت مشران وُو او هغوئ دا پېسې دې مزدورانو له ورکړې', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles034_verse_010.mp3', NULL, 1761760676, 1761760676),
(11171, '2 Chronicles 34:11', '2 Chronicles', 34, 11, '&nbsp;يعنې ترکاڼانو او ګِلکارانو له چې جوړ شوى کاڼى او لرګى واخلى او د هغه عمارت په مرمت کښې استعمال شى چې د يهوداه بادشاهانو پرېښے وو چې خراب شى.', NULL, '&nbsp;يعنې ترکاڼانو او ګِلکارانو له چې جوړ شوى کاڼى او لرګى واخلى او د هغه عمارت په مرمت کښې استعمال شى چې د يهوداه بادشاهانو پرېښے وو چې خراب شى.', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles034_verse_011.mp3', NULL, 1761760676, 1761760676),
(11172, '2 Chronicles 34:12', '2 Chronicles', 34, 12, '&nbsp;کومو خلقو چې دا کار کولو هغه ټول محنتى وُو. د هغوئ مشرى دې څلورو ليويانو کوله، د مرارى د قبيلې يحت او عبدياه او د قُهات د قبيلې زکرياه او مسلام. ليويان تکړه موسيقاران وُو.', NULL, '&nbsp;کومو خلقو چې دا کار کولو هغه ټول محنتى وُو. د هغوئ مشرى دې څلورو ليويانو کوله، د مرارى د قبيلې يحت او عبدياه او د قُهات د قبيلې زکرياه او مسلام. ليويان تکړه موسيقاران وُو.', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles034_verse_012.mp3', NULL, 1761760676, 1761760676),
(11173, '2 Chronicles 34:13', '2 Chronicles', 34, 13, '&nbsp;نور ليويان د سامان د وړلو راوړلو او د مختلفو کارونو د کاريګرو مشران وُو او نورو به حِساب کِتاب ساتلو او څوکيدارى به يې کوله.', NULL, '&nbsp;نور ليويان د سامان د وړلو راوړلو او د مختلفو کارونو د کاريګرو مشران وُو او نورو به حِساب کِتاب ساتلو او څوکيدارى به يې کوله.', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles034_verse_013.mp3', NULL, 1761760676, 1761760676),
(11174, '2 Chronicles 34:14', '2 Chronicles', 34, 14, '&nbsp;کله چې د ګودام نه پېسې ويستلے شوې نو په دې دوران کښې خِلقياه د مالِک خُدائ د شريعت کِتاب وموندلو، هغه شريعت چې خُدائ پاک موسىٰ له ورکړے وو.', NULL, '&nbsp;کله چې د ګودام نه پېسې ويستلے شوې نو په دې دوران کښې خِلقياه د مالِک خُدائ د شريعت کِتاب وموندلو، هغه شريعت چې خُدائ پاک موسىٰ له ورکړے وو.', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles034_verse_014.mp3', NULL, 1761760676, 1761760676),
(11175, '2 Chronicles 34:15', '2 Chronicles', 34, 15, '&nbsp;هغۀ سافن منشى ته وفرمائيل، ”ما دلته د مالِک خُدائ په کور کښې د شريعت کِتاب موندلے دے.“ هغۀ سافن له کِتاب ورکړو،', NULL, '&nbsp;هغۀ سافن منشى ته وفرمائيل، ”ما دلته د مالِک خُدائ په کور کښې د شريعت کِتاب موندلے دے.“ هغۀ سافن له کِتاب ورکړو،', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles034_verse_015.mp3', NULL, 1761760676, 1761760676),
(11176, '2 Chronicles 34:16', '2 Chronicles', 34, 16, '&nbsp;او سافن هغه کِتاب بادشاه له يوړو. سافن ورته ووئيل، ”تا چې د څۀ حُکم کړے وو نو مونږ هغه هر څۀ کړى دى.', NULL, '&nbsp;او سافن هغه کِتاب بادشاه له يوړو. سافن ورته ووئيل، ”تا چې د څۀ حُکم کړے وو نو مونږ هغه هر څۀ کړى دى.', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles034_verse_016.mp3', NULL, 1761760676, 1761760676),
(11177, '2 Chronicles 34:17', '2 Chronicles', 34, 17, '&nbsp;کومې پېسې چې د مالِک خُدائ په کور کښې اېښودے شوې وې مونږ هغه کاريګرانو او د هغوئ مشرانو ته حواله کړې دى.“', NULL, '&nbsp;کومې پېسې چې د مالِک خُدائ په کور کښې اېښودے شوې وې مونږ هغه کاريګرانو او د هغوئ مشرانو ته حواله کړې دى.“', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles034_verse_017.mp3', NULL, 1761760676, 1761760676),
(11178, '2 Chronicles 34:18', '2 Chronicles', 34, 18, '&nbsp;بيا هغۀ ووئيل، ”هغه کِتاب دلته ما سره دے چې خِلقياه ما له راکړے دے.“ او هغۀ بادشاه ته د دې تلاوت وکړو.', NULL, '&nbsp;بيا هغۀ ووئيل، ”هغه کِتاب دلته ما سره دے چې خِلقياه ما له راکړے دے.“ او هغۀ بادشاه ته د دې تلاوت وکړو.', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles034_verse_018.mp3', NULL, 1761760676, 1761760676),
(11179, '2 Chronicles 34:19', '2 Chronicles', 34, 19, '&nbsp;کله چې بادشاه هغه کِتاب واورېدو، نو هغۀ د خفګان نه خپلې جامې وشلولې.', NULL, '&nbsp;کله چې بادشاه هغه کِتاب واورېدو، نو هغۀ د خفګان نه خپلې جامې وشلولې.', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles034_verse_019.mp3', NULL, 1761760676, 1761760676),
(11180, '2 Chronicles 34:20', '2 Chronicles', 34, 20, '&nbsp;او هغۀ خِلقياه، د سافن زوئ اخيقام، د ميکاياه زوئ عبدون، د دربار منشى سافن او د بادشاه مدد کوونکى عساياه له دا حُکم ورکړو،', NULL, '&nbsp;او هغۀ خِلقياه، د سافن زوئ اخيقام، د ميکاياه زوئ عبدون، د دربار منشى سافن او د بادشاه مدد کوونکى عساياه له دا حُکم ورکړو،', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles034_verse_020.mp3', NULL, 1761760676, 1761760676),
(11181, '2 Chronicles 34:21', '2 Chronicles', 34, 21, '&nbsp;”لاړ شئ او د مالِک خُدائ سره زما او د هغه خلقو دپاره مشوره وکړئ چې هغوئ بيا هم په اِسرائيل او يهوداه کښې پاتې کيږى. د دې کِتاب تعليمات معلوم کړئ. مالِک خُدائ مونږ ته غصه دے ځکه چې زمونږ پلار نيکۀ د مالِک خُدائ کلام نۀ دے منلے او هغه کار يې نۀ دے کړے چې د کوم په حقله دا کِتاب فرمائى چې خامخا دې وکړے شى.“', NULL, '&nbsp;”لاړ شئ او د مالِک خُدائ سره زما او د هغه خلقو دپاره مشوره وکړئ چې هغوئ بيا هم په اِسرائيل او يهوداه کښې پاتې کيږى. د دې کِتاب تعليمات معلوم کړئ. مالِک خُدائ مونږ ته غصه دے ځکه چې زمونږ پلار نيکۀ د مالِک خُدائ کلام نۀ دے منلے او هغه کار يې نۀ دے کړے چې د کوم په حقله دا کِتاب فرمائى چې خامخا دې وکړے شى.“', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles034_verse_021.mp3', NULL, 1761760676, 1761760676),
(11182, '2 Chronicles 34:22', '2 Chronicles', 34, 22, '&nbsp;د بادشاه په حُکم، خِلقياه او نور لاړل چې د يوې ښځې سره مشوره وکړى چې نوم يې خُلده وو، دا پېغمبره د يروشلم په نوې حِصه کښې اوسېده. د هغې خاوند سلوم، د توقهت زوئ او د خسره نمسے وو، سلوم د مالِک خُدائ د کور د چُوغو مشر وو. چې څۀ شوى وُو نو هغوئ ورته هغه بيان وکړو،', NULL, '&nbsp;د بادشاه په حُکم، خِلقياه او نور لاړل چې د يوې ښځې سره مشوره وکړى چې نوم يې خُلده وو، دا پېغمبره د يروشلم په نوې حِصه کښې اوسېده. د هغې خاوند سلوم، د توقهت زوئ او د خسره نمسے وو، سلوم د مالِک خُدائ د کور د چُوغو مشر وو. چې څۀ شوى وُو نو هغوئ ورته هغه بيان وکړو،', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles034_verse_022.mp3', NULL, 1761760676, 1761760676),
(11183, '2 Chronicles 34:23', '2 Chronicles', 34, 23, '&nbsp;او هغې ورته ووئيل چې واپس بادشاه له لاړ شئ او ورته ووايئ', NULL, '&nbsp;او هغې ورته ووئيل چې واپس بادشاه له لاړ شئ او ورته ووايئ', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles034_verse_023.mp3', NULL, 1761760676, 1761760676),
(11184, '2 Chronicles 34:24', '2 Chronicles', 34, 24, '&nbsp;چې د مالِک خُدائ نه دا پېغام راغلے دے، ”زۀ به په يروشلم او د دې په ټولو خلقو افت راولم چې په کښې به هغه ټول لعنتونه وى چې په هغه کِتاب کښې ليکلے شوى دى کوم چې بادشاه ته بيان شو.', NULL, '&nbsp;چې د مالِک خُدائ نه دا پېغام راغلے دے، ”زۀ به په يروشلم او د دې په ټولو خلقو افت راولم چې په کښې به هغه ټول لعنتونه وى چې په هغه کِتاب کښې ليکلے شوى دى کوم چې بادشاه ته بيان شو.', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles034_verse_024.mp3', NULL, 1761760676, 1761760676),
(11185, '2 Chronicles 34:25', '2 Chronicles', 34, 25, '&nbsp;هغوئ زۀ رد کړے يم او نورو معبودانو ته يې نذرانې پېش کړې دى او دوئ چې دا هر څۀ کړى دى د هغې په وجه يې زما غصه راپارولې ده. زما غصه د يروشلم خِلاف راوچته شوې ده او دا به کمه نۀ شى.“', NULL, '&nbsp;هغوئ زۀ رد کړے يم او نورو معبودانو ته يې نذرانې پېش کړې دى او دوئ چې دا هر څۀ کړى دى د هغې په وجه يې زما غصه راپارولې ده. زما غصه د يروشلم خِلاف راوچته شوې ده او دا به کمه نۀ شى.“', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles034_verse_025.mp3', NULL, 1761760676, 1761760676),
(11186, '2 Chronicles 34:26', '2 Chronicles', 34, 26, '&nbsp;خو د يهوداه هغه بادشاه له واپس ورشه چا چې د مالِک خُدائ سره د مشورې دپاره رالېږلے يې او هغۀ ته ووايه چې، ”مالِک خُدائ د بنى اِسرائيلو خُدائ پاک د هغه پېغام په حقله داسې فرمائى چې تا اوس اوس واورېدو،', NULL, '&nbsp;خو د يهوداه هغه بادشاه له واپس ورشه چا چې د مالِک خُدائ سره د مشورې دپاره رالېږلے يې او هغۀ ته ووايه چې، ”مالِک خُدائ د بنى اِسرائيلو خُدائ پاک د هغه پېغام په حقله داسې فرمائى چې تا اوس اوس واورېدو،', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles034_verse_026.mp3', NULL, 1761760676, 1761760676),
(11187, '2 Chronicles 34:27', '2 Chronicles', 34, 27, '&nbsp;نو تۀ پښېمانه شوې او د خُدائ پاک په حضور کښې دې خپل ځان عاجز کړو، کله چې تا واورېدل چې هغۀ د دې ځائ او خلقو خلاف خبرې وکړې. کله چې تا خپل ځان زما د وړاندې عاجز کړو او خپلې جامې دې وشلولې او زما په حضور کښې وژړل، نو ما ستا دعا واورېدله، مالِک خُدائ فرمائى،', NULL, '&nbsp;نو تۀ پښېمانه شوې او د خُدائ پاک په حضور کښې دې خپل ځان عاجز کړو، کله چې تا واورېدل چې هغۀ د دې ځائ او خلقو خلاف خبرې وکړې. کله چې تا خپل ځان زما د وړاندې عاجز کړو او خپلې جامې دې وشلولې او زما په حضور کښې وژړل، نو ما ستا دعا واورېدله، مالِک خُدائ فرمائى،', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles034_verse_027.mp3', NULL, 1761760676, 1761760676),
(11188, '2 Chronicles 34:28', '2 Chronicles', 34, 28, '&nbsp;او زۀ چې يروشلم له کومه سزا ورکوم هغه به تر هغه وخت پورې نۀ راځى چې ترڅو تۀ مړ شوے نۀ يې. او زۀ به تا پرېږدم چې په سلامتۍ سره مړ شې.“ نو هغه سړى د دې پېغام سره يوسياه بادشاه ته راواپس شول.', NULL, '&nbsp;او زۀ چې يروشلم له کومه سزا ورکوم هغه به تر هغه وخت پورې نۀ راځى چې ترڅو تۀ مړ شوے نۀ يې. او زۀ به تا پرېږدم چې په سلامتۍ سره مړ شې.“ نو هغه سړى د دې پېغام سره يوسياه بادشاه ته راواپس شول.', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles034_verse_028.mp3', NULL, 1761760676, 1761760676),
(11189, '2 Chronicles 34:29', '2 Chronicles', 34, 29, '&nbsp;يوسياه بادشاه د يهوداه او يروشلم ټول مشران راغونډ کړل،', NULL, '&nbsp;يوسياه بادشاه د يهوداه او يروشلم ټول مشران راغونډ کړل،', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles034_verse_029.mp3', NULL, 1761760676, 1761760676),
(11190, '2 Chronicles 34:30', '2 Chronicles', 34, 30, '&nbsp;او هغوئ په يو ځائ د مالِک خُدائ کور ته لاړل، چې اِمامان او ليويان او ټول خلق، مالداره او غريبانان په کښې شامل وُو. بادشاه د هغوئ ټولو په مخکښې د لوظ د هغه کِتاب تلاوت وکړو، کوم چې د مالِک خُدائ په کور کښې موندلے شوے وو.', NULL, '&nbsp;او هغوئ په يو ځائ د مالِک خُدائ کور ته لاړل، چې اِمامان او ليويان او ټول خلق، مالداره او غريبانان په کښې شامل وُو. بادشاه د هغوئ ټولو په مخکښې د لوظ د هغه کِتاب تلاوت وکړو، کوم چې د مالِک خُدائ په کور کښې موندلے شوے وو.', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles034_verse_030.mp3', NULL, 1761760676, 1761760676),
(11191, '2 Chronicles 34:31', '2 Chronicles', 34, 31, '&nbsp;هغه د شاهى ستنې سره ولاړ وو او د مالِک خُدائ سره يې يو لوظ وکړو چې د هغۀ تابعدارى به کوى او د زړۀ د اخلاصه د هغۀ قانون او حُکمونه به منى او هغه مطالبې به پوره کوى کومې چې د دې لوظ سره تړلې دى، هم هغه شان چې څنګه په هغه کِتاب کښې ليکلے شوى دى.', NULL, '&nbsp;هغه د شاهى ستنې سره ولاړ وو او د مالِک خُدائ سره يې يو لوظ وکړو چې د هغۀ تابعدارى به کوى او د زړۀ د اخلاصه د هغۀ قانون او حُکمونه به منى او هغه مطالبې به پوره کوى کومې چې د دې لوظ سره تړلې دى، هم هغه شان چې څنګه په هغه کِتاب کښې ليکلے شوى دى.', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles034_verse_031.mp3', NULL, 1761760676, 1761760676),
(11192, '2 Chronicles 34:32', '2 Chronicles', 34, 32, '&nbsp;هغۀ د بنيامين خلق او د يروشلم خلق هم هغه لوظ ته مجبور کړل. نو د يروشلم خلقو د لوظ هغه مطالبې ومنلې کوم لوظ چې هغوئ د خپل پلار نيکۀ خُدائ پاک سره کړے وو.', NULL, '&nbsp;هغۀ د بنيامين خلق او د يروشلم خلق هم هغه لوظ ته مجبور کړل. نو د يروشلم خلقو د لوظ هغه مطالبې ومنلې کوم لوظ چې هغوئ د خپل پلار نيکۀ خُدائ پاک سره کړے وو.', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles034_verse_032.mp3', NULL, 1761760676, 1761760676),
(11193, '2 Chronicles 34:33', '2 Chronicles', 34, 33, '&nbsp;نو يوسياه بادشاه هغه ټول حرام کاره بُتان تباه کړل کوم چې د اِسرائيل په علاقه کښې وُو او چې ترڅو پورې هغه ژوندے وو، نو هغوئ د مالِک خُدائ د هغوئ د پلار نيکۀ خُدائ پاک نه نۀ اوړېدل.', NULL, '&nbsp;نو يوسياه بادشاه هغه ټول حرام کاره بُتان تباه کړل کوم چې د اِسرائيل په علاقه کښې وُو او چې ترڅو پورې هغه ژوندے وو، نو هغوئ د مالِک خُدائ د هغوئ د پلار نيکۀ خُدائ پاک نه نۀ اوړېدل.', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles034_verse_033.mp3', NULL, 1761760676, 1761760676),
(11194, '2 Chronicles 35:1', '2 Chronicles', 35, 1, '&nbsp;يوسياه بادشاه په يروشلم کښې د مالِک خُدائ د درناوى دپاره د فسحې اختر وکړو، د وړومبۍ مياشتې په څوارلسمه ورځ هغوئ د اختر دپاره ګډُورى حلال کړل.', NULL, '&nbsp;يوسياه بادشاه په يروشلم کښې د مالِک خُدائ د درناوى دپاره د فسحې اختر وکړو، د وړومبۍ مياشتې په څوارلسمه ورځ هغوئ د اختر دپاره ګډُورى حلال کړل.', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles035_verse_001.mp3', NULL, 1761760676, 1761760676),
(11195, '2 Chronicles 35:2', '2 Chronicles', 35, 2, '&nbsp;هغۀ اِمامانو ته هغه ذمه وارۍ حواله کړې کومې چې هغوئ د مالِک خُدائ په کور کښې کولې او د هغوئ حوصله افزائى يې وکړه چې دا په ښۀ طريقه کوى.', NULL, '&nbsp;هغۀ اِمامانو ته هغه ذمه وارۍ حواله کړې کومې چې هغوئ د مالِک خُدائ په کور کښې کولې او د هغوئ حوصله افزائى يې وکړه چې دا په ښۀ طريقه کوى.', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles035_verse_002.mp3', NULL, 1761760676, 1761760676),
(11196, '2 Chronicles 35:3', '2 Chronicles', 35, 3, '&nbsp;هغۀ د بنى اِسرائيلو اُستاذانو يعنې هغه ليويانو ته هم دا اصُول وښودل، چې هغوئ مالِک خُدائ ته وقف شوى وُو، ”د لوظ صندوق د مالِک خُدائ په هغه کور کښې کېږدئ کوم چې د داؤد زوئ سليمان بادشاه جوړ کړے دے. تاسو به نور دا يو ځائ نه بل ځائ ته نۀ وړۍ، خو تاسو به د مالِک خُدائ د خپل خُدائ پاک او د هغۀ د خلقو بنى اِسرائيلو خِدمت کوئ.', NULL, '&nbsp;هغۀ د بنى اِسرائيلو اُستاذانو يعنې هغه ليويانو ته هم دا اصُول وښودل، چې هغوئ مالِک خُدائ ته وقف شوى وُو، ”د لوظ صندوق د مالِک خُدائ په هغه کور کښې کېږدئ کوم چې د داؤد زوئ سليمان بادشاه جوړ کړے دے. تاسو به نور دا يو ځائ نه بل ځائ ته نۀ وړۍ، خو تاسو به د مالِک خُدائ د خپل خُدائ پاک او د هغۀ د خلقو بنى اِسرائيلو خِدمت کوئ.', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles035_verse_003.mp3', NULL, 1761760676, 1761760676),
(11197, '2 Chronicles 35:4', '2 Chronicles', 35, 4, '&nbsp;د ډلو په مطابق او د هغه ذمه وارو په مطابق په خپلو ځايونو باندې تيار ودرېږئ، کومې چې درته داؤد بادشاه او د هغۀ زوئ سليمان بادشاه حواله کړى دى،', NULL, '&nbsp;د ډلو په مطابق او د هغه ذمه وارو په مطابق په خپلو ځايونو باندې تيار ودرېږئ، کومې چې درته داؤد بادشاه او د هغۀ زوئ سليمان بادشاه حواله کړى دى،', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles035_verse_004.mp3', NULL, 1761760676, 1761760676),
(11198, '2 Chronicles 35:5', '2 Chronicles', 35, 5, '&nbsp;او خپلو ځانونو له داسې ترتيب ورکړئ چې تاسو موجود يئ نو چې د بنى اِسرائيلو د هر خاندان مدد وکړئ.', NULL, '&nbsp;او خپلو ځانونو له داسې ترتيب ورکړئ چې تاسو موجود يئ نو چې د بنى اِسرائيلو د هر خاندان مدد وکړئ.', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles035_verse_005.mp3', NULL, 1761760676, 1761760676),
(11199, '2 Chronicles 35:6', '2 Chronicles', 35, 6, '&nbsp;تاسو به د فسحې د اختر ګډُورى او چېلى حلال کړئ. اوس خپل ځانونه پاک کړئ او د دې دپاره قربانۍ تيارې کړئ چې ستاسو بنى اِسرائيليان هغه اصُول ومنى کوم چې مالِک خُدائ د موسىٰ په ذريعه ښودلى دى.“', NULL, '&nbsp;تاسو به د فسحې د اختر ګډُورى او چېلى حلال کړئ. اوس خپل ځانونه پاک کړئ او د دې دپاره قربانۍ تيارې کړئ چې ستاسو بنى اِسرائيليان هغه اصُول ومنى کوم چې مالِک خُدائ د موسىٰ په ذريعه ښودلى دى.“', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles035_verse_006.mp3', NULL, 1761760676, 1761760676),
(11200, '2 Chronicles 35:7', '2 Chronicles', 35, 7, '&nbsp;د فسحې د اختر دپاره يوسياه بادشاه خلقو له د خپلو څاروو او رَمو نه دېرش زره ګډان، ګډُورى او د چېلو بچى او درې زره غوَيى ورکړل.', NULL, '&nbsp;د فسحې د اختر دپاره يوسياه بادشاه خلقو له د خپلو څاروو او رَمو نه دېرش زره ګډان، ګډُورى او د چېلو بچى او درې زره غوَيى ورکړل.', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles035_verse_007.mp3', NULL, 1761760676, 1761760676),
(11201, '2 Chronicles 35:8', '2 Chronicles', 35, 8, '&nbsp;د هغۀ آفسرانو په خپله خوښه خلقو، اِمامانو او د ليويانو د استعمال دپاره هم ځناور ورکړل. او د مالِک خُدائ د کور مشرانو آفسرانو، مشر اِمام خِلقياه، زکرياه او يحى‌ايل اِمامانو له دوه زره او شپږ سوه ګډُورى او د چېلو بچى او درې سوه غوَيى ورکړل چې په اختر کښې قربانى شى.', NULL, '&nbsp;د هغۀ آفسرانو په خپله خوښه خلقو، اِمامانو او د ليويانو د استعمال دپاره هم ځناور ورکړل. او د مالِک خُدائ د کور مشرانو آفسرانو، مشر اِمام خِلقياه، زکرياه او يحى‌ايل اِمامانو له دوه زره او شپږ سوه ګډُورى او د چېلو بچى او درې سوه غوَيى ورکړل چې په اختر کښې قربانى شى.', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles035_verse_008.mp3', NULL, 1761760676, 1761760676),
(11202, '2 Chronicles 35:9', '2 Chronicles', 35, 9, '&nbsp;د ليويانو مشرانو، کنعنياه، او د هغۀ وروڼه سمعياه او نتنى‌ايل، او ورسره حسبياه، يعى‌ايل او يوزبد پينځۀ زره ګډُورى او د چېلو بچى او پينځۀ سوه غوَيى ليويانو له ورکړل چې د فسحې په اختر کښې يې قربانى کړى.', NULL, '&nbsp;د ليويانو مشرانو، کنعنياه، او د هغۀ وروڼه سمعياه او نتنى‌ايل، او ورسره حسبياه، يعى‌ايل او يوزبد پينځۀ زره ګډُورى او د چېلو بچى او پينځۀ سوه غوَيى ليويانو له ورکړل چې د فسحې په اختر کښې يې قربانى کړى.', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles035_verse_009.mp3', NULL, 1761760676, 1761760676),
(11203, '2 Chronicles 35:10', '2 Chronicles', 35, 10, '&nbsp;کله چې د فسحې اختر دپاره هر څۀ تيار شول، نو اِمامان او ليويان د بادشاه د حُکم په مطابق په خپلو ځايونو ودرېدل.', NULL, '&nbsp;کله چې د فسحې اختر دپاره هر څۀ تيار شول، نو اِمامان او ليويان د بادشاه د حُکم په مطابق په خپلو ځايونو ودرېدل.', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles035_verse_010.mp3', NULL, 1761760676, 1761760676),
(11204, '2 Chronicles 35:11', '2 Chronicles', 35, 11, '&nbsp;کله چې ګډُورى او چېلى حلال کړے شول، نو اِمامانو په قربان‌ګاه باندې وينه وشيندله او ليويانو د هغې نه څرمنې وويستلې.', NULL, '&nbsp;کله چې ګډُورى او چېلى حلال کړے شول، نو اِمامانو په قربان‌ګاه باندې وينه وشيندله او ليويانو د هغې نه څرمنې وويستلې.', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles035_verse_011.mp3', NULL, 1761760676, 1761760676),
(11205, '2 Chronicles 35:12', '2 Chronicles', 35, 12, '&nbsp;بيا هغوئ څاروى د سوزېدونکې نذرانې دپاره د کورَنو د ډلو په مطابق په خلقو باندې تقسيم کړل، نو هغوئ دا د موسىٰ د شريعت د اصُولو په مطابق پېش کړل.', NULL, '&nbsp;بيا هغوئ څاروى د سوزېدونکې نذرانې دپاره د کورَنو د ډلو په مطابق په خلقو باندې تقسيم کړل، نو هغوئ دا د موسىٰ د شريعت د اصُولو په مطابق پېش کړل.', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles035_verse_012.mp3', NULL, 1761760676, 1761760676),
(11206, '2 Chronicles 35:13', '2 Chronicles', 35, 13, '&nbsp;ليويانو د اصُولو په مطابق د فسحې اختر قربانۍ په اور وريتې کړې او مقدسې نذرانې يې په لوښو کښې، دېګونو او پَتيلو کښې ويشولې او غوښه يې زر زر په خلقو باندې تقسيم کړه.', NULL, '&nbsp;ليويانو د اصُولو په مطابق د فسحې اختر قربانۍ په اور وريتې کړې او مقدسې نذرانې يې په لوښو کښې، دېګونو او پَتيلو کښې ويشولې او غوښه يې زر زر په خلقو باندې تقسيم کړه.', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles035_verse_013.mp3', NULL, 1761760676, 1761760676),
(11207, '2 Chronicles 35:14', '2 Chronicles', 35, 14, '&nbsp;د دې کېدو نه پس، ليويانو د خپل ځان دپاره او د هارون د اولاد اِمامانو دپاره د غوښې بندوبست وکړو، ځکه چې اِمامان د سحر نه واخله تر ماښام پورې مصروف وُو او د قربانو وازګه او هغه څاروى يې سوزول چې په پوره توګه سوزولے شول.', NULL, '&nbsp;د دې کېدو نه پس، ليويانو د خپل ځان دپاره او د هارون د اولاد اِمامانو دپاره د غوښې بندوبست وکړو، ځکه چې اِمامان د سحر نه واخله تر ماښام پورې مصروف وُو او د قربانو وازګه او هغه څاروى يې سوزول چې په پوره توګه سوزولے شول.', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles035_verse_014.mp3', NULL, 1761760676, 1761760676),
(11208, '2 Chronicles 35:15', '2 Chronicles', 35, 15, '&nbsp;د ليوى قبيلې د آسف د قبيلې دا موسيقاران په هغه ځايونو کښې وُو کوم چې هغوئ ته د داؤد د اصُولو په مطابق حواله شوى وُو، آسف، هيمان او د بادشاه پېغمبر يدوتون. د مالِک خُدائ د کور د دروازو څوکيدارانو ته د خپلو ځايونو نه د تلو ضرورت نۀ وو، ځکه چې نورو ليويانو د هغوئ دپاره د فسحې اختر تيار کړے وو.', NULL, '&nbsp;د ليوى قبيلې د آسف د قبيلې دا موسيقاران په هغه ځايونو کښې وُو کوم چې هغوئ ته د داؤد د اصُولو په مطابق حواله شوى وُو، آسف، هيمان او د بادشاه پېغمبر يدوتون. د مالِک خُدائ د کور د دروازو څوکيدارانو ته د خپلو ځايونو نه د تلو ضرورت نۀ وو، ځکه چې نورو ليويانو د هغوئ دپاره د فسحې اختر تيار کړے وو.', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles035_verse_015.mp3', NULL, 1761760676, 1761760676),
(11209, '2 Chronicles 35:16', '2 Chronicles', 35, 16, '&nbsp;څنګه چې يوسياه بادشاه حُکم کړے وو نو په هغه ورځ د مالِک خُدائ د عبادت دپاره او د فسحې اختر کولو دپاره او په قربان‌ګاه باندې د سوزېدونکې نذرانې سوزولو دپاره هر څۀ شوى وُو.', NULL, '&nbsp;څنګه چې يوسياه بادشاه حُکم کړے وو نو په هغه ورځ د مالِک خُدائ د عبادت دپاره او د فسحې اختر کولو دپاره او په قربان‌ګاه باندې د سوزېدونکې نذرانې سوزولو دپاره هر څۀ شوى وُو.', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles035_verse_016.mp3', NULL, 1761760676, 1761760676),
(11210, '2 Chronicles 35:17', '2 Chronicles', 35, 17, '&nbsp;کوم بنى اِسرائيليان چې موجود وُو نو هغه ټولو اووۀ ورځې د فسحې اختر او د پتيرې روټۍ اختر وکړو.', NULL, '&nbsp;کوم بنى اِسرائيليان چې موجود وُو نو هغه ټولو اووۀ ورځې د فسحې اختر او د پتيرې روټۍ اختر وکړو.', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles035_verse_017.mp3', NULL, 1761760676, 1761760676),
(11211, '2 Chronicles 35:18', '2 Chronicles', 35, 18, '&nbsp;د سموئيل پېغمبر د وخت نه د فسحې اختر دغه شان نۀ وو شوے. په پخوانو بادشاهانو کښې يو کس کله هم د فسحې داسې اختر نۀ وو کړے، چې کوم يوسياه بادشاه، اِمامانو، ليويانو او د يهوداه، اِسرائيل او د يروشلم خلقو وکړو.', NULL, '&nbsp;د سموئيل پېغمبر د وخت نه د فسحې اختر دغه شان نۀ وو شوے. په پخوانو بادشاهانو کښې يو کس کله هم د فسحې داسې اختر نۀ وو کړے، چې کوم يوسياه بادشاه، اِمامانو، ليويانو او د يهوداه، اِسرائيل او د يروشلم خلقو وکړو.', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles035_verse_018.mp3', NULL, 1761760676, 1761760676),
(11212, '2 Chronicles 35:19', '2 Chronicles', 35, 19, '&nbsp;د يوسياه د بادشاهۍ په اتلسم کال داسې وشول.', NULL, '&nbsp;د يوسياه د بادشاهۍ په اتلسم کال داسې وشول.', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles035_verse_019.mp3', NULL, 1761760676, 1761760676),
(11213, '2 Chronicles 35:20', '2 Chronicles', 35, 20, '&nbsp;کله چې يوسياه بادشاه د مالِک خُدائ کور دپاره دا هر څۀ وکړل، نو د مِصر بادشاه نِکوه يو لښکر روان کړو چې د فرات په سيند په کرکميس کښې جنګ وکړى. او يوسياه د هغۀ خِلاف د جنګ کولو دپاره راووتلو،', NULL, '&nbsp;کله چې يوسياه بادشاه د مالِک خُدائ کور دپاره دا هر څۀ وکړل، نو د مِصر بادشاه نِکوه يو لښکر روان کړو چې د فرات په سيند په کرکميس کښې جنګ وکړى. او يوسياه د هغۀ خِلاف د جنګ کولو دپاره راووتلو،', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles035_verse_020.mp3', NULL, 1761760676, 1761760676),
(11214, '2 Chronicles 35:21', '2 Chronicles', 35, 21, '&nbsp;خو نِکوه يوسياه له دا پېغام ولېږلو، ”د يهوداه بادشاه دا جنګ چې زۀ کوم د دې تعلق تا سره نشته. زۀ تا سره جنګ کولو دپاره نۀ يم راغلے، زۀ د خپلو دشمنانو سره د جنګ کولو دپاره راغلے يم او خُدائ پاک راته فرمائيلى دى چې تېز لاړ شه. خُدائ پاک زما مل دے، نو زما مخالفت مۀ کوه، ګنې هغه به تا تباه کړى.“', NULL, '&nbsp;خو نِکوه يوسياه له دا پېغام ولېږلو، ”د يهوداه بادشاه دا جنګ چې زۀ کوم د دې تعلق تا سره نشته. زۀ تا سره جنګ کولو دپاره نۀ يم راغلے، زۀ د خپلو دشمنانو سره د جنګ کولو دپاره راغلے يم او خُدائ پاک راته فرمائيلى دى چې تېز لاړ شه. خُدائ پاک زما مل دے، نو زما مخالفت مۀ کوه، ګنې هغه به تا تباه کړى.“', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles035_verse_021.mp3', NULL, 1761760676, 1761760676),
(11215, '2 Chronicles 35:22', '2 Chronicles', 35, 22, '&nbsp;خو خُدائ پاک چې د نِکوه فِرعون په ذريعه څۀ وفرمائيل نو يوسياه هغې ته غوږ نۀ کېښودو، نو هغۀ خپل شکل بدل کړو او د مِجدو په مېدان کښې د جنګ دپاره لاړو.', NULL, '&nbsp;خو خُدائ پاک چې د نِکوه فِرعون په ذريعه څۀ وفرمائيل نو يوسياه هغې ته غوږ نۀ کېښودو، نو هغۀ خپل شکل بدل کړو او د مِجدو په مېدان کښې د جنګ دپاره لاړو.', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles035_verse_022.mp3', NULL, 1761760676, 1761760676),
(11216, '2 Chronicles 35:23', '2 Chronicles', 35, 23, '&nbsp;د جنګ په دوران کښې يوسياه بادشاه د مِصريانو په غشو باندې ولګېدو. هغۀ خپلو نوکرانو له حُکم ورکړو، ”ما د دې ځائ نه بوځئ، زۀ سخت زخمى شوے يم.“', NULL, '&nbsp;د جنګ په دوران کښې يوسياه بادشاه د مِصريانو په غشو باندې ولګېدو. هغۀ خپلو نوکرانو له حُکم ورکړو، ”ما د دې ځائ نه بوځئ، زۀ سخت زخمى شوے يم.“', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles035_verse_023.mp3', NULL, 1761760676, 1761760676),
(11217, '2 Chronicles 35:24', '2 Chronicles', 35, 24, '&nbsp;هغوئ هغه د خپل جنګى ګاډۍ نه اوچت کړو او چې هلته د هغۀ کومه دوېمه جنګى ګاډۍ وه په هغې کښې يې واچولو او يروشلم ته يې يوړو. هلته هغه مړ شو او په شاهى اديره کښې ښخ کړے شو. د يهوداه او يروشلم ټولو خلقو د هغۀ په مرګ باندې د غم ژړا وکړه.', NULL, '&nbsp;هغوئ هغه د خپل جنګى ګاډۍ نه اوچت کړو او چې هلته د هغۀ کومه دوېمه جنګى ګاډۍ وه په هغې کښې يې واچولو او يروشلم ته يې يوړو. هلته هغه مړ شو او په شاهى اديره کښې ښخ کړے شو. د يهوداه او يروشلم ټولو خلقو د هغۀ په مرګ باندې د غم ژړا وکړه.', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles035_verse_024.mp3', NULL, 1761760676, 1761760676),
(11218, '2 Chronicles 35:25', '2 Chronicles', 35, 25, '&nbsp;يرمياه پېغمبر د يوسياه بادشاه دپاره يوه د غم سندره جوړه کړه. نو د اِسرائيل په مُلک کښې د سندرغاړو، ناريناؤ او زناناؤ دواړو دا يو رِواج جوړ شو، چې کله به هغوئ د هغۀ دپاره د غم ژړا کوله نو دا سندره به يې وئيله. دا سندره د مرثيو په کِتاب کښې ليکلے شوې ده.', NULL, '&nbsp;يرمياه پېغمبر د يوسياه بادشاه دپاره يوه د غم سندره جوړه کړه. نو د اِسرائيل په مُلک کښې د سندرغاړو، ناريناؤ او زناناؤ دواړو دا يو رِواج جوړ شو، چې کله به هغوئ د هغۀ دپاره د غم ژړا کوله نو دا سندره به يې وئيله. دا سندره د مرثيو په کِتاب کښې ليکلے شوې ده.', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles035_verse_025.mp3', NULL, 1761760676, 1761760676),
(11219, '2 Chronicles 35:26', '2 Chronicles', 35, 26, '&nbsp;يوسياه چې نور هر څۀ هم کړى وُو، مالِک خُدائ ته د هغۀ وقف کېدل، د هغۀ د شريعت تابعدارى،', NULL, '&nbsp;يوسياه چې نور هر څۀ هم کړى وُو، مالِک خُدائ ته د هغۀ وقف کېدل، د هغۀ د شريعت تابعدارى،', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles035_verse_026.mp3', NULL, 1761760676, 1761760676),
(11220, '2 Chronicles 35:27', '2 Chronicles', 35, 27, '&nbsp;او د اول نه واخله تر آخره پورې د هغۀ تاريخ دا هر څۀ د اِسرائيل او يهوداه په تاريخ کښې ليکلے شوى دى.', NULL, '&nbsp;او د اول نه واخله تر آخره پورې د هغۀ تاريخ دا هر څۀ د اِسرائيل او يهوداه په تاريخ کښې ليکلے شوى دى.', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles035_verse_027.mp3', NULL, 1761760676, 1761760676),
(11221, '2 Chronicles 36:1', '2 Chronicles', 36, 1, '&nbsp;د يهوداه خلقو د يوسياه زوئ يهوآخز خوښ کړو او په يروشلم کښې يې بادشاه جوړ کړو.', NULL, '&nbsp;د يهوداه خلقو د يوسياه زوئ يهوآخز خوښ کړو او په يروشلم کښې يې بادشاه جوړ کړو.', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles036_verse_001.mp3', NULL, 1761760676, 1761760676),
(11222, '2 Chronicles 36:2', '2 Chronicles', 36, 2, '&nbsp;يهوآخز د درويشتو کالو وو چې هغه د يهوداه بادشاه شو او درې مياشتې يې په يروشلم بادشاهى وکړه.', NULL, '&nbsp;يهوآخز د درويشتو کالو وو چې هغه د يهوداه بادشاه شو او درې مياشتې يې په يروشلم بادشاهى وکړه.', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles036_verse_002.mp3', NULL, 1761760676, 1761760676),
(11223, '2 Chronicles 36:3', '2 Chronicles', 36, 3, '&nbsp;د مِصر بادشاه نِکوه هغه قېدى کړو او د يهوداه خلق يې دې ته مجبور کړل چې درې زره او څلور سوه کلو سپين زر او څلور دېرش کلو سرۀ زر محصُول ورکوى.', NULL, '&nbsp;د مِصر بادشاه نِکوه هغه قېدى کړو او د يهوداه خلق يې دې ته مجبور کړل چې درې زره او څلور سوه کلو سپين زر او څلور دېرش کلو سرۀ زر محصُول ورکوى.', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles036_verse_003.mp3', NULL, 1761760676, 1761760676),
(11224, '2 Chronicles 36:4', '2 Chronicles', 36, 4, '&nbsp;نِکوه اِلياقيم د يهوداه بادشاه جوړ کړو چې هغه د يهوآخز ورور وو او د هغۀ نوم يې يهويقيم ته بدل کړو. نِکوه يهوآخز مِصر ته بوتلے وو.', NULL, '&nbsp;نِکوه اِلياقيم د يهوداه بادشاه جوړ کړو چې هغه د يهوآخز ورور وو او د هغۀ نوم يې يهويقيم ته بدل کړو. نِکوه يهوآخز مِصر ته بوتلے وو.', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles036_verse_004.mp3', NULL, 1761760676, 1761760676),
(11225, '2 Chronicles 36:5', '2 Chronicles', 36, 5, '&nbsp;يهويقيم د پينځويشتو کالو وو چې هغه د يهوداه بادشاه شو او هغۀ په يروشلم باندې يوولس کاله بادشاهى وکړه. هغۀ د مالِک خُدائ خپل خُدائ پاک خِلاف ګناه وکړه.', NULL, '&nbsp;يهويقيم د پينځويشتو کالو وو چې هغه د يهوداه بادشاه شو او هغۀ په يروشلم باندې يوولس کاله بادشاهى وکړه. هغۀ د مالِک خُدائ خپل خُدائ پاک خِلاف ګناه وکړه.', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles036_verse_005.mp3', NULL, 1761760676, 1761760676),
(11226, '2 Chronicles 36:6', '2 Chronicles', 36, 6, '&nbsp;د بابل بادشاه نبوکدنضر په يهوداه حمله وکړه، يهويقيم يې ونيولو او بابل ته يې په زنځيرونو کښې بوتلو.', NULL, '&nbsp;د بابل بادشاه نبوکدنضر په يهوداه حمله وکړه، يهويقيم يې ونيولو او بابل ته يې په زنځيرونو کښې بوتلو.', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles036_verse_006.mp3', NULL, 1761760676, 1761760676),
(11227, '2 Chronicles 36:7', '2 Chronicles', 36, 7, '&nbsp;نبوکدنضر د مالِک خُدائ د کور څۀ خزانې يوړې او په بابل کښې يې په خپل محل کښې کېښودې.', NULL, '&nbsp;نبوکدنضر د مالِک خُدائ د کور څۀ خزانې يوړې او په بابل کښې يې په خپل محل کښې کېښودې.', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles036_verse_007.mp3', NULL, 1761760676, 1761760676),
(11228, '2 Chronicles 36:8', '2 Chronicles', 36, 8, '&nbsp;يهويقيم چې هر څۀ هم کړى وُو، سره د هغۀ د خرابو رسمونو او چې هغۀ کوم حرام کارونه کړى وُو، هغه د اِسرائيل او د يهوداه د بادشاهانو په تاريخ کښې ليکلے شوى دى. نو د هغۀ زوئ يهوياکين د هغۀ نه پس بادشاه جوړ شو.', NULL, '&nbsp;يهويقيم چې هر څۀ هم کړى وُو، سره د هغۀ د خرابو رسمونو او چې هغۀ کوم حرام کارونه کړى وُو، هغه د اِسرائيل او د يهوداه د بادشاهانو په تاريخ کښې ليکلے شوى دى. نو د هغۀ زوئ يهوياکين د هغۀ نه پس بادشاه جوړ شو.', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles036_verse_008.mp3', NULL, 1761760676, 1761760676),
(11229, '2 Chronicles 36:9', '2 Chronicles', 36, 9, '&nbsp;يهوياکين د اتلسو کالو وو چې هغه د يهوداه بادشاه شو او هغۀ په يروشلم درې مياشتې او لس ورځې بادشاهى وکړه. هغۀ هم د مالِک خُدائ خِلاف ګناه وکړه.', NULL, '&nbsp;يهوياکين د اتلسو کالو وو چې هغه د يهوداه بادشاه شو او هغۀ په يروشلم درې مياشتې او لس ورځې بادشاهى وکړه. هغۀ هم د مالِک خُدائ خِلاف ګناه وکړه.', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles036_verse_009.mp3', NULL, 1761760676, 1761760676),
(11230, '2 Chronicles 36:10', '2 Chronicles', 36, 10, '&nbsp;کله چې سپرلے شو، نو نبوکدنضر بادشاه يهوياکين بابل ته قېدى بوتلو او د مالِک خُدائ د کور خزانې يې يوړې. بيا نبوکدنضر د يهوياکين ترۀ صدقياه د يهوداه او يروشلم بادشاه جوړ کړو.', NULL, '&nbsp;کله چې سپرلے شو، نو نبوکدنضر بادشاه يهوياکين بابل ته قېدى بوتلو او د مالِک خُدائ د کور خزانې يې يوړې. بيا نبوکدنضر د يهوياکين ترۀ صدقياه د يهوداه او يروشلم بادشاه جوړ کړو.', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles036_verse_010.mp3', NULL, 1761760676, 1761760676),
(11231, '2 Chronicles 36:11', '2 Chronicles', 36, 11, '&nbsp;صدقياه د يوويشتو کالو وو چې هغه د يهوداه بادشاه شو او په يروشلم يې يوولس کاله بادشاهى وکړه.', NULL, '&nbsp;صدقياه د يوويشتو کالو وو چې هغه د يهوداه بادشاه شو او په يروشلم يې يوولس کاله بادشاهى وکړه.', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles036_verse_011.mp3', NULL, 1761760676, 1761760676),
(11232, '2 Chronicles 36:12', '2 Chronicles', 36, 12, '&nbsp;هغۀ د مالِک خُدائ خِلاف ګناه وکړه او د يرمياه پېغمبر خبرې يې په عاجزۍ سره وانۀ ورېدلې، چا چې د مالِک خُدائ خبرې کولې.', NULL, '&nbsp;هغۀ د مالِک خُدائ خِلاف ګناه وکړه او د يرمياه پېغمبر خبرې يې په عاجزۍ سره وانۀ ورېدلې، چا چې د مالِک خُدائ خبرې کولې.', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles036_verse_012.mp3', NULL, 1761760676, 1761760676),
(11233, '2 Chronicles 36:13', '2 Chronicles', 36, 13, '&nbsp;صدقياه د نبوکدنضر بادشاه خِلاف بغاوت وکړو، اګر چې هغۀ د خُدائ پاک په وړاندې دا لوظ کړے وو چې د نبوکدنضر وفادار به وى. هغه د خپل ضد په وجه نۀ توبه ګار کېدو او مالِک خُدائ، د بنى اِسرائيلو خُدائ پاک يې څۀ پرواه نۀ ساتله.', NULL, '&nbsp;صدقياه د نبوکدنضر بادشاه خِلاف بغاوت وکړو، اګر چې هغۀ د خُدائ پاک په وړاندې دا لوظ کړے وو چې د نبوکدنضر وفادار به وى. هغه د خپل ضد په وجه نۀ توبه ګار کېدو او مالِک خُدائ، د بنى اِسرائيلو خُدائ پاک يې څۀ پرواه نۀ ساتله.', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles036_verse_013.mp3', NULL, 1761760676, 1761760676),
(11234, '2 Chronicles 36:14', '2 Chronicles', 36, 14, '&nbsp;د دې نه علاوه، د يهوداه لار ښوونکى اِمامان او خلق د بُتانو په عبادت کښې د هغوئ نه ګېرچاپېره ګناهګارو قومونو په نقش قدم باندې روان وُو او د هغوئ په شان حرام کارونه يې وکړل، هغوئ د مالِک خُدائ هغه کور ناپاک کړو کوم چې مالِک خُدائ په خپله مقدس کړے وو.', NULL, '&nbsp;د دې نه علاوه، د يهوداه لار ښوونکى اِمامان او خلق د بُتانو په عبادت کښې د هغوئ نه ګېرچاپېره ګناهګارو قومونو په نقش قدم باندې روان وُو او د هغوئ په شان حرام کارونه يې وکړل، هغوئ د مالِک خُدائ هغه کور ناپاک کړو کوم چې مالِک خُدائ په خپله مقدس کړے وو.', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles036_verse_014.mp3', NULL, 1761760676, 1761760676),
(11235, '2 Chronicles 36:15', '2 Chronicles', 36, 15, '&nbsp;مالِک خُدائ د هغوئ د پلار نيکۀ خُدائ پاک د خپلو خلقو د خبردارى دپاره پېغمبران رالېږل، ځکه چې خُدائ پاک غوښتل چې هغوئ او خپل کور بچ کړى.', NULL, '&nbsp;مالِک خُدائ د هغوئ د پلار نيکۀ خُدائ پاک د خپلو خلقو د خبردارى دپاره پېغمبران رالېږل، ځکه چې خُدائ پاک غوښتل چې هغوئ او خپل کور بچ کړى.', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles036_verse_015.mp3', NULL, 1761760676, 1761760676),
(11236, '2 Chronicles 36:16', '2 Chronicles', 36, 16, '&nbsp;خو هغوئ د خُدائ پاک په پېغام وړونکو پورې ټوقې وکړې، د هغوئ خبرو ته يې توجو ورنۀ کړه او د هغۀ په پېغمبرانو پورې يې خندا وکړه، تر دې پورې چې د مالِک خُدائ غصه د هغۀ د خلقو خِلاف دومره زياته شوه چې د هغې نه د خلاصون لار نۀ وه.', NULL, '&nbsp;خو هغوئ د خُدائ پاک په پېغام وړونکو پورې ټوقې وکړې، د هغوئ خبرو ته يې توجو ورنۀ کړه او د هغۀ په پېغمبرانو پورې يې خندا وکړه، تر دې پورې چې د مالِک خُدائ غصه د هغۀ د خلقو خِلاف دومره زياته شوه چې د هغې نه د خلاصون لار نۀ وه.', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles036_verse_016.mp3', NULL, 1761760676, 1761760676),
(11237, '2 Chronicles 36:17', '2 Chronicles', 36, 17, '&nbsp;نو مالِک خُدائ د بابل بادشاه راوستو چې په هغوئ حمله وکړى، تر دې چې د مالِک خُدائ په کور کښې هم هغۀ د يهوداه زلمى ووژل. هغۀ په ځوان يا بوډا، په نر يا ښځه، بيمار يا روغ په هيچا هم رحم نۀ کولو. خُدائ پاک هغوئ ټول ورته حواله کړل.', NULL, '&nbsp;نو مالِک خُدائ د بابل بادشاه راوستو چې په هغوئ حمله وکړى، تر دې چې د مالِک خُدائ په کور کښې هم هغۀ د يهوداه زلمى ووژل. هغۀ په ځوان يا بوډا، په نر يا ښځه، بيمار يا روغ په هيچا هم رحم نۀ کولو. خُدائ پاک هغوئ ټول ورته حواله کړل.', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles036_verse_017.mp3', NULL, 1761760676, 1761760676),
(11238, '2 Chronicles 36:18', '2 Chronicles', 36, 18, '&nbsp;د بابل بادشاه د مالِک خُدائ کور، د دې خزانې او د بادشاه او د هغۀ د آفسرانو دولت لوټ کړو او هر څۀ يې بابل ته يوړل.', NULL, '&nbsp;د بابل بادشاه د مالِک خُدائ کور، د دې خزانې او د بادشاه او د هغۀ د آفسرانو دولت لوټ کړو او هر څۀ يې بابل ته يوړل.', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles036_verse_018.mp3', NULL, 1761760676, 1761760676),
(11239, '2 Chronicles 36:19', '2 Chronicles', 36, 19, '&nbsp;هغۀ د مالِک خُدائ کور او ښار، سره د دې ټولو محلونو او دولت وسوزولو او د ښار دېوال يې راوغورزولو.', NULL, '&nbsp;هغۀ د مالِک خُدائ کور او ښار، سره د دې ټولو محلونو او دولت وسوزولو او د ښار دېوال يې راوغورزولو.', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles036_verse_019.mp3', NULL, 1761760676, 1761760676),
(11240, '2 Chronicles 36:20', '2 Chronicles', 36, 20, '&nbsp;هغۀ ټول ژوندى پاتې کسان بابل ته بوتلل، چرته چې هغوئ او د هغوئ اولاد تر هغې پورې د نوکرانو په توګه د هغۀ خِدمت کولو چې د فارس حکومت را اوچت شوے نۀ وو.', NULL, '&nbsp;هغۀ ټول ژوندى پاتې کسان بابل ته بوتلل، چرته چې هغوئ او د هغوئ اولاد تر هغې پورې د نوکرانو په توګه د هغۀ خِدمت کولو چې د فارس حکومت را اوچت شوے نۀ وو.', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles036_verse_020.mp3', NULL, 1761760676, 1761760676),
(11241, '2 Chronicles 36:21', '2 Chronicles', 36, 21, '&nbsp;د يرمياه پېغمبر په ذريعه چې د مالِک خُدائ کوم پېغام اورولے شوے وو نو هغه پوره شو چې، ”اويا کاله به هغه زمکه شاړه پرته وى، ځکه چې هغې د سبت آرام نۀ وو کړے.“', NULL, '&nbsp;د يرمياه پېغمبر په ذريعه چې د مالِک خُدائ کوم پېغام اورولے شوے وو نو هغه پوره شو چې، ”اويا کاله به هغه زمکه شاړه پرته وى، ځکه چې هغې د سبت آرام نۀ وو کړے.“', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles036_verse_021.mp3', NULL, 1761760676, 1761760676),
(11242, '2 Chronicles 36:22', '2 Chronicles', 36, 22, '&nbsp;د فارس د خورس بادشاه د بادشاهۍ په وړومبى کال مالِک خُدائ هغه څۀ رښتيا کړل چې څۀ يې د يرمياه پېغمبر په ذريعه فرمائيلى وُو. هغۀ د خورس حوصله افزائى وکړه چې دا حُکم جارى کړى او د خط په شکل کښې د هغۀ د بادشاهۍ هر ځائ ته ولېږلے شى او بيان شى:', NULL, '&nbsp;د فارس د خورس بادشاه د بادشاهۍ په وړومبى کال مالِک خُدائ هغه څۀ رښتيا کړل چې څۀ يې د يرمياه پېغمبر په ذريعه فرمائيلى وُو. هغۀ د خورس حوصله افزائى وکړه چې دا حُکم جارى کړى او د خط په شکل کښې د هغۀ د بادشاهۍ هر ځائ ته ولېږلے شى او بيان شى:', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles036_verse_022.mp3', NULL, 1761760676, 1761760676),
(11243, '2 Chronicles 36:23', '2 Chronicles', 36, 23, '&nbsp;”دا د فارس د خورس بادشاه حُکم دے. مالِک خُدائ، د آسمان خُدائ پاک زۀ په ټوله دُنيا باندې حکمران جوړ کړے يم او ما له يې دا ذمه وارى راکړې ده چې د هغۀ دپاره د يروشلم په يهوداه کښې يو کور جوړ کړم، نو تاسو ټول څوک چې د خُدائ پاک خلق يئ، هلته ځئ او مالِک خُدائ ستاسو خُدائ پاک دې ستاسو مل شى.“', NULL, '&nbsp;”دا د فارس د خورس بادشاه حُکم دے. مالِک خُدائ، د آسمان خُدائ پاک زۀ په ټوله دُنيا باندې حکمران جوړ کړے يم او ما له يې دا ذمه وارى راکړې ده چې د هغۀ دپاره د يروشلم په يهوداه کښې يو کور جوړ کړم، نو تاسو ټول څوک چې د خُدائ پاک خلق يئ، هلته ځئ او مالِک خُدائ ستاسو خُدائ پاک دې ستاسو مل شى.“', 'NT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/nt/yousafzai_2-chronicles036_verse_023.mp3', NULL, 1761760676, 1761760676),
(11244, 'Ezra 1:1', 'Ezra', 1, 1, '&nbsp;په وړومبى کال کښې چې خورس د فارس بادشاه وو، نو مالِک خُدائ هغه پېشګوئې پوره کړه چې هغۀ د يرمياه په ذريعه کړې وه. هغۀ د خورس په زړۀ کښې دا خبره واچوله چې دا فرمان وليکى او جارى يې کړى او خپلې ټولې بادشاهۍ ته يې ولېږى:', NULL, '&nbsp;په وړومبى کال کښې چې خورس د فارس بادشاه وو، نو مالِک خُدائ هغه پېشګوئې پوره کړه چې هغۀ د يرمياه په ذريعه کړې وه. هغۀ د خورس په زړۀ کښې دا خبره واچوله چې دا فرمان وليکى او جارى يې کړى او خپلې ټولې بادشاهۍ ته يې ولېږى:', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_ezra001_verse_001.mp3', NULL, 1761760676, 1761760676),
(11245, 'Ezra 1:2', 'Ezra', 1, 2, '&nbsp;”دا د فارس د بادشاه خورس حُکم دے. مالِک خُدائ، د آسمانونو خُدائ پاک زۀ په ټوله دُنيا باندې حکمران کړے يم او دا ذمه وارى يې راکړې ده چې د مالِک خُدائ دپاره په يهوداه کښې د يروشلم په ښار کښې کور جوړ کړم.', NULL, '&nbsp;”دا د فارس د بادشاه خورس حُکم دے. مالِک خُدائ، د آسمانونو خُدائ پاک زۀ په ټوله دُنيا باندې حکمران کړے يم او دا ذمه وارى يې راکړې ده چې د مالِک خُدائ دپاره په يهوداه کښې د يروشلم په ښار کښې کور جوړ کړم.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_ezra001_verse_002.mp3', NULL, 1761760676, 1761760676),
(11246, 'Ezra 1:3', 'Ezra', 1, 3, '&nbsp;هر څوک چې د هغۀ خلق وى نو هغه د يهوداه يروشلم ته تلے شئ چې د مالِک خُدائ د بنى اِسرائيلو خُدائ پاک دپاره يو کور بيا جوړ کړئ، د چا عبادت چې په يروشلم کښې کيږى. او ستاسو خُدائ پاک دې ستاسو مل شى.', NULL, '&nbsp;هر څوک چې د هغۀ خلق وى نو هغه د يهوداه يروشلم ته تلے شئ چې د مالِک خُدائ د بنى اِسرائيلو خُدائ پاک دپاره يو کور بيا جوړ کړئ، د چا عبادت چې په يروشلم کښې کيږى. او ستاسو خُدائ پاک دې ستاسو مل شى.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_ezra001_verse_003.mp3', NULL, 1761760676, 1761760676),
(11247, 'Ezra 1:4', 'Ezra', 1, 4, '&nbsp;ژوندى پاتې شوى خلق چې چرته هم اوسيږى، نو خپل ګاونډيان به ورله په مدد کښې دا څيزونه ورکړى لکه چې سپين زر، سرۀ زر، د سفر دپاره توښه، د سورلۍ ځناور او داسې نذرانې هم چې په يروشلم کښې د خُدائ پاک په کور کښې پېش کړے شى.“', NULL, '&nbsp;ژوندى پاتې شوى خلق چې چرته هم اوسيږى، نو خپل ګاونډيان به ورله په مدد کښې دا څيزونه ورکړى لکه چې سپين زر، سرۀ زر، د سفر دپاره توښه، د سورلۍ ځناور او داسې نذرانې هم چې په يروشلم کښې د خُدائ پاک په کور کښې پېش کړے شى.“', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_ezra001_verse_004.mp3', NULL, 1761760676, 1761760676),
(11248, 'Ezra 1:5', 'Ezra', 1, 5, '&nbsp;بيا د يهوداه او د بنيامين قبيلو د ډلو مشران، اِمامان او ليويان او هغه نور ټول تيار شول چې خُدائ پاک د هغوئ زړونه راپاڅولى وُو او په يروشلم کښې د مالِک خُدائ د کور د بيا جوړولو دپاره لاړل.', NULL, '&nbsp;بيا د يهوداه او د بنيامين قبيلو د ډلو مشران، اِمامان او ليويان او هغه نور ټول تيار شول چې خُدائ پاک د هغوئ زړونه راپاڅولى وُو او په يروشلم کښې د مالِک خُدائ د کور د بيا جوړولو دپاره لاړل.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_ezra001_verse_005.mp3', NULL, 1761760676, 1761760676),
(11249, 'Ezra 1:6', 'Ezra', 1, 6, '&nbsp;د هغوئ ټولو ګاونډيانو د هغوئ مدد وکړو او هغوئ له يې د سپينو زرو څيزونه، سرۀ زر، د سفر دپاره توښه، د سورلۍ دپاره ځناور او قيمتى څيزونه ورکړل، د دې هر څۀ نه علاوه رضاکارانه نذرانې يې هم ورکړې.', NULL, '&nbsp;د هغوئ ټولو ګاونډيانو د هغوئ مدد وکړو او هغوئ له يې د سپينو زرو څيزونه، سرۀ زر، د سفر دپاره توښه، د سورلۍ دپاره ځناور او قيمتى څيزونه ورکړل، د دې هر څۀ نه علاوه رضاکارانه نذرانې يې هم ورکړې.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_ezra001_verse_006.mp3', NULL, 1761760676, 1761760676),
(11250, 'Ezra 1:7', 'Ezra', 1, 7, '&nbsp;خورس بادشاه هغوئ له هغه جامونه او پيالۍ واپس ورکړې چې کومې نبوکدنضر بادشاه په يروشلم کښې د مالِک خُدائ د کور نه اوړې وې او د خپلو بُتانو په کور کښې يې اېښې وې.', NULL, '&nbsp;خورس بادشاه هغوئ له هغه جامونه او پيالۍ واپس ورکړې چې کومې نبوکدنضر بادشاه په يروشلم کښې د مالِک خُدائ د کور نه اوړې وې او د خپلو بُتانو په کور کښې يې اېښې وې.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_ezra001_verse_007.mp3', NULL, 1761760676, 1761760676),
(11251, 'Ezra 1:8', 'Ezra', 1, 8, '&nbsp;د فارس بادشاه خورس دا د شاهى خزانې مشر مِتردات ته حواله کړل، مِتردات د دې نه يو فهرست جوړ کړو او د يهوداه مشر شيسبضر له ورکړو،', NULL, '&nbsp;د فارس بادشاه خورس دا د شاهى خزانې مشر مِتردات ته حواله کړل، مِتردات د دې نه يو فهرست جوړ کړو او د يهوداه مشر شيسبضر له ورکړو،', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_ezra001_verse_008.mp3', NULL, 1761760676, 1761760676),
(11252, 'Ezra 1:11', 'Ezra', 1, 11, '&nbsp;هلته ټول پينځۀ زره او څلور سوه د سرو زرو او سپينو زرو لوښى وُو او هغه نور سامان وو کوم چې شيسبضر په هغه وخت کښې د ځان سره وړے وو چې کله هغه او نور جلاوطن شوى کسان د بابل نه يروشلم ته تلل.', NULL, '&nbsp;هلته ټول پينځۀ زره او څلور سوه د سرو زرو او سپينو زرو لوښى وُو او هغه نور سامان وو کوم چې شيسبضر په هغه وخت کښې د ځان سره وړے وو چې کله هغه او نور جلاوطن شوى کسان د بابل نه يروشلم ته تلل.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761760676, 1761760676),
(11253, 'Ezra 2:1', 'Ezra', 2, 1, '&nbsp;دا د يهوديانو د جلاوطن شوو خلقو تفصيل دے څوک چې د آزادېدو نه پس واپس خپلو صُوبو ته تلل. نبوکدنضر بادشاه هغوئ بابل ته قېديان بوتلى وُو، خو اوس يروشلم، يهوداه او خپلو نورو ښارونو ته راواپس شول چرته چې هغوئ مخکښې اوسېدل.', NULL, '&nbsp;دا د يهوديانو د جلاوطن شوو خلقو تفصيل دے څوک چې د آزادېدو نه پس واپس خپلو صُوبو ته تلل. نبوکدنضر بادشاه هغوئ بابل ته قېديان بوتلى وُو، خو اوس يروشلم، يهوداه او خپلو نورو ښارونو ته راواپس شول چرته چې هغوئ مخکښې اوسېدل.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_ezra002_verse_001.mp3', NULL, 1761760676, 1761760676),
(11254, 'Ezra 2:2', 'Ezra', 2, 2, '&nbsp;د هغوئ مشران زرُبابل، يشوَع، نحمياه، شراياه، رعلاياه، مردکى، بِلشان، مِسفار، بِګوئ، رحُوم او بعنه وُو. دا د بنى اِسرائيلو د ډلو تفصيل دے، دا تفصيل د هغه هرې قبيلې د شمېر سره دے کوم چې د جلاوطنۍ نه راواپس شوى وُو:', NULL, '&nbsp;د هغوئ مشران زرُبابل، يشوَع، نحمياه، شراياه، رعلاياه، مردکى، بِلشان، مِسفار، بِګوئ، رحُوم او بعنه وُو. دا د بنى اِسرائيلو د ډلو تفصيل دے، دا تفصيل د هغه هرې قبيلې د شمېر سره دے کوم چې د جلاوطنۍ نه راواپس شوى وُو:', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_ezra002_verse_002.mp3', NULL, 1761760676, 1761760676),
(11255, 'Ezra 2:58', 'Ezra', 2, 58, '&nbsp;د مالِک خُدائ د کور د خِدمتګارانو د اولاد او د سليمان د نوکرانو د اولاد ټول شمېر اتۀ کم څلور سوه وو کوم چې د جلاوطنۍ نه راواپس شول.', NULL, '&nbsp;د مالِک خُدائ د کور د خِدمتګارانو د اولاد او د سليمان د نوکرانو د اولاد ټول شمېر اتۀ کم څلور سوه وو کوم چې د جلاوطنۍ نه راواپس شول.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761760676, 1761760676),
(11256, 'Ezra 2:63', 'Ezra', 2, 63, '&nbsp;د يهوداه حکمران ورته وئيلى وُو چې هغوئ تر هغه وخته پورې خُدائ پاک ته پېش کړے شوے خوراک نۀ شى خوړلے چې ترڅو يو داسې اِمام نۀ وى چې هغه اُوريم او تميم نه کار واخلى.', NULL, '&nbsp;د يهوداه حکمران ورته وئيلى وُو چې هغوئ تر هغه وخته پورې خُدائ پاک ته پېش کړے شوے خوراک نۀ شى خوړلے چې ترڅو يو داسې اِمام نۀ وى چې هغه اُوريم او تميم نه کار واخلى.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761760676, 1761760676),
(11257, 'Ezra 2:68', 'Ezra', 2, 68, '&nbsp;کله چې جلاوطن شوى کسان په يروشلم کښې د مالِک خُدائ کور ته راورسېدل، نو د ډلو څۀ مشرانو رضاکارانه نذرانې د دې دپاره ورکړې چې د مالِک خُدائ کور په خپل زوړ ځائ کښې بيا جوړ کړى.', NULL, '&nbsp;کله چې جلاوطن شوى کسان په يروشلم کښې د مالِک خُدائ کور ته راورسېدل، نو د ډلو څۀ مشرانو رضاکارانه نذرانې د دې دپاره ورکړې چې د مالِک خُدائ کور په خپل زوړ ځائ کښې بيا جوړ کړى.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761760676, 1761760676),
(11258, 'Ezra 2:69', 'Ezra', 2, 69, '&nbsp;هغوئ چې د دې کار دپاره څومره نذرانې ورکولے شوې نو هغه هومره يې ورکړې او ټول پينځۀ سوه کلو سرۀ زر، دوه زره او اتۀ سوه کلو سپين زر او د اِمامانو دپاره سل چُوغې ورکړې.', NULL, '&nbsp;هغوئ چې د دې کار دپاره څومره نذرانې ورکولے شوې نو هغه هومره يې ورکړې او ټول پينځۀ سوه کلو سرۀ زر، دوه زره او اتۀ سوه کلو سپين زر او د اِمامانو دپاره سل چُوغې ورکړې.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761760676, 1761760676),
(11259, 'Ezra 2:70', 'Ezra', 2, 70, '&nbsp;اِمامان، ليويان او څۀ خلق په يروشلم کښې يا د دې سره نزدې دېره شول، موسيقاران، د مالِک خُدائ د کور څوکيداران او د مالِک خُدائ د کور خِدمتګاران په نزدې ښارونو کښې دېره شول، او باقى نور بنى اِسرائيليان په هغه ښارونو کښې دېره شول چرته چې د هغوئ پلار نيکۀ اوسېدلى وُو.', NULL, '&nbsp;اِمامان، ليويان او څۀ خلق په يروشلم کښې يا د دې سره نزدې دېره شول، موسيقاران، د مالِک خُدائ د کور څوکيداران او د مالِک خُدائ د کور خِدمتګاران په نزدې ښارونو کښې دېره شول، او باقى نور بنى اِسرائيليان په هغه ښارونو کښې دېره شول چرته چې د هغوئ پلار نيکۀ اوسېدلى وُو.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761760676, 1761760676),
(11260, 'Ezra 3:1', 'Ezra', 3, 1, '&nbsp;په اوومه مياشت کښې ټول بنى اِسرائيل په خپلو خپلو ښارونو کښې دېره شول. بيا هغوئ ټول په يروشلم کښې په اتفاق سره راغونډ شول،', NULL, '&nbsp;په اوومه مياشت کښې ټول بنى اِسرائيل په خپلو خپلو ښارونو کښې دېره شول. بيا هغوئ ټول په يروشلم کښې په اتفاق سره راغونډ شول،', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_ezra003_verse_001.mp3', NULL, 1761760676, 1761760676),
(11261, 'Ezra 3:2', 'Ezra', 3, 2, '&nbsp;او د يوصدق زوئ يشوَع، د هغۀ ملګرو اِمامانو او د شلتى‌اېل زوئ زرُبابل سره د خپلو رشته‌دارانو، د بنى اِسرائيلو د خُدائ پاک قربان‌ګاه بيا جوړه کړه، نو چې هغوئ په دې باندې د هغه اصُولو په مطابق قربانۍ وسوزوى کوم چې د موسىٰ په شريعت کښې ليکلے شوى وُو، موسىٰ د خُدائ پاک خِدمتګار وو.', NULL, '&nbsp;او د يوصدق زوئ يشوَع، د هغۀ ملګرو اِمامانو او د شلتى‌اېل زوئ زرُبابل سره د خپلو رشته‌دارانو، د بنى اِسرائيلو د خُدائ پاک قربان‌ګاه بيا جوړه کړه، نو چې هغوئ په دې باندې د هغه اصُولو په مطابق قربانۍ وسوزوى کوم چې د موسىٰ په شريعت کښې ليکلے شوى وُو، موسىٰ د خُدائ پاک خِدمتګار وو.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_ezra003_verse_002.mp3', NULL, 1761760676, 1761760676),
(11262, 'Ezra 3:3', 'Ezra', 3, 3, '&nbsp;اګر چې د جلاوطنۍ نه واپس راتلونکى کسان بيا هم د هغه خلقو نه يرېدل کوم چې په هغه مُلک کښې اوسېدل، هغوئ قربان‌ګاه په هغه ځائ کښې بيا جوړه کړه چرته چې مخکښې ولاړه وه. بيا هغوئ يو ځل بيا په هغې باندې د هر سحر او هر ماښام نذرانې سوزول شروع کړل.', NULL, '&nbsp;اګر چې د جلاوطنۍ نه واپس راتلونکى کسان بيا هم د هغه خلقو نه يرېدل کوم چې په هغه مُلک کښې اوسېدل، هغوئ قربان‌ګاه په هغه ځائ کښې بيا جوړه کړه چرته چې مخکښې ولاړه وه. بيا هغوئ يو ځل بيا په هغې باندې د هر سحر او هر ماښام نذرانې سوزول شروع کړل.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_ezra003_verse_003.mp3', NULL, 1761760676, 1761760676),
(11263, 'Ezra 3:4', 'Ezra', 3, 4, '&nbsp;هغوئ د اصُولو په مطابق د جونګړو اختر وکړو، هغوئ هره ورځ د هغه ورځې مقررې قربانۍ پېش کولې،', NULL, '&nbsp;هغوئ د اصُولو په مطابق د جونګړو اختر وکړو، هغوئ هره ورځ د هغه ورځې مقررې قربانۍ پېش کولې،', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_ezra003_verse_004.mp3', NULL, 1761760676, 1761760676),
(11264, 'Ezra 3:5', 'Ezra', 3, 5, '&nbsp;او د دې نه علاوه هغوئ د هرې ورځې سوزېدونکې نذرانې هم پېش کولې او هغه نذرانې يې هم پېش کولې چې د نوې مياشتې په اختر او په کلنى اخترونو کښې پېش کېدلې چې په دې اخترونو کښې به د مالِک خُدائ عبادت کېدلو، او هم داسې هغه ټولې نذرانې هم پېش کېدلې کومې چې مالِک خُدائ ته په رضاکارانه توګه ورکولے شوې.', NULL, '&nbsp;او د دې نه علاوه هغوئ د هرې ورځې سوزېدونکې نذرانې هم پېش کولې او هغه نذرانې يې هم پېش کولې چې د نوې مياشتې په اختر او په کلنى اخترونو کښې پېش کېدلې چې په دې اخترونو کښې به د مالِک خُدائ عبادت کېدلو، او هم داسې هغه ټولې نذرانې هم پېش کېدلې کومې چې مالِک خُدائ ته په رضاکارانه توګه ورکولے شوې.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_ezra003_verse_005.mp3', NULL, 1761760676, 1761760676),
(11265, 'Ezra 3:6', 'Ezra', 3, 6, '&nbsp;اګر چې خلقو تر اوسه پورې د مالِک خُدائ د کور بنياد جوړول هم شروع کړى نۀ وُو، خو هغوئ د اوومې مياشتې په اوله ورځ مالِک خُدائ ته قربانۍ سوزول شروع کړل.', NULL, '&nbsp;اګر چې خلقو تر اوسه پورې د مالِک خُدائ د کور بنياد جوړول هم شروع کړى نۀ وُو، خو هغوئ د اوومې مياشتې په اوله ورځ مالِک خُدائ ته قربانۍ سوزول شروع کړل.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_ezra003_verse_006.mp3', NULL, 1761760676, 1761760676),
(11266, 'Ezra 3:7', 'Ezra', 3, 7, '&nbsp;خلقو د کاڼو ګِلکارانو او ترکاڼانو د مزدورۍ دپاره پېسې ورکولې او خوراک، څښاک او د زيتُونو تېل يې د صور او صيدا خلقو له لېږل او د دې څيزونو په بدل کښې د لبنان د غرونو نه د دِيار لرګى د يافا ښار ته د سمندر په ذريعه راوړلے کېدل. دا هر څۀ د فارس د بادشاه خورس په اجازت سره کېدل.', NULL, '&nbsp;خلقو د کاڼو ګِلکارانو او ترکاڼانو د مزدورۍ دپاره پېسې ورکولې او خوراک، څښاک او د زيتُونو تېل يې د صور او صيدا خلقو له لېږل او د دې څيزونو په بدل کښې د لبنان د غرونو نه د دِيار لرګى د يافا ښار ته د سمندر په ذريعه راوړلے کېدل. دا هر څۀ د فارس د بادشاه خورس په اجازت سره کېدل.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_ezra003_verse_007.mp3', NULL, 1761760676, 1761760676),
(11267, 'Ezra 3:8', 'Ezra', 3, 8, '&nbsp;د هغې نه پس چې هغوئ په يروشلم کښې د مالِک خُدائ د کور ځائ ته واپس راغلى وُو نو د هغه کال په دوېمه مياشت يې کار شروع کړو. زرُبابل، يشوَع او د هغۀ نور وطنداران، اِمامان او ليويان او هغه ټول خلق په کار کښې شامل شول کوم چې د جلاوطنۍ نه يروشلم ته واپس راغلى وُو. هغه ټول ليويان چې د هغوئ عُمر شل کاله يا د دې نه زيات وو هغوئ د مالِک خُدائ د کور د بيا جوړېدو مشران مقرر شول.', NULL, '&nbsp;د هغې نه پس چې هغوئ په يروشلم کښې د مالِک خُدائ د کور ځائ ته واپس راغلى وُو نو د هغه کال په دوېمه مياشت يې کار شروع کړو. زرُبابل، يشوَع او د هغۀ نور وطنداران، اِمامان او ليويان او هغه ټول خلق په کار کښې شامل شول کوم چې د جلاوطنۍ نه يروشلم ته واپس راغلى وُو. هغه ټول ليويان چې د هغوئ عُمر شل کاله يا د دې نه زيات وو هغوئ د مالِک خُدائ د کور د بيا جوړېدو مشران مقرر شول.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_ezra003_verse_008.mp3', NULL, 1761760676, 1761760676),
(11268, 'Ezra 3:9', 'Ezra', 3, 9, '&nbsp;ليوى يشوَع او د هغۀ زامنو او خپلوانو او د هُوداوياه د قبيلې قدمى‌اېل او د هغۀ زامنو د مالِک خُدائ د کور په بيا جوړېدو کښې په شريکه مشرى کوله. د هغوئ مدد د حنداد د قبيلې ليويانو هم کولو.', NULL, '&nbsp;ليوى يشوَع او د هغۀ زامنو او خپلوانو او د هُوداوياه د قبيلې قدمى‌اېل او د هغۀ زامنو د مالِک خُدائ د کور په بيا جوړېدو کښې په شريکه مشرى کوله. د هغوئ مدد د حنداد د قبيلې ليويانو هم کولو.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_ezra003_verse_009.mp3', NULL, 1761760676, 1761760676),
(11269, 'Ezra 3:10', 'Ezra', 3, 10, '&nbsp;کله چې ګِلکارانو د مالِک خُدائ د کور بنياد کېښودل شروع کړل، نو اِمامان په خپلو ځايونو باندې ولاړ وُو، چُوغې يې اغوستې وې او بيګل د هغوئ په لاسونو کښې وُو او د آسف د قبېلې ليويان د چمټو سره هلته ولاړ وُو. هغوئ د مالِک خُدائ ثناء صِفت د هغه اصُولو په مطابق کولو کوم اصُول چې داؤد بادشاه ښودلى وُو.', NULL, '&nbsp;کله چې ګِلکارانو د مالِک خُدائ د کور بنياد کېښودل شروع کړل، نو اِمامان په خپلو ځايونو باندې ولاړ وُو، چُوغې يې اغوستې وې او بيګل د هغوئ په لاسونو کښې وُو او د آسف د قبېلې ليويان د چمټو سره هلته ولاړ وُو. هغوئ د مالِک خُدائ ثناء صِفت د هغه اصُولو په مطابق کولو کوم اصُول چې داؤد بادشاه ښودلى وُو.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_ezra003_verse_010.mp3', NULL, 1761760676, 1761760676),
(11270, 'Ezra 3:11', 'Ezra', 3, 11, '&nbsp;هغوئ وار په وار د مالِک خُدائ ثناء صِفت کولو، ”مالِک خُدائ مهربان دے او د بنى اِسرائيلو سره د هغۀ مينه د همېشه دپاره ده.“ هر چا به په اوچت آواز سره د مالِک خُدائ ثناء صِفت کولو، ځکه چې د مالِک خُدائ د کور د بنياد کار شروع شوے وو.', NULL, '&nbsp;هغوئ وار په وار د مالِک خُدائ ثناء صِفت کولو، ”مالِک خُدائ مهربان دے او د بنى اِسرائيلو سره د هغۀ مينه د همېشه دپاره ده.“ هر چا به په اوچت آواز سره د مالِک خُدائ ثناء صِفت کولو، ځکه چې د مالِک خُدائ د کور د بنياد کار شروع شوے وو.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_ezra003_verse_011.mp3', NULL, 1761760676, 1761760676),
(11271, 'Ezra 3:12', 'Ezra', 3, 12, '&nbsp;چې کله د مالِک خُدائ د دې کور بنياد کېښودے شو نو کومو ډېرو بوډاګانو اِمامانو، ليويانو او د ډلو مشرانو چې د مالِک خُدائ هغه وړومبے کور ليدلے وو، نو په چغو يې وژړل. خو چې هلته نور کوم خلق وُو هغوئ د خوشحالۍ نه چغې وهلې.', NULL, '&nbsp;چې کله د مالِک خُدائ د دې کور بنياد کېښودے شو نو کومو ډېرو بوډاګانو اِمامانو، ليويانو او د ډلو مشرانو چې د مالِک خُدائ هغه وړومبے کور ليدلے وو، نو په چغو يې وژړل. خو چې هلته نور کوم خلق وُو هغوئ د خوشحالۍ نه چغې وهلې.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_ezra003_verse_012.mp3', NULL, 1761760676, 1761760676),
(11272, 'Ezra 3:13', 'Ezra', 3, 13, '&nbsp;څۀ خلقو د خوشحالۍ نه چغې وهلې او څۀ خلقو ژړا کوله، او هغوئ دومره شور کولو چې تر لرې لرې پورې اورېدلے شو او هيچا ته پته نۀ لګېده چې څوک ژاړى او څوک خوشحاله دى.', NULL, '&nbsp;څۀ خلقو د خوشحالۍ نه چغې وهلې او څۀ خلقو ژړا کوله، او هغوئ دومره شور کولو چې تر لرې لرې پورې اورېدلے شو او هيچا ته پته نۀ لګېده چې څوک ژاړى او څوک خوشحاله دى.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_ezra003_verse_013.mp3', NULL, 1761760676, 1761760676),
(11273, 'Ezra 4:1', 'Ezra', 4, 1, '&nbsp;د يهوداه او بنيامين د خلقو دشمنان د دې نه خبر شول چې کوم خلق د جلاوطنۍ نه راواپس شوى دى نو هغوئ د مالِک خُدائ د بنى اِسرائيلو د خُدائ پاک کور بيا جوړوى.', NULL, '&nbsp;د يهوداه او بنيامين د خلقو دشمنان د دې نه خبر شول چې کوم خلق د جلاوطنۍ نه راواپس شوى دى نو هغوئ د مالِک خُدائ د بنى اِسرائيلو د خُدائ پاک کور بيا جوړوى.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_ezra004_verse_001.mp3', NULL, 1761760676, 1761760676),
(11274, 'Ezra 4:2', 'Ezra', 4, 2, '&nbsp;نو هغوئ د زرُبابل او د ډلو مشرانو سره مِلاوېدو له راغلل او ورته يې ووئيل، ”د مالِک خُدائ په کور جوړولو کښې به مونږ هم درسره ملګرى شُو. مونږ هم د هغه خُدائ پاک عبادت کوُو د کوم چې تاسو کوئ، مونږ هغۀ ته قربانۍ پېش کوُو د اسور بادشاه اسرحدون د وخت نه چا چې مونږ دلته د اوسېدو دپاره راولېږلو.“', NULL, '&nbsp;نو هغوئ د زرُبابل او د ډلو مشرانو سره مِلاوېدو له راغلل او ورته يې ووئيل، ”د مالِک خُدائ په کور جوړولو کښې به مونږ هم درسره ملګرى شُو. مونږ هم د هغه خُدائ پاک عبادت کوُو د کوم چې تاسو کوئ، مونږ هغۀ ته قربانۍ پېش کوُو د اسور بادشاه اسرحدون د وخت نه چا چې مونږ دلته د اوسېدو دپاره راولېږلو.“', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_ezra004_verse_002.mp3', NULL, 1761760676, 1761760676),
(11275, 'Ezra 4:3', 'Ezra', 4, 3, '&nbsp;نو زرُبابل، يشوَع او د ډلو مشرانو هغوئ ته ووئيل، ”مونږ ته د مالِک خُدائ زمونږ د خُدائ پاک په کور جوړولو کښې ستاسو د مدد هيڅ ضرورت نشته. مونږ به دا په خپله جوړوُو هم هغه شان چې څنګه د فارس بادشاه خورس حُکم راکړے دے.“', NULL, '&nbsp;نو زرُبابل، يشوَع او د ډلو مشرانو هغوئ ته ووئيل، ”مونږ ته د مالِک خُدائ زمونږ د خُدائ پاک په کور جوړولو کښې ستاسو د مدد هيڅ ضرورت نشته. مونږ به دا په خپله جوړوُو هم هغه شان چې څنګه د فارس بادشاه خورس حُکم راکړے دے.“', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_ezra004_verse_003.mp3', NULL, 1761760676, 1761760676),
(11276, 'Ezra 4:4', 'Ezra', 4, 4, '&nbsp;او چې کوم خلق په هغه مُلک کښې اوسېدل نو هغوئ دا کوشش کولو چې يهوديان بې‌حوصلې کړى او د مالِک خُدائ د کور جوړولو نه يې ويروى.', NULL, '&nbsp;او چې کوم خلق په هغه مُلک کښې اوسېدل نو هغوئ دا کوشش کولو چې يهوديان بې‌حوصلې کړى او د مالِک خُدائ د کور جوړولو نه يې ويروى.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_ezra004_verse_004.mp3', NULL, 1761760676, 1761760676),
(11277, 'Ezra 4:5', 'Ezra', 4, 5, '&nbsp;هغوئ د فارس د حکومت آفسرانو له د دې دپاره رشوت هم ورکولو چې د هغوئ خِلاف کار وکړى. هغوئ د فارس بادشاه خورس په ټوله بادشاهۍ کښې داسې کول او هغوئ د فارس بادشاه داريوس د بادشاهۍ شروع کېدو پورې دا کار نۀ پرېښودو.', NULL, '&nbsp;هغوئ د فارس د حکومت آفسرانو له د دې دپاره رشوت هم ورکولو چې د هغوئ خِلاف کار وکړى. هغوئ د فارس بادشاه خورس په ټوله بادشاهۍ کښې داسې کول او هغوئ د فارس بادشاه داريوس د بادشاهۍ شروع کېدو پورې دا کار نۀ پرېښودو.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_ezra004_verse_005.mp3', NULL, 1761760676, 1761760676),
(11278, 'Ezra 4:6', 'Ezra', 4, 6, '&nbsp;د اخسويرس بادشاه د بادشاهۍ په شروع کښې، د يهوداه او يروشلم خلقو دشمنانو د هغوئ خِلاف يو ليکلے شوے اِلزام راوړو.', NULL, '&nbsp;د اخسويرس بادشاه د بادشاهۍ په شروع کښې، د يهوداه او يروشلم خلقو دشمنانو د هغوئ خِلاف يو ليکلے شوے اِلزام راوړو.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_ezra004_verse_006.mp3', NULL, 1761760676, 1761760676),
(11279, 'Ezra 4:7', 'Ezra', 4, 7, '&nbsp;يو ځل بيا د فارس بادشاه ارتخششتا په دوران کښې، بِشلام، مِتردات، طابئيل او د هغوئ ملګرو بادشاه ته يو خط وليکلو. هغه خط په آرامى ژبه کښې ليکلے شوے وو او بيا د بادشاه دپاره ترجمه کړے شو.', NULL, '&nbsp;يو ځل بيا د فارس بادشاه ارتخششتا په دوران کښې، بِشلام، مِتردات، طابئيل او د هغوئ ملګرو بادشاه ته يو خط وليکلو. هغه خط په آرامى ژبه کښې ليکلے شوے وو او بيا د بادشاه دپاره ترجمه کړے شو.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_ezra004_verse_007.mp3', NULL, 1761760676, 1761760676),
(11280, 'Ezra 4:8', 'Ezra', 4, 8, '&nbsp;رحُوم حکمران او د صُوبې منشى شِمسى هم د يروشلم په حقله ارتخششتا بادشاه ته دا خط وليکلو،', NULL, '&nbsp;رحُوم حکمران او د صُوبې منشى شِمسى هم د يروشلم په حقله ارتخششتا بادشاه ته دا خط وليکلو،', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_ezra004_verse_008.mp3', NULL, 1761760676, 1761760676),
(11281, 'Ezra 4:9', 'Ezra', 4, 9, '&nbsp;”د حکمران رحُوم، د صُوبې منشى شِمسى، د هغوئ د ملګرو، قاضيانو او د نورو ټولو آفسرانو نه، کوم چې د عيلام په مُلک کښې د ارک، بابل او د سوسه سړى دى،', NULL, '&nbsp;”د حکمران رحُوم، د صُوبې منشى شِمسى، د هغوئ د ملګرو، قاضيانو او د نورو ټولو آفسرانو نه، کوم چې د عيلام په مُلک کښې د ارک، بابل او د سوسه سړى دى،', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_ezra004_verse_009.mp3', NULL, 1761760676, 1761760676),
(11282, 'Ezra 4:10', 'Ezra', 4, 10, '&nbsp;د هغه نورو خلقو په شمول کوم چې عظيم او عزتمند اسور‌بنى‌پال د خپلو کورونو نه بوتلل او د سامريه په ښار کښې او د فرات سيند نمرپرېواتۀ طرف ته سامريه کښې په نورو ځايونو کښې يې دېره کړل.“', NULL, '&nbsp;د هغه نورو خلقو په شمول کوم چې عظيم او عزتمند اسور‌بنى‌پال د خپلو کورونو نه بوتلل او د سامريه په ښار کښې او د فرات سيند نمرپرېواتۀ طرف ته سامريه کښې په نورو ځايونو کښې يې دېره کړل.“', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_ezra004_verse_010.mp3', NULL, 1761760676, 1761760676),
(11283, 'Ezra 4:11', 'Ezra', 4, 11, '&nbsp;په خط کښې داسې ليکلے شوى وُو، ”د فرات سيند نمرپرېواتۀ په طرف د هغۀ د خِدمتګارانو نه، ارتخششتا بادشاه ته.', NULL, '&nbsp;په خط کښې داسې ليکلے شوى وُو، ”د فرات سيند نمرپرېواتۀ په طرف د هغۀ د خِدمتګارانو نه، ارتخششتا بادشاه ته.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_ezra004_verse_011.mp3', NULL, 1761760676, 1761760676),
(11284, 'Ezra 4:12', 'Ezra', 4, 12, '&nbsp;بادشاه سلامت، مونږ تا خبرول غواړُو چې هغه يهوديان کوم ستا د نورو علاقو نه راغلى دى هغوئ په يروشلم کښې دېره شوى دى او هغه خراب او سرکشه ښار بيا جوړوى. هغوئ د دېوالونو بيا جوړول شروع کړى دى او ډېر زر به يې تيار کړى.', NULL, '&nbsp;بادشاه سلامت، مونږ تا خبرول غواړُو چې هغه يهوديان کوم ستا د نورو علاقو نه راغلى دى هغوئ په يروشلم کښې دېره شوى دى او هغه خراب او سرکشه ښار بيا جوړوى. هغوئ د دېوالونو بيا جوړول شروع کړى دى او ډېر زر به يې تيار کړى.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_ezra004_verse_012.mp3', NULL, 1761760676, 1761760676),
(11285, 'Ezra 4:13', 'Ezra', 4, 13, '&nbsp;بادشاه سلامت، کۀ دا ښار بيا جوړ شى او د دې دېوالونه سر ته ورسيږى، نو خلق به محصُول، جزيه او پېسې ورکول بند کړى او ستا شاهى محصُول به کم شى.', NULL, '&nbsp;بادشاه سلامت، کۀ دا ښار بيا جوړ شى او د دې دېوالونه سر ته ورسيږى، نو خلق به محصُول، جزيه او پېسې ورکول بند کړى او ستا شاهى محصُول به کم شى.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_ezra004_verse_013.mp3', NULL, 1761760676, 1761760676),
(11286, 'Ezra 4:14', 'Ezra', 4, 14, '&nbsp;نو بادشاه سلامت، مونږ ستا وفادار يُو او مونږ نۀ غواړُو چې د بادشاه دې داسې بې‌عزتى وشى، نو دا ځکه مونږ بادشاه له دا خبر ورلېږلے دے،', NULL, '&nbsp;نو بادشاه سلامت، مونږ ستا وفادار يُو او مونږ نۀ غواړُو چې د بادشاه دې داسې بې‌عزتى وشى، نو دا ځکه مونږ بادشاه له دا خبر ورلېږلے دے،', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_ezra004_verse_014.mp3', NULL, 1761760676, 1761760676),
(11287, 'Ezra 4:15', 'Ezra', 4, 15, '&nbsp;چې تۀ دا حُکم ورکړه چې هغه تاريخ دې ولټولے شى کوم چې ستا پلار نيکۀ ليکلے وو. نو بيا به تا ته پته ولګى چې دا ښار همېشه د بغاوت نه ډک وى او د پخوانى وختونو نه دې بادشاهانو او د صُوبو حکمرانانو له تکليف ورکړے دے. د دې په خلقو باندې حکومت کول همېشه مشکل وُو. نو په دې وجه دا ښار تباه شوے وو.', NULL, '&nbsp;چې تۀ دا حُکم ورکړه چې هغه تاريخ دې ولټولے شى کوم چې ستا پلار نيکۀ ليکلے وو. نو بيا به تا ته پته ولګى چې دا ښار همېشه د بغاوت نه ډک وى او د پخوانى وختونو نه دې بادشاهانو او د صُوبو حکمرانانو له تکليف ورکړے دے. د دې په خلقو باندې حکومت کول همېشه مشکل وُو. نو په دې وجه دا ښار تباه شوے وو.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_ezra004_verse_015.mp3', NULL, 1761760676, 1761760676),
(11288, 'Ezra 4:16', 'Ezra', 4, 16, '&nbsp;نو په دې وجه زمونږ دا يقين دے کۀ دا ښار بيا جوړ شى او د دې دېوالونه مکمل شى، نو بادشاه سلامت، د فرات سيند نمرپرېواتۀ طرف ته صُوبه به ستا د قابو نه بهر شى.“', NULL, '&nbsp;نو په دې وجه زمونږ دا يقين دے کۀ دا ښار بيا جوړ شى او د دې دېوالونه مکمل شى، نو بادشاه سلامت، د فرات سيند نمرپرېواتۀ طرف ته صُوبه به ستا د قابو نه بهر شى.“', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_ezra004_verse_016.mp3', NULL, 1761760676, 1761760676),
(11289, 'Ezra 4:17', 'Ezra', 4, 17, '&nbsp;نو بادشاه دا جواب ورولېږلو، ”رحُوم حکمران، د صُوبې منشى شِمسى او د هغوئ هغه ملګرو ته چې کوم په سامريه کښې اوسيږى او د فرات سيند نمرپرېواتۀ طرف ټولو خلقو ته، سلامونه.', NULL, '&nbsp;نو بادشاه دا جواب ورولېږلو، ”رحُوم حکمران، د صُوبې منشى شِمسى او د هغوئ هغه ملګرو ته چې کوم په سامريه کښې اوسيږى او د فرات سيند نمرپرېواتۀ طرف ټولو خلقو ته، سلامونه.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_ezra004_verse_017.mp3', NULL, 1761760676, 1761760676),
(11290, 'Ezra 4:18', 'Ezra', 4, 18, '&nbsp;کوم خط چې تاسو رالېږلے دے هغه لوستلے شوے دے او زما په وړاندې ترجمه شوے دے.', NULL, '&nbsp;کوم خط چې تاسو رالېږلے دے هغه لوستلے شوے دے او زما په وړاندې ترجمه شوے دے.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_ezra004_verse_018.mp3', NULL, 1761760676, 1761760676),
(11291, 'Ezra 4:19', 'Ezra', 4, 19, '&nbsp;ما حُکم وکړو چې تفتيش دې وکړے شى او دا خبره معلومه کړے شوې ده چې يروشلم بې‌شکه د پخوا نه د بادشاهانو خِلاف بغاوت کولو او دا د باغيانو او سرکشه خلقو نه ډک وو.', NULL, '&nbsp;ما حُکم وکړو چې تفتيش دې وکړے شى او دا خبره معلومه کړے شوې ده چې يروشلم بې‌شکه د پخوا نه د بادشاهانو خِلاف بغاوت کولو او دا د باغيانو او سرکشه خلقو نه ډک وو.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_ezra004_verse_019.mp3', NULL, 1761760676, 1761760676),
(11292, 'Ezra 4:20', 'Ezra', 4, 20, '&nbsp;هلته طاقتورو بادشاهانو بادشاهى کړې ده او د فرات سيند نمرپرېواتۀ طرف ته په ټوله صُوبه يې حکومت کړے دے او جزيه، محصُول او پېسې يې راټولولې.', NULL, '&nbsp;هلته طاقتورو بادشاهانو بادشاهى کړې ده او د فرات سيند نمرپرېواتۀ طرف ته په ټوله صُوبه يې حکومت کړے دے او جزيه، محصُول او پېسې يې راټولولې.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_ezra004_verse_020.mp3', NULL, 1761760676, 1761760676),
(11293, 'Ezra 4:21', 'Ezra', 4, 21, '&nbsp;نو په دې وجه تۀ به فرمان جارى کړې چې ترڅو پورې ما بل حُکم نۀ وى درکړے نو هغه خلق دې د ښار په جوړولو باندې کار بند کړى.', NULL, '&nbsp;نو په دې وجه تۀ به فرمان جارى کړې چې ترڅو پورې ما بل حُکم نۀ وى درکړے نو هغه خلق دې د ښار په جوړولو باندې کار بند کړى.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_ezra004_verse_021.mp3', NULL, 1761760676, 1761760676),
(11294, 'Ezra 4:22', 'Ezra', 4, 22, '&nbsp;دا کار سمدستى وکړئ چې داسې زما فائدې ته نور تاوان ونۀ رسيږى.“', NULL, '&nbsp;دا کار سمدستى وکړئ چې داسې زما فائدې ته نور تاوان ونۀ رسيږى.“', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_ezra004_verse_022.mp3', NULL, 1761760676, 1761760676),
