(11297, 'Ezra 5:1', 'Ezra', 5, 1, '&nbsp;په هغه وخت کښې دوه پېغمبران حجى او د عدو زوئ زکرياه وُو. هغوئ په يهوداه او يروشلم کښې اوسېدونکو يهوديانو له د بنى اِسرائيلو هغه خُدائ پاک په نوم پېشګوئې ورکوله چې کوم د هغوئ دپاسه وو.', NULL, '&nbsp;په هغه وخت کښې دوه پېغمبران حجى او د عدو زوئ زکرياه وُو. هغوئ په يهوداه او يروشلم کښې اوسېدونکو يهوديانو له د بنى اِسرائيلو هغه خُدائ پاک په نوم پېشګوئې ورکوله چې کوم د هغوئ دپاسه وو.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_ezra005_verse_001.mp3', NULL, 1761760676, 1761760676),
(11298, 'Ezra 5:2', 'Ezra', 5, 2, '&nbsp;کله چې د شلتى‌اېل زوئ زرُبابل او د يوصدق زوئ يشوَع د هغوئ پېغام واورېدو، نو هغوئ په يروشلم کښې د خُدائ پاک د کور بيا جوړول شروع کړل او د خُدائ پاک هغه دوه پېغمبران د هغوئ سره وُو او د هغوئ مدد يې کولو.', NULL, '&nbsp;کله چې د شلتى‌اېل زوئ زرُبابل او د يوصدق زوئ يشوَع د هغوئ پېغام واورېدو، نو هغوئ په يروشلم کښې د خُدائ پاک د کور بيا جوړول شروع کړل او د خُدائ پاک هغه دوه پېغمبران د هغوئ سره وُو او د هغوئ مدد يې کولو.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_ezra005_verse_002.mp3', NULL, 1761760676, 1761760676),
(11299, 'Ezra 5:3', 'Ezra', 5, 3, '&nbsp;نو د نمرپرېواتۀ طرف ته فرات حکمران تتنى، شتربوزنى او د هغوئ ملګرى آفسران سمدستى يروشلم ته راغلل او وې وئيل، ”تا له دا حُکم څوک درکوى چې دا کور بيا جوړ کړه او سر ته يې ورسوه؟“', NULL, '&nbsp;نو د نمرپرېواتۀ طرف ته فرات حکمران تتنى، شتربوزنى او د هغوئ ملګرى آفسران سمدستى يروشلم ته راغلل او وې وئيل، ”تا له دا حُکم څوک درکوى چې دا کور بيا جوړ کړه او سر ته يې ورسوه؟“', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_ezra005_verse_003.mp3', NULL, 1761760676, 1761760676),
(11300, 'Ezra 5:4', 'Ezra', 5, 4, '&nbsp;هغوئ د هغه ټولو سړو د نومونو تپوس هم وکړو کومو چې د دې په جوړولو کښې مدد کولو.', NULL, '&nbsp;هغوئ د هغه ټولو سړو د نومونو تپوس هم وکړو کومو چې د دې په جوړولو کښې مدد کولو.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_ezra005_verse_004.mp3', NULL, 1761760676, 1761760676),
(11301, 'Ezra 5:5', 'Ezra', 5, 5, '&nbsp;خو په يهودى مشرانو باندې د خُدائ پاک نظر وو او د فارس آفسرانو دا فېصله وکړه چې تر هغې پورې به يو کار هم نۀ کوى چې ترڅو يې داريوس بادشاه له خط نۀ وى لېږلے او جواب يې نۀ وى راغلے.', NULL, '&nbsp;خو په يهودى مشرانو باندې د خُدائ پاک نظر وو او د فارس آفسرانو دا فېصله وکړه چې تر هغې پورې به يو کار هم نۀ کوى چې ترڅو يې داريوس بادشاه له خط نۀ وى لېږلے او جواب يې نۀ وى راغلے.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_ezra005_verse_005.mp3', NULL, 1761760676, 1761760676),
(11302, 'Ezra 5:6', 'Ezra', 5, 6, '&nbsp;هغوئ داريوس بادشاه له دا خبر ورولېږلو،', NULL, '&nbsp;هغوئ داريوس بادشاه له دا خبر ورولېږلو،', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_ezra005_verse_006.mp3', NULL, 1761760676, 1761760676),
(11303, 'Ezra 5:7', 'Ezra', 5, 7, '&nbsp;”داريوس بادشاه ته ډېر ډېر سلامونه.', NULL, '&nbsp;”داريوس بادشاه ته ډېر ډېر سلامونه.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_ezra005_verse_007.mp3', NULL, 1761760676, 1761760676),
(11304, 'Ezra 5:8', 'Ezra', 5, 8, '&nbsp;بادشاه سلامت، تا ته دې پته وى چې مونږ د يهوداه صُوبې ته ورغلو او ومو ليدل چې د عظيم خُدائ پاک کور د لويو کاڼو او په دېوالونو کښې د لرګو د ستنو سره بيا جوړيږى. کار د ډېر احتياط سره کولے شى او ډېر ښۀ روان دے.', NULL, '&nbsp;بادشاه سلامت، تا ته دې پته وى چې مونږ د يهوداه صُوبې ته ورغلو او ومو ليدل چې د عظيم خُدائ پاک کور د لويو کاڼو او په دېوالونو کښې د لرګو د ستنو سره بيا جوړيږى. کار د ډېر احتياط سره کولے شى او ډېر ښۀ روان دے.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_ezra005_verse_008.mp3', NULL, 1761760676, 1761760676),
(11305, 'Ezra 5:9', 'Ezra', 5, 9, '&nbsp;مونږ بيا د خلقو د مشرانو نه تپوس وکړو چې مونږ ته ووائى چې هغوئ له دا اختيار چا ورکړ‌ے دے چې د خُدائ پاک کور بيا جوړ کړى او سر ته يې ورسوى.', NULL, '&nbsp;مونږ بيا د خلقو د مشرانو نه تپوس وکړو چې مونږ ته ووائى چې هغوئ له دا اختيار چا ورکړ‌ے دے چې د خُدائ پاک کور بيا جوړ کړى او سر ته يې ورسوى.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_ezra005_verse_009.mp3', NULL, 1761760676, 1761760676),
