(11307, 'Ezra 5:11', 'Ezra', 5, 11, '&nbsp;هغوئ مونږ له جواب راکړو چې مونږ د آسمان او زمکې د خُدائ پاک خِدمتګار يُو او مونږ هغه کور بيا جوړوُو کوم چې په اصل کښې ډېره موده مخکښې د بنى اِسرائيلو يو تکړه بادشاه جوړ کړے وو او سر ته يې رسولے وو.', NULL, '&nbsp;هغوئ مونږ له جواب راکړو چې مونږ د آسمان او زمکې د خُدائ پاک خِدمتګار يُو او مونږ هغه کور بيا جوړوُو کوم چې په اصل کښې ډېره موده مخکښې د بنى اِسرائيلو يو تکړه بادشاه جوړ کړے وو او سر ته يې رسولے وو.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_ezra005_verse_011.mp3', NULL, 1761760676, 1761760676),
(11308, 'Ezra 5:12', 'Ezra', 5, 12, '&nbsp;خو زمونږ پلار نيکۀ د آسمان خُدائ پاک غصه کړو نو په دې وجه هغوئ يې د بابل بادشاه نبوکدنضر ته پرېښودل، چا چې دا کور وران کړو او خلق يې بابل ته جلاوطن کړل.', NULL, '&nbsp;خو زمونږ پلار نيکۀ د آسمان خُدائ پاک غصه کړو نو په دې وجه هغوئ يې د بابل بادشاه نبوکدنضر ته پرېښودل، چا چې دا کور وران کړو او خلق يې بابل ته جلاوطن کړل.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_ezra005_verse_012.mp3', NULL, 1761760676, 1761760676),
