(11310, 'Ezra 5:14', 'Ezra', 5, 14, '&nbsp;هغۀ د خُدائ پاک په کور کښې د سرو زرو او سپينو زرو لوښى بيا کېښودل کوم چې نبوکدنضر د خُدائ پاک د کور نه اوړى وُو چې هغه کور په يروشلم کښې وو او په بابل کښې يې په عبادتخانه کښې اېښى وُو. خورس بادشاه دا لوښى د يو سړى په حواله کړل چې د هغۀ نوم شيسبضر وو، کوم چې هغۀ د يهوداه حکمران مقرر کړے وو.', NULL, '&nbsp;هغۀ د خُدائ پاک په کور کښې د سرو زرو او سپينو زرو لوښى بيا کېښودل کوم چې نبوکدنضر د خُدائ پاک د کور نه اوړى وُو چې هغه کور په يروشلم کښې وو او په بابل کښې يې په عبادتخانه کښې اېښى وُو. خورس بادشاه دا لوښى د يو سړى په حواله کړل چې د هغۀ نوم شيسبضر وو، کوم چې هغۀ د يهوداه حکمران مقرر کړے وو.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_ezra005_verse_014.mp3', NULL, 1761760676, 1761760676),
