(11312, 'Ezra 5:16', 'Ezra', 5, 16, '&nbsp;نو شيسبضر راغلو او د دې بنياد يې کېښودو، د دې جوړېدل د هغه وخت نه واخله تر ننه پورې جارى وُو، خو د خُدائ پاک کور تر اوسه پورې مکمل شوے نۀ دے.', NULL, '&nbsp;نو شيسبضر راغلو او د دې بنياد يې کېښودو، د دې جوړېدل د هغه وخت نه واخله تر ننه پورې جارى وُو، خو د خُدائ پاک کور تر اوسه پورې مکمل شوے نۀ دے.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_ezra005_verse_016.mp3', NULL, 1761760676, 1761760676),
(11313, 'Ezra 5:17', 'Ezra', 5, 17, '&nbsp;نو بادشاه سلامت، کۀ ستا خوښه وى نو د بابل شاهى تاريخ دې ولټولے شى نو دا به معلوم شى چې خورس په يروشلم کښې د خُدائ پاک د کور د بيا جوړولو حُکم ورکړے وو او کۀ نه، او بيا مونږ خبر کړه چې په دې معامله کښې ستا خوښه څۀ ده.“', NULL, '&nbsp;نو بادشاه سلامت، کۀ ستا خوښه وى نو د بابل شاهى تاريخ دې ولټولے شى نو دا به معلوم شى چې خورس په يروشلم کښې د خُدائ پاک د کور د بيا جوړولو حُکم ورکړے وو او کۀ نه، او بيا مونږ خبر کړه چې په دې معامله کښې ستا خوښه څۀ ده.“', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_ezra005_verse_017.mp3', NULL, 1761760676, 1761760676),
