(11315, 'Ezra 6:2', 'Ezra', 6, 2, '&nbsp;خو د مادى صُوبې په اکبتانا ښار کښې يو طومار پېدا شو، چې دا ليکل په کښې شوى وُو،', NULL, '&nbsp;خو د مادى صُوبې په اکبتانا ښار کښې يو طومار پېدا شو، چې دا ليکل په کښې شوى وُو،', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_ezra006_verse_002.mp3', NULL, 1761760676, 1761760676),
(11316, 'Ezra 6:3', 'Ezra', 6, 3, '&nbsp;”د خپلې بادشاهۍ په وړومبى کال خورس بادشاه حُکم وکړو چې په يروشلم کښې دې د خُدائ پاک کور بيا جوړ کړے شى چې هغه يو داسې ځائ وى چرته به چې قربانۍ کيږى او نذرانې به سوزولے شى. د خُدائ پاک کور به تقريباً دېرش ګزه اوچت او دېرش ګزه پلن جوړولے شى.', NULL, '&nbsp;”د خپلې بادشاهۍ په وړومبى کال خورس بادشاه حُکم وکړو چې په يروشلم کښې دې د خُدائ پاک کور بيا جوړ کړے شى چې هغه يو داسې ځائ وى چرته به چې قربانۍ کيږى او نذرانې به سوزولے شى. د خُدائ پاک کور به تقريباً دېرش ګزه اوچت او دېرش ګزه پلن جوړولے شى.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_ezra006_verse_003.mp3', NULL, 1761760676, 1761760676),
(11317, 'Ezra 6:4', 'Ezra', 6, 4, '&nbsp;دېوالونه به داسې جوړولے شى چې درې ردې د لويو کاڼو وى او په يوه رَده کښې د لرګى تختې لګولے شوى وى. دا ټوله خرچه به شاهى خزانه ورکوى.', NULL, '&nbsp;دېوالونه به داسې جوړولے شى چې درې ردې د لويو کاڼو وى او په يوه رَده کښې د لرګى تختې لګولے شوى وى. دا ټوله خرچه به شاهى خزانه ورکوى.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_ezra006_verse_004.mp3', NULL, 1761760676, 1761760676),
(11318, 'Ezra 6:5', 'Ezra', 6, 5, '&nbsp;نبوکدنضر بادشاه چې په يروشلم کښې د خُدائ پاک د کور نه کوم د سرو زرو او سپينو زرو لوښى بابل ته اوړى وُو نو هغه به هم د خُدائ پاک کور يعنې خپل صحيح ځائ ته راواپس کولے شى کوم چې په يروشلم کښې دے.“', NULL, '&nbsp;نبوکدنضر بادشاه چې په يروشلم کښې د خُدائ پاک د کور نه کوم د سرو زرو او سپينو زرو لوښى بابل ته اوړى وُو نو هغه به هم د خُدائ پاک کور يعنې خپل صحيح ځائ ته راواپس کولے شى کوم چې په يروشلم کښې دے.“', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_ezra006_verse_005.mp3', NULL, 1761760676, 1761760676),
(11319, 'Ezra 6:6', 'Ezra', 6, 6, '&nbsp;نو بيا داريوس بادشاه دا جواب ورولېږلو، ”دا د نمرپرېواتۀ طرف ته فرات حکمران تتنى، شتربوزنى او د نمرپرېواتۀ طرف ته فرات ستا آفسرانو ته دے، چې تاسو به د خُدائ پاک د کور سره کار نۀ ساتئ', NULL, '&nbsp;نو بيا داريوس بادشاه دا جواب ورولېږلو، ”دا د نمرپرېواتۀ طرف ته فرات حکمران تتنى، شتربوزنى او د نمرپرېواتۀ طرف ته فرات ستا آفسرانو ته دے، چې تاسو به د خُدائ پاک د کور سره کار نۀ ساتئ', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_ezra006_verse_006.mp3', NULL, 1761760676, 1761760676),
(11320, 'Ezra 6:7', 'Ezra', 6, 7, '&nbsp;او د دې په جوړېدو کښې کار مۀ ساتئ. د يهوداه حکمران او يهودى مشران پرېږدئ چې هغوئ د خُدائ پاک کور هلته جوړ کړى چرته چې مخکښې ولاړ وو.', NULL, '&nbsp;او د دې په جوړېدو کښې کار مۀ ساتئ. د يهوداه حکمران او يهودى مشران پرېږدئ چې هغوئ د خُدائ پاک کور هلته جوړ کړى چرته چې مخکښې ولاړ وو.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_ezra006_verse_007.mp3', NULL, 1761760676, 1761760676),
(11321, 'Ezra 6:8', 'Ezra', 6, 8, '&nbsp;او دې سره زۀ تاسو له حُکم درکوم چې د يهوداه د مشرانو مدد وکړئ چې دا بيا جوړ کړى. هغوئ له به د پوره خرچې دپاره د شاهى خزانې پېسې ورکولے شى چې د نمرپرېواتۀ طرف ته د فرات د محصُول نه اخستے شى، د دې دپاره چې کار ايسار نۀ شى.', NULL, '&nbsp;او دې سره زۀ تاسو له حُکم درکوم چې د يهوداه د مشرانو مدد وکړئ چې دا بيا جوړ کړى. هغوئ له به د پوره خرچې دپاره د شاهى خزانې پېسې ورکولے شى چې د نمرپرېواتۀ طرف ته د فرات د محصُول نه اخستے شى، د دې دپاره چې کار ايسار نۀ شى.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_ezra006_verse_008.mp3', NULL, 1761760676, 1761760676),
(11322, 'Ezra 6:9', 'Ezra', 6, 9, '&nbsp;بغېر د څۀ کمى نه، هره ورځ تاسو به په يروشلم کښې اِمامانو له هغه هر څۀ ورکوئ چې هغوئ ته د څۀ ضرورت وى، چې هغه سخى، ګډې، يا ګډُورى وى، چې د آسمان خُدائ پاک ته د قربانۍ په توګه سوزولے شى، يا چې هغه غنم، مالګه، مے، يا د زيتُونو تېل وى.', NULL, '&nbsp;بغېر د څۀ کمى نه، هره ورځ تاسو به په يروشلم کښې اِمامانو له هغه هر څۀ ورکوئ چې هغوئ ته د څۀ ضرورت وى، چې هغه سخى، ګډې، يا ګډُورى وى، چې د آسمان خُدائ پاک ته د قربانۍ په توګه سوزولے شى، يا چې هغه غنم، مالګه، مے، يا د زيتُونو تېل وى.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_ezra006_verse_009.mp3', NULL, 1761760676, 1761760676),
(11323, 'Ezra 6:10', 'Ezra', 6, 10, '&nbsp;نو چې داسې هغوئ هغه قربانۍ پېش کړى په کومو باندې چې د آسمان خُدائ پاک رضا کيږى او زما او زما د زامنو دپاره د هغۀ نه برکت غواړى.', NULL, '&nbsp;نو چې داسې هغوئ هغه قربانۍ پېش کړى په کومو باندې چې د آسمان خُدائ پاک رضا کيږى او زما او زما د زامنو دپاره د هغۀ نه برکت غواړى.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_ezra006_verse_010.mp3', NULL, 1761760676, 1761760676),
(11324, 'Ezra 6:11', 'Ezra', 6, 11, '&nbsp;زۀ بل دا حُکم کوم کۀ څوک هم دا حُکم ونۀ منى، نو د هغۀ کور نه به د لرګى تير راوويستلے شى، د هغې يو سر دې تېرۀ کړے شى او په هغې دې ووژلے شى. او د هغۀ کور دې د ډېران يو ډېرے جوړ کړے شى.', NULL, '&nbsp;زۀ بل دا حُکم کوم کۀ څوک هم دا حُکم ونۀ منى، نو د هغۀ کور نه به د لرګى تير راوويستلے شى، د هغې يو سر دې تېرۀ کړے شى او په هغې دې ووژلے شى. او د هغۀ کور دې د ډېران يو ډېرے جوړ کړے شى.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_ezra006_verse_011.mp3', NULL, 1761760676, 1761760676),
(11325, 'Ezra 6:12', 'Ezra', 6, 12, '&nbsp;هغه خُدائ پاک چا چې يروشلم د دې دپاره خوښ کړے دے چې هلته به د هغۀ عبادت کيږى نو کۀ کوم بادشاه يا قوم د دې حُکم نه اِنکار وکړى يا د دې کور د تباه کولو کوشش کوى نو خُدائ پاک دې ورله شکست ورکړى. ما داريوس دا حُکم کړے دے او دا حُکم دې پوره ومنلے شى.“', NULL, '&nbsp;هغه خُدائ پاک چا چې يروشلم د دې دپاره خوښ کړے دے چې هلته به د هغۀ عبادت کيږى نو کۀ کوم بادشاه يا قوم د دې حُکم نه اِنکار وکړى يا د دې کور د تباه کولو کوشش کوى نو خُدائ پاک دې ورله شکست ورکړى. ما داريوس دا حُکم کړے دے او دا حُکم دې پوره ومنلے شى.“', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_ezra006_verse_012.mp3', NULL, 1761760676, 1761760676),
(11326, 'Ezra 6:13', 'Ezra', 6, 13, '&nbsp;بيا تتنى حکمران، شتربوزنى او د هغوئ آفسرانو هم هغه شان وکړل چې څنګه داريوس بادشاه حُکم کړے وو.', NULL, '&nbsp;بيا تتنى حکمران، شتربوزنى او د هغوئ آفسرانو هم هغه شان وکړل چې څنګه داريوس بادشاه حُکم کړے وو.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_ezra006_verse_013.mp3', NULL, 1761760676, 1761760676),
(11327, 'Ezra 6:14', 'Ezra', 6, 14, '&nbsp;يهودى مشرانو د خُدائ پاک د کور عمارت په ښۀ طريقه جوړولو، چې د هغوئ حوصله افزائى حجى او زکرياه پېغمبرانو کوله. هغوئ د خُدائ پاک کور هم هغه شان سر ته ورسولو لکه څنګه چې د بنى اِسرائيلو خُدائ پاک حُکم کړے وو او خورس، داريوس او د فارس بادشاه ارتخششتا فرمان جارى کړے وو.', NULL, '&nbsp;يهودى مشرانو د خُدائ پاک د کور عمارت په ښۀ طريقه جوړولو، چې د هغوئ حوصله افزائى حجى او زکرياه پېغمبرانو کوله. هغوئ د خُدائ پاک کور هم هغه شان سر ته ورسولو لکه څنګه چې د بنى اِسرائيلو خُدائ پاک حُکم کړے وو او خورس، داريوس او د فارس بادشاه ارتخششتا فرمان جارى کړے وو.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_ezra006_verse_014.mp3', NULL, 1761760676, 1761760676),
(11328, 'Ezra 6:15', 'Ezra', 6, 15, '&nbsp;هغوئ د خُدائ پاک کور د داريوس بادشاه د بادشاهۍ په شپږم کال کښې د ادر مياشتې په درېمه ورځ سر ته ورسولو.', NULL, '&nbsp;هغوئ د خُدائ پاک کور د داريوس بادشاه د بادشاهۍ په شپږم کال کښې د ادر مياشتې په درېمه ورځ سر ته ورسولو.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_ezra006_verse_015.mp3', NULL, 1761760676, 1761760676),
