(11330, 'Ezra 6:17', 'Ezra', 6, 17, '&nbsp;د وقف کولو دپاره هغوئ سل غوَيى، دوه سوه ګډان او څلور سوه ګډُورى د قربانۍ په توګه پېش کړل او دولس چېلى يې د ګناه د نذرانې په توګه پېش کړل چې د بنى اِسرائيلو د هرې يوې قبيلې دپاره يو يو وو.', NULL, '&nbsp;د وقف کولو دپاره هغوئ سل غوَيى، دوه سوه ګډان او څلور سوه ګډُورى د قربانۍ په توګه پېش کړل او دولس چېلى يې د ګناه د نذرانې په توګه پېش کړل چې د بنى اِسرائيلو د هرې يوې قبيلې دپاره يو يو وو.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_ezra006_verse_017.mp3', NULL, 1761760676, 1761760676),
