(11333, 'Ezra 6:20', 'Ezra', 6, 20, '&nbsp;ټولو اِمامانو او ليويانو خپل ځانونه پاک کړى وُو او د پاکېدو رسم يې ادا کړے وو. ليويانو د فسحې د اختر د قربانۍ دپاره د ټولو راواپس شوو خلقو، د اِمامانو او د خپلو ځانونو دپاره څاروى حلال کړى وُو.', NULL, '&nbsp;ټولو اِمامانو او ليويانو خپل ځانونه پاک کړى وُو او د پاکېدو رسم يې ادا کړے وو. ليويانو د فسحې د اختر د قربانۍ دپاره د ټولو راواپس شوو خلقو، د اِمامانو او د خپلو ځانونو دپاره څاروى حلال کړى وُو.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_ezra006_verse_020.mp3', NULL, 1761760676, 1761760676),
(11334, 'Ezra 6:21', 'Ezra', 6, 21, '&nbsp;دا قربانۍ هغه ټولو بنى اِسرائيلو وخوړلې چې څوک د جلاوطنۍ نه راواپس شوى وُو او ورسره هغه خلقو هم وخوړلې چا چې د غېرو قومونو غلط رسمونه پرېښى وُو د دې دپاره چې د مالِک خُدائ د بنى اِسرائيلو د خُدائ پاک عبادت وکړى.', NULL, '&nbsp;دا قربانۍ هغه ټولو بنى اِسرائيلو وخوړلې چې څوک د جلاوطنۍ نه راواپس شوى وُو او ورسره هغه خلقو هم وخوړلې چا چې د غېرو قومونو غلط رسمونه پرېښى وُو د دې دپاره چې د مالِک خُدائ د بنى اِسرائيلو د خُدائ پاک عبادت وکړى.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_ezra006_verse_021.mp3', NULL, 1761760676, 1761760676),
(11335, 'Ezra 6:22', 'Ezra', 6, 22, '&nbsp;هغوئ د خوشحالۍ سره اووۀ ورځې د پتيرې روټۍ اختر وکړو. هغوئ ډېر خوشحاله وُو ځکه چې مالِک خُدائ د اسور بادشاه په هغوئ باندې مهربان کړے وو، نو په دې وجه هغۀ د هغوئ په کار کښې مدد وکړو چې د بنى اِسرائيلو د خُدائ پاک کور جوړ کړى.', NULL, '&nbsp;هغوئ د خوشحالۍ سره اووۀ ورځې د پتيرې روټۍ اختر وکړو. هغوئ ډېر خوشحاله وُو ځکه چې مالِک خُدائ د اسور بادشاه په هغوئ باندې مهربان کړے وو، نو په دې وجه هغۀ د هغوئ په کار کښې مدد وکړو چې د بنى اِسرائيلو د خُدائ پاک کور جوړ کړى.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_ezra006_verse_022.mp3', NULL, 1761760676, 1761760676),
(11336, 'Ezra 7:1', 'Ezra', 7, 1, '&nbsp;ډېره موده پس، کله چې ارتخششتا د فارس بادشاه وو، نو يو سړے وو چې نوم يې عزرا وو. هغۀ خپله شجره نسب مشر اِمام هارون ته ورسوله، چې داسې ده: عزرا د شراياه زوئ وو چې هغه زوئ د عزرياه، زوئ د خِلقياه،', NULL, '&nbsp;ډېره موده پس، کله چې ارتخششتا د فارس بادشاه وو، نو يو سړے وو چې نوم يې عزرا وو. هغۀ خپله شجره نسب مشر اِمام هارون ته ورسوله، چې داسې ده: عزرا د شراياه زوئ وو چې هغه زوئ د عزرياه، زوئ د خِلقياه،', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_ezra007_verse_001.mp3', NULL, 1761760676, 1761760676),
