(11340, 'Ezra 7:5', 'Ezra', 7, 5, '&nbsp;زوئ د ابيسوع، زوئ د فينحاس، زوئ د اِلى‌عزر او زوئ د هارون څوک چې مشر اِمام وو.', NULL, '&nbsp;زوئ د ابيسوع، زوئ د فينحاس، زوئ د اِلى‌عزر او زوئ د هارون څوک چې مشر اِمام وو.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_ezra007_verse_005.mp3', NULL, 1761760676, 1761760676),
(11341, 'Ezra 7:10', 'Ezra', 7, 10, '&nbsp;عزرا خپل ژوند دې ته وقف کړے وو چې د مالِک خُدائ په قانون باندې پوهه شى، په هغې عمل وکړى او د دې ټول قانون او اصُول بنى اِسرائيلو ته وښائى.', NULL, '&nbsp;عزرا خپل ژوند دې ته وقف کړے وو چې د مالِک خُدائ په قانون باندې پوهه شى، په هغې عمل وکړى او د دې ټول قانون او اصُول بنى اِسرائيلو ته وښائى.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_ezra007_verse_010.mp3', NULL, 1761760676, 1761760676),
(11342, 'Ezra 7:11', 'Ezra', 7, 11, '&nbsp;ارتخششتا عزرا اِمام او عالِم له دا کاغذ ورکړو، چې هغۀ د هغه قانون او حُکمونه پوره پوهه لرله کوم چې مالِک خُدائ بنى اِسرائيلو ته ورکړى وُو،', NULL, '&nbsp;ارتخششتا عزرا اِمام او عالِم له دا کاغذ ورکړو، چې هغۀ د هغه قانون او حُکمونه پوره پوهه لرله کوم چې مالِک خُدائ بنى اِسرائيلو ته ورکړى وُو،', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_ezra007_verse_011.mp3', NULL, 1761760676, 1761760676),
(11343, 'Ezra 7:12', 'Ezra', 7, 12, '&nbsp;”د ارتخششتا بادشاه د طرف نه، عزرا اِمام ته، چې هغه د آسمان د خُدائ پاک د قانون عالِم دے، ډېر سلامونه. او اوس،', NULL, '&nbsp;”د ارتخششتا بادشاه د طرف نه، عزرا اِمام ته، چې هغه د آسمان د خُدائ پاک د قانون عالِم دے، ډېر سلامونه. او اوس،', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_ezra007_verse_012.mp3', NULL, 1761760676, 1761760676),
(11344, 'Ezra 7:13', 'Ezra', 7, 13, '&nbsp;زۀ دا حُکم کوم چې زما په ټول سلطنت کښې چې کوم بنى اِسرائيليان، اِمامان او ليويان چې د هغوئ زړۀ غواړى چې تا سره يروشلم ته لاړ شى نو لاړ دې شى.', NULL, '&nbsp;زۀ دا حُکم کوم چې زما په ټول سلطنت کښې چې کوم بنى اِسرائيليان، اِمامان او ليويان چې د هغوئ زړۀ غواړى چې تا سره يروشلم ته لاړ شى نو لاړ دې شى.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_ezra007_verse_013.mp3', NULL, 1761760676, 1761760676),
(11345, 'Ezra 7:14', 'Ezra', 7, 14, '&nbsp;زۀ، تا زما د خپلو اووۀ مشيرانو سره لېږم چې په يروشلم او يهوداه کښې حالات معلوم کړئ چې دا پته ولګى چې ستا د خُدائ پاک په قانون باندې څومره ښۀ عمل کيږى، هغه قانون چې تا سره موجود دے.', NULL, '&nbsp;زۀ، تا زما د خپلو اووۀ مشيرانو سره لېږم چې په يروشلم او يهوداه کښې حالات معلوم کړئ چې دا پته ولګى چې ستا د خُدائ پاک په قانون باندې څومره ښۀ عمل کيږى، هغه قانون چې تا سره موجود دے.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_ezra007_verse_014.mp3', NULL, 1761760676, 1761760676),
(11346, 'Ezra 7:15', 'Ezra', 7, 15, '&nbsp;تاسو به د ځان سره د سرو زرو او سپينو زرو هغه نذرانې يوسئ د کومو چې زۀ او زما مشيران د بنى اِسرائيلو خُدائ پاک له د ورکولو خواهش لرو، هغه خُدائ پاک چې د هغۀ کور په يروشلم کښې دے.', NULL, '&nbsp;تاسو به د ځان سره د سرو زرو او سپينو زرو هغه نذرانې يوسئ د کومو چې زۀ او زما مشيران د بنى اِسرائيلو خُدائ پاک له د ورکولو خواهش لرو، هغه خُدائ پاک چې د هغۀ کور په يروشلم کښې دے.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_ezra007_verse_015.mp3', NULL, 1761760676, 1761760676),
(11347, 'Ezra 7:16', 'Ezra', 7, 16, '&nbsp;تاسو به هغه ټول سرۀ زر او سپين زر هم د ځان سره اوړئ کوم چې تاسو د بابل په ټوله صُوبه کښې راغونډ کړئ او هغه نذرانې به هم اوړئ کومې چې بنى اِسرائيليان او د هغوئ اِمامان په يروشلم کښې د خپل خُدائ پاک کور دپاره ورکوى.', NULL, '&nbsp;تاسو به هغه ټول سرۀ زر او سپين زر هم د ځان سره اوړئ کوم چې تاسو د بابل په ټوله صُوبه کښې راغونډ کړئ او هغه نذرانې به هم اوړئ کومې چې بنى اِسرائيليان او د هغوئ اِمامان په يروشلم کښې د خپل خُدائ پاک کور دپاره ورکوى.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_ezra007_verse_016.mp3', NULL, 1761760676, 1761760676),
