(11350, 'Ezra 7:19', 'Ezra', 7, 19, '&nbsp;تاسو به په يروشلم کښې خُدائ پاک ته هغه ټول لوښى پېش کوئ کوم چې د خُدائ پاک د کور د خِدمت د استعمال دپاره درکړے شوى دى.', NULL, '&nbsp;تاسو به په يروشلم کښې خُدائ پاک ته هغه ټول لوښى پېش کوئ کوم چې د خُدائ پاک د کور د خِدمت د استعمال دپاره درکړے شوى دى.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_ezra007_verse_019.mp3', NULL, 1761760676, 1761760676),
(11351, 'Ezra 7:20', 'Ezra', 7, 20, '&nbsp;او تاسو ته چې د خُدائ پاک د کور دپاره د بل هر څيز ضرورت وى، نو تاسو هغه د شاهى خزانې نه اخستلے شئ.', NULL, '&nbsp;او تاسو ته چې د خُدائ پاک د کور دپاره د بل هر څيز ضرورت وى، نو تاسو هغه د شاهى خزانې نه اخستلے شئ.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_ezra007_verse_020.mp3', NULL, 1761760676, 1761760676),
