(11354, 'Ezra 7:23', 'Ezra', 7, 23, '&nbsp;تاسو به خامخا د هغه هر څۀ په بندوبست کولو کښې د احتياط نه کار اخلئ چې د آسمان خُدائ پاک يې د خپل کور دپاره غوښتنه کوى او پام کوئ چې هغه ما ته او هغه کسانو ته هيڅکله غصه نۀ شى کوم چې زما نه پس بادشاهى کوى.', NULL, '&nbsp;تاسو به خامخا د هغه هر څۀ په بندوبست کولو کښې د احتياط نه کار اخلئ چې د آسمان خُدائ پاک يې د خپل کور دپاره غوښتنه کوى او پام کوئ چې هغه ما ته او هغه کسانو ته هيڅکله غصه نۀ شى کوم چې زما نه پس بادشاهى کوى.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_ezra007_verse_023.mp3', NULL, 1761760676, 1761760676),
(11355, 'Ezra 7:24', 'Ezra', 7, 24, '&nbsp;تاسو ته د دې اجازت نشته چې د اِمامانو، ليويانو، موسيقارانو، څوکيدارانو، کاريګرو، يا د بل هر هغه چا نه محصُول، جزيه او پېسې واخلئ چې د چا تعلق د خُدائ پاک د دې کور سره وى.', NULL, '&nbsp;تاسو ته د دې اجازت نشته چې د اِمامانو، ليويانو، موسيقارانو، څوکيدارانو، کاريګرو، يا د بل هر هغه چا نه محصُول، جزيه او پېسې واخلئ چې د چا تعلق د خُدائ پاک د دې کور سره وى.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_ezra007_verse_024.mp3', NULL, 1761760676, 1761760676),
(11356, 'Ezra 7:25', 'Ezra', 7, 25, '&nbsp;عزرا، تۀ به د هغه حِکمت نه کار اخلې کوم چې ستا خُدائ پاک درکړے دے، تۀ به اِنتظام کوونکى او قاضيان مقرروې چې په هغه ټولو خلقو باندې حکومت کوى چې د فرات سيند نمرپرېواتۀ طرف ته د خُدائ پاک د قانون لاندې ژوند تېروى. تۀ به هغه هر چا ته دا قانون ښائې چې څوک ورباندې نۀ پوهيږى.', NULL, '&nbsp;عزرا، تۀ به د هغه حِکمت نه کار اخلې کوم چې ستا خُدائ پاک درکړے دے، تۀ به اِنتظام کوونکى او قاضيان مقرروې چې په هغه ټولو خلقو باندې حکومت کوى چې د فرات سيند نمرپرېواتۀ طرف ته د خُدائ پاک د قانون لاندې ژوند تېروى. تۀ به هغه هر چا ته دا قانون ښائې چې څوک ورباندې نۀ پوهيږى.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_ezra007_verse_025.mp3', NULL, 1761760676, 1761760676),
(11357, 'Ezra 7:26', 'Ezra', 7, 26, '&nbsp;کۀ هر څوک هم ستا د خُدائ پاک د قانون يا د بادشاه د قانون نافرمانى کوى، نو هغۀ له به هم په هغه وخت سزا ورکولے شى، چې وژلے به شى، يا به جلاوطن کړے شى، يا به د هغۀ نه جائيداد ضبط کولے شى، يا به قېد کولے شى.“', NULL, '&nbsp;کۀ هر څوک هم ستا د خُدائ پاک د قانون يا د بادشاه د قانون نافرمانى کوى، نو هغۀ له به هم په هغه وخت سزا ورکولے شى، چې وژلے به شى، يا به جلاوطن کړے شى، يا به د هغۀ نه جائيداد ضبط کولے شى، يا به قېد کولے شى.“', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_ezra007_verse_026.mp3', NULL, 1761760676, 1761760676),
(11358, 'Ezra 7:27', 'Ezra', 7, 27, '&nbsp;عزرا وفرمائيل، ”د مالِک خُدائ زمونږ د پلار نيکۀ د خُدائ پاک ثناء صِفت دې وى. هغۀ بادشاه دې ته راضى کړے دے چې په دې طريقه باندې په يروشلم کښې د مالِک خُدائ د کور درناوى وکړى.', NULL, '&nbsp;عزرا وفرمائيل، ”د مالِک خُدائ زمونږ د پلار نيکۀ د خُدائ پاک ثناء صِفت دې وى. هغۀ بادشاه دې ته راضى کړے دے چې په دې طريقه باندې په يروشلم کښې د مالِک خُدائ د کور درناوى وکړى.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761760676, 1761760676),
(11359, 'Ezra 7:28', 'Ezra', 7, 28, '&nbsp;د خُدائ پاک په فضل سره په ما باندې بادشاه، د هغۀ مشيران او د هغۀ ټول طاقتور آفسران مهربان شوى دى، مالِک خُدائ زما خُدائ پاک ما له حوصله راکړې ده او زۀ د دې قابل شوے يم چې د بنى اِسرائيلو د ډلو ډېر مشران دې ته جوړ کړم چې زما سره راواپس شى.“', NULL, '&nbsp;د خُدائ پاک په فضل سره په ما باندې بادشاه، د هغۀ مشيران او د هغۀ ټول طاقتور آفسران مهربان شوى دى، مالِک خُدائ زما خُدائ پاک ما له حوصله راکړې ده او زۀ د دې قابل شوے يم چې د بنى اِسرائيلو د ډلو ډېر مشران دې ته جوړ کړم چې زما سره راواپس شى.“', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761760676, 1761760676),
(11360, 'Ezra 8:1', 'Ezra', 8, 1, '&nbsp;دا د هغه ډلو د مشرانو تفصيل دے کوم چې په بابل کښې جلاوطن وُو او چې هغوئ د عزرا سره په هغه وخت کښې يروشلم ته راواپس شول چې په کوم وخت کښې ارتخششتا بادشاه وُو:', NULL, '&nbsp;دا د هغه ډلو د مشرانو تفصيل دے کوم چې په بابل کښې جلاوطن وُو او چې هغوئ د عزرا سره په هغه وخت کښې يروشلم ته راواپس شول چې په کوم وخت کښې ارتخششتا بادشاه وُو:', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_ezra008_verse_001.mp3', NULL, 1761760676, 1761760676),
(11361, 'Ezra 8:15', 'Ezra', 8, 15, '&nbsp;ما د هغه نِهر سره ټوله ډله راغونډه کړه کوم چې د اهاوا ښار ته بهيږى او مونږ هلته درې ورځې خېمې لګولې وې. ما وليدل چې هلته په ډله کښې اِمامان وُو، خو ليويان نۀ وُو.', NULL, '&nbsp;ما د هغه نِهر سره ټوله ډله راغونډه کړه کوم چې د اهاوا ښار ته بهيږى او مونږ هلته درې ورځې خېمې لګولې وې. ما وليدل چې هلته په ډله کښې اِمامان وُو، خو ليويان نۀ وُو.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_ezra008_verse_015.mp3', NULL, 1761760676, 1761760676),
(11362, 'Ezra 8:16', 'Ezra', 8, 16, '&nbsp;نو ما دا نهۀ مشران راوغوښتل: اِلى‌عزر، ارى‌ايل، سمعياه، الناتن، يريب، الناتن، ناتن، زکرياه او مسلام او دوه عالمان يويريب او الناتن مې هم راوغوښتل.', NULL, '&nbsp;نو ما دا نهۀ مشران راوغوښتل: اِلى‌عزر، ارى‌ايل، سمعياه، الناتن، يريب، الناتن، ناتن، زکرياه او مسلام او دوه عالمان يويريب او الناتن مې هم راوغوښتل.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_ezra008_verse_016.mp3', NULL, 1761760676, 1761760676),
(11363, 'Ezra 8:17', 'Ezra', 8, 17, '&nbsp;ما هغوئ په کسيفيا کښې د قبيلې مشر عدو ته ولېږل، چې هغۀ او د هغۀ د قبيلې نه د خُدائ پاک د کور دپاره کاريګر وغواړى او مونږ له داسې خلق راولېږى چې د خُدائ پاک په کور کښې خِدمت وکړى.', NULL, '&nbsp;ما هغوئ په کسيفيا کښې د قبيلې مشر عدو ته ولېږل، چې هغۀ او د هغۀ د قبيلې نه د خُدائ پاک د کور دپاره کاريګر وغواړى او مونږ له داسې خلق راولېږى چې د خُدائ پاک په کور کښې خِدمت وکړى.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_ezra008_verse_017.mp3', NULL, 1761760676, 1761760676),
(11364, 'Ezra 8:18', 'Ezra', 8, 18, '&nbsp;د خُدائ پاک په فضل سره هغوئ مونږ له يو تکړه سړے سربياه راولېږلو، چې دے د محلى د قبيلې ليوے وو او اتلس زامن او وروڼه د هغۀ سره راغلل.', NULL, '&nbsp;د خُدائ پاک په فضل سره هغوئ مونږ له يو تکړه سړے سربياه راولېږلو، چې دے د محلى د قبيلې ليوے وو او اتلس زامن او وروڼه د هغۀ سره راغلل.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_ezra008_verse_018.mp3', NULL, 1761760676, 1761760676),
(11365, 'Ezra 8:19', 'Ezra', 8, 19, '&nbsp;هغوئ د مرارى قبيلې حسبياه او يشعياه هم د هغوئ د شلو خپلوانو سره راولېږل.', NULL, '&nbsp;هغوئ د مرارى قبيلې حسبياه او يشعياه هم د هغوئ د شلو خپلوانو سره راولېږل.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_ezra008_verse_019.mp3', NULL, 1761760676, 1761760676),
(11366, 'Ezra 8:20', 'Ezra', 8, 20, '&nbsp;د دې نه علاوه د خُدائ پاک د کور دوه سوه او شل داسې خِدمتګاران هم وُو چې داؤد بادشاه او د هغۀ آفسرانو د هغوئ پلار نيکۀ د دې دپاره مقرر کړى وُو چې د ليويانو مدد کوى. او د هغوئ ټولو نومونه ليکلے شوى وُو.', NULL, '&nbsp;د دې نه علاوه د خُدائ پاک د کور دوه سوه او شل داسې خِدمتګاران هم وُو چې داؤد بادشاه او د هغۀ آفسرانو د هغوئ پلار نيکۀ د دې دپاره مقرر کړى وُو چې د ليويانو مدد کوى. او د هغوئ ټولو نومونه ليکلے شوى وُو.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_ezra008_verse_020.mp3', NULL, 1761760676, 1761760676),
(11367, 'Ezra 8:21', 'Ezra', 8, 21, '&nbsp;هلته د اهاوا نِهر سره ما ټولو له دا حُکم ورکړو چې روژه ونيسئ او د خپل خُدائ پاک په وړاندې خپل ځانونه عاجزان کړئ او هغۀ ته سوال وکړئ چې په سفر کښې زمونږ مدد وکړى او زمونږ، زمونږ د بچو او زمونږ د مال دولت حِفاظت وکړى.', NULL, '&nbsp;هلته د اهاوا نِهر سره ما ټولو له دا حُکم ورکړو چې روژه ونيسئ او د خپل خُدائ پاک په وړاندې خپل ځانونه عاجزان کړئ او هغۀ ته سوال وکړئ چې په سفر کښې زمونږ مدد وکړى او زمونږ، زمونږ د بچو او زمونږ د مال دولت حِفاظت وکړى.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_ezra008_verse_021.mp3', NULL, 1761760676, 1761760676),
(11368, 'Ezra 8:22', 'Ezra', 8, 22, '&nbsp;زۀ په دې باندې شرمېدلم چې د بادشاه نه مې يو لښکر او په آسونو سوارۀ فوجيان غوښتى وے چې زمونږ د سفر په دوران کښې د دشمنانو نه زمونږ حِفاظت وکړى، ځکه چې ما هغۀ ته وئيلى وُو چې زمونږ خُدائ پاک هغه هر چا له برکت ورکوى چې څوک ورباندې ايمان لرى، خو هر څوک چې د هغۀ نه واوړى نو د هغوئ نه خفه کيږى او سزا ورکوى.', NULL, '&nbsp;زۀ په دې باندې شرمېدلم چې د بادشاه نه مې يو لښکر او په آسونو سوارۀ فوجيان غوښتى وے چې زمونږ د سفر په دوران کښې د دشمنانو نه زمونږ حِفاظت وکړى، ځکه چې ما هغۀ ته وئيلى وُو چې زمونږ خُدائ پاک هغه هر چا له برکت ورکوى چې څوک ورباندې ايمان لرى، خو هر څوک چې د هغۀ نه واوړى نو د هغوئ نه خفه کيږى او سزا ورکوى.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_ezra008_verse_022.mp3', NULL, 1761760676, 1761760676),
(11369, 'Ezra 8:23', 'Ezra', 8, 23, '&nbsp;نو مونږ روژه ونيوله او خُدائ پاک ته مو سوال وکړو چې زمونږ حِفاظت وکړى او هغۀ زمونږ سوال قبول کړو.', NULL, '&nbsp;نو مونږ روژه ونيوله او خُدائ پاک ته مو سوال وکړو چې زمونږ حِفاظت وکړى او هغۀ زمونږ سوال قبول کړو.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_ezra008_verse_023.mp3', NULL, 1761760676, 1761760676),
(11370, 'Ezra 8:24', 'Ezra', 8, 24, '&nbsp;د مشرانو اِمامانو نه ما سربياه، حسبياه او لس نور کسان خوښ کړل.', NULL, '&nbsp;د مشرانو اِمامانو نه ما سربياه، حسبياه او لس نور کسان خوښ کړل.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761760676, 1761760676),
