(11372, 'Ezra 8:28', 'Ezra', 8, 28, '&nbsp;ما اِمامانو ته ووئيل، ”تاسو مالِک خُدائ ستاسو د پلار نيکۀ خُدائ پاک ته وقف او مقدس شوى يئ او داسې هغه ټول سپين زر، سرۀ زر او لوښى هم ستاسو په شان مقدس دى کوم چې هغۀ ته د رضاکارانه نذرانو په توګه راوړلے شوى دى.', NULL, '&nbsp;ما اِمامانو ته ووئيل، ”تاسو مالِک خُدائ ستاسو د پلار نيکۀ خُدائ پاک ته وقف او مقدس شوى يئ او داسې هغه ټول سپين زر، سرۀ زر او لوښى هم ستاسو په شان مقدس دى کوم چې هغۀ ته د رضاکارانه نذرانو په توګه راوړلے شوى دى.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761760676, 1761760676),
(11373, 'Ezra 8:29', 'Ezra', 8, 29, '&nbsp;د مالِک خُدائ کور ته تر رسېدو پورې د دې ښۀ حِفاظت وکړئ. هلته د اِمامانو په کوټه کښې دا وتلئ او د مشرانو اِمامانو او د ليويانو او په يروشلم کښې د بنى اِسرائيلو مشرانو ته يې حواله کړئ.“', NULL, '&nbsp;د مالِک خُدائ کور ته تر رسېدو پورې د دې ښۀ حِفاظت وکړئ. هلته د اِمامانو په کوټه کښې دا وتلئ او د مشرانو اِمامانو او د ليويانو او په يروشلم کښې د بنى اِسرائيلو مشرانو ته يې حواله کړئ.“', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761760676, 1761760676),
(11374, 'Ezra 8:30', 'Ezra', 8, 30, '&nbsp;نو اِمامانو او ليويانو د هغه سپينو زرو، سرو زرو او د لوښو ذمه وارى واخستله چې په يروشلم کښې يې د مالِک خُدائ کور ته يوسى.', NULL, '&nbsp;نو اِمامانو او ليويانو د هغه سپينو زرو، سرو زرو او د لوښو ذمه وارى واخستله چې په يروشلم کښې يې د مالِک خُدائ کور ته يوسى.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761760676, 1761760676),
(11375, 'Ezra 8:31', 'Ezra', 8, 31, '&nbsp;دا د اولې مياشتې دولسمه ورځ وه چې مونږ يروشلم ته د تلو دپاره د اهاوا نِهر نه روان شُو. زمونږ خُدائ پاک مل وو او چې مونږ سفر کولو نو مونږ يې د دشمن د حملو نه او د ډاکوانو نه بچ کولو.', NULL, '&nbsp;دا د اولې مياشتې دولسمه ورځ وه چې مونږ يروشلم ته د تلو دپاره د اهاوا نِهر نه روان شُو. زمونږ خُدائ پاک مل وو او چې مونږ سفر کولو نو مونږ يې د دشمن د حملو نه او د ډاکوانو نه بچ کولو.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761760676, 1761760676),
