(11378, 'Ezra 8:34', 'Ezra', 8, 34, '&nbsp;هر يو څيز وشمېرلے شو او تللے شو او په هغه وخت پوره حِساب کِتاب وشو.', NULL, '&nbsp;هر يو څيز وشمېرلے شو او تللے شو او په هغه وخت پوره حِساب کِتاب وشو.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761760676, 1761760676),
(11379, 'Ezra 8:35', 'Ezra', 8, 35, '&nbsp;بيا هغه ټولو خلقو نذرانې راوړې کوم چې د جلاوطنۍ نه راغلى وُو چې د بنى اِسرائيلو خُدائ پاک ته د قربانۍ په توګه وسوزولے شى. هغوئ د ټولو بنى اِسرائيلو دپاره دولس غوَيى، څلور کم سل ګډان، اووۀ اويا ګډُورى پېش کړل، هغوئ دولس چېلى هم پېش کړل چې خپل ځانونه د ګناه نه پاک کړى. دا ټول ځناور مالِک خُدائ ته د قربانۍ په توګه وسوزولے شول.', NULL, '&nbsp;بيا هغه ټولو خلقو نذرانې راوړې کوم چې د جلاوطنۍ نه راغلى وُو چې د بنى اِسرائيلو خُدائ پاک ته د قربانۍ په توګه وسوزولے شى. هغوئ د ټولو بنى اِسرائيلو دپاره دولس غوَيى، څلور کم سل ګډان، اووۀ اويا ګډُورى پېش کړل، هغوئ دولس چېلى هم پېش کړل چې خپل ځانونه د ګناه نه پاک کړى. دا ټول ځناور مالِک خُدائ ته د قربانۍ په توګه وسوزولے شول.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761760676, 1761760676),
(11380, 'Ezra 8:36', 'Ezra', 8, 36, '&nbsp;هغوئ هغه ليکلے شوے فرمان هم راوخستلو کوم چې بادشاه ورکړے وو او هغه يې حکمرانانو او د نمرپرېواتۀ طرف فرات ته د صُوبې آفسرانو له ورکړو، چې هغوئ بيا د هغه خلقو سره او د خُدائ پاک د کور سره مدد وکړو.', NULL, '&nbsp;هغوئ هغه ليکلے شوے فرمان هم راوخستلو کوم چې بادشاه ورکړے وو او هغه يې حکمرانانو او د نمرپرېواتۀ طرف فرات ته د صُوبې آفسرانو له ورکړو، چې هغوئ بيا د هغه خلقو سره او د خُدائ پاک د کور سره مدد وکړو.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761760676, 1761760676),
(11381, 'Ezra 9:1', 'Ezra', 9, 1, '&nbsp;کله چې دا هر څۀ وشول نو د بنى اِسرائيلو څۀ مشران راغلل او ما ته يې ووئيل چې خلقو، اِمامانو او ليويانو خپل ځانونه د ګاونډى مُلکونو يعنې عمون، موآب، مِصر، کنعان، حِتى، فرزى، يبوس او امورى مُلک د خلقو نه جدا نۀ ساتل. دوئ هم هغه حرام کارونه کول چې کوم هغه خلقو کول.', NULL, '&nbsp;کله چې دا هر څۀ وشول نو د بنى اِسرائيلو څۀ مشران راغلل او ما ته يې ووئيل چې خلقو، اِمامانو او ليويانو خپل ځانونه د ګاونډى مُلکونو يعنې عمون، موآب، مِصر، کنعان، حِتى، فرزى، يبوس او امورى مُلک د خلقو نه جدا نۀ ساتل. دوئ هم هغه حرام کارونه کول چې کوم هغه خلقو کول.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_ezra009_verse_001.mp3', NULL, 1761760676, 1761760676),
