(11385, 'Ezra 9:5', 'Ezra', 9, 5, '&nbsp;کله چې د ماښام د نذرانې وخت راغلو نو زۀ چې د خفګان نه چرته ناست وم د هغه ځائ نه پاڅېدم، چې تر اوسه پورې مې شلېدلے قميص او چُوغه اغوستې وه سجده مې وکړه او بيا مالِک خُدائ خپل خُدائ پاک ته مې لاسونه پورته کړل.', NULL, '&nbsp;کله چې د ماښام د نذرانې وخت راغلو نو زۀ چې د خفګان نه چرته ناست وم د هغه ځائ نه پاڅېدم، چې تر اوسه پورې مې شلېدلے قميص او چُوغه اغوستې وه سجده مې وکړه او بيا مالِک خُدائ خپل خُدائ پاک ته مې لاسونه پورته کړل.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_ezra009_verse_005.mp3', NULL, 1761760676, 1761760676),
(11386, 'Ezra 9:6', 'Ezra', 9, 6, '&nbsp;ما وئيل، ”خُدايه پاکه، ما له په دې باندې ډېر سخت شرم راځى چې ستا په حضور کښې خپل لاسونه اوچت کړم. زمونږ ګناهونه زمونږ د سرونو نه پاس اوړېدلى دى او زمونږ ګناهونه تر آسمانه پورې رسېدلى دى.', NULL, '&nbsp;ما وئيل، ”خُدايه پاکه، ما له په دې باندې ډېر سخت شرم راځى چې ستا په حضور کښې خپل لاسونه اوچت کړم. زمونږ ګناهونه زمونږ د سرونو نه پاس اوړېدلى دى او زمونږ ګناهونه تر آسمانه پورې رسېدلى دى.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_ezra009_verse_006.mp3', NULL, 1761760676, 1761760676),
(11387, 'Ezra 9:7', 'Ezra', 9, 7, '&nbsp;زمونږ د پلار نيکۀ د وخت نه واخله تر اوسه پورې مونږ يعنې ستا خلقو لوئې ګناهونه کړې دى. زمونږ د خپلې ګناه په وجه مونږ، زمونږ بادشاهان او زمونږ اِمامان د پردى مُلک بادشاهانو له په لاس ورغلى يُو او مونږ وژلے شُو، غلا رانه کيږى او د قېديانو په توګه بوتلے شُو. زمونږ ډېره بې‌عزتى شوې ده لکه څنګه چې تر اوسه پورې بې‌عزته يُو.', NULL, '&nbsp;زمونږ د پلار نيکۀ د وخت نه واخله تر اوسه پورې مونږ يعنې ستا خلقو لوئې ګناهونه کړې دى. زمونږ د خپلې ګناه په وجه مونږ، زمونږ بادشاهان او زمونږ اِمامان د پردى مُلک بادشاهانو له په لاس ورغلى يُو او مونږ وژلے شُو، غلا رانه کيږى او د قېديانو په توګه بوتلے شُو. زمونږ ډېره بې‌عزتى شوې ده لکه څنګه چې تر اوسه پورې بې‌عزته يُو.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_ezra009_verse_007.mp3', NULL, 1761760676, 1761760676),
(11388, 'Ezra 9:8', 'Ezra', 9, 8, '&nbsp;خو اے مالِکه خُدايه، زمونږ خُدايه پاکه، تۀ د لږ وخت دپاره په مونږ مِهربانه يې چې زمونږ څۀ کسان دې ژوندى پرېښى دى چې د غلامۍ نه وتښتى او په دې مقدس ځائ کښې په حِفاظت سره اوسيږى. تا مونږ د غلامۍ نه آزاد کړى يُو او يو نوے ژوند دې راکړے دے.', NULL, '&nbsp;خو اے مالِکه خُدايه، زمونږ خُدايه پاکه، تۀ د لږ وخت دپاره په مونږ مِهربانه يې چې زمونږ څۀ کسان دې ژوندى پرېښى دى چې د غلامۍ نه وتښتى او په دې مقدس ځائ کښې په حِفاظت سره اوسيږى. تا مونږ د غلامۍ نه آزاد کړى يُو او يو نوے ژوند دې راکړے دے.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_ezra009_verse_008.mp3', NULL, 1761760676, 1761760676),
(11389, 'Ezra 9:9', 'Ezra', 9, 9, '&nbsp;مونږ غلامان وُو، خو تا مونږ په غلامۍ کښې پرې نۀ ښودو. تا د فارس بادشاهان مونږ سره ښۀ کړل او دا اجازت دې راکړو چې خپل ژوند تېروو او ستا هغه کور بيا جوړ کړُو، کوم چې تباه شوے وو او دې ته دې هم پرېښودو چې په يهوداه او يروشلم کښې مونږ ته حِفاظت مِلاو شى.', NULL, '&nbsp;مونږ غلامان وُو، خو تا مونږ په غلامۍ کښې پرې نۀ ښودو. تا د فارس بادشاهان مونږ سره ښۀ کړل او دا اجازت دې راکړو چې خپل ژوند تېروو او ستا هغه کور بيا جوړ کړُو، کوم چې تباه شوے وو او دې ته دې هم پرېښودو چې په يهوداه او يروشلم کښې مونږ ته حِفاظت مِلاو شى.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_ezra009_verse_009.mp3', NULL, 1761760676, 1761760676),
