(11395, 'Ezra 9:15', 'Ezra', 9, 15, '&nbsp;مالِکه خُدايه، د بنى اِسرائيلو خُدايه پاکه، تۀ صادق يې، خو تا مونږ پرېښودو چې ژوندى پاتې شُو. مونږ په ګناه کښې ستا په وړاندې ولاړ يُو، خو د دې ګناه په وجه زمونږ يو کس هم دا حق نۀ لرى چې ستا حضور ته راشى.“', NULL, '&nbsp;مالِکه خُدايه، د بنى اِسرائيلو خُدايه پاکه، تۀ صادق يې، خو تا مونږ پرېښودو چې ژوندى پاتې شُو. مونږ په ګناه کښې ستا په وړاندې ولاړ يُو، خو د دې ګناه په وجه زمونږ يو کس هم دا حق نۀ لرى چې ستا حضور ته راشى.“', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_ezra009_verse_015.mp3', NULL, 1761760676, 1761760676),
(11396, 'Ezra 10:1', 'Ezra', 10, 1, '&nbsp;کله چې عزرا د خُدائ پاک د کور په مخکښې پړمخې پرېوتو، چې هغۀ ژړل او د ګناهونو اِقرار يې کولو، نو د بنى اِسرائيلو يوه لويه ډله د هغۀ نه راتاو شوه چې په کښې سړى، ښځې او ماشومان شامل وُو او بد بد يې ژړل.', NULL, '&nbsp;کله چې عزرا د خُدائ پاک د کور په مخکښې پړمخې پرېوتو، چې هغۀ ژړل او د ګناهونو اِقرار يې کولو، نو د بنى اِسرائيلو يوه لويه ډله د هغۀ نه راتاو شوه چې په کښې سړى، ښځې او ماشومان شامل وُو او بد بد يې ژړل.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_ezra010_verse_001.mp3', NULL, 1761760676, 1761760676),
