(11406, 'Ezra 10:11', 'Ezra', 10, 11, '&nbsp;نو اوس مالِک خُدائ د خپل پلار نيکۀ خُدائ پاک ته د خپلو ګناهونو اِقرار وکړئ او هغه کار کوئ چې هغه پرې رضا کيږى. د پردى مُلک د هغه خلقو نه خپل ځانونه جدا کړئ چې کوم زمونږ په مُلک کښې اوسيږى او د غېرو قومونو د ښځو نه ځان خلاص کړئ.“', NULL, '&nbsp;نو اوس مالِک خُدائ د خپل پلار نيکۀ خُدائ پاک ته د خپلو ګناهونو اِقرار وکړئ او هغه کار کوئ چې هغه پرې رضا کيږى. د پردى مُلک د هغه خلقو نه خپل ځانونه جدا کړئ چې کوم زمونږ په مُلک کښې اوسيږى او د غېرو قومونو د ښځو نه ځان خلاص کړئ.“', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_ezra010_verse_011.mp3', NULL, 1761760676, 1761760676),
(11407, 'Ezra 10:12', 'Ezra', 10, 12, '&nbsp;نو ټولې ګڼې په جواب کښې چغه کړه، ”تۀ صحيح خبره کوې او چې څۀ وائې نو مونږ به هغه هر څۀ وکړُو.“', NULL, '&nbsp;نو ټولې ګڼې په جواب کښې چغه کړه، ”تۀ صحيح خبره کوې او چې څۀ وائې نو مونږ به هغه هر څۀ وکړُو.“', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_ezra010_verse_012.mp3', NULL, 1761760676, 1761760676),
(11408, 'Ezra 10:13', 'Ezra', 10, 13, '&nbsp;خو هغوئ دا هم ووئيل، ”ګڼه ډېره لويه ده او دا د باران موسم دے. مونږ دلته په داسې کولاو ځائ کښې نۀ شُو ودرېدے. دا داسې کار نۀ دے چې په يو دوو ورځو کښې وشى، ځکه چې په دې ګناه کښې زمونږ ډېر کسان شامل دى.', NULL, '&nbsp;خو هغوئ دا هم ووئيل، ”ګڼه ډېره لويه ده او دا د باران موسم دے. مونږ دلته په داسې کولاو ځائ کښې نۀ شُو ودرېدے. دا داسې کار نۀ دے چې په يو دوو ورځو کښې وشى، ځکه چې په دې ګناه کښې زمونږ ډېر کسان شامل دى.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_ezra010_verse_013.mp3', NULL, 1761760676, 1761760676),
(11409, 'Ezra 10:14', 'Ezra', 10, 14, '&nbsp;زمونږ آفسران دې زمونږ ټولو په ځائ کار وکړى. بيا هغه هر يو دې چې د غېر قوم ښځه لرى هغه دې په يو مقرر وخت باندې د مشرانو او د خپل ښار د قاضيانو سره راشى. نو د دې معاملې په حقله به د خُدائ پاک قهر سوړ شى.“', NULL, '&nbsp;زمونږ آفسران دې زمونږ ټولو په ځائ کار وکړى. بيا هغه هر يو دې چې د غېر قوم ښځه لرى هغه دې په يو مقرر وخت باندې د مشرانو او د خپل ښار د قاضيانو سره راشى. نو د دې معاملې په حقله به د خُدائ پاک قهر سوړ شى.“', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_ezra010_verse_014.mp3', NULL, 1761760676, 1761760676),
(11410, 'Ezra 10:15', 'Ezra', 10, 15, '&nbsp;صرف د عساهيل زوئ يونتن، د تِقوه زوئ يحزياه د دې منصوبې مخالفت وکړو، مسلام او يو ليوى سبتى ورسره په دې کښې ملګرى وُو.', NULL, '&nbsp;صرف د عساهيل زوئ يونتن، د تِقوه زوئ يحزياه د دې منصوبې مخالفت وکړو، مسلام او يو ليوى سبتى ورسره په دې کښې ملګرى وُو.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_ezra010_verse_015.mp3', NULL, 1761760676, 1761760676),
(11411, 'Ezra 10:16', 'Ezra', 10, 16, '&nbsp;د جلاوطنۍ نه راواپس شوو کسانو دا منصوبه منظوره کړه، نو عزرا اِمام د ډلو د مشرانو نه سړى مقرر کړل او د هغوئ نومونه يې وليکل. د لسمې مياشتې په وړومبۍ ورځ هغوئ تفتيش شروع کړو،', NULL, '&nbsp;د جلاوطنۍ نه راواپس شوو کسانو دا منصوبه منظوره کړه، نو عزرا اِمام د ډلو د مشرانو نه سړى مقرر کړل او د هغوئ نومونه يې وليکل. د لسمې مياشتې په وړومبۍ ورځ هغوئ تفتيش شروع کړو،', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_ezra010_verse_016.mp3', NULL, 1761760676, 1761760676),
(11412, 'Ezra 10:17', 'Ezra', 10, 17, '&nbsp;او په ورپسې درېو مياشتو کښې هغوئ د هغه ټولو معامِلو معلومات وکړو چې کومو سړو د غېرو قومونو د ښځو سره ودونه کړى وُو.', NULL, '&nbsp;او په ورپسې درېو مياشتو کښې هغوئ د هغه ټولو معامِلو معلومات وکړو چې کومو سړو د غېرو قومونو د ښځو سره ودونه کړى وُو.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_ezra010_verse_017.mp3', NULL, 1761760676, 1761760676),
(11413, 'Ezra 10:18', 'Ezra', 10, 18, '&nbsp;دا د هغه سړو نومونه دى چا چې د غېرو قومونو ښځې کړې وې، د هغه اِمامانو نومونه د قبيلې په حِساب سره ليکلے شوى دى: د يشوَع ډله او د هغۀ د وروڼو چې د يوصدق زامن وُو: معسياه، اِلى‌عزر، يريب او جدلياه.', NULL, '&nbsp;دا د هغه سړو نومونه دى چا چې د غېرو قومونو ښځې کړې وې، د هغه اِمامانو نومونه د قبيلې په حِساب سره ليکلے شوى دى: د يشوَع ډله او د هغۀ د وروڼو چې د يوصدق زامن وُو: معسياه، اِلى‌عزر، يريب او جدلياه.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_ezra010_verse_018.mp3', NULL, 1761760676, 1761760676),
(11414, 'Ezra 10:19', 'Ezra', 10, 19, '&nbsp;هغوئ دا قسم وکړو چې خپلو ښځو له به طلاق ورکړى او د خپلو د ګناه د تاوان د نذرانو دپاره يې د يو يو ګډ نذرانه پېش کړه.', NULL, '&nbsp;هغوئ دا قسم وکړو چې خپلو ښځو له به طلاق ورکړى او د خپلو د ګناه د تاوان د نذرانو دپاره يې د يو يو ګډ نذرانه پېش کړه.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_ezra010_verse_019.mp3', NULL, 1761760676, 1761760676),
