(11428, 'Ezra 10:44', 'Ezra', 10, 44, '&nbsp;دې هر يو سړى د غېرو قومونو ښځې لرلې او د څۀ سړو د دې ښځو نه بچى هم پېدا شوى وُو.', NULL, '&nbsp;دې هر يو سړى د غېرو قومونو ښځې لرلې او د څۀ سړو د دې ښځو نه بچى هم پېدا شوى وُو.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761760676, 1761760676),
(11429, 'Nehemiah 1:1', 'Nehemiah', 1, 1, '&nbsp;دا د حکلياه د زوئ د حضرت نحمياه کلام دے. کله چې ارتخششتا د فارس بادشاه وو نو د هغۀ د بادشاهۍ په شلم کال د کِسليو په مياشت کښې زۀ يعنې حضرت نحمياه په مرکزى ښار سوسه کښې وم.', NULL, '&nbsp;دا د حکلياه د زوئ د حضرت نحمياه کلام دے. کله چې ارتخششتا د فارس بادشاه وو نو د هغۀ د بادشاهۍ په شلم کال د کِسليو په مياشت کښې زۀ يعنې حضرت نحمياه په مرکزى ښار سوسه کښې وم.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah001_verse_001.mp3', NULL, 1761760676, 1761760676),
(11430, 'Nehemiah 1:2', 'Nehemiah', 1, 2, '&nbsp;زما ورور حنانى د يهوداه د يو څو سړو سره راورسېدو او ما د هغوئ نه د يروشلم او د هغه يهوديانو په حقله تپوس وکړو کوم چې د بابل د جلاوطنۍ نه راواپس شوى وُو.', NULL, '&nbsp;زما ورور حنانى د يهوداه د يو څو سړو سره راورسېدو او ما د هغوئ نه د يروشلم او د هغه يهوديانو په حقله تپوس وکړو کوم چې د بابل د جلاوطنۍ نه راواپس شوى وُو.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah001_verse_002.mp3', NULL, 1761760676, 1761760676),
(11431, 'Nehemiah 1:3', 'Nehemiah', 1, 3, '&nbsp;هغوئ ما ته ووئيل چې کوم کسان د جلاوطنۍ نه بچ شوى وُو او د يهوداه صُوبې ته واپس راغلى وُو هغوئ د لوئ تکليف او بې‌عزتۍ سره مخ وُو. هغوئ ما ته دا هم ووئيل چې د يروشلم دېوالونه تر اوسه پورې مات پراتۀ دى او د دې دروازې د هغه وخت نه بيا نۀ دى جوړې شوې چې د کوم وخت نه هغه په اور سوزولے شوې وې.', NULL, '&nbsp;هغوئ ما ته ووئيل چې کوم کسان د جلاوطنۍ نه بچ شوى وُو او د يهوداه صُوبې ته واپس راغلى وُو هغوئ د لوئ تکليف او بې‌عزتۍ سره مخ وُو. هغوئ ما ته دا هم ووئيل چې د يروشلم دېوالونه تر اوسه پورې مات پراتۀ دى او د دې دروازې د هغه وخت نه بيا نۀ دى جوړې شوې چې د کوم وخت نه هغه په اور سوزولے شوې وې.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah001_verse_003.mp3', NULL, 1761760676, 1761760676),
(11432, 'Nehemiah 1:4', 'Nehemiah', 1, 4, '&nbsp;کله چې زۀ د دې هر څۀ نه خبر شوم، نو زۀ کښېناستم او ومې ژړل. څو ورځې زۀ غمژن وم او خوراک مې نۀ کولو. ما د آسمان خُدائ پاک ته سوال وکړو', NULL, '&nbsp;کله چې زۀ د دې هر څۀ نه خبر شوم، نو زۀ کښېناستم او ومې ژړل. څو ورځې زۀ غمژن وم او خوراک مې نۀ کولو. ما د آسمان خُدائ پاک ته سوال وکړو', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah001_verse_004.mp3', NULL, 1761760676, 1761760676),
(11433, 'Nehemiah 1:5', 'Nehemiah', 1, 5, '&nbsp;او ما ووئيل، ”اے مالِکه خُدايه، د آسمان خُدايه پاکه، اے عظيمه او د رُعب خُدايه پاکه، تۀ د هغه چا سره خپل د رحم لوظ پوره کوې چې څوک درسره مينه کوى او ستا حُکمونه منى،', NULL, '&nbsp;او ما ووئيل، ”اے مالِکه خُدايه، د آسمان خُدايه پاکه، اے عظيمه او د رُعب خُدايه پاکه، تۀ د هغه چا سره خپل د رحم لوظ پوره کوې چې څوک درسره مينه کوى او ستا حُکمونه منى،', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah001_verse_005.mp3', NULL, 1761760676, 1761760676),
(11434, 'Nehemiah 1:6', 'Nehemiah', 1, 6, '&nbsp;مالِکه خُدايه، ما ته وګوره او زما سوال واوره، لکه څنګه چې زۀ ستا د خِدمتګارانو يعنې بنى اِسرائيلو دپاره شپه او ورځ دُعا کوم. زۀ دا اِقرار کوم چې مونږ بنى اِسرائيلو ګناه کړې ده. ما او زما پلار نيکۀ ګناه کړې ده.', NULL, '&nbsp;مالِکه خُدايه، ما ته وګوره او زما سوال واوره، لکه څنګه چې زۀ ستا د خِدمتګارانو يعنې بنى اِسرائيلو دپاره شپه او ورځ دُعا کوم. زۀ دا اِقرار کوم چې مونږ بنى اِسرائيلو ګناه کړې ده. ما او زما پلار نيکۀ ګناه کړې ده.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah001_verse_006.mp3', NULL, 1761760676, 1761760676),
(11435, 'Nehemiah 1:7', 'Nehemiah', 1, 7, '&nbsp;مونږ ستا خِلاف بدعملې کړې ده او تا چې څۀ حُکم کړے وو په هغې مو عمل نۀ دے کړے. تا چې د خپل خِدمتګار موسىٰ په ذريعه کوم قانون مونږ له راکړے وو په هغې مو عمل نۀ دے کړے.', NULL, '&nbsp;مونږ ستا خِلاف بدعملې کړې ده او تا چې څۀ حُکم کړے وو په هغې مو عمل نۀ دے کړے. تا چې د خپل خِدمتګار موسىٰ په ذريعه کوم قانون مونږ له راکړے وو په هغې مو عمل نۀ دے کړے.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah001_verse_007.mp3', NULL, 1761760676, 1761760676),
(11436, 'Nehemiah 1:8', 'Nehemiah', 1, 8, '&nbsp;تۀ اوس هغه څۀ راياد کړه چې خپل خِدمت کوونکى موسىٰ ته دې فرمائيلى وُو چې کۀ تاسو بنى اِسرائيلو ما سره بې‌وفائى وکړه، نو زۀ به تاسو په نورو قومونو کښې خوارۀ وارۀ کړم.', NULL, '&nbsp;تۀ اوس هغه څۀ راياد کړه چې خپل خِدمت کوونکى موسىٰ ته دې فرمائيلى وُو چې کۀ تاسو بنى اِسرائيلو ما سره بې‌وفائى وکړه، نو زۀ به تاسو په نورو قومونو کښې خوارۀ وارۀ کړم.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah001_verse_008.mp3', NULL, 1761760676, 1761760676),
(11437, 'Nehemiah 1:9', 'Nehemiah', 1, 9, '&nbsp;خو کۀ بيا تاسو ما ته راوګرځېدئ او زما په حُکمونو عمل کوئ، نو زۀ به تاسو واپس هغه ځائ ته راولم کوم ځائ چې ما د خپل نوم د درناوى دپاره خوښ کړے دے، کۀ تاسو د دُنيا د يو سر نه تر بل سره پورې هم خوارۀ وارۀ يئ.', NULL, '&nbsp;خو کۀ بيا تاسو ما ته راوګرځېدئ او زما په حُکمونو عمل کوئ، نو زۀ به تاسو واپس هغه ځائ ته راولم کوم ځائ چې ما د خپل نوم د درناوى دپاره خوښ کړے دے، کۀ تاسو د دُنيا د يو سر نه تر بل سره پورې هم خوارۀ وارۀ يئ.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah001_verse_009.mp3', NULL, 1761760676, 1761760676),
(11438, 'Nehemiah 1:10', 'Nehemiah', 1, 10, '&nbsp;مالِکه خُدايه، دا ستا خِدمتګاران او ستا خپل خلق دى. تا هغوئ د خپل لوئ طاقت او قوت سره په بيعه آزاد کړل.', NULL, '&nbsp;مالِکه خُدايه، دا ستا خِدمتګاران او ستا خپل خلق دى. تا هغوئ د خپل لوئ طاقت او قوت سره په بيعه آزاد کړل.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah001_verse_010.mp3', NULL, 1761760676, 1761760676),
(11439, 'Nehemiah 1:11', 'Nehemiah', 1, 11, '&nbsp;مالِکه خُدايه، اوس زما سوال واوره او د خپلو نورو ټولو خِدمتګارانو دُعاګانې واوره چې چا ته ستا د نوم په درناوى کولو کښې خوشحالى ملاويږى. او ما له کاميابى راکړه او داسې بادشاه نن په ما مِهربانه کړه. د هغۀ په زړۀ کښې دا خبره واچوه چې په ما رحم وکړى.“ په هغه وخت کښې زۀ د بادشاه ساقى وم.', NULL, '&nbsp;مالِکه خُدايه، اوس زما سوال واوره او د خپلو نورو ټولو خِدمتګارانو دُعاګانې واوره چې چا ته ستا د نوم په درناوى کولو کښې خوشحالى ملاويږى. او ما له کاميابى راکړه او داسې بادشاه نن په ما مِهربانه کړه. د هغۀ په زړۀ کښې دا خبره واچوه چې په ما رحم وکړى.“ په هغه وخت کښې زۀ د بادشاه ساقى وم.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah001_verse_011.mp3', NULL, 1761760676, 1761760676),
(11440, 'Nehemiah 2:1', 'Nehemiah', 2, 1, '&nbsp;د ارتخششتا بادشاه د بادشاهۍ په شلم کال د نيسان په مياشت کښې په کوم وخت چې بادشاه له مے راغلل، نو ما مے واخستل او بادشاه له مې ورکړل. زۀ د هغۀ په حضور کښې د دې نه مخکښې هيڅکله نۀ وم خفه شوے،', NULL, '&nbsp;د ارتخششتا بادشاه د بادشاهۍ په شلم کال د نيسان په مياشت کښې په کوم وخت چې بادشاه له مے راغلل، نو ما مے واخستل او بادشاه له مې ورکړل. زۀ د هغۀ په حضور کښې د دې نه مخکښې هيڅکله نۀ وم خفه شوے،', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah002_verse_001.mp3', NULL, 1761760676, 1761760676),
(11441, 'Nehemiah 2:2', 'Nehemiah', 2, 2, '&nbsp;نو ځکه هغۀ تپوس وکړو، ”تۀ ولې دومره غمژن يې؟ تۀ خو بيمار هم نۀ يې، ما ته پته ده چې تۀ ډېر سخت خفه يې.“ زۀ ډېر زيات يرېدم', NULL, '&nbsp;نو ځکه هغۀ تپوس وکړو، ”تۀ ولې دومره غمژن يې؟ تۀ خو بيمار هم نۀ يې، ما ته پته ده چې تۀ ډېر سخت خفه يې.“ زۀ ډېر زيات يرېدم', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah002_verse_002.mp3', NULL, 1761760676, 1761760676),
