(11444, 'Nehemiah 2:5', 'Nehemiah', 2, 5, '&nbsp;او بيا مې بادشاه ته ووئيل، ”بادشاه سلامت، کۀ تۀ په ما باندې مِهربانى کول غواړې او دا چې زما درخواست منظور کړې، نو ما له دا اجازت راکړه چې زۀ يهوداه ته لاړ شم، نو چې داسې زۀ هغه ښار بيا جوړ کړم چرته چې زما پلار نيکۀ ښخ شوى دى.“', NULL, '&nbsp;او بيا مې بادشاه ته ووئيل، ”بادشاه سلامت، کۀ تۀ په ما باندې مِهربانى کول غواړې او دا چې زما درخواست منظور کړې، نو ما له دا اجازت راکړه چې زۀ يهوداه ته لاړ شم، نو چې داسې زۀ هغه ښار بيا جوړ کړم چرته چې زما پلار نيکۀ ښخ شوى دى.“', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah002_verse_005.mp3', NULL, 1761760676, 1761760676),
