(11447, 'Nehemiah 2:8', 'Nehemiah', 2, 8, '&nbsp;ما د شاهى ځنګلو څوکيدار آسف دپاره هم يو خط وغوښتو، چې هغۀ ته په کښې ليکلى شوى وُو چې د هغه قلعې د دروازو دپاره چې د خُدائ پاک د کور حِفاظت کوى، د ښار د دېوالونو دپاره او د هغه کور دپاره ما له لرګى راکړى چې په کوم کښې به زۀ اوسېدم. ما چې څۀ غوښتى وُو نو بادشاه ما له هغه هر څۀ راکړل، ځکه چې خُدائ پاک په ما مِهربانه وو.', NULL, '&nbsp;ما د شاهى ځنګلو څوکيدار آسف دپاره هم يو خط وغوښتو، چې هغۀ ته په کښې ليکلى شوى وُو چې د هغه قلعې د دروازو دپاره چې د خُدائ پاک د کور حِفاظت کوى، د ښار د دېوالونو دپاره او د هغه کور دپاره ما له لرګى راکړى چې په کوم کښې به زۀ اوسېدم. ما چې څۀ غوښتى وُو نو بادشاه ما له هغه هر څۀ راکړل، ځکه چې خُدائ پاک په ما مِهربانه وو.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah002_verse_008.mp3', NULL, 1761760676, 1761760676),
(11448, 'Nehemiah 2:9', 'Nehemiah', 2, 9, '&nbsp;نو بادشاه ما سره يو څو فوجى آفسران او په آسونو د سوارو کسانو يوه ډله ولېږله او زۀ د نمرپرېواتۀ طرف ته فرات په سفر باندې روان شوم. هلته مې حکمرانانو له د بادشاه خطونه ورکړل.', NULL, '&nbsp;نو بادشاه ما سره يو څو فوجى آفسران او په آسونو د سوارو کسانو يوه ډله ولېږله او زۀ د نمرپرېواتۀ طرف ته فرات په سفر باندې روان شوم. هلته مې حکمرانانو له د بادشاه خطونه ورکړل.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah002_verse_009.mp3', NULL, 1761760676, 1761760676),
(11449, 'Nehemiah 2:10', 'Nehemiah', 2, 10, '&nbsp;خو د بيت‌حورون ښار سنبلط، او طوبياه چې هغه د عمون صُوبې يو آفسر وو، خبر شو چې څوک راغلى دى چې د بنى اِسرائيلو د فائدې دپاره کار کوى، نو هغوئ ډېر زيات خفه شول.', NULL, '&nbsp;خو د بيت‌حورون ښار سنبلط، او طوبياه چې هغه د عمون صُوبې يو آفسر وو، خبر شو چې څوک راغلى دى چې د بنى اِسرائيلو د فائدې دپاره کار کوى، نو هغوئ ډېر زيات خفه شول.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah002_verse_010.mp3', NULL, 1761760676, 1761760676),
(11450, 'Nehemiah 2:11', 'Nehemiah', 2, 11, '&nbsp;زۀ يروشلم ته لاړم او تر درېو ورځو پورې', NULL, '&nbsp;زۀ يروشلم ته لاړم او تر درېو ورځو پورې', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah002_verse_011.mp3', NULL, 1761760676, 1761760676),
(11451, 'Nehemiah 2:12', 'Nehemiah', 2, 12, '&nbsp;ما هيچا ته هغه خبره ونۀ کړه چې کومه خُدائ پاک زما په زړۀ کښې د يروشلم په حقله اچولې وه. بيا په نيمه شپه زۀ پاڅېدم او بهر لاړم، يو څو ملګرى مې ځان سره کړل. مونږ صِرف يو ځناور د ځان سره بوتلو، دا هغه خر وو چې په کوم زۀ سور وم.', NULL, '&nbsp;ما هيچا ته هغه خبره ونۀ کړه چې کومه خُدائ پاک زما په زړۀ کښې د يروشلم په حقله اچولې وه. بيا په نيمه شپه زۀ پاڅېدم او بهر لاړم، يو څو ملګرى مې ځان سره کړل. مونږ صِرف يو ځناور د ځان سره بوتلو، دا هغه خر وو چې په کوم زۀ سور وم.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah002_verse_012.mp3', NULL, 1761760676, 1761760676),
(11452, 'Nehemiah 2:13', 'Nehemiah', 2, 13, '&nbsp;کله چې زۀ د ښار نه روان شوم نو تر اوسه پورې شپه وه. د وادۍ په دروازه باندې ووتلم او د ګيدړ کوهى نه تېر شوم او د ګند دروازې ته لاړم. کله چې زۀ روان وم، نو ما د ښار غورزېدلى دېوالونه او هغه دروازې وليدې کومې چې په اور تباه شوې وې.', NULL, '&nbsp;کله چې زۀ د ښار نه روان شوم نو تر اوسه پورې شپه وه. د وادۍ په دروازه باندې ووتلم او د ګيدړ کوهى نه تېر شوم او د ګند دروازې ته لاړم. کله چې زۀ روان وم، نو ما د ښار غورزېدلى دېوالونه او هغه دروازې وليدې کومې چې په اور تباه شوې وې.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah002_verse_013.mp3', NULL, 1761760676, 1761760676),
(11453, 'Nehemiah 2:14', 'Nehemiah', 2, 14, '&nbsp;نو بيا زۀ د فوارې دروازې ته او د بادشاه تالاب ته لاړم، خو په کوم خر باندې چې ما سورلى کوله نو هغۀ د تېرېدو لار پېدا نۀ کړه،', NULL, '&nbsp;نو بيا زۀ د فوارې دروازې ته او د بادشاه تالاب ته لاړم، خو په کوم خر باندې چې ما سورلى کوله نو هغۀ د تېرېدو لار پېدا نۀ کړه،', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah002_verse_014.mp3', NULL, 1761760676, 1761760676),
(11454, 'Nehemiah 2:15', 'Nehemiah', 2, 15, '&nbsp;بيا زۀ لاندې د قِدرون وادۍ ته لاړم او په خر باندې سور وم، دېوال ته مې کتل. بيا زۀ په هغه لار راواپس شوم چې په کومه راغلے وم او د وادۍ په دروازه باندې واپس ښار ته لاړم.', NULL, '&nbsp;بيا زۀ لاندې د قِدرون وادۍ ته لاړم او په خر باندې سور وم، دېوال ته مې کتل. بيا زۀ په هغه لار راواپس شوم چې په کومه راغلے وم او د وادۍ په دروازه باندې واپس ښار ته لاړم.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah002_verse_015.mp3', NULL, 1761760676, 1761760676),
(11455, 'Nehemiah 2:16', 'Nehemiah', 2, 16, '&nbsp;د هغې علاقې يو آفسر ته هم دا پته ونۀ لګېده چې زۀ چرته وم يا مې څۀ کول. تر اوسه پورې ما يهوديانو، اِمامانو، مشرانو، آفسرانو، يا بل چا ته هيڅ نۀ وُو وئيلى چې څوک به دا کار کوى.', NULL, '&nbsp;د هغې علاقې يو آفسر ته هم دا پته ونۀ لګېده چې زۀ چرته وم يا مې څۀ کول. تر اوسه پورې ما يهوديانو، اِمامانو، مشرانو، آفسرانو، يا بل چا ته هيڅ نۀ وُو وئيلى چې څوک به دا کار کوى.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah002_verse_016.mp3', NULL, 1761760676, 1761760676),
(11456, 'Nehemiah 2:17', 'Nehemiah', 2, 17, '&nbsp;خو بيا ما هغوئ ته ووئيل، ”ګورئ مونږ په دې وجه په تکليف کښې يُو چې يروشلم تباه شوے دے او د دې دروازې سوزولے شوې دى. راځئ چې د يروشلم دېوالونه بيا جوړ کړُو او د دې بې‌عزتۍ نه ځان خلاص کړُو.“', NULL, '&nbsp;خو بيا ما هغوئ ته ووئيل، ”ګورئ مونږ په دې وجه په تکليف کښې يُو چې يروشلم تباه شوے دے او د دې دروازې سوزولے شوې دى. راځئ چې د يروشلم دېوالونه بيا جوړ کړُو او د دې بې‌عزتۍ نه ځان خلاص کړُو.“', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah002_verse_017.mp3', NULL, 1761760676, 1761760676),
(11457, 'Nehemiah 2:18', 'Nehemiah', 2, 18, '&nbsp;او ما هغوئ ته ووئيل چې خُدائ پاک زما څنګه مل وو او هغه څۀ مې ورته ووئيل چې ما ته بادشاه وئيلى وُو. نو هغوئ په جواب کښې ووئيل، ”راځئ چې د دېوالونو په جوړولو بيا شروع وکړُو.“ او هغوئ د نېکۍ په دې کار کولو باندې شروع وکړه.', NULL, '&nbsp;او ما هغوئ ته ووئيل چې خُدائ پاک زما څنګه مل وو او هغه څۀ مې ورته ووئيل چې ما ته بادشاه وئيلى وُو. نو هغوئ په جواب کښې ووئيل، ”راځئ چې د دېوالونو په جوړولو بيا شروع وکړُو.“ او هغوئ د نېکۍ په دې کار کولو باندې شروع وکړه.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah002_verse_018.mp3', NULL, 1761760676, 1761760676),
(11458, 'Nehemiah 2:19', 'Nehemiah', 2, 19, '&nbsp;کله چې سنبلط حورونى، عمونى طوبياه او جشم نومې يو عربے زمونږ د منصوبې نه خبر شول، نو هغوئ په مونږ پورې ټوقې او مسخرې وکړې او وې وئيل، ”تاسو دا څۀ شروع کړى دى؟ ولې تاسو د بادشاه خِلاف بغاوت کول غواړئ؟“', NULL, '&nbsp;کله چې سنبلط حورونى، عمونى طوبياه او جشم نومې يو عربے زمونږ د منصوبې نه خبر شول، نو هغوئ په مونږ پورې ټوقې او مسخرې وکړې او وې وئيل، ”تاسو دا څۀ شروع کړى دى؟ ولې تاسو د بادشاه خِلاف بغاوت کول غواړئ؟“', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah002_verse_019.mp3', NULL, 1761760676, 1761760676),
(11459, 'Nehemiah 2:20', 'Nehemiah', 2, 20, '&nbsp;ما جواب ورکړو، ”د آسمان خُدائ پاک به مونږ له کاميابى راکړى. مونږ د هغۀ خِدمت کوونکى يُو او مونږ کار شروع کوُو. خو تاسو په يروشلم کښې د جائيداد لرلو هيڅ حق نۀ لرئ، او نۀ حِصه لرئ.“', NULL, '&nbsp;ما جواب ورکړو، ”د آسمان خُدائ پاک به مونږ له کاميابى راکړى. مونږ د هغۀ خِدمت کوونکى يُو او مونږ کار شروع کوُو. خو تاسو په يروشلم کښې د جائيداد لرلو هيڅ حق نۀ لرئ، او نۀ حِصه لرئ.“', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah002_verse_020.mp3', NULL, 1761760676, 1761760676),
(11460, 'Nehemiah 3:1', 'Nehemiah', 3, 1, '&nbsp;بيا مشر اِمام اِلياسب او د هغۀ ملګرو اِمامانو د ګډو دروازه بيا جوړه کړه، هغوئ هغه وقف کړه او دروازې يې په خپل ځائ ولګولې. هغوئ د سلو مينارو پورې دېوال او د حنن‌ايل ميناره پورې دېوال وقف کړو.', NULL, '&nbsp;بيا مشر اِمام اِلياسب او د هغۀ ملګرو اِمامانو د ګډو دروازه بيا جوړه کړه، هغوئ هغه وقف کړه او دروازې يې په خپل ځائ ولګولې. هغوئ د سلو مينارو پورې دېوال او د حنن‌ايل ميناره پورې دېوال وقف کړو.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah003_verse_001.mp3', NULL, 1761760676, 1761760676),
(11461, 'Nehemiah 3:2', 'Nehemiah', 3, 2, '&nbsp;د يريحو خلقو ورپسې برخه جوړه کړه. د اِمرى زوئ زکور بله برخه جوړه کړه.', NULL, '&nbsp;د يريحو خلقو ورپسې برخه جوړه کړه. د اِمرى زوئ زکور بله برخه جوړه کړه.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah003_verse_002.mp3', NULL, 1761760676, 1761760676),
(11462, 'Nehemiah 3:3', 'Nehemiah', 3, 3, '&nbsp;د سناآه قبيلې د کبانو دروازه جوړه کړه. هغوئ تيرونه او دروازې په خپل ځائ باندې ولګولې، د دروازې د تالا کولو دپاره يې سيخونه او زنځيرونه ولګول.', NULL, '&nbsp;د سناآه قبيلې د کبانو دروازه جوړه کړه. هغوئ تيرونه او دروازې په خپل ځائ باندې ولګولې، د دروازې د تالا کولو دپاره يې سيخونه او زنځيرونه ولګول.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah003_verse_003.mp3', NULL, 1761760676, 1761760676),
(11463, 'Nehemiah 3:4', 'Nehemiah', 3, 4, '&nbsp;د اورِياه زوئ او د هقوض نمسى مريموت ورپسې برخه جوړه کړه. د برکياه زوئ او د مشيزب‌ايل نمسى مسلام ورپسې برخه جوړه کړه. د بعنه زوئ صدوق بله برخه جوړه کړه.', NULL, '&nbsp;د اورِياه زوئ او د هقوض نمسى مريموت ورپسې برخه جوړه کړه. د برکياه زوئ او د مشيزب‌ايل نمسى مسلام ورپسې برخه جوړه کړه. د بعنه زوئ صدوق بله برخه جوړه کړه.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah003_verse_004.mp3', NULL, 1761760676, 1761760676),
(11464, 'Nehemiah 3:5', 'Nehemiah', 3, 5, '&nbsp;د تقوع سړو ورپسې برخه جوړه کړه، خو د هغوئ مشرانو د هغه کار کولو نه اِنکار وکړو کوم کار چې هغوئ ته خپلو ټېکدارانو حواله کړے وو.', NULL, '&nbsp;د تقوع سړو ورپسې برخه جوړه کړه، خو د هغوئ مشرانو د هغه کار کولو نه اِنکار وکړو کوم کار چې هغوئ ته خپلو ټېکدارانو حواله کړے وو.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah003_verse_005.mp3', NULL, 1761760676, 1761760676),
(11465, 'Nehemiah 3:6', 'Nehemiah', 3, 6, '&nbsp;د فاسح زوئ يويدع او د بسودياه زوئ مسلام د يسانه دروازه بيا جوړه کړه. هغوئ تيرونه او دروازې په خپلو ځايونو کښې ولګول او د تاله کولو دپاره يې په دروازه کښې اړمونه او کُنډې ولګول.', NULL, '&nbsp;د فاسح زوئ يويدع او د بسودياه زوئ مسلام د يسانه دروازه بيا جوړه کړه. هغوئ تيرونه او دروازې په خپلو ځايونو کښې ولګول او د تاله کولو دپاره يې په دروازه کښې اړمونه او کُنډې ولګول.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah003_verse_006.mp3', NULL, 1761760676, 1761760676),
(11466, 'Nehemiah 3:7', 'Nehemiah', 3, 7, '&nbsp;د جبعون ملطياه، د مرونوت يدون او د جبعون او مصفاه سړو ورپسې برخه جوړه کړه چې د نمرپرېواتۀ طرف ته فرات د حکمران کور پورې حِصه وه.', NULL, '&nbsp;د جبعون ملطياه، د مرونوت يدون او د جبعون او مصفاه سړو ورپسې برخه جوړه کړه چې د نمرپرېواتۀ طرف ته فرات د حکمران کور پورې حِصه وه.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah003_verse_007.mp3', NULL, 1761760676, 1761760676),
(11467, 'Nehemiah 3:8', 'Nehemiah', 3, 8, '&nbsp;د حرهياه زوئ عُزى‌اېل زرګر ورپسې برخه جوړه کړه. حننياه عطر جوړوونکى ورپسې برخه جوړه کړه، چې د پلن دېوال پورې حِصه وه.', NULL, '&nbsp;د حرهياه زوئ عُزى‌اېل زرګر ورپسې برخه جوړه کړه. حننياه عطر جوړوونکى ورپسې برخه جوړه کړه، چې د پلن دېوال پورې حِصه وه.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah003_verse_008.mp3', NULL, 1761760676, 1761760676),
(11468, 'Nehemiah 3:9', 'Nehemiah', 3, 9, '&nbsp;د يروشلم د نيمې ضِلعې حکمران د حُور زوئ رفاياه ورپسې برخه جوړه کړه.', NULL, '&nbsp;د يروشلم د نيمې ضِلعې حکمران د حُور زوئ رفاياه ورپسې برخه جوړه کړه.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah003_verse_009.mp3', NULL, 1761760676, 1761760676),
(11469, 'Nehemiah 3:10', 'Nehemiah', 3, 10, '&nbsp;د حرومف زوئ يدعياه ورپسې برخه جوړه کړه، کومه چې د هغۀ د خپل کور سره نزدې وه. د حسبنياه زوئ حطوش ورپسې برخه جوړه کړه.', NULL, '&nbsp;د حرومف زوئ يدعياه ورپسې برخه جوړه کړه، کومه چې د هغۀ د خپل کور سره نزدې وه. د حسبنياه زوئ حطوش ورپسې برخه جوړه کړه.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah003_verse_010.mp3', NULL, 1761760676, 1761760676),
(11470, 'Nehemiah 3:11', 'Nehemiah', 3, 11, '&nbsp;د حارِم زوئ مُلکياه او د پخت موآب زوئ حسوب دوئ دواړو ورپسې برخه او د تنور ميناره يې جوړه کړه.', NULL, '&nbsp;د حارِم زوئ مُلکياه او د پخت موآب زوئ حسوب دوئ دواړو ورپسې برخه او د تنور ميناره يې جوړه کړه.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah003_verse_011.mp3', NULL, 1761760676, 1761760676),
(11471, 'Nehemiah 3:12', 'Nehemiah', 3, 12, '&nbsp;د يروشلم د نورې نيمې ضِلعې حکمران يعنې د هلوحيس زوئ سلوم ورپسې برخه جوړه کړه. د هغۀ لوڼو په دې کار کښې د هغۀ مدد کولو.', NULL, '&nbsp;د يروشلم د نورې نيمې ضِلعې حکمران يعنې د هلوحيس زوئ سلوم ورپسې برخه جوړه کړه. د هغۀ لوڼو په دې کار کښې د هغۀ مدد کولو.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah003_verse_012.mp3', NULL, 1761760676, 1761760676),
(11472, 'Nehemiah 3:13', 'Nehemiah', 3, 13, '&nbsp;حنون او د زنوح ښار اوسېدونکو د وادۍ دروازه بيا جوړه کړه. هغوئ هغه دروازې په خپلو خپلو ځايونو باندې ولګولې، هغوئ د دروازې تالا کولو دپاره په دې کښې سيخونه او زنځيرونه ولګول او د ګند دروازې پورې هغوئ پينځۀ سوه ګزه دېوال بيا جوړ کړو.', NULL, '&nbsp;حنون او د زنوح ښار اوسېدونکو د وادۍ دروازه بيا جوړه کړه. هغوئ هغه دروازې په خپلو خپلو ځايونو باندې ولګولې، هغوئ د دروازې تالا کولو دپاره په دې کښې سيخونه او زنځيرونه ولګول او د ګند دروازې پورې هغوئ پينځۀ سوه ګزه دېوال بيا جوړ کړو.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah003_verse_013.mp3', NULL, 1761760676, 1761760676),
(11473, 'Nehemiah 3:14', 'Nehemiah', 3, 14, '&nbsp;د بيت‌هکرم ضِلعې حکمران د ريکاب زوئ مُلکياه د ګند دروازه بيا جوړه کړه. هغۀ دروازې په خپلو ځايونو باندې ولګولې او د دروازې تالا کولو دپاره يې په کښې سيخونه او زنځيرونه ولګول.', NULL, '&nbsp;د بيت‌هکرم ضِلعې حکمران د ريکاب زوئ مُلکياه د ګند دروازه بيا جوړه کړه. هغۀ دروازې په خپلو ځايونو باندې ولګولې او د دروازې تالا کولو دپاره يې په کښې سيخونه او زنځيرونه ولګول.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah003_verse_014.mp3', NULL, 1761760676, 1761760676),
(11474, 'Nehemiah 3:15', 'Nehemiah', 3, 15, '&nbsp;د مصفاه ضِلعې حکمران د کولحوزه زوئ سلوم د فوارې دروازه بيا جوړه کړه. هغۀ د دروازې دپاسه چت جوړ کړو، دروازې يې په خپل ځائ باندې ولګولې او سيخونه او زنځيرونه يې په کښې ولګول. د سِلح تالاب سره د شاهى باغ سره نزدې هغۀ دېوال جوړ کړو، دا تر هغه ځائ پورې وو چرته چې د داؤد د ښار نه لاندې پوړۍ کوزې شوې وې.', NULL, '&nbsp;د مصفاه ضِلعې حکمران د کولحوزه زوئ سلوم د فوارې دروازه بيا جوړه کړه. هغۀ د دروازې دپاسه چت جوړ کړو، دروازې يې په خپل ځائ باندې ولګولې او سيخونه او زنځيرونه يې په کښې ولګول. د سِلح تالاب سره د شاهى باغ سره نزدې هغۀ دېوال جوړ کړو، دا تر هغه ځائ پورې وو چرته چې د داؤد د ښار نه لاندې پوړۍ کوزې شوې وې.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah003_verse_015.mp3', NULL, 1761760676, 1761760676),
(11475, 'Nehemiah 3:16', 'Nehemiah', 3, 16, '&nbsp;د بيت‌صور د نيمې ضِلعې حکمران د عُزبق زوئ نحمياه ورپسې برخه جوړه کړه، چې دا د داؤد د خاندان د قبرستان، تالاب او د فوجيانو کورونو پورې وه.', NULL, '&nbsp;د بيت‌صور د نيمې ضِلعې حکمران د عُزبق زوئ نحمياه ورپسې برخه جوړه کړه، چې دا د داؤد د خاندان د قبرستان، تالاب او د فوجيانو کورونو پورې وه.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah003_verse_016.mp3', NULL, 1761760676, 1761760676),
(11476, 'Nehemiah 3:17', 'Nehemiah', 3, 17, '&nbsp;دې ليويانو د هغه دېوال نورې برخې بيا جوړې کړې: د بانى زوئ رحُوم ورپسې برخه جوړه کړه، د قعيله د نيمې ضِلعې حکمران، حسبياه د خپلې ضِلعې د طرفه ورپسې برخه جوړه کړه،', NULL, '&nbsp;دې ليويانو د هغه دېوال نورې برخې بيا جوړې کړې: د بانى زوئ رحُوم ورپسې برخه جوړه کړه، د قعيله د نيمې ضِلعې حکمران، حسبياه د خپلې ضِلعې د طرفه ورپسې برخه جوړه کړه،', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah003_verse_017.mp3', NULL, 1761760676, 1761760676),
(11477, 'Nehemiah 3:18', 'Nehemiah', 3, 18, '&nbsp;د قعيله د نورې نيمې ضِلعې د حکمران د حنداد زوئ باوى ورپسې برخه جوړه کړه،', NULL, '&nbsp;د قعيله د نورې نيمې ضِلعې د حکمران د حنداد زوئ باوى ورپسې برخه جوړه کړه،', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah003_verse_018.mp3', NULL, 1761760676, 1761760676),
(11478, 'Nehemiah 3:19', 'Nehemiah', 3, 19, '&nbsp;د مصفاه حکمران د يشوَع زوئ ايصر د وسلې د ګودام په مخکښې ورپسې حِصه جوړه کړه، دا تر هغه ځائ پورې وه چرته چې دېوال تاويږى،', NULL, '&nbsp;د مصفاه حکمران د يشوَع زوئ ايصر د وسلې د ګودام په مخکښې ورپسې حِصه جوړه کړه، دا تر هغه ځائ پورې وه چرته چې دېوال تاويږى،', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah003_verse_019.mp3', NULL, 1761760676, 1761760676),
(11479, 'Nehemiah 3:20', 'Nehemiah', 3, 20, '&nbsp;د زبى زوئ باروک ورپسې برخه جوړه کړه، دا تر هغه ځائ پورې وه چرته چې د مشر اِمام اِلياسب کور ته د ننوتلو دروازه وه،', NULL, '&nbsp;د زبى زوئ باروک ورپسې برخه جوړه کړه، دا تر هغه ځائ پورې وه چرته چې د مشر اِمام اِلياسب کور ته د ننوتلو دروازه وه،', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah003_verse_020.mp3', NULL, 1761760676, 1761760676),
(11480, 'Nehemiah 3:21', 'Nehemiah', 3, 21, '&nbsp;د اورِياه زوئ او د هقوض نمسى مريموت ورپسې برخه جوړه کړه، چې دا د اِلياسب د کور تر آخرى سر پورې رسېدلې وه.', NULL, '&nbsp;د اورِياه زوئ او د هقوض نمسى مريموت ورپسې برخه جوړه کړه، چې دا د اِلياسب د کور تر آخرى سر پورې رسېدلې وه.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah003_verse_021.mp3', NULL, 1761760676, 1761760676),
(11481, 'Nehemiah 3:22', 'Nehemiah', 3, 22, '&nbsp;دې اِمامانو د دېوال يو څو نورې برخې بيا جوړې کړې: د يروشلم د ګېرچاپېره علاقې نه اِمامانو ورپسې برخه بيا جوړه کړه،', NULL, '&nbsp;دې اِمامانو د دېوال يو څو نورې برخې بيا جوړې کړې: د يروشلم د ګېرچاپېره علاقې نه اِمامانو ورپسې برخه بيا جوړه کړه،', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah003_verse_022.mp3', NULL, 1761760676, 1761760676),
(11482, 'Nehemiah 3:23', 'Nehemiah', 3, 23, '&nbsp;بنيامين او د حسوب ورپسې برخه جوړه کړه، کومه چې د هغوئ کورونو ته مخامخ وه، د معسياه زوئ او د عننياه نمسى عزرياه ورپسې برخه جوړه کړه، کومه چې د هغۀ د کور مخې ته وه،', NULL, '&nbsp;بنيامين او د حسوب ورپسې برخه جوړه کړه، کومه چې د هغوئ کورونو ته مخامخ وه، د معسياه زوئ او د عننياه نمسى عزرياه ورپسې برخه جوړه کړه، کومه چې د هغۀ د کور مخې ته وه،', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah003_verse_023.mp3', NULL, 1761760676, 1761760676),
(11483, 'Nehemiah 3:24', 'Nehemiah', 3, 24, '&nbsp;د حنداد زوئ بِنوئى ورپسې برخه جوړه کړه، چې دا د عزرياه د کور نه واخله د دېوال د ګوټ پورې وه،', NULL, '&nbsp;د حنداد زوئ بِنوئى ورپسې برخه جوړه کړه، چې دا د عزرياه د کور نه واخله د دېوال د ګوټ پورې وه،', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah003_verse_024.mp3', NULL, 1761760676, 1761760676),
(11484, 'Nehemiah 3:27', 'Nehemiah', 3, 27, '&nbsp;د تقوع سړو ورپسې برخه جوړه کړه، د هغوئ دوېمه برخه، د هغه ځائ نه واخله چې د خُدائ پاک د کور د څوکيدارۍ د لوئې مينارې مخامخ وه د هغې نه واخله تر عوفل سره نزدې دېوال پورې وه.', NULL, '&nbsp;د تقوع سړو ورپسې برخه جوړه کړه، د هغوئ دوېمه برخه، د هغه ځائ نه واخله چې د خُدائ پاک د کور د څوکيدارۍ د لوئې مينارې مخامخ وه د هغې نه واخله تر عوفل سره نزدې دېوال پورې وه.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah003_verse_027.mp3', NULL, 1761760676, 1761760676),
(11485, 'Nehemiah 3:28', 'Nehemiah', 3, 28, '&nbsp;د اِمامانو يوې قبيلې ورپسې برخه جوړه کړه، چې شمالى طرف ته د آسونو د دروازې نه تلې وه، هر يو د خپل کور په مخکښې حِصه جوړه کړه.', NULL, '&nbsp;د اِمامانو يوې قبيلې ورپسې برخه جوړه کړه، چې شمالى طرف ته د آسونو د دروازې نه تلې وه، هر يو د خپل کور په مخکښې حِصه جوړه کړه.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah003_verse_028.mp3', NULL, 1761760676, 1761760676),
(11486, 'Nehemiah 3:29', 'Nehemiah', 3, 29, '&nbsp;د اِمير زوئ صدوق ورپسې برخه جوړه کړه، کومه چې د هغۀ کور په مخکښې وه. د نمرخاتۀ طرف دروازې څوکيدار د سکانياه زوئ سمعياه ورپسې برخه جوړه کړه.', NULL, '&nbsp;د اِمير زوئ صدوق ورپسې برخه جوړه کړه، کومه چې د هغۀ کور په مخکښې وه. د نمرخاتۀ طرف دروازې څوکيدار د سکانياه زوئ سمعياه ورپسې برخه جوړه کړه.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah003_verse_029.mp3', NULL, 1761760676, 1761760676),
(11487, 'Nehemiah 3:30', 'Nehemiah', 3, 30, '&nbsp;د شلمياه زوئ حننياه او د صلف شپږم زوئ حنون ورپسې دوېمه برخه جوړه کړه. د برکياه زوئ مسلام ورپسې برخه جوړه کړه، کومه چې د هغۀ کور مخې ته وه.', NULL, '&nbsp;د شلمياه زوئ حننياه او د صلف شپږم زوئ حنون ورپسې دوېمه برخه جوړه کړه. د برکياه زوئ مسلام ورپسې برخه جوړه کړه، کومه چې د هغۀ کور مخې ته وه.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah003_verse_030.mp3', NULL, 1761760676, 1761760676),
(11488, 'Nehemiah 3:31', 'Nehemiah', 3, 31, '&nbsp;مُلکياه زرګر ورپسې برخه جوړه کړه، دا تر هغې پورې وه چې کوم کور د خُدائ پاک د کور کاريګرو او سوداګرو استعمالولو، کوم چې د حاضرۍ دروازې سره وو، دا د هغه کوټې سره نزدې وو چې د شمالى نمرخاتۀ طرف ته د ګوټ دېوال دپاسه وو.', NULL, '&nbsp;مُلکياه زرګر ورپسې برخه جوړه کړه، دا تر هغې پورې وه چې کوم کور د خُدائ پاک د کور کاريګرو او سوداګرو استعمالولو، کوم چې د حاضرۍ دروازې سره وو، دا د هغه کوټې سره نزدې وو چې د شمالى نمرخاتۀ طرف ته د ګوټ دېوال دپاسه وو.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah003_verse_031.mp3', NULL, 1761760676, 1761760676),
(11489, 'Nehemiah 3:32', 'Nehemiah', 3, 32, '&nbsp;زرګرانو او سوداګرو آخرى برخه جوړه کړه، دا د ګوټ سره د کوټې نه واخله د ګډو د دروازې پورې وه.', NULL, '&nbsp;زرګرانو او سوداګرو آخرى برخه جوړه کړه، دا د ګوټ سره د کوټې نه واخله د ګډو د دروازې پورې وه.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761760676, 1761760676),
(11490, 'Nehemiah 4:1', 'Nehemiah', 4, 1, '&nbsp;کله چې سنبلط خبر شو چې مونږ يهوديانو دېوال جوړول بيا شروع کړى دى، نو هغه سخت غصه شو او مونږ پورې يې خندا شروع کړه.', NULL, '&nbsp;کله چې سنبلط خبر شو چې مونږ يهوديانو دېوال جوړول بيا شروع کړى دى، نو هغه سخت غصه شو او مونږ پورې يې خندا شروع کړه.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah004_verse_001.mp3', NULL, 1761760676, 1761760676),
(11491, 'Nehemiah 4:2', 'Nehemiah', 4, 2, '&nbsp;د خپلو ملګرو او د سامرى فوجيانو په مخکښې يې ووئيل، ”دا بدبخته يهوديان چې څۀ کوى د هغې په حقله يې څۀ خيال دے؟ د هغوئ اراده د ښار بيا جوړولو ده څۀ؟ ولې د هغوئ خيال دا دے چې صِرف د يو څو قربانو پېش کولو په وجه به هغوئ هغه دېوال په يوه ورځ کښې جوړ کړى؟ هغوئ د سوزېدلو کاڼو او د ملبې د ډېرى نه د عمارت کاڼى جوړولے شى څۀ؟“', NULL, '&nbsp;د خپلو ملګرو او د سامرى فوجيانو په مخکښې يې ووئيل، ”دا بدبخته يهوديان چې څۀ کوى د هغې په حقله يې څۀ خيال دے؟ د هغوئ اراده د ښار بيا جوړولو ده څۀ؟ ولې د هغوئ خيال دا دے چې صِرف د يو څو قربانو پېش کولو په وجه به هغوئ هغه دېوال په يوه ورځ کښې جوړ کړى؟ هغوئ د سوزېدلو کاڼو او د ملبې د ډېرى نه د عمارت کاڼى جوړولے شى څۀ؟“', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah004_verse_002.mp3', NULL, 1761760676, 1761760676),
(11492, 'Nehemiah 4:3', 'Nehemiah', 4, 3, '&nbsp;طوبياه هلته د هغۀ په څنګ کښې ولاړ وو او دا خبره يې وکړه، ”هغوئ څۀ قسم دېوال جوړولے شى؟ داسې چې يو لومبړه يې هم راغورزولے شى.“', NULL, '&nbsp;طوبياه هلته د هغۀ په څنګ کښې ولاړ وو او دا خبره يې وکړه، ”هغوئ څۀ قسم دېوال جوړولے شى؟ داسې چې يو لومبړه يې هم راغورزولے شى.“', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah004_verse_003.mp3', NULL, 1761760676, 1761760676),
(11493, 'Nehemiah 4:4', 'Nehemiah', 4, 4, '&nbsp;ما دُعا وکړه، ”خُدايه پاکه، د هغوئ خندا واوره چې په مونږ پورې يې کوى، د هغوئ کنځل دې هم هغوئ ته بلا شى. هغوئ دې وتښتولے شى او پردى مُلک ته دې قېديان بوتلے شى.', NULL, '&nbsp;ما دُعا وکړه، ”خُدايه پاکه، د هغوئ خندا واوره چې په مونږ پورې يې کوى، د هغوئ کنځل دې هم هغوئ ته بلا شى. هغوئ دې وتښتولے شى او پردى مُلک ته دې قېديان بوتلے شى.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah004_verse_004.mp3', NULL, 1761760676, 1761760676),
(11494, 'Nehemiah 4:5', 'Nehemiah', 4, 5, '&nbsp;هغوئ چې کوم بد عمل کوى هغه مۀ معاف کوه او د هغوئ ګناهونه مۀ هېروه، ځکه چې مونږ کله دېوال جوړولو نو هغوئ زمونږ بې‌عزتى کړې ده.“', NULL, '&nbsp;هغوئ چې کوم بد عمل کوى هغه مۀ معاف کوه او د هغوئ ګناهونه مۀ هېروه، ځکه چې مونږ کله دېوال جوړولو نو هغوئ زمونږ بې‌عزتى کړې ده.“', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah004_verse_005.mp3', NULL, 1761760676, 1761760676),
(11495, 'Nehemiah 4:6', 'Nehemiah', 4, 6, '&nbsp;نو مونږ د دېوال په جوړولو باندې لګيا وُو او دا دېوال زر د نيم اوچتوالى پورې جوړ شو، ځکه چې خلقو به په شوق سره د دې کار کولو.', NULL, '&nbsp;نو مونږ د دېوال په جوړولو باندې لګيا وُو او دا دېوال زر د نيم اوچتوالى پورې جوړ شو، ځکه چې خلقو به په شوق سره د دې کار کولو.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah004_verse_006.mp3', NULL, 1761760676, 1761760676),
(11496, 'Nehemiah 4:7', 'Nehemiah', 4, 7, '&nbsp;خو کله چې سنبلط، طوبياه، او د عربو، د عمون او د اشدود خلقو واورېدل چې د يروشلم د دېوال د بيا جوړېدلو کار شروع شوے وو او چې د دېوال غورزېدلى ځايونه بيا جوړيږى نو هغوئ سخت غصه شُو.', NULL, '&nbsp;خو کله چې سنبلط، طوبياه، او د عربو، د عمون او د اشدود خلقو واورېدل چې د يروشلم د دېوال د بيا جوړېدلو کار شروع شوے وو او چې د دېوال غورزېدلى ځايونه بيا جوړيږى نو هغوئ سخت غصه شُو.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah004_verse_007.mp3', NULL, 1761760676, 1761760676),
(11497, 'Nehemiah 4:8', 'Nehemiah', 4, 8, '&nbsp;نو هغوئ ټولو دا منصوبه جوړه کړه چې راشى او په يروشلم باندې حمله وکړى او ګډوډى پېدا کړى،', NULL, '&nbsp;نو هغوئ ټولو دا منصوبه جوړه کړه چې راشى او په يروشلم باندې حمله وکړى او ګډوډى پېدا کړى،', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah004_verse_008.mp3', NULL, 1761760676, 1761760676),
(11498, 'Nehemiah 4:9', 'Nehemiah', 4, 9, '&nbsp;خو مونږ خپل خُدائ پاک ته سوال وکړو او د هغوئ خِلاف مو شپه او ورځ په څوکيدارۍ باندې سړى ولګول.', NULL, '&nbsp;خو مونږ خپل خُدائ پاک ته سوال وکړو او د هغوئ خِلاف مو شپه او ورځ په څوکيدارۍ باندې سړى ولګول.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah004_verse_009.mp3', NULL, 1761760676, 1761760676),
(11499, 'Nehemiah 4:10', 'Nehemiah', 4, 10, '&nbsp;د يهوداه خلقو يوه سندره لرله او هغوئ ووئيله، ”مونږ مزدوران کمزورى شوى يُو، دومره ماتې خَښتې به څنګه اوچتوُو. مونږ دا دېوال نن څنګه جوړ کړُو؟“', NULL, '&nbsp;د يهوداه خلقو يوه سندره لرله او هغوئ ووئيله، ”مونږ مزدوران کمزورى شوى يُو، دومره ماتې خَښتې به څنګه اوچتوُو. مونږ دا دېوال نن څنګه جوړ کړُو؟“', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah004_verse_010.mp3', NULL, 1761760676, 1761760676),
(11500, 'Nehemiah 4:11', 'Nehemiah', 4, 11, '&nbsp;زمونږ د دشمنانو خيال دا وو چې مونږ به خپل دشمنان ونۀ ګورو او نۀ به تر هغې پورې دا پته راته ولګى چې څۀ کيږى چې ترڅو پورې هغوئ مونږ ته رارسېدلى نۀ وى، مونږ به ووژنى او زمونږ کار به بند کړى.', NULL, '&nbsp;زمونږ د دشمنانو خيال دا وو چې مونږ به خپل دشمنان ونۀ ګورو او نۀ به تر هغې پورې دا پته راته ولګى چې څۀ کيږى چې ترڅو پورې هغوئ مونږ ته رارسېدلى نۀ وى، مونږ به ووژنى او زمونږ کار به بند کړى.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah004_verse_011.mp3', NULL, 1761760676, 1761760676),
(11501, 'Nehemiah 4:12', 'Nehemiah', 4, 12, '&nbsp;خو چې زمونږ د دشمنانو سره کوم يهوديان اوسېدل هغوئ وخت په وخت راتلل او چې زمونږ دشمنانو زمونږ خِلاف کومې منصوبې جوړولې نو د هغې نه به يې خبرولو.', NULL, '&nbsp;خو چې زمونږ د دشمنانو سره کوم يهوديان اوسېدل هغوئ وخت په وخت راتلل او چې زمونږ دشمنانو زمونږ خِلاف کومې منصوبې جوړولې نو د هغې نه به يې خبرولو.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah004_verse_012.mp3', NULL, 1761760676, 1761760676),
(11502, 'Nehemiah 4:13', 'Nehemiah', 4, 13, '&nbsp;نو ما خلقو له تُورې، نېزې او غشى ورکړل او قبيله په قبيله مې د دېوال شاته په هغه ځايونو کښې ودرول چرته چې کار لا ختم شوے نۀ وو.', NULL, '&nbsp;نو ما خلقو له تُورې، نېزې او غشى ورکړل او قبيله په قبيله مې د دېوال شاته په هغه ځايونو کښې ودرول چرته چې کار لا ختم شوے نۀ وو.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah004_verse_013.mp3', NULL, 1761760676, 1761760676),
(11503, 'Nehemiah 4:14', 'Nehemiah', 4, 14, '&nbsp;ما ته پته ولګېده چې خلق يرېدلى وُو، نو ما هغوئ، او د هغوئ مشرانو او آفسرانو ته ووئيل، ”زمونږ د دشمنانو نه مۀ يرېږئ. ياد ساتئ چې مالِک خُدائ ډېر لوئ او يروونکے دے او ستاسو وطندارانو، ستاسو زامنو، لوڼو، ښځو او ستاسو د کورونو دپاره جنګ وکړى.“', NULL, '&nbsp;ما ته پته ولګېده چې خلق يرېدلى وُو، نو ما هغوئ، او د هغوئ مشرانو او آفسرانو ته ووئيل، ”زمونږ د دشمنانو نه مۀ يرېږئ. ياد ساتئ چې مالِک خُدائ ډېر لوئ او يروونکے دے او ستاسو وطندارانو، ستاسو زامنو، لوڼو، ښځو او ستاسو د کورونو دپاره جنګ وکړى.“', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah004_verse_014.mp3', NULL, 1761760676, 1761760676),
(11504, 'Nehemiah 4:15', 'Nehemiah', 4, 15, '&nbsp;زمونږ دشمنان خبر شول چې مونږ ته دا پته لګېدلې ده چې هغوئ څۀ منصوبه جوړوله او چې خُدائ پاک د هغوئ منصوبې خرابې کړې دى. نو مونږ ټول د دېوال د بيا جوړولو دپاره واپس روان شُو.', NULL, '&nbsp;زمونږ دشمنان خبر شول چې مونږ ته دا پته لګېدلې ده چې هغوئ څۀ منصوبه جوړوله او چې خُدائ پاک د هغوئ منصوبې خرابې کړې دى. نو مونږ ټول د دېوال د بيا جوړولو دپاره واپس روان شُو.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah004_verse_015.mp3', NULL, 1761760676, 1761760676),
(11505, 'Nehemiah 4:16', 'Nehemiah', 4, 16, '&nbsp;د هغه وخت نه واخله زما نيمو سړو به کار کولو او نيم کسان به د څوکيدارۍ دپاره ولاړ وُو. هغوئ زغرې اغوستې وې او نېزې، ډالونه او غشى ورسره وُو. او زمونږ مشرانو د خلقو سره پوره مدد کولو،', NULL, '&nbsp;د هغه وخت نه واخله زما نيمو سړو به کار کولو او نيم کسان به د څوکيدارۍ دپاره ولاړ وُو. هغوئ زغرې اغوستې وې او نېزې، ډالونه او غشى ورسره وُو. او زمونږ مشرانو د خلقو سره پوره مدد کولو،', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah004_verse_016.mp3', NULL, 1761760676, 1761760676),
(11506, 'Nehemiah 4:17', 'Nehemiah', 4, 17, '&nbsp;يعنې د هغه خلقو سره چا چې دېوال جوړولو. چې کومو کسانو به د عمارت سامان وړلو نو هغوئ به هم په يو لاس باندې کار کولو او په بل لاس کښې به يې وسله نيولې وه،', NULL, '&nbsp;يعنې د هغه خلقو سره چا چې دېوال جوړولو. چې کومو کسانو به د عمارت سامان وړلو نو هغوئ به هم په يو لاس باندې کار کولو او په بل لاس کښې به يې وسله نيولې وه،', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah004_verse_017.mp3', NULL, 1761760676, 1761760676),
(11507, 'Nehemiah 4:18', 'Nehemiah', 4, 18, '&nbsp;او هر چا به چې د جوړولو کار کولو نو هر يو به په خپله ملا پورې تُوره تړلې وه خو چې کوم سړى به د خبردارى دپاره بيګل غږولو نو هغه به ما سره ايسارېدو.', NULL, '&nbsp;او هر چا به چې د جوړولو کار کولو نو هر يو به په خپله ملا پورې تُوره تړلې وه خو چې کوم سړى به د خبردارى دپاره بيګل غږولو نو هغه به ما سره ايسارېدو.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah004_verse_018.mp3', NULL, 1761760676, 1761760676),
(11508, 'Nehemiah 4:19', 'Nehemiah', 4, 19, '&nbsp;ما خلقو، د هغوئ آفسرانو او مشرانو ته ووئيل، ”دا کار په دومره ډېره فاصله باندې خور دے چې مونږ په دېوال باندې د يو بل نه ډېر زيات لرې يُو.', NULL, '&nbsp;ما خلقو، د هغوئ آفسرانو او مشرانو ته ووئيل، ”دا کار په دومره ډېره فاصله باندې خور دے چې مونږ په دېوال باندې د يو بل نه ډېر زيات لرې يُو.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah004_verse_019.mp3', NULL, 1761760676, 1761760676),
(11509, 'Nehemiah 4:20', 'Nehemiah', 4, 20, '&nbsp;کۀ تاسو د بيګل آواز واورئ، نو ما ته راغونډ شئ. زمونږ خُدائ پاک به زمونږ دپاره جنګ کوى.“', NULL, '&nbsp;کۀ تاسو د بيګل آواز واورئ، نو ما ته راغونډ شئ. زمونږ خُدائ پاک به زمونږ دپاره جنګ کوى.“', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah004_verse_020.mp3', NULL, 1761760676, 1761760676),
(11510, 'Nehemiah 4:21', 'Nehemiah', 4, 21, '&nbsp;نو هره ورځ، د سحر نه واخله د شپې تر هغه وخته پورې چې ستورى به راښکاره شول، زمونږ نيمو کسانو به کار کولو، خو هغه نور نيم به د نېزو سره د څوکيدارۍ دپاره ولاړ وُو.', NULL, '&nbsp;نو هره ورځ، د سحر نه واخله د شپې تر هغه وخته پورې چې ستورى به راښکاره شول، زمونږ نيمو کسانو به کار کولو، خو هغه نور نيم به د نېزو سره د څوکيدارۍ دپاره ولاړ وُو.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah004_verse_021.mp3', NULL, 1761760676, 1761760676),
(11511, 'Nehemiah 4:22', 'Nehemiah', 4, 22, '&nbsp;په هغه وخت کښې ما هغه مشرانو سړو ته ووئيل چې هغوئ او د هغوئ ټول مدد کوونکى به د شپې په يروشلم کښې ايساريږى، نو چې داسې مونږ د شپې د ښار څوکيدارى کوُو او د ورځې به کار کوُو.', NULL, '&nbsp;په هغه وخت کښې ما هغه مشرانو سړو ته ووئيل چې هغوئ او د هغوئ ټول مدد کوونکى به د شپې په يروشلم کښې ايساريږى، نو چې داسې مونږ د شپې د ښار څوکيدارى کوُو او د ورځې به کار کوُو.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah004_verse_022.mp3', NULL, 1761760676, 1761760676),
(11512, 'Nehemiah 4:23', 'Nehemiah', 4, 23, '&nbsp;ما د شپې هم خپلې جامې نۀ ويستلې، نۀ زما ملګرو، نۀ زما خِدمتګارانو او نۀ زما څوکيدارانو ويستلې. او کۀ مونږ د اوبو دپاره هم تلو نو مونږ ټولو به وسله د ځان سره ساتله.', NULL, '&nbsp;ما د شپې هم خپلې جامې نۀ ويستلې، نۀ زما ملګرو، نۀ زما خِدمتګارانو او نۀ زما څوکيدارانو ويستلې. او کۀ مونږ د اوبو دپاره هم تلو نو مونږ ټولو به وسله د ځان سره ساتله.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah004_verse_023.mp3', NULL, 1761760676, 1761760676),
(11513, 'Nehemiah 5:1', 'Nehemiah', 5, 1, '&nbsp;څۀ موده وروستو ډېرو سړو او ښځو، د خپلو يهوديانو خِلاف شکايت شروع کړو.', NULL, '&nbsp;څۀ موده وروستو ډېرو سړو او ښځو، د خپلو يهوديانو خِلاف شکايت شروع کړو.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah005_verse_001.mp3', NULL, 1761760676, 1761760676),
(11514, 'Nehemiah 5:2', 'Nehemiah', 5, 2, '&nbsp;څۀ کسانو ووئيل، ”زمونږ خاندان غټ شوے دے او د ژوندى پاتې کېدو دپاره مونږ ته د خوراک ضرورت دے.“', NULL, '&nbsp;څۀ کسانو ووئيل، ”زمونږ خاندان غټ شوے دے او د ژوندى پاتې کېدو دپاره مونږ ته د خوراک ضرورت دے.“', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah005_verse_002.mp3', NULL, 1761760676, 1761760676),
(11515, 'Nehemiah 5:3', 'Nehemiah', 5, 3, '&nbsp;څۀ کسانو ووئيل، ”مونږ خپل پټى، د انګورو باغونه او خپل کورونه د دې دپاره ګاڼه کړى دى چې د قحط په وخت کښې راته کافى خوراک مِلاو شى.“', NULL, '&nbsp;څۀ کسانو ووئيل، ”مونږ خپل پټى، د انګورو باغونه او خپل کورونه د دې دپاره ګاڼه کړى دى چې د قحط په وخت کښې راته کافى خوراک مِلاو شى.“', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah005_verse_003.mp3', NULL, 1761760676, 1761760676),
(11516, 'Nehemiah 5:4', 'Nehemiah', 5, 4, '&nbsp;خو څۀ کسانو دا هم ووئيل، ”مونږ پېسې قرض کړې وې چې په خپلو پټو او د انګورو په باغونو مو بادشاه له محصُول ورکړى.', NULL, '&nbsp;خو څۀ کسانو دا هم ووئيل، ”مونږ پېسې قرض کړې وې چې په خپلو پټو او د انګورو په باغونو مو بادشاه له محصُول ورکړى.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah005_verse_004.mp3', NULL, 1761760676, 1761760676),
(11517, 'Nehemiah 5:5', 'Nehemiah', 5, 5, '&nbsp;مونږ يهوديان د يو نسل نه يُو. ولې زمونږ بچى د هغوئ د بچو په شان نۀ دى؟ خو بيا هم مونږ مجبور يُو چې د خپلو بچو نه غلامان جوړوُو. زمونږ څۀ لوڼه د وړاندې نه د وينځو په توګه خرڅې شوې دى. مونږ په دې وجه بې‌مددګاره يُو چې زمونږ پټى او د انګورو باغونه زمونږ نه اخستے شوى دى.“', NULL, '&nbsp;مونږ يهوديان د يو نسل نه يُو. ولې زمونږ بچى د هغوئ د بچو په شان نۀ دى؟ خو بيا هم مونږ مجبور يُو چې د خپلو بچو نه غلامان جوړوُو. زمونږ څۀ لوڼه د وړاندې نه د وينځو په توګه خرڅې شوې دى. مونږ په دې وجه بې‌مددګاره يُو چې زمونږ پټى او د انګورو باغونه زمونږ نه اخستے شوى دى.“', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah005_verse_005.mp3', NULL, 1761760676, 1761760676),
(11518, 'Nehemiah 5:6', 'Nehemiah', 5, 6, '&nbsp;کله چې ما د هغوئ شکايتونه واورېدل، نو زۀ غصه شوم.', NULL, '&nbsp;کله چې ما د هغوئ شکايتونه واورېدل، نو زۀ غصه شوم.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah005_verse_006.mp3', NULL, 1761760676, 1761760676),
(11519, 'Nehemiah 5:7', 'Nehemiah', 5, 7, '&nbsp;په دې باندې د سوچ کولو نه پس، ما د خلقو مشران او آفسران ورټل او ورته مې ووئيل، ”تاسو د خپلو خلقو نه سود اخلئ.“ نو ما د دې دپاره د خلقو يو جرګه راوغوښته چې د دې مسئلې حل راوباسو', NULL, '&nbsp;په دې باندې د سوچ کولو نه پس، ما د خلقو مشران او آفسران ورټل او ورته مې ووئيل، ”تاسو د خپلو خلقو نه سود اخلئ.“ نو ما د دې دپاره د خلقو يو جرګه راوغوښته چې د دې مسئلې حل راوباسو', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah005_verse_007.mp3', NULL, 1761760676, 1761760676),
(11520, 'Nehemiah 5:8', 'Nehemiah', 5, 8, '&nbsp;او ورته مې ووئيل، ”زمونږ چې څومره وس وى نو مونږ خپل هغه يهودى خپلوان واپس اخلو کومو چې خپل ځانونه په غېرو خلقو باندې خرڅ کړى دى. خو اوس تاسو خپل رشته‌داران او خپل خلق دې ته مجبوروئ چې خپل ځانونه په تاسو باندې خرڅ کړى.“ مشران خاموش ولاړ وُو او د وئيلو دپاره ورسره هيڅ هم نۀ وُو.', NULL, '&nbsp;او ورته مې ووئيل، ”زمونږ چې څومره وس وى نو مونږ خپل هغه يهودى خپلوان واپس اخلو کومو چې خپل ځانونه په غېرو خلقو باندې خرڅ کړى دى. خو اوس تاسو خپل رشته‌داران او خپل خلق دې ته مجبوروئ چې خپل ځانونه په تاسو باندې خرڅ کړى.“ مشران خاموش ولاړ وُو او د وئيلو دپاره ورسره هيڅ هم نۀ وُو.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah005_verse_008.mp3', NULL, 1761760676, 1761760676),
(11521, 'Nehemiah 5:9', 'Nehemiah', 5, 9, '&nbsp;بيا ورته ما ووئيل، ”تاسو چې څۀ کوئ دا ټيک نۀ دى. په کار دى چې تاسو زمونږ د خُدائ پاک نه په يره کښې ژوند تېر کړئ نو چې مونږ د غېرو قومونو د دشمنانو د پېغور نه خپل ځانونه بچ کړُو.', NULL, '&nbsp;بيا ورته ما ووئيل، ”تاسو چې څۀ کوئ دا ټيک نۀ دى. په کار دى چې تاسو زمونږ د خُدائ پاک نه په يره کښې ژوند تېر کړئ نو چې مونږ د غېرو قومونو د دشمنانو د پېغور نه خپل ځانونه بچ کړُو.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah005_verse_009.mp3', NULL, 1761760676, 1761760676),
(11522, 'Nehemiah 5:10', 'Nehemiah', 5, 10, '&nbsp;ما خلق دې ته پرېښى دى چې زما نه پېسه او غله قرض واخلى او هم زما د ملګرو او خلقو نه چې زما دپاره کار کوى. نو راځئ چې دا سود اخستل بند کړُو.', NULL, '&nbsp;ما خلق دې ته پرېښى دى چې زما نه پېسه او غله قرض واخلى او هم زما د ملګرو او خلقو نه چې زما دپاره کار کوى. نو راځئ چې دا سود اخستل بند کړُو.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah005_verse_010.mp3', NULL, 1761760676, 1761760676),
(11523, 'Nehemiah 5:11', 'Nehemiah', 5, 11, '&nbsp;نو تاسو به نن خامخا هغوئ له د هغوئ پټى، د انګورو باغونه، د زيتُونو ونې او د هغوئ کورونه واپس ورکوئ. او لکه کله چې مو پېسې، غله، د انګورو نوى مے او د زيتُونو تېل قرض ورکول او چې کوم سود مو ترې نه اخستے دے هغه واپس ورکړئ.“', NULL, '&nbsp;نو تاسو به نن خامخا هغوئ له د هغوئ پټى، د انګورو باغونه، د زيتُونو ونې او د هغوئ کورونه واپس ورکوئ. او لکه کله چې مو پېسې، غله، د انګورو نوى مے او د زيتُونو تېل قرض ورکول او چې کوم سود مو ترې نه اخستے دے هغه واپس ورکړئ.“', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah005_verse_011.mp3', NULL, 1761760676, 1761760676),
(11524, 'Nehemiah 5:12', 'Nehemiah', 5, 12, '&nbsp;مشرانو ورته ووئيل، ”تا چې څۀ ووئيل مونږ به هغه هم دغه شان وکړُو. مونږ به جائيدادونه واپس کړُو او د قرض د راغونډولو کوشش به نۀ کوُو.“ نو ما اِمامان راوغوښتل او د هغوئ په مخکښې مې د مشرانو نه دا قسم واخستلو چې هغوئ اوس اوس کومه وعده وکړه نو هغه به پوره کوى.', NULL, '&nbsp;مشرانو ورته ووئيل، ”تا چې څۀ ووئيل مونږ به هغه هم دغه شان وکړُو. مونږ به جائيدادونه واپس کړُو او د قرض د راغونډولو کوشش به نۀ کوُو.“ نو ما اِمامان راوغوښتل او د هغوئ په مخکښې مې د مشرانو نه دا قسم واخستلو چې هغوئ اوس اوس کومه وعده وکړه نو هغه به پوره کوى.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah005_verse_012.mp3', NULL, 1761760676, 1761760676),
(11525, 'Nehemiah 5:13', 'Nehemiah', 5, 13, '&nbsp;نو ما خپله لمن وڅنډله او ومې وئيل، ”کۀ تاسو دا وعده پوره نۀ کړه، نو خُدائ پاک دې تاسو د خپلو کورونو او خپلو جائيدادونو نه داسې وڅنډى.“ نو ټولو خلقو په جواب کښې ووئيل، ”آمين“ او هغوئ د مالِک خُدائ ثناء صِفت وکړو. او خلقو هم هغه شان وکړل چې څنګه يې وعده کړې وه.', NULL, '&nbsp;نو ما خپله لمن وڅنډله او ومې وئيل، ”کۀ تاسو دا وعده پوره نۀ کړه، نو خُدائ پاک دې تاسو د خپلو کورونو او خپلو جائيدادونو نه داسې وڅنډى.“ نو ټولو خلقو په جواب کښې ووئيل، ”آمين“ او هغوئ د مالِک خُدائ ثناء صِفت وکړو. او خلقو هم هغه شان وکړل چې څنګه يې وعده کړې وه.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah005_verse_013.mp3', NULL, 1761760676, 1761760676),
(11526, 'Nehemiah 5:14', 'Nehemiah', 5, 14, '&nbsp;په هغه ټولو دولسو کالو کښې چې زۀ د يهوداه د مُلک حکمران وم، د ارتخششتا د سلطنت د شلم کال نه د هغۀ د بادشاهۍ د دوه دېرشم کال پورې، نۀ ما او نۀ زما خپلوانو هغه خوراک خوړلے دے چې کوم د حکمران دپاره مقرر وو.', NULL, '&nbsp;په هغه ټولو دولسو کالو کښې چې زۀ د يهوداه د مُلک حکمران وم، د ارتخششتا د سلطنت د شلم کال نه د هغۀ د بادشاهۍ د دوه دېرشم کال پورې، نۀ ما او نۀ زما خپلوانو هغه خوراک خوړلے دے چې کوم د حکمران دپاره مقرر وو.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah005_verse_014.mp3', NULL, 1761760676, 1761760676),
(11527, 'Nehemiah 5:15', 'Nehemiah', 5, 15, '&nbsp;زما نه مخکښې به چې کوم يو حکمران هم په دفتر کښې وو هغه به په خلقو بوج وو. د ميو او د خوراک دپاره به يې هره ورځ ترې نه څلوېښت د سپينو زرو سيکې غوښتې. د هغوئ نوکرانو به هم د خلقو سره زياتے کولو. خو ما به د هغوئ په شان کار نۀ کولو، ځکه چې زۀ د خُدائ پاک نه يرېدلم.', NULL, '&nbsp;زما نه مخکښې به چې کوم يو حکمران هم په دفتر کښې وو هغه به په خلقو بوج وو. د ميو او د خوراک دپاره به يې هره ورځ ترې نه څلوېښت د سپينو زرو سيکې غوښتې. د هغوئ نوکرانو به هم د خلقو سره زياتے کولو. خو ما به د هغوئ په شان کار نۀ کولو، ځکه چې زۀ د خُدائ پاک نه يرېدلم.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah005_verse_015.mp3', NULL, 1761760676, 1761760676),
(11528, 'Nehemiah 5:16', 'Nehemiah', 5, 16, '&nbsp;ما خپل ځان د دېوال د بيا جوړولو دپاره وقف کړے وو او هيڅ جائيداد مې نۀ اخستلو. هر چا چې زما دپاره کار کولو نو هغه د دېوال په بيا جوړېدو کښې شريک وُو.', NULL, '&nbsp;ما خپل ځان د دېوال د بيا جوړولو دپاره وقف کړے وو او هيڅ جائيداد مې نۀ اخستلو. هر چا چې زما دپاره کار کولو نو هغه د دېوال په بيا جوړېدو کښې شريک وُو.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah005_verse_016.mp3', NULL, 1761760676, 1761760676),
(11529, 'Nehemiah 5:17', 'Nehemiah', 5, 17, '&nbsp;ما به د خپل دسترخوان نه هره ورځ يو نيم سل يهوديانو او د هغوئ مشرانو له روټۍ ورکوله. دا د هغه ټولو خلقو نه علاوه وُو کوم چې د ګېرچاپېره مُلکونو نه ما له راغلى وُو.', NULL, '&nbsp;ما به د خپل دسترخوان نه هره ورځ يو نيم سل يهوديانو او د هغوئ مشرانو له روټۍ ورکوله. دا د هغه ټولو خلقو نه علاوه وُو کوم چې د ګېرچاپېره مُلکونو نه ما له راغلى وُو.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah005_verse_017.mp3', NULL, 1761760676, 1761760676),
(11530, 'Nehemiah 5:18', 'Nehemiah', 5, 18, '&nbsp;هره ورځ به مې يو غوَيے، شپږ ښۀ ګډان او ډېرې چرګې تيارولې او په هره لسمه ورځ مې د انګورو د تازه ميو بندوبست کولو. خو بيا هم ما هغه پېسې نۀ غوښتلې کومې چې د حکمران دپاره مقررې وې، ځکه چې خلقو ډېر دروند بوج برداشت کولو.', NULL, '&nbsp;هره ورځ به مې يو غوَيے، شپږ ښۀ ګډان او ډېرې چرګې تيارولې او په هره لسمه ورځ مې د انګورو د تازه ميو بندوبست کولو. خو بيا هم ما هغه پېسې نۀ غوښتلې کومې چې د حکمران دپاره مقررې وې، ځکه چې خلقو ډېر دروند بوج برداشت کولو.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah005_verse_018.mp3', NULL, 1761760676, 1761760676),
(11531, 'Nehemiah 5:19', 'Nehemiah', 5, 19, '&nbsp;نو اے خُدايه پاکه، زۀ ستا نه سوال کوم چې زما هغه هر يو کار ياد ساته چې ما د دې خلقو دپاره کړے دے.', NULL, '&nbsp;نو اے خُدايه پاکه، زۀ ستا نه سوال کوم چې زما هغه هر يو کار ياد ساته چې ما د دې خلقو دپاره کړے دے.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah005_verse_019.mp3', NULL, 1761760676, 1761760676),
(11532, 'Nehemiah 6:1', 'Nehemiah', 6, 1, '&nbsp;سنبلط، طوبياه، عربى جشم او زمونږ نور دشمنان خبر شول چې مونږ د دېوال جوړول ختم کړى دى او چې په دې کښې يو مات ځائ هم پاتې نۀ دے، اګر چې مونږ د دروازو په ځايونو کښې دروازې هم لا نۀ وې لګولې.', NULL, '&nbsp;سنبلط، طوبياه، عربى جشم او زمونږ نور دشمنان خبر شول چې مونږ د دېوال جوړول ختم کړى دى او چې په دې کښې يو مات ځائ هم پاتې نۀ دے، اګر چې مونږ د دروازو په ځايونو کښې دروازې هم لا نۀ وې لګولې.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah006_verse_001.mp3', NULL, 1761760676, 1761760676),
(11533, 'Nehemiah 6:2', 'Nehemiah', 6, 2, '&nbsp;نو سنبلط او جشم ما له يو پېغام راولېږلو، دا مشوره يې راکوله چې د اونو په مېدان کښې په يو کلى کښې زۀ د هغوئ سره مِلاو شم. خو ما ته پته ولګېده چې دا ما ته د هغوئ د نقصان رسولو يوه منصوبه وه.', NULL, '&nbsp;نو سنبلط او جشم ما له يو پېغام راولېږلو، دا مشوره يې راکوله چې د اونو په مېدان کښې په يو کلى کښې زۀ د هغوئ سره مِلاو شم. خو ما ته پته ولګېده چې دا ما ته د هغوئ د نقصان رسولو يوه منصوبه وه.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah006_verse_002.mp3', NULL, 1761760676, 1761760676),
(11534, 'Nehemiah 6:3', 'Nehemiah', 6, 3, '&nbsp;ما هغوئ له پېغام وړُونکى ولېږل چې ورته ووائى، ”زۀ يو اهم کار کوم او لاندې نۀ شم درتلے. صِرف تاسو سره مِلاوېدو دپاره خپل کار نۀ شم بندولے.“', NULL, '&nbsp;ما هغوئ له پېغام وړُونکى ولېږل چې ورته ووائى، ”زۀ يو اهم کار کوم او لاندې نۀ شم درتلے. صِرف تاسو سره مِلاوېدو دپاره خپل کار نۀ شم بندولے.“', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah006_verse_003.mp3', NULL, 1761760676, 1761760676),
(11535, 'Nehemiah 6:4', 'Nehemiah', 6, 4, '&nbsp;هغوئ څلور ځلې ما له هم دغه پېغام رالېږلو او هر ځل ما هغوئ له هم دغه جواب ورولېږلو.', NULL, '&nbsp;هغوئ څلور ځلې ما له هم دغه پېغام رالېږلو او هر ځل ما هغوئ له هم دغه جواب ورولېږلو.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah006_verse_004.mp3', NULL, 1761760676, 1761760676),
(11536, 'Nehemiah 6:5', 'Nehemiah', 6, 5, '&nbsp;بيا سنبلط خپل يو نوکر ما له د پينځم پېغام سره راولېږلو، دا د خط په شکل کښې وو او دا خط کولاو وو.', NULL, '&nbsp;بيا سنبلط خپل يو نوکر ما له د پينځم پېغام سره راولېږلو، دا د خط په شکل کښې وو او دا خط کولاو وو.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah006_verse_005.mp3', NULL, 1761760676, 1761760676),
(11537, 'Nehemiah 6:6', 'Nehemiah', 6, 6, '&nbsp;ما ولوستلو، ”جشمه ووئيل چې په ګاونډيانو کښې دا افواه خوره ده چې تۀ او يهوديان د بغاوت اراده لرئ نو دا ځکه تاسو دا دېوال بيا جوړَوئ. هغۀ دا هم ووئيل چې ستا منصوبه دا ده چې خپل ځان بادشاه کړې', NULL, '&nbsp;ما ولوستلو، ”جشمه ووئيل چې په ګاونډيانو کښې دا افواه خوره ده چې تۀ او يهوديان د بغاوت اراده لرئ نو دا ځکه تاسو دا دېوال بيا جوړَوئ. هغۀ دا هم ووئيل چې ستا منصوبه دا ده چې خپل ځان بادشاه کړې', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah006_verse_006.mp3', NULL, 1761760676, 1761760676),
(11538, 'Nehemiah 6:7', 'Nehemiah', 6, 7, '&nbsp;او تا د يو څو پېغمبرانو بندوبست کړے دے چې په يروشلم کښې دا اِعلان وکړى چې تۀ د يهوداه بادشاه يې. خو بادشاه سلامت به يقيناً د دې نه خبر شى، نو ځکه زۀ دا مشوره درکوم چې مونږ دواړه مِلاو شُو چې په حالاتو باندې خبرې وکړُو.“', NULL, '&nbsp;او تا د يو څو پېغمبرانو بندوبست کړے دے چې په يروشلم کښې دا اِعلان وکړى چې تۀ د يهوداه بادشاه يې. خو بادشاه سلامت به يقيناً د دې نه خبر شى، نو ځکه زۀ دا مشوره درکوم چې مونږ دواړه مِلاو شُو چې په حالاتو باندې خبرې وکړُو.“', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah006_verse_007.mp3', NULL, 1761760676, 1761760676),
(11539, 'Nehemiah 6:8', 'Nehemiah', 6, 8, '&nbsp;نو ما هغۀ له جواب ورولېږلو، ”تۀ چې څۀ وائې په هغۀ کښې هيڅ هم رښتيا نشته. دا هر څۀ تا د خپل ځان نه جوړ کړى دى.“', NULL, '&nbsp;نو ما هغۀ له جواب ورولېږلو، ”تۀ چې څۀ وائې په هغۀ کښې هيڅ هم رښتيا نشته. دا هر څۀ تا د خپل ځان نه جوړ کړى دى.“', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah006_verse_008.mp3', NULL, 1761760676, 1761760676),
(11540, 'Nehemiah 6:9', 'Nehemiah', 6, 9, '&nbsp;د هغوئ دا کوشش وو چې مونږ ويروى چې کار بند کړُو. خو ما دُعا وکړه، ”خُدايه پاکه، ما له طاقت راکړه.“', NULL, '&nbsp;د هغوئ دا کوشش وو چې مونږ ويروى چې کار بند کړُو. خو ما دُعا وکړه، ”خُدايه پاکه، ما له طاقت راکړه.“', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah006_verse_009.mp3', NULL, 1761760676, 1761760676),
(11541, 'Nehemiah 6:10', 'Nehemiah', 6, 10, '&nbsp;په هغه وخت زۀ د مهيطب‌اېل نمسى او د دلاياه زوئ سمعياه سره مِلاوېدو له لاړم، چې هغه د دې قابل نۀ وو چې د خپل کور نه لاړ شى. هغۀ ما ته ووئيل، ”زۀ او تۀ به لاړ شُو او د خُدائ پاک د کور په مقدس ځائ کښې به دواړه پټ شُو او دروازې به تالا کړُو، ځکه چې هغوئ ستا د وژلو دپاره راروان دى. نو هغوئ به ستا د وژلو دپاره د شپې راشى.“', NULL, '&nbsp;په هغه وخت زۀ د مهيطب‌اېل نمسى او د دلاياه زوئ سمعياه سره مِلاوېدو له لاړم، چې هغه د دې قابل نۀ وو چې د خپل کور نه لاړ شى. هغۀ ما ته ووئيل، ”زۀ او تۀ به لاړ شُو او د خُدائ پاک د کور په مقدس ځائ کښې به دواړه پټ شُو او دروازې به تالا کړُو، ځکه چې هغوئ ستا د وژلو دپاره راروان دى. نو هغوئ به ستا د وژلو دپاره د شپې راشى.“', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah006_verse_010.mp3', NULL, 1761760676, 1761760676),
(11542, 'Nehemiah 6:11', 'Nehemiah', 6, 11, '&nbsp;ما په جواب کښې ورته ووئيل، ”زۀ داسې سړے نۀ يم چې وتښتم او پټ شم. ستا خيال دا دے څۀ چې زۀ به د خپل ژوند د بچ کولو دپاره د خُدائ پاک په کور کښې پټېږم؟ زۀ به داسې نۀ کوم.“', NULL, '&nbsp;ما په جواب کښې ورته ووئيل، ”زۀ داسې سړے نۀ يم چې وتښتم او پټ شم. ستا خيال دا دے څۀ چې زۀ به د خپل ژوند د بچ کولو دپاره د خُدائ پاک په کور کښې پټېږم؟ زۀ به داسې نۀ کوم.“', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah006_verse_011.mp3', NULL, 1761760676, 1761760676),
(11543, 'Nehemiah 6:12', 'Nehemiah', 6, 12, '&nbsp;کله چې ما په دې باندې سوچ وکړو، نو ما ته پته ولګېده چې خُدائ پاک د سمعياه سره خبرې نۀ دى کړې، خو طوبياه او سنبلط هغۀ له د دې دپاره رشوت ورکړے دے چې ما له دا خبردارے راکړى.', NULL, '&nbsp;کله چې ما په دې باندې سوچ وکړو، نو ما ته پته ولګېده چې خُدائ پاک د سمعياه سره خبرې نۀ دى کړې، خو طوبياه او سنبلط هغۀ له د دې دپاره رشوت ورکړے دے چې ما له دا خبردارے راکړى.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah006_verse_012.mp3', NULL, 1761760676, 1761760676),
