(11546, 'Nehemiah 6:15', 'Nehemiah', 6, 15, '&nbsp;د کار دوه پنځوسمې ورځې نه پس د الول د مياشتې په پينځويشتمه ورځ ټول دېوال ختم شو.', NULL, '&nbsp;د کار دوه پنځوسمې ورځې نه پس د الول د مياشتې په پينځويشتمه ورځ ټول دېوال ختم شو.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah006_verse_015.mp3', NULL, 1761760676, 1761760676),
(11547, 'Nehemiah 6:16', 'Nehemiah', 6, 16, '&nbsp;کله چې په ګېرچاپېره مُلکونو کښې زمونږ دشمنان د دې نه خبر شول، نو هغوئ ويرېدل او خپل ځانونه ورته کمزورى ښکاره شول، ځکه چې هغوئ ته پته وه چې دا کار د خُدائ پاک د مدد سره شوے دے.', NULL, '&nbsp;کله چې په ګېرچاپېره مُلکونو کښې زمونږ دشمنان د دې نه خبر شول، نو هغوئ ويرېدل او خپل ځانونه ورته کمزورى ښکاره شول، ځکه چې هغوئ ته پته وه چې دا کار د خُدائ پاک د مدد سره شوے دے.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah006_verse_016.mp3', NULL, 1761760676, 1761760676),
(11548, 'Nehemiah 6:17', 'Nehemiah', 6, 17, '&nbsp;په دې ټول وخت کښې د يهوديانو مشرانو او طوبياه يو بل ته ډېر خطونه لېږل رالېږل.', NULL, '&nbsp;په دې ټول وخت کښې د يهوديانو مشرانو او طوبياه يو بل ته ډېر خطونه لېږل رالېږل.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah006_verse_017.mp3', NULL, 1761760676, 1761760676),
(11549, 'Nehemiah 6:18', 'Nehemiah', 6, 18, '&nbsp;په يهوداه کښې ډېرو خلقو د طوبياه ملګرتيا ځکه کوله چې د هغۀ سخر د ارخ زوئ سکانياه يهودى وو. د دې نه علاوه، د هغۀ زوئ يهوحنان د برکياه د زوئ د مسلام لور وادۀ کړې وه.', NULL, '&nbsp;په يهوداه کښې ډېرو خلقو د طوبياه ملګرتيا ځکه کوله چې د هغۀ سخر د ارخ زوئ سکانياه يهودى وو. د دې نه علاوه، د هغۀ زوئ يهوحنان د برکياه د زوئ د مسلام لور وادۀ کړې وه.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah006_verse_018.mp3', NULL, 1761760676, 1761760676),
(11550, 'Nehemiah 6:19', 'Nehemiah', 6, 19, '&nbsp;طوبياه چې کوم ښۀ کارونه کړى وُو نو خلقو به د هغې ټولو په حقله زما په وړاندې خبرې کولې او ما چې څۀ وئيل نو هغه به يې طوبياه ته وئيل. او هغۀ زما د يرولو دپاره خطونه رالېږل.', NULL, '&nbsp;طوبياه چې کوم ښۀ کارونه کړى وُو نو خلقو به د هغې ټولو په حقله زما په وړاندې خبرې کولې او ما چې څۀ وئيل نو هغه به يې طوبياه ته وئيل. او هغۀ زما د يرولو دپاره خطونه رالېږل.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah006_verse_019.mp3', NULL, 1761760676, 1761760676),
(11551, 'Nehemiah 7:1', 'Nehemiah', 7, 1, '&nbsp;نو دېوال بيا جوړ شو، ټولې دروازې په خپلو ځايونو کښې ولګولے شوې او څوکيداران، حمد ويونکى او ليويان مقرر کړے شول.', NULL, '&nbsp;نو دېوال بيا جوړ شو، ټولې دروازې په خپلو ځايونو کښې ولګولے شوې او څوکيداران، حمد ويونکى او ليويان مقرر کړے شول.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah007_verse_001.mp3', NULL, 1761760676, 1761760676),
(11552, 'Nehemiah 7:2', 'Nehemiah', 7, 2, '&nbsp;ما دوه سړى د يروشلم په ښار باندې مشران مقرر کړل، هغه زما ورور حنانى او د قلعه مشر آفسر حننياه وُو. حننياه اعتمادى سړے وو او هغه د نورو نه زيات د خُدائ پاک نه يرېدو.', NULL, '&nbsp;ما دوه سړى د يروشلم په ښار باندې مشران مقرر کړل، هغه زما ورور حنانى او د قلعه مشر آفسر حننياه وُو. حننياه اعتمادى سړے وو او هغه د نورو نه زيات د خُدائ پاک نه يرېدو.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah007_verse_002.mp3', NULL, 1761760676, 1761760676),
(11553, 'Nehemiah 7:3', 'Nehemiah', 7, 3, '&nbsp;ما هغوئ ته ووئيل، ”ترڅو پورې چې نمر تود شوے نۀ وى نو د يروشلم دروازې به نۀ کولاووئ. په کوم وخت کښې چې څوکيداران په ماښام کښې چهټى کوى نو هغوئ دې دروازې بندوى او اړمونه دې ورته واچوى. ما هغوئ ته دا هم ووئيل چې د يروشلم د اوسېدونکو خلقو نه يو څو څوکيداران مقرر کړئ چې څۀ کسانو ته په کښې خاص ځايونه حواله شى او نور دې د خپلو کورونو نه ګېرچاپېره ګشت کوى.“', NULL, '&nbsp;ما هغوئ ته ووئيل، ”ترڅو پورې چې نمر تود شوے نۀ وى نو د يروشلم دروازې به نۀ کولاووئ. په کوم وخت کښې چې څوکيداران په ماښام کښې چهټى کوى نو هغوئ دې دروازې بندوى او اړمونه دې ورته واچوى. ما هغوئ ته دا هم ووئيل چې د يروشلم د اوسېدونکو خلقو نه يو څو څوکيداران مقرر کړئ چې څۀ کسانو ته په کښې خاص ځايونه حواله شى او نور دې د خپلو کورونو نه ګېرچاپېره ګشت کوى.“', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah007_verse_003.mp3', NULL, 1761760676, 1761760676),
(11554, 'Nehemiah 7:4', 'Nehemiah', 7, 4, '&nbsp;يروشلم يو لوئ ښار وو، خو ډېر خلق په کښې نۀ اوسېدل او ډېر کورونه په کښې نۀ وُو جوړ شوى.', NULL, '&nbsp;يروشلم يو لوئ ښار وو، خو ډېر خلق په کښې نۀ اوسېدل او ډېر کورونه په کښې نۀ وُو جوړ شوى.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah007_verse_004.mp3', NULL, 1761760676, 1761760676),
(11555, 'Nehemiah 7:5', 'Nehemiah', 7, 5, '&nbsp;خُدائ پاک دا خيال زما په زړۀ کښې واچولو چې دا خلق، د هغوئ مشران او آفسران راغونډ کړم او د هغوئ نسب‌نامه وګورم. ما د هغه خلقو حِساب کِتاب پېدا کړو کوم چې اول د جلاوطنۍ نه راواپس شوى وُو او ما ته چې کوم معلومات مِلاو شول هغه دا دى:', NULL, '&nbsp;خُدائ پاک دا خيال زما په زړۀ کښې واچولو چې دا خلق، د هغوئ مشران او آفسران راغونډ کړم او د هغوئ نسب‌نامه وګورم. ما د هغه خلقو حِساب کِتاب پېدا کړو کوم چې اول د جلاوطنۍ نه راواپس شوى وُو او ما ته چې کوم معلومات مِلاو شول هغه دا دى:', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah007_verse_005.mp3', NULL, 1761760676, 1761760676),
(11556, 'Nehemiah 7:6', 'Nehemiah', 7, 6, '&nbsp;ډېر جلاوطن شوى کسان د بابل صُوبې نه لاړل او يروشلم او يهوداه ته راواپس شول، هر يو خپل ښار ته راغلو. د هغوئ خاندان په بابل کښې د جلاوطنۍ په دوران کښې د هغه وخت نه اوسېدې چې نبوکدنضر بادشاه هغوئ هلته قېديان بوتلى وُو.', NULL, '&nbsp;ډېر جلاوطن شوى کسان د بابل صُوبې نه لاړل او يروشلم او يهوداه ته راواپس شول، هر يو خپل ښار ته راغلو. د هغوئ خاندان په بابل کښې د جلاوطنۍ په دوران کښې د هغه وخت نه اوسېدې چې نبوکدنضر بادشاه هغوئ هلته قېديان بوتلى وُو.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah007_verse_006.mp3', NULL, 1761760676, 1761760676),
(11557, 'Nehemiah 7:7', 'Nehemiah', 7, 7, '&nbsp;د هغوئ مشران دا وُو، زرُبابل، يشوَع، نحمياه، عزرياه، رعمياه، نحمانى، مردکى، بِلشان، مِسفرت، بِګوئ، نحُوم او بعنه.', NULL, '&nbsp;د هغوئ مشران دا وُو، زرُبابل، يشوَع، نحمياه، عزرياه، رعمياه، نحمانى، مردکى، بِلشان، مِسفرت، بِګوئ، نحُوم او بعنه.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah007_verse_007.mp3', NULL, 1761760676, 1761760676),
(11558, 'Nehemiah 7:60', 'Nehemiah', 7, 60, '&nbsp;د خُدائ پاک د کور د خِدمتګارانو اولاد او د سليمان د هغه نوکرانو شمېر اتۀ کم څلور سوه وو کوم چې د جلاوطنۍ نه راواپس شول.', NULL, '&nbsp;د خُدائ پاک د کور د خِدمتګارانو اولاد او د سليمان د هغه نوکرانو شمېر اتۀ کم څلور سوه وو کوم چې د جلاوطنۍ نه راواپس شول.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761760676, 1761760676),
(11559, 'Nehemiah 7:65', 'Nehemiah', 7, 65, '&nbsp;يهودى حکمران هغوئ ته وئيلى وُو چې هغوئ تر هغې پورې خُدائ پاک ته پېش کړے شوے خوراک نۀ شى خوړلے چې ترڅو پورې اِمام اُوريم او تميم نۀ وى استعمال کړے.', NULL, '&nbsp;يهودى حکمران هغوئ ته وئيلى وُو چې هغوئ تر هغې پورې خُدائ پاک ته پېش کړے شوے خوراک نۀ شى خوړلے چې ترڅو پورې اِمام اُوريم او تميم نۀ وى استعمال کړے.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761760676, 1761760676),
(11560, 'Nehemiah 7:73', 'Nehemiah', 7, 73, '&nbsp;اِمامان، ليويان، څوکيداران، سندرغاړى، او څۀ عام خلق، د خُدائ پاک د کور خِدمتګاران، او ټول بنى اِسرائيليان په وړو ښارونو او د يهوداه په ښارونو کښې دېره شول.', NULL, '&nbsp;اِمامان، ليويان، څوکيداران، سندرغاړى، او څۀ عام خلق، د خُدائ پاک د کور خِدمتګاران، او ټول بنى اِسرائيليان په وړو ښارونو او د يهوداه په ښارونو کښې دېره شول.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761760676, 1761760676),
(11561, 'Nehemiah 8:1', 'Nehemiah', 8, 1, '&nbsp;تر اوومې مياشتې پورې ټول بنى اِسرائيل په خپلو ښارونو کښې دېره شول. د دې مياشتې په اوله ورځ هغوئ ټول په يروشلم کښې د اوبو دروازې سره دننه د جرګې په ځائ کښې راغونډ شول. هغوئ عزرا عالِم ته ووئيل چې د موسىٰ د شريعت هغه کِتاب راوړى کوم چې مالِک خُدائ بنى اِسرائيلو له ورکړے وو.', NULL, '&nbsp;تر اوومې مياشتې پورې ټول بنى اِسرائيل په خپلو ښارونو کښې دېره شول. د دې مياشتې په اوله ورځ هغوئ ټول په يروشلم کښې د اوبو دروازې سره دننه د جرګې په ځائ کښې راغونډ شول. هغوئ عزرا عالِم ته ووئيل چې د موسىٰ د شريعت هغه کِتاب راوړى کوم چې مالِک خُدائ بنى اِسرائيلو له ورکړے وو.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah008_verse_001.mp3', NULL, 1761760676, 1761760676),
(11562, 'Nehemiah 8:2', 'Nehemiah', 8, 2, '&nbsp;نو عزرا د شريعت کِتاب هغه ځائ ته راوړو او دا د اوومې مياشت اوله ورځ وه چرته چې خلق راغونډ وُو. په هغوئ کښې سړى، ښځې او هغه ماشومان وُو چې د هغوئ عُمر دومره وو چې په دې باندې پوهېدل.', NULL, '&nbsp;نو عزرا د شريعت کِتاب هغه ځائ ته راوړو او دا د اوومې مياشت اوله ورځ وه چرته چې خلق راغونډ وُو. په هغوئ کښې سړى، ښځې او هغه ماشومان وُو چې د هغوئ عُمر دومره وو چې په دې باندې پوهېدل.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah008_verse_002.mp3', NULL, 1761760676, 1761760676),
(11563, 'Nehemiah 8:3', 'Nehemiah', 8, 3, '&nbsp;هلته د دروازې سره د جرګې په ځائ کښې هغۀ ورته د سحر وختى نه واخله تر غرمې پورې شريعت لوستلو او هغوئ ټولو ورته په توجو سره غوږ اېښے وو.', NULL, '&nbsp;هلته د دروازې سره د جرګې په ځائ کښې هغۀ ورته د سحر وختى نه واخله تر غرمې پورې شريعت لوستلو او هغوئ ټولو ورته په توجو سره غوږ اېښے وو.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah008_verse_003.mp3', NULL, 1761760676, 1761760676),
(11564, 'Nehemiah 8:4', 'Nehemiah', 8, 4, '&nbsp;عزرا د لرګى د پايو په ممبر باندې ولاړ وو کوم چې د دې موقعې دپاره جوړ شوے وو. دا کسان د هغۀ ښى طرف ته ولاړ وُو، متتياه، سمع، عناياه، اورِياه، خِلقياه، او معسياه، او دا کسان يې ګس طرف ته ولاړ وُو، فداياه، ميسائيل، مُلکياه، حاشوم، حسبدانه، زکرياه او مسلام.', NULL, '&nbsp;عزرا د لرګى د پايو په ممبر باندې ولاړ وو کوم چې د دې موقعې دپاره جوړ شوے وو. دا کسان د هغۀ ښى طرف ته ولاړ وُو، متتياه، سمع، عناياه، اورِياه، خِلقياه، او معسياه، او دا کسان يې ګس طرف ته ولاړ وُو، فداياه، ميسائيل، مُلکياه، حاشوم، حسبدانه، زکرياه او مسلام.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah008_verse_004.mp3', NULL, 1761760676, 1761760676),
(11565, 'Nehemiah 8:5', 'Nehemiah', 8, 5, '&nbsp;عزرا په داسې اوچت ځائ باندې ولاړ وو چې ټولو خلقو ليدلے شو. چې څنګه هغۀ کِتاب کولاو کړو، نو هغوئ ټول ودرېدل.', NULL, '&nbsp;عزرا په داسې اوچت ځائ باندې ولاړ وو چې ټولو خلقو ليدلے شو. چې څنګه هغۀ کِتاب کولاو کړو، نو هغوئ ټول ودرېدل.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah008_verse_005.mp3', NULL, 1761760676, 1761760676),
(11566, 'Nehemiah 8:6', 'Nehemiah', 8, 6, '&nbsp;عزرا وفرمائيل، ”د مالِک خُدائ د لوئ خُدائ پاک ثناء صِفت دې وى.“ نو ټولو خلقو خپل لاسونه اوچت کړل او وې وئيل، ”آمين، آمين.“ هغوئ په عبادت کښې ټيټ شول او په زمکه يې مالِک خُدائ ته سجده ولګوله.', NULL, '&nbsp;عزرا وفرمائيل، ”د مالِک خُدائ د لوئ خُدائ پاک ثناء صِفت دې وى.“ نو ټولو خلقو خپل لاسونه اوچت کړل او وې وئيل، ”آمين، آمين.“ هغوئ په عبادت کښې ټيټ شول او په زمکه يې مالِک خُدائ ته سجده ولګوله.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah008_verse_006.mp3', NULL, 1761760676, 1761760676),
(11567, 'Nehemiah 8:7', 'Nehemiah', 8, 7, '&nbsp;بيا هغوئ په خپلو خپلو ځايونو باندې ودرېدل، او دې ليويانو ورته د شريعت تشريح وکړه، يشوَع، بانى، سربياه، يمين، عقوب، سبتى، هودياه، معسياه، قليتاه، عزرياه، يوزبد، حنان او فلاياه.', NULL, '&nbsp;بيا هغوئ په خپلو خپلو ځايونو باندې ودرېدل، او دې ليويانو ورته د شريعت تشريح وکړه، يشوَع، بانى، سربياه، يمين، عقوب، سبتى، هودياه، معسياه، قليتاه، عزرياه، يوزبد، حنان او فلاياه.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah008_verse_007.mp3', NULL, 1761760676, 1761760676),
(11568, 'Nehemiah 8:8', 'Nehemiah', 8, 8, '&nbsp;هغوئ ورته د خُدائ پاک شريعت ولوستلو او د دې تشريح يې ورته وکړه، چې خلق يې په مطلب باندې پوهه شى.', NULL, '&nbsp;هغوئ ورته د خُدائ پاک شريعت ولوستلو او د دې تشريح يې ورته وکړه، چې خلق يې په مطلب باندې پوهه شى.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah008_verse_008.mp3', NULL, 1761760676, 1761760676),
(11569, 'Nehemiah 8:9', 'Nehemiah', 8, 9, '&nbsp;کله چې خلقو ته پته ولګېده چې د شريعت مطالبه څۀ ده، نو هغوئ په ژړا شروع وکړه. نو نحمياه چې حکمران وو، عزرا چې د شريعت اِمام او عالِم وو او هغه ليويانو چې د شريعت تشريح يې کوله هغوئ ټولو هغه خلقو ته وفرمائيل چې، ”دا ورځ د مالِک خُدائ ستاسو د خُدائ پاک دپاره مقدسه ده، نو تاسو له نۀ دى په کار چې غم يا ژړا وکړئ.', NULL, '&nbsp;کله چې خلقو ته پته ولګېده چې د شريعت مطالبه څۀ ده، نو هغوئ په ژړا شروع وکړه. نو نحمياه چې حکمران وو، عزرا چې د شريعت اِمام او عالِم وو او هغه ليويانو چې د شريعت تشريح يې کوله هغوئ ټولو هغه خلقو ته وفرمائيل چې، ”دا ورځ د مالِک خُدائ ستاسو د خُدائ پاک دپاره مقدسه ده، نو تاسو له نۀ دى په کار چې غم يا ژړا وکړئ.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah008_verse_009.mp3', NULL, 1761760676, 1761760676),
(11570, 'Nehemiah 8:10', 'Nehemiah', 8, 10, '&nbsp;نو د خوراک څښاک دپاره خپلو کورونو ته لاړ شئ او په خپل خوراک او ميو کښې د هغه خلقو هم حِصه وکړئ چې چا سره دا څيزونه نۀ وى. نن زمونږ د مالِک خُدائ دپاره يوه مقدسه ورځ ده، نو مۀ خفه کېږئ. د مالِک خُدائ خوشحالى ستاسو د طاقت بنياد دے.“', NULL, '&nbsp;نو د خوراک څښاک دپاره خپلو کورونو ته لاړ شئ او په خپل خوراک او ميو کښې د هغه خلقو هم حِصه وکړئ چې چا سره دا څيزونه نۀ وى. نن زمونږ د مالِک خُدائ دپاره يوه مقدسه ورځ ده، نو مۀ خفه کېږئ. د مالِک خُدائ خوشحالى ستاسو د طاقت بنياد دے.“', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah008_verse_010.mp3', NULL, 1761760676, 1761760676),
(11571, 'Nehemiah 8:11', 'Nehemiah', 8, 11, '&nbsp;نو ليويانو خلق قلارول او ورته يې وئيل چې په داسې مقدسه ورځ خفګان مۀ کوئ.', NULL, '&nbsp;نو ليويانو خلق قلارول او ورته يې وئيل چې په داسې مقدسه ورځ خفګان مۀ کوئ.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah008_verse_011.mp3', NULL, 1761760676, 1761760676),
(11572, 'Nehemiah 8:12', 'Nehemiah', 8, 12, '&nbsp;نو ټول خلق خپلو کورونو ته لاړل او په خوشحالۍ سره يې خوراک څښاک وکړو او په دې خوراک څښاک کښې يې د نورو خلقو حِصه هم وکړه، ځکه چې هغوئ د خُدائ پاک کلام اورېدلے وو او په هغې پوهه شوى وُو.', NULL, '&nbsp;نو ټول خلق خپلو کورونو ته لاړل او په خوشحالۍ سره يې خوراک څښاک وکړو او په دې خوراک څښاک کښې يې د نورو خلقو حِصه هم وکړه، ځکه چې هغوئ د خُدائ پاک کلام اورېدلے وو او په هغې پوهه شوى وُو.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah008_verse_012.mp3', NULL, 1761760676, 1761760676),
(11573, 'Nehemiah 8:13', 'Nehemiah', 8, 13, '&nbsp;په ورپسې ورځ د ډلو مشران چې د هغوئ اِمامان او ليويان هم ورسره وُو، هغوئ عزرا عالِم له لاړل چې د شريعت حُکمونه زده کړى.', NULL, '&nbsp;په ورپسې ورځ د ډلو مشران چې د هغوئ اِمامان او ليويان هم ورسره وُو، هغوئ عزرا عالِم له لاړل چې د شريعت حُکمونه زده کړى.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah008_verse_013.mp3', NULL, 1761760676, 1761760676),
(11574, 'Nehemiah 8:14', 'Nehemiah', 8, 14, '&nbsp;هغوئ ته دا پته ولګېده چې هغه شريعت دا حُکم کوى کوم چې مالِک خُدائ د موسىٰ په ذريعه ورکړے وو چې د جونګړو د اختر په دوران کښې دې بنى اِسرائيليان په جونګړو کښې اوسيږى.', NULL, '&nbsp;هغوئ ته دا پته ولګېده چې هغه شريعت دا حُکم کوى کوم چې مالِک خُدائ د موسىٰ په ذريعه ورکړے وو چې د جونګړو د اختر په دوران کښې دې بنى اِسرائيليان په جونګړو کښې اوسيږى.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah008_verse_014.mp3', NULL, 1761760676, 1761760676),
(11575, 'Nehemiah 8:15', 'Nehemiah', 8, 15, '&nbsp;نو هغوئ ورته دا اصُول وښودل او ټول يې يروشلم او نورو وړو او غټو ښارونو ته ولېږل، ”غرونو ته لاړ شئ او د نختر، د زيتُونو، د کجورو او د هغه نورو ونو لښتې راؤړئ چې سورے جوړوى، چې د هغه اصُولو په مطابق جونګړې جوړې کړُو چې د شريعت په کِتاب کښې ليکلے شوى دى.“', NULL, '&nbsp;نو هغوئ ورته دا اصُول وښودل او ټول يې يروشلم او نورو وړو او غټو ښارونو ته ولېږل، ”غرونو ته لاړ شئ او د نختر، د زيتُونو، د کجورو او د هغه نورو ونو لښتې راؤړئ چې سورے جوړوى، چې د هغه اصُولو په مطابق جونګړې جوړې کړُو چې د شريعت په کِتاب کښې ليکلے شوى دى.“', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah008_verse_015.mp3', NULL, 1761760676, 1761760676),
(11576, 'Nehemiah 8:16', 'Nehemiah', 8, 16, '&nbsp;نو خلقو څانګې راوړې او د خپلو کورونو په چتونو، په خپلو صحنونو کښې، د خُدائ پاک د کور په دربار کښې او د اِفرائيم دروازې او د اوبو دروازې سره د جرګې په عوامى ځايونو کښې يې جونګړې جوړې کړې.', NULL, '&nbsp;نو خلقو څانګې راوړې او د خپلو کورونو په چتونو، په خپلو صحنونو کښې، د خُدائ پاک د کور په دربار کښې او د اِفرائيم دروازې او د اوبو دروازې سره د جرګې په عوامى ځايونو کښې يې جونګړې جوړې کړې.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah008_verse_016.mp3', NULL, 1761760676, 1761760676),
(11577, 'Nehemiah 8:17', 'Nehemiah', 8, 17, '&nbsp;هغه ټول خلق کوم چې د جلاوطنۍ نه واپس راغلى وُو هغوئ جونګړې جوړې کړې او په هغې کښې اوسېدل او هر يو کس جذباتى او خوشحاله وو. د نون زوئ يشوَع د وخت نه پس داسې نۀ وُو شوى.', NULL, '&nbsp;هغه ټول خلق کوم چې د جلاوطنۍ نه واپس راغلى وُو هغوئ جونګړې جوړې کړې او په هغې کښې اوسېدل او هر يو کس جذباتى او خوشحاله وو. د نون زوئ يشوَع د وخت نه پس داسې نۀ وُو شوى.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah008_verse_017.mp3', NULL, 1761760676, 1761760676),
(11578, 'Nehemiah 8:18', 'Nehemiah', 8, 18, '&nbsp;د اختر د وړومبۍ ورځې نه واخله تر آخرى ورځې پورې هغوئ هره ورځ د خُدائ پاک د شريعت يوه حِصه لوستله. هغوئ اووۀ ورځې دا اختر وکړو او په اتمه ورځ د اختر د ختمېدو اجتماع وشوه، هم هغه شان لکه څنګه چې په شريعت کښې لازمى شوى وُو.', NULL, '&nbsp;د اختر د وړومبۍ ورځې نه واخله تر آخرى ورځې پورې هغوئ هره ورځ د خُدائ پاک د شريعت يوه حِصه لوستله. هغوئ اووۀ ورځې دا اختر وکړو او په اتمه ورځ د اختر د ختمېدو اجتماع وشوه، هم هغه شان لکه څنګه چې په شريعت کښې لازمى شوى وُو.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah008_verse_018.mp3', NULL, 1761760676, 1761760676),
