(11581, 'Nehemiah 9:3', 'Nehemiah', 9, 3, '&nbsp;تقريباً درې ګينټې هغوئ ولاړ وُو او د مالِک خُدائ د هغوئ د خُدائ پاک قانون ورته ولوستلے شو او ورپسې درې ګينټې هغوئ د خپلو ګناهونو اِقرار وکړو او د مالِک خُدائ د خپل خُدائ پاک عبادت يې وکړو.', NULL, '&nbsp;تقريباً درې ګينټې هغوئ ولاړ وُو او د مالِک خُدائ د هغوئ د خُدائ پاک قانون ورته ولوستلے شو او ورپسې درې ګينټې هغوئ د خپلو ګناهونو اِقرار وکړو او د مالِک خُدائ د خپل خُدائ پاک عبادت يې وکړو.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah009_verse_003.mp3', NULL, 1761760676, 1761760676),
(11582, 'Nehemiah 9:4', 'Nehemiah', 9, 4, '&nbsp;هلته د ليويانو په ممبر باندې دا کسان ولاړ وُو، يشوَع، بانى، قدمى‌اېل، شبنياه، بُنى، سربياه، بانى او کنعنياه. هغوئ مالِک خُدائ خپل خُدائ پاک ته په چغو چغو وژړل.', NULL, '&nbsp;هلته د ليويانو په ممبر باندې دا کسان ولاړ وُو، يشوَع، بانى، قدمى‌اېل، شبنياه، بُنى، سربياه، بانى او کنعنياه. هغوئ مالِک خُدائ خپل خُدائ پاک ته په چغو چغو وژړل.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah009_verse_004.mp3', NULL, 1761760676, 1761760676),
(11583, 'Nehemiah 9:5', 'Nehemiah', 9, 5, '&nbsp;د ليويانو دې مشرانو خلقو ته آواز وکړو، يشوَع، قدمى‌اېل، بانى، حسبنياه، سربياه، هودياه، شبنياه او فتحياه، او هغوئ ووئيل: ”پاڅئ او د مالِک خُدائ ستاسو د خُدائ پاک ثناء صِفت وکړئ، د هغۀ ثناء صِفت همېشه همېشه کوئ. د هغۀ د شان شوکت والا نوم دې برکتناک وى، دا دې د ټولو صِفتونو او برکتونو نه اوچت وى.“', NULL, '&nbsp;د ليويانو دې مشرانو خلقو ته آواز وکړو، يشوَع، قدمى‌اېل، بانى، حسبنياه، سربياه، هودياه، شبنياه او فتحياه، او هغوئ ووئيل: ”پاڅئ او د مالِک خُدائ ستاسو د خُدائ پاک ثناء صِفت وکړئ، د هغۀ ثناء صِفت همېشه همېشه کوئ. د هغۀ د شان شوکت والا نوم دې برکتناک وى، دا دې د ټولو صِفتونو او برکتونو نه اوچت وى.“', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah009_verse_005.mp3', NULL, 1761760676, 1761760676),
(11584, 'Nehemiah 9:6', 'Nehemiah', 9, 6, '&nbsp;او بيا بنى اِسرائيلو دا دُعا وکړه، ”مالِکه خُدايه، يواځې تۀ مالِک خُدائ يې، تا آسمانونه او د آسمان ستورى جوړ کړى دى. تا زمکه او سمندر او په دې کښې هر څۀ جوړ کړى دى، تا هر څيز له ساه ورکړې ده. آسمانى مخلوق تا ته سجده کوى او ستا عبادت کوى.', NULL, '&nbsp;او بيا بنى اِسرائيلو دا دُعا وکړه، ”مالِکه خُدايه، يواځې تۀ مالِک خُدائ يې، تا آسمانونه او د آسمان ستورى جوړ کړى دى. تا زمکه او سمندر او په دې کښې هر څۀ جوړ کړى دى، تا هر څيز له ساه ورکړې ده. آسمانى مخلوق تا ته سجده کوى او ستا عبادت کوى.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah009_verse_006.mp3', NULL, 1761760676, 1761760676),
(11585, 'Nehemiah 9:7', 'Nehemiah', 9, 7, '&nbsp;مالِکه خُدايه، خُدايه پاکه، تا ابرام غوره کړو، او تا هغه د بابل ښار اُور نه راوويستلو، تا د هغۀ نوم اِبراهيم ته بدل کړو.', NULL, '&nbsp;مالِکه خُدايه، خُدايه پاکه، تا ابرام غوره کړو، او تا هغه د بابل ښار اُور نه راوويستلو، تا د هغۀ نوم اِبراهيم ته بدل کړو.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah009_verse_007.mp3', NULL, 1761760676, 1761760676),
(11586, 'Nehemiah 9:8', 'Nehemiah', 9, 8, '&nbsp;تا ته پته ولګېده چې هغه ستا وفادار دے، نو تا د هغۀ سره يو لوظ وکړو. دا لوظ چې د کنعانيانو مُلک به ورکوې، د حِتيانو او اموريانو مُلک، د فرزيانو، يبوسيانو او جرجاسيانو مُلک، چې هغه به داسې يو مُلک وى چې د هغۀ اولاد په کښې اوسيږى. تا خپله وعده ځکه پوره کړه چې تۀ وفادار يې.', NULL, '&nbsp;تا ته پته ولګېده چې هغه ستا وفادار دے، نو تا د هغۀ سره يو لوظ وکړو. دا لوظ چې د کنعانيانو مُلک به ورکوې، د حِتيانو او اموريانو مُلک، د فرزيانو، يبوسيانو او جرجاسيانو مُلک، چې هغه به داسې يو مُلک وى چې د هغۀ اولاد په کښې اوسيږى. تا خپله وعده ځکه پوره کړه چې تۀ وفادار يې.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah009_verse_008.mp3', NULL, 1761760676, 1761760676),
(11587, 'Nehemiah 9:9', 'Nehemiah', 9, 9, '&nbsp;تا وکتل چې زمونږ پلار نيکۀ په مِصر کښې څومره کړېدلى وُو، تا د بحرِقُلزم سره د هغوئ د مدد دپاره فرياد واورېدو.', NULL, '&nbsp;تا وکتل چې زمونږ پلار نيکۀ په مِصر کښې څومره کړېدلى وُو، تا د بحرِقُلزم سره د هغوئ د مدد دپاره فرياد واورېدو.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah009_verse_009.mp3', NULL, 1761760676, 1761760676),
(11588, 'Nehemiah 9:10', 'Nehemiah', 9, 10, '&nbsp;تا د فِرعون خِلاف عجيبه معجزې وکړې، دا معجزې د هغۀ آفسرانو او د هغه مُلک د خلقو خِلاف وې، ځکه چې تا ته پته وه چې هغوئ ستا په خلقو باندې څومره ظلم کولو. تا هغه شُهرت حاصل کړو چې تر ننه پورې يې لرې.', NULL, '&nbsp;تا د فِرعون خِلاف عجيبه معجزې وکړې، دا معجزې د هغۀ آفسرانو او د هغه مُلک د خلقو خِلاف وې، ځکه چې تا ته پته وه چې هغوئ ستا په خلقو باندې څومره ظلم کولو. تا هغه شُهرت حاصل کړو چې تر ننه پورې يې لرې.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah009_verse_010.mp3', NULL, 1761760676, 1761760676),
(11589, 'Nehemiah 9:11', 'Nehemiah', 9, 11, '&nbsp;تا د خپلو خلقو دپاره په درياب کښې لار جوړه کړه او هغوئ دې په اوچه زمکه باندې تېر کړل. او چې څوک ورپسې وُو نو هغوئ په ژورو اوبو کښې ډُوب شول، داسې لکه چې يو غضبناک سمندر کښې کاڼے ډوبيږى.', NULL, '&nbsp;تا د خپلو خلقو دپاره په درياب کښې لار جوړه کړه او هغوئ دې په اوچه زمکه باندې تېر کړل. او چې څوک ورپسې وُو نو هغوئ په ژورو اوبو کښې ډُوب شول، داسې لکه چې يو غضبناک سمندر کښې کاڼے ډوبيږى.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah009_verse_011.mp3', NULL, 1761760676, 1761760676),
(11590, 'Nehemiah 9:12', 'Nehemiah', 9, 12, '&nbsp;د وريځې د ستنې په ذريعه تا هغوئ د ورځې په وخت بوتلل، او د شپې په وخت دې د اور د ستنې په ذريعه د هغوئ په لار کښې رڼا جوړوله.', NULL, '&nbsp;د وريځې د ستنې په ذريعه تا هغوئ د ورځې په وخت بوتلل، او د شپې په وخت دې د اور د ستنې په ذريعه د هغوئ په لار کښې رڼا جوړوله.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah009_verse_012.mp3', NULL, 1761760676, 1761760676),
(11591, 'Nehemiah 9:13', 'Nehemiah', 9, 13, '&nbsp;د سينا غر سره تۀ د آسمان نه راکوز شوې، تا د خپلو خلقو سره خبرې وکړې او هغوئ ته دې اِنصاف قانون او ښۀ اصُول وښودل.', NULL, '&nbsp;د سينا غر سره تۀ د آسمان نه راکوز شوې، تا د خپلو خلقو سره خبرې وکړې او هغوئ ته دې اِنصاف قانون او ښۀ اصُول وښودل.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah009_verse_013.mp3', NULL, 1761760676, 1761760676),
(11592, 'Nehemiah 9:14', 'Nehemiah', 9, 14, '&nbsp;تا هغوئ ته وښودل چې ستا د سبت ورځ مقدسه وګڼى، او تا د خپل خِدمت کوونکى موسىٰ په ذريعه هغوئ له خپل قانون ورکړو.', NULL, '&nbsp;تا هغوئ ته وښودل چې ستا د سبت ورځ مقدسه وګڼى، او تا د خپل خِدمت کوونکى موسىٰ په ذريعه هغوئ له خپل قانون ورکړو.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah009_verse_014.mp3', NULL, 1761760676, 1761760676),
(11593, 'Nehemiah 9:15', 'Nehemiah', 9, 15, '&nbsp;کله چې هغوئ اوږى وُو، نو تا هغوئ له د آسمان نه روټۍ ورکړه، او چې کله هغوئ تږى وُو نو تا د يو کاڼى نه هغوئ له اوبۀ ورکړې. تا هغوئ ته ووئيل چې هغه مُلک قبضه کړئ د کوم چې تا هغوئ له د ورکولو وعده کړې وه.', NULL, '&nbsp;کله چې هغوئ اوږى وُو، نو تا هغوئ له د آسمان نه روټۍ ورکړه، او چې کله هغوئ تږى وُو نو تا د يو کاڼى نه هغوئ له اوبۀ ورکړې. تا هغوئ ته ووئيل چې هغه مُلک قبضه کړئ د کوم چې تا هغوئ له د ورکولو وعده کړې وه.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah009_verse_015.mp3', NULL, 1761760676, 1761760676),
(11594, 'Nehemiah 9:16', 'Nehemiah', 9, 16, '&nbsp;خو زمونږ پلار نيکۀ مغروره او ضديان شول او ستا د حُکمونو د منلو نه يې اِنکار وکړو.', NULL, '&nbsp;خو زمونږ پلار نيکۀ مغروره او ضديان شول او ستا د حُکمونو د منلو نه يې اِنکار وکړو.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah009_verse_016.mp3', NULL, 1761760676, 1761760676),
(11595, 'Nehemiah 9:17', 'Nehemiah', 9, 17, '&nbsp;هغوئ نافرمانى وکړه، تا چې کومې معجزې کړې وې هغه يې هېرې کړې. په خپله سرکشۍ کښې هغوئ يو مشر خوښ کړو چې د مِصر غلامۍ له يې واپس بوځى. خو تۀ بخښونکے خُدائ پاک يې، تۀ مهربان او مينه کوونکے يې، زر نۀ غصه کېږې. ستا رحم لوئ دے، تا هغوئ پرې نۀ ښودل.', NULL, '&nbsp;هغوئ نافرمانى وکړه، تا چې کومې معجزې کړې وې هغه يې هېرې کړې. په خپله سرکشۍ کښې هغوئ يو مشر خوښ کړو چې د مِصر غلامۍ له يې واپس بوځى. خو تۀ بخښونکے خُدائ پاک يې، تۀ مهربان او مينه کوونکے يې، زر نۀ غصه کېږې. ستا رحم لوئ دے، تا هغوئ پرې نۀ ښودل.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah009_verse_017.mp3', NULL, 1761760676, 1761760676),
(11596, 'Nehemiah 9:18', 'Nehemiah', 9, 18, '&nbsp;هغوئ د سخى په شکل کښې يو بُت جوړ کړو او وې وئيل چې دا هغه خُدائ دے چې تاسو يې د مِصر نه راوويستلئ. مالِکه خُدايه، هغوئ ستا څومره بې‌عزتى وکړه.', NULL, '&nbsp;هغوئ د سخى په شکل کښې يو بُت جوړ کړو او وې وئيل چې دا هغه خُدائ دے چې تاسو يې د مِصر نه راوويستلئ. مالِکه خُدايه، هغوئ ستا څومره بې‌عزتى وکړه.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah009_verse_018.mp3', NULL, 1761760676, 1761760676),
(11597, 'Nehemiah 9:19', 'Nehemiah', 9, 19, '&nbsp;خو هغوئ دې هلته په صحرا کښې پرې نۀ ښودل، ځکه چې ستا رحم ډېر لوئ دے. تا نۀ د وريځې او نۀ د اور ستن لرې کړه چې د شپې او ورځې يې ورته لار ښودله.', NULL, '&nbsp;خو هغوئ دې هلته په صحرا کښې پرې نۀ ښودل، ځکه چې ستا رحم ډېر لوئ دے. تا نۀ د وريځې او نۀ د اور ستن لرې کړه چې د شپې او ورځې يې ورته لار ښودله.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah009_verse_019.mp3', NULL, 1761760676, 1761760676),
(11598, 'Nehemiah 9:20', 'Nehemiah', 9, 20, '&nbsp;تا د خپل نېک روح په ذريعه د هغوئ لارښودنه وکړه، تا هغوئ له د خوراک دپاره من ورکولو او د څښلو دپاره دې اوبۀ ورکولې.', NULL, '&nbsp;تا د خپل نېک روح په ذريعه د هغوئ لارښودنه وکړه، تا هغوئ له د خوراک دپاره من ورکولو او د څښلو دپاره دې اوبۀ ورکولې.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah009_verse_020.mp3', NULL, 1761760676, 1761760676),
(11599, 'Nehemiah 9:21', 'Nehemiah', 9, 21, '&nbsp;په صحرا کښې په ټولو څلوېښتو کالو کښې چې هغوئ ته د څۀ ضرورت وو د هغې هر څۀ بندوبست دې ورله وکړو، د هغوئ جامې هيڅکله زړې نۀ شوې، او د هغوئ پښې ونۀ پړسېدلې.', NULL, '&nbsp;په صحرا کښې په ټولو څلوېښتو کالو کښې چې هغوئ ته د څۀ ضرورت وو د هغې هر څۀ بندوبست دې ورله وکړو، د هغوئ جامې هيڅکله زړې نۀ شوې، او د هغوئ پښې ونۀ پړسېدلې.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah009_verse_021.mp3', NULL, 1761760676, 1761760676),
(11600, 'Nehemiah 9:22', 'Nehemiah', 9, 22, '&nbsp;په قومونو او بادشاهو فتح کولو کښې تا د هغوئ مدد کولو، او تا خپل خلق په هر ځائ کښې آباد کړل. هغوئ د حسبون مُلک فتح کړو، چرته چې سيحون بادشاهى کوله، او د بسن مُلک، چرته چې عوج بادشاه وو.', NULL, '&nbsp;په قومونو او بادشاهو فتح کولو کښې تا د هغوئ مدد کولو، او تا خپل خلق په هر ځائ کښې آباد کړل. هغوئ د حسبون مُلک فتح کړو، چرته چې سيحون بادشاهى کوله، او د بسن مُلک، چرته چې عوج بادشاه وو.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah009_verse_022.mp3', NULL, 1761760676, 1761760676),
(11601, 'Nehemiah 9:23', 'Nehemiah', 9, 23, '&nbsp;تا هغوئ له دومره بچى ورکړل لکه چې په آسمان کښې څومره ستورى دى، او تا هغوئ راوستل چې هغه مُلک قبضه کړى او هلته اوسيږى هغه مُلک کوم چې تا د هغوئ پلار نيکۀ له د ورکولو وعده کړې وه.', NULL, '&nbsp;تا هغوئ له دومره بچى ورکړل لکه چې په آسمان کښې څومره ستورى دى، او تا هغوئ راوستل چې هغه مُلک قبضه کړى او هلته اوسيږى هغه مُلک کوم چې تا د هغوئ پلار نيکۀ له د ورکولو وعده کړې وه.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah009_verse_023.mp3', NULL, 1761760676, 1761760676),
(11602, 'Nehemiah 9:24', 'Nehemiah', 9, 24, '&nbsp;هغوئ د کنعان مُلک قبضه کړو، هلته چې کوم خلق اوسېدل تۀ په هغوئ باندې غالِب راغلې. تا خپلو خلقو له هغه طاقت ورکړو چې د هغوئ سره هغه شان کار وکړى چې څۀ يې خوښه وى څوک چې د کنعان بادشاهان او خلق وُو.', NULL, '&nbsp;هغوئ د کنعان مُلک قبضه کړو، هلته چې کوم خلق اوسېدل تۀ په هغوئ باندې غالِب راغلې. تا خپلو خلقو له هغه طاقت ورکړو چې د هغوئ سره هغه شان کار وکړى چې څۀ يې خوښه وى څوک چې د کنعان بادشاهان او خلق وُو.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah009_verse_024.mp3', NULL, 1761760676, 1761760676),
(11603, 'Nehemiah 9:25', 'Nehemiah', 9, 25, '&nbsp;ستا خلقو د پَخو دېوالونو ښارونه قبضه کړل، چې آباده زمکه، د دولت نه ډک کورونه ونيسى، هغه کوهى چې د مخکښې نه کنستلے شوى دى، د زيتُونو ونې، د مېوو ونې او د انګورو باغونه. هغوئ په مړه خېټه خوراک کولو او غټ شول، تا چې کوم ښۀ څيزونه هغوئ له ورکړى وُو د هغه هر څۀ نه يې خوند اخستلو.', NULL, '&nbsp;ستا خلقو د پَخو دېوالونو ښارونه قبضه کړل، چې آباده زمکه، د دولت نه ډک کورونه ونيسى، هغه کوهى چې د مخکښې نه کنستلے شوى دى، د زيتُونو ونې، د مېوو ونې او د انګورو باغونه. هغوئ په مړه خېټه خوراک کولو او غټ شول، تا چې کوم ښۀ څيزونه هغوئ له ورکړى وُو د هغه هر څۀ نه يې خوند اخستلو.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah009_verse_025.mp3', NULL, 1761760676, 1761760676),
(11604, 'Nehemiah 9:26', 'Nehemiah', 9, 26, '&nbsp;خو ستا خلقو سرکشى وکړه او ستا نافرمانى يې وکړه، هغوئ ستا قانون ته شا کړه. هغوئ به هغه پېغمبران وژل چې خبردارے يې ورکولو، کومو چې ورته فرمائيل چې تا ته واپس راوګرځى. هغوئ ستا خِلاف لويه ګستاخى کوله،', NULL, '&nbsp;خو ستا خلقو سرکشى وکړه او ستا نافرمانى يې وکړه، هغوئ ستا قانون ته شا کړه. هغوئ به هغه پېغمبران وژل چې خبردارے يې ورکولو، کومو چې ورته فرمائيل چې تا ته واپس راوګرځى. هغوئ ستا خِلاف لويه ګستاخى کوله،', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah009_verse_026.mp3', NULL, 1761760676, 1761760676),
(11605, 'Nehemiah 9:27', 'Nehemiah', 9, 27, '&nbsp;نو تا هغوئ خپلو دشمنانو ته حواله کړل. په خپلو تکليفونو کښې هغوئ تا ته د مدد دپاره چغه کړه، او په آسمان کښې تا د هغوئ فرياد واورېدو. د خپل لوئ رحم په وجه تا هغوئ له خلاصوونکى ورولېږل چا چې هغوئ د دشمنانو نه بچ کړل.', NULL, '&nbsp;نو تا هغوئ خپلو دشمنانو ته حواله کړل. په خپلو تکليفونو کښې هغوئ تا ته د مدد دپاره چغه کړه، او په آسمان کښې تا د هغوئ فرياد واورېدو. د خپل لوئ رحم په وجه تا هغوئ له خلاصوونکى ورولېږل چا چې هغوئ د دشمنانو نه بچ کړل.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah009_verse_027.mp3', NULL, 1761760676, 1761760676),
(11606, 'Nehemiah 9:28', 'Nehemiah', 9, 28, '&nbsp;کله به چې خېر شو، نو هغوئ به ستا خِلاف بيا ګناه وکړه، او تا يو ځل بيا هغوئ دشمنانو ته حواله کړل. خو کله چې هغوئ توبه وويستله او سوال يې وکړو چې هغوئ بچ کړې، نو په آسمان کښې تا وخت په وخت د هغوئ سوال اورېدو او تا د خپل لوئ رحم په وجه هغوئ بچ کول.', NULL, '&nbsp;کله به چې خېر شو، نو هغوئ به ستا خِلاف بيا ګناه وکړه، او تا يو ځل بيا هغوئ دشمنانو ته حواله کړل. خو کله چې هغوئ توبه وويستله او سوال يې وکړو چې هغوئ بچ کړې، نو په آسمان کښې تا وخت په وخت د هغوئ سوال اورېدو او تا د خپل لوئ رحم په وجه هغوئ بچ کول.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah009_verse_028.mp3', NULL, 1761760676, 1761760676),
(11607, 'Nehemiah 9:29', 'Nehemiah', 9, 29, '&nbsp;تا هغوئ له خبردارے ورکړو چې ستا قانون ته بيا راواپس شى، خو په غرور سره هغوئ ستا قانون و نۀ منلو، اګر چې ستا د قانون منل د ژوند لاره ده. هغه د سخت زړۀ او ضديانو خلقو نافرمانى وکړه او تا ته يې غوږ نۀ نيولو.', NULL, '&nbsp;تا هغوئ له خبردارے ورکړو چې ستا قانون ته بيا راواپس شى، خو په غرور سره هغوئ ستا قانون و نۀ منلو، اګر چې ستا د قانون منل د ژوند لاره ده. هغه د سخت زړۀ او ضديانو خلقو نافرمانى وکړه او تا ته يې غوږ نۀ نيولو.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah009_verse_029.mp3', NULL, 1761760676, 1761760676),
(11608, 'Nehemiah 9:30', 'Nehemiah', 9, 30, '&nbsp;ډېر کالونه تا هغوئ ته صبر کولو. تا د خپلو پېغمبرانو په ذريعه هغوئ له خبردارے ورکولو، خو ستا خلقو غوږ نۀ نيولو، نو تا هغوئ نورو قومونو ته حواله کړل چې فتح يې کړى.', NULL, '&nbsp;ډېر کالونه تا هغوئ ته صبر کولو. تا د خپلو پېغمبرانو په ذريعه هغوئ له خبردارے ورکولو، خو ستا خلقو غوږ نۀ نيولو، نو تا هغوئ نورو قومونو ته حواله کړل چې فتح يې کړى.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah009_verse_030.mp3', NULL, 1761760676, 1761760676),
(11609, 'Nehemiah 9:31', 'Nehemiah', 9, 31, '&nbsp;خو ستا د لوئ رحم په وجه، تا هغوئ نۀ پرېښودل او نۀ دې تباه کړل. تۀ رحمان او رحيم خُدائ پاک يې.', NULL, '&nbsp;خو ستا د لوئ رحم په وجه، تا هغوئ نۀ پرېښودل او نۀ دې تباه کړل. تۀ رحمان او رحيم خُدائ پاک يې.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah009_verse_031.mp3', NULL, 1761760676, 1761760676),
(11610, 'Nehemiah 9:32', 'Nehemiah', 9, 32, '&nbsp;اے خُدايه پاکه، زمونږ خُدايه پاکه، تۀ څومره لوئ يې، تۀ څومره د رُعب والا او طاقتور يې. تۀ په وفادارۍ سره خپل لوظ پوره کوې. د هغه وخت نه کله چې د اسور بادشاهانو په مونږ ظلم کولو، تر اوسه پورې، مونږ څومره کړېدلى يُو. زمونږ بادشاهان، زمونږ مشران، زمونږ اِمامان او زمونږ پېغمبران، زمونږ پلار نيکۀ او زمونږ ټول خلق کړېدلى دى. مونږ چې څومره کړېدلى يُو نو هغه مۀ هېروه.', NULL, '&nbsp;اے خُدايه پاکه، زمونږ خُدايه پاکه، تۀ څومره لوئ يې، تۀ څومره د رُعب والا او طاقتور يې. تۀ په وفادارۍ سره خپل لوظ پوره کوې. د هغه وخت نه کله چې د اسور بادشاهانو په مونږ ظلم کولو، تر اوسه پورې، مونږ څومره کړېدلى يُو. زمونږ بادشاهان، زمونږ مشران، زمونږ اِمامان او زمونږ پېغمبران، زمونږ پلار نيکۀ او زمونږ ټول خلق کړېدلى دى. مونږ چې څومره کړېدلى يُو نو هغه مۀ هېروه.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah009_verse_032.mp3', NULL, 1761760676, 1761760676),
(11611, 'Nehemiah 9:33', 'Nehemiah', 9, 33, '&nbsp;تا ښۀ وکړل چې مونږ له دې سزا راکړه، اګر چې مونږ ګناه هم کړې ده، خو تا مونږ سره اِنصاف وکړو.', NULL, '&nbsp;تا ښۀ وکړل چې مونږ له دې سزا راکړه، اګر چې مونږ ګناه هم کړې ده، خو تا مونږ سره اِنصاف وکړو.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah009_verse_033.mp3', NULL, 1761760676, 1761760676),
(11612, 'Nehemiah 9:34', 'Nehemiah', 9, 34, '&nbsp;زمونږ بادشاهانو، زمونږ مشرانو او زمونږ اِمامانو، زمونږ پلار نيکۀ ستا قانون نۀ دے منلے. هغوئ ستا قانون او خبردارى ته غوږ نۀ نيولو.', NULL, '&nbsp;زمونږ بادشاهانو، زمونږ مشرانو او زمونږ اِمامانو، زمونږ پلار نيکۀ ستا قانون نۀ دے منلے. هغوئ ستا قانون او خبردارى ته غوږ نۀ نيولو.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah009_verse_034.mp3', NULL, 1761760676, 1761760676),
(11613, 'Nehemiah 9:35', 'Nehemiah', 9, 35, '&nbsp;کۀ څۀ هم چې د هغوئ په بادشاهۍ کښې تا هغوئ له لوئ برکت ورکړے وو، کله چې هغوئ په هغه کولاو او آباد مُلک کښې اوسېدل کوم چې تا هغوئ له ورکړے وو، خو بيا هم هغوئ د ګناه نه راونۀ ګرځېدل او نۀ يې ستا خِدمت کړے وو.', NULL, '&nbsp;کۀ څۀ هم چې د هغوئ په بادشاهۍ کښې تا هغوئ له لوئ برکت ورکړے وو، کله چې هغوئ په هغه کولاو او آباد مُلک کښې اوسېدل کوم چې تا هغوئ له ورکړے وو، خو بيا هم هغوئ د ګناه نه راونۀ ګرځېدل او نۀ يې ستا خِدمت کړے وو.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah009_verse_035.mp3', NULL, 1761760676, 1761760676),
(11614, 'Nehemiah 9:36', 'Nehemiah', 9, 36, '&nbsp;نو مونږ تر اوسه په هغه مُلک کښې غلامان يُو چې تا زمونږ پلار نيکۀ له ورکړے وو، چې د هغې په مېوه او پېداوار باندې مزې وکړى.', NULL, '&nbsp;نو مونږ تر اوسه په هغه مُلک کښې غلامان يُو چې تا زمونږ پلار نيکۀ له ورکړے وو، چې د هغې په مېوه او پېداوار باندې مزې وکړى.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah009_verse_036.mp3', NULL, 1761760676, 1761760676),
(11615, 'Nehemiah 9:37', 'Nehemiah', 9, 37, '&nbsp;چې زمکه څۀ پېدا کوى نو هغه بادشاهانو له ځى چې زمونږ د ګناه په وجه تا په مونږ باندې مقرر کړى دى. هغوئ زمونږ او زمونږ د څاروو سره هغه څۀ کوى چې څۀ يې خوښه وى، او مونږ په يوه سخته پرېشانۍ کښې يُو.“', NULL, '&nbsp;چې زمکه څۀ پېدا کوى نو هغه بادشاهانو له ځى چې زمونږ د ګناه په وجه تا په مونږ باندې مقرر کړى دى. هغوئ زمونږ او زمونږ د څاروو سره هغه څۀ کوى چې څۀ يې خوښه وى، او مونږ په يوه سخته پرېشانۍ کښې يُو.“', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah009_verse_037.mp3', NULL, 1761760676, 1761760676),
(11616, 'Nehemiah 9:38', 'Nehemiah', 9, 38, '&nbsp;”چې دا هر څۀ شوى دى نو مونږ بنى اِسرائيليان دا پخه ليکلې معاهده کوُو او زمونږ مشران، ليويان او زمونږ اِمامان به په دې باندې خپل مهرونه ولګوى.“', NULL, '&nbsp;”چې دا هر څۀ شوى دى نو مونږ بنى اِسرائيليان دا پخه ليکلې معاهده کوُو او زمونږ مشران، ليويان او زمونږ اِمامان به په دې باندې خپل مهرونه ولګوى.“', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah009_verse_038.mp3', NULL, 1761760676, 1761760676),
(11617, 'Nehemiah 10:1', 'Nehemiah', 10, 1, '&nbsp;کومو کسانو چې دستخطونه وکړل هغوئ دا وُو: د حکلياه زوئ نحمياه حکمران. صدقياه،', NULL, '&nbsp;کومو کسانو چې دستخطونه وکړل هغوئ دا وُو: د حکلياه زوئ نحمياه حکمران. صدقياه،', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah010_verse_001.mp3', NULL, 1761760676, 1761760676),
(11618, 'Nehemiah 10:28', 'Nehemiah', 10, 28, '&nbsp;مونږ يعنې بنى اِسرائيلو، اِمامانو، ليويانو، څوکيدارانو، سندرغاړو، د خُدائ پاک د کور خِدمتګارانو او هغه نورو ټولو خلقو د خُدائ پاک د قانون د تابعدارۍ په بنياد خپل ځانونه د پردى مُلک د هغه خلقو نه جدا کړى وُو کوم چې زمونږ په مُلک کښې اوسېدل. مونږ د خپلو ښځو او د هغه ټولو بچو سره د کومو عُمر چې پوهېدو ته رسېدلے دے،', NULL, '&nbsp;مونږ يعنې بنى اِسرائيلو، اِمامانو، ليويانو، څوکيدارانو، سندرغاړو، د خُدائ پاک د کور خِدمتګارانو او هغه نورو ټولو خلقو د خُدائ پاک د قانون د تابعدارۍ په بنياد خپل ځانونه د پردى مُلک د هغه خلقو نه جدا کړى وُو کوم چې زمونږ په مُلک کښې اوسېدل. مونږ د خپلو ښځو او د هغه ټولو بچو سره د کومو عُمر چې پوهېدو ته رسېدلے دے،', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761760676, 1761760676),
(11619, 'Nehemiah 10:29', 'Nehemiah', 10, 29, '&nbsp;مونږ د خپلو مشرانو سره په يو قسم کولو کښې شريک شُو او ومو وئيل چې مونږ کۀ قسم مات کړو نو په مونږ دې لعنت وى او دا چې مونږ به د خُدائ پاک د قانون په مطابق خپل ژوند تېروو، هم هغه قانون کوم چې خُدائ پاک د خپل خِدمت کوونکى موسىٰ په ذريعه راکړے وو، چې مونږ به هغه هر څۀ منو چې مالِک خُدائ زمونږ خُدائ پاک يې حُکم راکوى، او چې مونږ به د هغۀ ټول قانون او اصُول منو.', NULL, '&nbsp;مونږ د خپلو مشرانو سره په يو قسم کولو کښې شريک شُو او ومو وئيل چې مونږ کۀ قسم مات کړو نو په مونږ دې لعنت وى او دا چې مونږ به د خُدائ پاک د قانون په مطابق خپل ژوند تېروو، هم هغه قانون کوم چې خُدائ پاک د خپل خِدمت کوونکى موسىٰ په ذريعه راکړے وو، چې مونږ به هغه هر څۀ منو چې مالِک خُدائ زمونږ خُدائ پاک يې حُکم راکوى، او چې مونږ به د هغۀ ټول قانون او اصُول منو.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761760676, 1761760676),
(11620, 'Nehemiah 10:30', 'Nehemiah', 10, 30, '&nbsp;مونږ دا وعده وکړه چې د هغه مُلک د غېرو قومونو خلقو له به خپلې لوڼه نۀ ورکوو او د هغوئ لوڼه به خپلو زامنو ته نۀ وادۀ کوُو.', NULL, '&nbsp;مونږ دا وعده وکړه چې د هغه مُلک د غېرو قومونو خلقو له به خپلې لوڼه نۀ ورکوو او د هغوئ لوڼه به خپلو زامنو ته نۀ وادۀ کوُو.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761760676, 1761760676),
(11621, 'Nehemiah 10:31', 'Nehemiah', 10, 31, '&nbsp;کۀ د پردى مُلک خلق څۀ غله يا بل هر څيز هم د سبت يا په بله هره مقدسه ورځ په مونږ باندې د خرڅولو دپاره راوړى، نو مونږ به يې د هغوئ نه نۀ اخلو. په هر اوؤم کال به مونږ زمکه نۀ کرو او ټول قرضونه به معاف کوُو.', NULL, '&nbsp;کۀ د پردى مُلک خلق څۀ غله يا بل هر څيز هم د سبت يا په بله هره مقدسه ورځ په مونږ باندې د خرڅولو دپاره راوړى، نو مونږ به يې د هغوئ نه نۀ اخلو. په هر اوؤم کال به مونږ زمکه نۀ کرو او ټول قرضونه به معاف کوُو.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761760676, 1761760676),
(11622, 'Nehemiah 10:32', 'Nehemiah', 10, 32, '&nbsp;زمونږ هر يو کس به هر کال پينځۀ ګرامه سپين زر د خُدائ پاک د کور د خرچې دپاره په چنده کښې ورکوى.', NULL, '&nbsp;زمونږ هر يو کس به هر کال پينځۀ ګرامه سپين زر د خُدائ پاک د کور د خرچې دپاره په چنده کښې ورکوى.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761760676, 1761760676),
(11623, 'Nehemiah 10:33', 'Nehemiah', 10, 33, '&nbsp;مونږ به د خُدائ پاک د کور د عبادت دپاره د دې څيزونو بندوبست کوُو، مقدسه روټۍ، د هرې ورځې د غلې نذرانه، هغه ځناور چې هره ورځ د قربانۍ په توګه سوزولے شى، د سبت د ورځو، د نوې مياشتې د اختر او د نورو اخترونو دپاره مقدسې نذرانې، د بنى اِسرائيلو د ګناه کفارې دپاره نذرانې او هغه بل هر يو څيز چې د خُدائ پاک په کور کښې يې ضرورت وى.', NULL, '&nbsp;مونږ به د خُدائ پاک د کور د عبادت دپاره د دې څيزونو بندوبست کوُو، مقدسه روټۍ، د هرې ورځې د غلې نذرانه، هغه ځناور چې هره ورځ د قربانۍ په توګه سوزولے شى، د سبت د ورځو، د نوې مياشتې د اختر او د نورو اخترونو دپاره مقدسې نذرانې، د بنى اِسرائيلو د ګناه کفارې دپاره نذرانې او هغه بل هر يو څيز چې د خُدائ پاک په کور کښې يې ضرورت وى.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761760676, 1761760676),
(11624, 'Nehemiah 10:34', 'Nehemiah', 10, 34, '&nbsp;زمونږ خلق، اِمامان او ليويان به هر کال پچه اچوى چې دا معلومه کړى چې کومه يوه ډله د مالِک خُدائ زمونږ خُدائ پاک په قربان‌ګاه باندې د سوزولو دپاره لرګو بندوبست کوى او دا به د قانون په مطابق وى.', NULL, '&nbsp;زمونږ خلق، اِمامان او ليويان به هر کال پچه اچوى چې دا معلومه کړى چې کومه يوه ډله د مالِک خُدائ زمونږ خُدائ پاک په قربان‌ګاه باندې د سوزولو دپاره لرګو بندوبست کوى او دا به د قانون په مطابق وى.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761760676, 1761760676),
(11625, 'Nehemiah 10:35', 'Nehemiah', 10, 35, '&nbsp;مونږ به هر کال د خپل وړومبى رېبلے شوى فصل او زمونږ په ونو کښې د وړومبى پېدا شوې مېوې يوه نذرانه د مالِک خُدائ کور ته وړُو.', NULL, '&nbsp;مونږ به هر کال د خپل وړومبى رېبلے شوى فصل او زمونږ په ونو کښې د وړومبى پېدا شوې مېوې يوه نذرانه د مالِک خُدائ کور ته وړُو.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761760676, 1761760676),
(11626, 'Nehemiah 10:36', 'Nehemiah', 10, 36, '&nbsp;زمونږ د هر يو کس وړومبے پېدا شوے زوئ به اِمامانو له د خُدائ پاک کور ته بوځُو او هلته به يې د خُدائ پاک د ښودلى شوى قانون په مطابق خُدائ پاک ته وقف کوُو. زمونږ د هر يو کس د غواګانو وړومبے پېدا شوے سخے او زمونږ د هر يو کس وړومبے پېدا شوے ګډُورے يا د چېلۍ بچے به هم وقف کيږى.', NULL, '&nbsp;زمونږ د هر يو کس وړومبے پېدا شوے زوئ به اِمامانو له د خُدائ پاک کور ته بوځُو او هلته به يې د خُدائ پاک د ښودلى شوى قانون په مطابق خُدائ پاک ته وقف کوُو. زمونږ د هر يو کس د غواګانو وړومبے پېدا شوے سخے او زمونږ د هر يو کس وړومبے پېدا شوے ګډُورے يا د چېلۍ بچے به هم وقف کيږى.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761760676, 1761760676),
(11627, 'Nehemiah 10:37', 'Nehemiah', 10, 37, '&nbsp;مونږ به هر کال اِمامانو له د خُدائ پاک کور ته د وړومبى رېبلى شوى فصل نه جوړې شوې پېړې او د انګورو د ميو خپلې نورې نذرانې، د زيتُونو تېل او هر قِسم مېوې هم وړُو. او مونږ به هغه هر څۀ نه لسمه حِصه ليويانو له راؤړو څۀ چې زمونږ په پټو کښې شوى دى، ځکه چې هغوئ زمونږ په کلو کښې د دې څيزونو د راټولو ذمه وار دى.', NULL, '&nbsp;مونږ به هر کال اِمامانو له د خُدائ پاک کور ته د وړومبى رېبلى شوى فصل نه جوړې شوې پېړې او د انګورو د ميو خپلې نورې نذرانې، د زيتُونو تېل او هر قِسم مېوې هم وړُو. او مونږ به هغه هر څۀ نه لسمه حِصه ليويانو له راؤړو څۀ چې زمونږ په پټو کښې شوى دى، ځکه چې هغوئ زمونږ په کلو کښې د دې څيزونو د راټولو ذمه وار دى.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761760676, 1761760676),
(11628, 'Nehemiah 10:38', 'Nehemiah', 10, 38, '&nbsp;کله چې لسمه حِصه راټولولے شى نو د هارون د اولاد اِمامان به ليويانو سره وى. او د هغه ټولې راټولې شوې لسمې حِصې نه به ليويان لسمه حِصه د خُدائ پاک د کور ګودامونو ته يوسى.', NULL, '&nbsp;کله چې لسمه حِصه راټولولے شى نو د هارون د اولاد اِمامان به ليويانو سره وى. او د هغه ټولې راټولې شوې لسمې حِصې نه به ليويان لسمه حِصه د خُدائ پاک د کور ګودامونو ته يوسى.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761760676, 1761760676),
(11629, 'Nehemiah 10:39', 'Nehemiah', 10, 39, '&nbsp;بنى اِسرائيل او ليويان به د فصل، ميو او د زيتُونو تېلو برخې هغه ګودامونو ته يوسى چرته چې د خُدائ پاک د کور سامان کېښودلے شى او چرته چې اِمامان، د دروازو څوکيداران او سندرغاړى حاضر وى. مونږ به زمونږ د خُدائ پاک د کور نه مخ نۀ اړوُو.', NULL, '&nbsp;بنى اِسرائيل او ليويان به د فصل، ميو او د زيتُونو تېلو برخې هغه ګودامونو ته يوسى چرته چې د خُدائ پاک د کور سامان کېښودلے شى او چرته چې اِمامان، د دروازو څوکيداران او سندرغاړى حاضر وى. مونږ به زمونږ د خُدائ پاک د کور نه مخ نۀ اړوُو.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761760676, 1761760676),
(11630, 'Nehemiah 11:1', 'Nehemiah', 11, 1, '&nbsp;مشران په يروشلم کښې دېره شول او باقى خلقو پچه واچوله چې د هر لسم خاندان نه يو خاندان خوښ کړى چې لاړ شى او د يروشلم په مقدس ښار کښې اوسيږى، خو هغه نور په خپلو ښارونو کښې اوسېدل.', NULL, '&nbsp;مشران په يروشلم کښې دېره شول او باقى خلقو پچه واچوله چې د هر لسم خاندان نه يو خاندان خوښ کړى چې لاړ شى او د يروشلم په مقدس ښار کښې اوسيږى، خو هغه نور په خپلو ښارونو کښې اوسېدل.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah011_verse_001.mp3', NULL, 1761760676, 1761760676),
