(11632, 'Nehemiah 11:3', 'Nehemiah', 11, 3, '&nbsp;د يهوداه په ښارونو کښې بنى اِسرائيل، اِمامان، ليويان، د خُدائ پاک د کور کاريګران او د سليمان د نوکرانو اولاد په خپلو ښارونو کښې په خپلو جائيدادونو کښې اوسېدل. دا د يهوداه صُوبې د مشرانو ښاريانو تفصيل دے کوم چې په يروشلم کښې اوسېدل:', NULL, '&nbsp;د يهوداه په ښارونو کښې بنى اِسرائيل، اِمامان، ليويان، د خُدائ پاک د کور کاريګران او د سليمان د نوکرانو اولاد په خپلو ښارونو کښې په خپلو جائيدادونو کښې اوسېدل. دا د يهوداه صُوبې د مشرانو ښاريانو تفصيل دے کوم چې په يروشلم کښې اوسېدل:', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah011_verse_003.mp3', NULL, 1761760676, 1761760676),
(11633, 'Nehemiah 11:4', 'Nehemiah', 11, 4, '&nbsp;د يهوداه قبيلې کسان دا دى: د زکرياه نمسے او د عُزياه زوئ عتاياه. د هغۀ په آباواجداد کښې امرياه، سفطياه او محلل‌اېل شامل وُو، چې د يهوداه زوئ د فارص اولاد وو.', NULL, '&nbsp;د يهوداه قبيلې کسان دا دى: د زکرياه نمسے او د عُزياه زوئ عتاياه. د هغۀ په آباواجداد کښې امرياه، سفطياه او محلل‌اېل شامل وُو، چې د يهوداه زوئ د فارص اولاد وو.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah011_verse_004.mp3', NULL, 1761760676, 1761760676),
