(11635, 'Nehemiah 11:6', 'Nehemiah', 11, 6, '&nbsp;د فارص د اولاد څلور سوه او اتۀ شپېتۀ ښۀ تکړه سړى په يروشلم کښې اوسېدل.', NULL, '&nbsp;د فارص د اولاد څلور سوه او اتۀ شپېتۀ ښۀ تکړه سړى په يروشلم کښې اوسېدل.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah011_verse_006.mp3', NULL, 1761760676, 1761760676),
(11636, 'Nehemiah 11:7', 'Nehemiah', 11, 7, '&nbsp;د بنيامين د قبيلې کسان دا دى: د يوئيد نمسے او د مسلام زوئ سلو وو. د هغۀ په نورو آباواجداد کښې فداياه، قولاياه، معسياه، ايتى‌اېل او يشعياه شامل وُو.', NULL, '&nbsp;د بنيامين د قبيلې کسان دا دى: د يوئيد نمسے او د مسلام زوئ سلو وو. د هغۀ په نورو آباواجداد کښې فداياه، قولاياه، معسياه، ايتى‌اېل او يشعياه شامل وُو.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah011_verse_007.mp3', NULL, 1761760676, 1761760676),
(11637, 'Nehemiah 11:8', 'Nehemiah', 11, 8, '&nbsp;د سلو نزدې خپلوان جبى او سلى وُو. ټول نهۀ سوه او اتۀويشت بنيامينيان په يروشلم کښې اوسېدل.', NULL, '&nbsp;د سلو نزدې خپلوان جبى او سلى وُو. ټول نهۀ سوه او اتۀويشت بنيامينيان په يروشلم کښې اوسېدل.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah011_verse_008.mp3', NULL, 1761760676, 1761760676),
(11638, 'Nehemiah 11:9', 'Nehemiah', 11, 9, '&nbsp;د زِکرى زوئ يوايل د هغوئ مشر وو، د هسينوآه زوئ يهوداه په ښار کښې دوېم مشر آفسر وو.', NULL, '&nbsp;د زِکرى زوئ يوايل د هغوئ مشر وو، د هسينوآه زوئ يهوداه په ښار کښې دوېم مشر آفسر وو.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah011_verse_009.mp3', NULL, 1761760676, 1761760676),
(11639, 'Nehemiah 11:10', 'Nehemiah', 11, 10, '&nbsp;اِمامان: د يويريب زوئ يدعياه او يکين.', NULL, '&nbsp;اِمامان: د يويريب زوئ يدعياه او يکين.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah011_verse_010.mp3', NULL, 1761760676, 1761760676),
(11640, 'Nehemiah 11:11', 'Nehemiah', 11, 11, '&nbsp;شراياه زوئ د خِلقياه، زوئ د مسلام، زوئ د صدوق، زوئ د مرايوت، زوئ د اخيطوب، څوک چې د خُدائ پاک د کور مشر اِمام وو.', NULL, '&nbsp;شراياه زوئ د خِلقياه، زوئ د مسلام، زوئ د صدوق، زوئ د مرايوت، زوئ د اخيطوب، څوک چې د خُدائ پاک د کور مشر اِمام وو.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah011_verse_011.mp3', NULL, 1761760676, 1761760676),
(11641, 'Nehemiah 11:12', 'Nehemiah', 11, 12, '&nbsp;د دې قبيلې ټولو اتۀ سوه او دوويشتو کسانو د خُدائ پاک په کور کښې خِدمت کولو. د فللياه نمسے او د يروحام زوئ عداياه. د هغۀ په آباواجداد کښې امصى، زکرياه، فشحور او مُلکياه شامل وُو.', NULL, '&nbsp;د دې قبيلې ټولو اتۀ سوه او دوويشتو کسانو د خُدائ پاک په کور کښې خِدمت کولو. د فللياه نمسے او د يروحام زوئ عداياه. د هغۀ په آباواجداد کښې امصى، زکرياه، فشحور او مُلکياه شامل وُو.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah011_verse_012.mp3', NULL, 1761760676, 1761760676),
(11642, 'Nehemiah 11:13', 'Nehemiah', 11, 13, '&nbsp;د هغۀ د قبيلې ټول دوه سوه او دوه څلوېښت کسان د کورَنو مشران وُو. د اخزائى نمسے او د عزراېل زوئ امشى. د هغۀ په آباواجداد کښې اِمير او مسلموت شامل وُو.', NULL, '&nbsp;د هغۀ د قبيلې ټول دوه سوه او دوه څلوېښت کسان د کورَنو مشران وُو. د اخزائى نمسے او د عزراېل زوئ امشى. د هغۀ په آباواجداد کښې اِمير او مسلموت شامل وُو.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah011_verse_013.mp3', NULL, 1761760676, 1761760676),
(11643, 'Nehemiah 11:14', 'Nehemiah', 11, 14, '&nbsp;د هغۀ د قبيلې يو سل او اتۀويشت کسان ښۀ تکړه فوجيان وُو. د هغوئ مشر زبدى‌اېل وو چې د هجدوليم زوئ وو.', NULL, '&nbsp;د هغۀ د قبيلې يو سل او اتۀويشت کسان ښۀ تکړه فوجيان وُو. د هغوئ مشر زبدى‌اېل وو چې د هجدوليم زوئ وو.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah011_verse_014.mp3', NULL, 1761760676, 1761760676),
(11644, 'Nehemiah 11:15', 'Nehemiah', 11, 15, '&nbsp;ليويان: د عزريقام نمسے او د حسوب زوئ سمعياه. د هغۀ په آباواجداد کښې حسبياه او بُنى شامل وُو.', NULL, '&nbsp;ليويان: د عزريقام نمسے او د حسوب زوئ سمعياه. د هغۀ په آباواجداد کښې حسبياه او بُنى شامل وُو.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah011_verse_015.mp3', NULL, 1761760676, 1761760676),
