(11648, 'Nehemiah 11:19', 'Nehemiah', 11, 19, '&nbsp;د خُدائ پاک د کور څوکيداران: عقوب، طلمون او د هغوئ خپلوان، ټول يو سل او دوه اويا کسان وُو.', NULL, '&nbsp;د خُدائ پاک د کور څوکيداران: عقوب، طلمون او د هغوئ خپلوان، ټول يو سل او دوه اويا کسان وُو.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah011_verse_019.mp3', NULL, 1761760676, 1761760676),
(11649, 'Nehemiah 11:20', 'Nehemiah', 11, 20, '&nbsp;نور بنى اِسرائيليان او پاتې اِمامان او ليويان د يهوداه په ښارونو کښې په خپلو خپلو جائيدادونو کښې اوسېدل.', NULL, '&nbsp;نور بنى اِسرائيليان او پاتې اِمامان او ليويان د يهوداه په ښارونو کښې په خپلو خپلو جائيدادونو کښې اوسېدل.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah011_verse_020.mp3', NULL, 1761760676, 1761760676),
(11650, 'Nehemiah 11:21', 'Nehemiah', 11, 21, '&nbsp;د خُدائ پاک د کور خِدمتګاران د يروشلم په هغه برخه کښې اوسېدل چې نوم يې عوفل وو او هغوئ د ضيحا او جِسفا د مشرۍ لاندې کار کولو.', NULL, '&nbsp;د خُدائ پاک د کور خِدمتګاران د يروشلم په هغه برخه کښې اوسېدل چې نوم يې عوفل وو او هغوئ د ضيحا او جِسفا د مشرۍ لاندې کار کولو.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah011_verse_021.mp3', NULL, 1761760676, 1761760676),
(11651, 'Nehemiah 11:22', 'Nehemiah', 11, 22, '&nbsp;د ليويانو هغه مشر چې په يروشلم کښې اوسېدو هغه د حسبياه نمسے او د بانى زوئ عُزى وو. د هغۀ په پلارانو نيکونو کښې متنياه او ميکا شامل وُو او هغه د آسف د قبيلې نه وو. دا هغه ډله وه چې د دې کسان د خُدائ پاک په کور کښې د موسيقۍ ذمه وار وُو.', NULL, '&nbsp;د ليويانو هغه مشر چې په يروشلم کښې اوسېدو هغه د حسبياه نمسے او د بانى زوئ عُزى وو. د هغۀ په پلارانو نيکونو کښې متنياه او ميکا شامل وُو او هغه د آسف د قبيلې نه وو. دا هغه ډله وه چې د دې کسان د خُدائ پاک په کور کښې د موسيقۍ ذمه وار وُو.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah011_verse_022.mp3', NULL, 1761760676, 1761760676),
(11652, 'Nehemiah 11:23', 'Nehemiah', 11, 23, '&nbsp;د دې دپاره شاهى اصُول مقرر وُو چې قبيلې به هره ورځ د خُدائ پاک د کور په موسيقۍ کښې مشرى څنګه کوى.', NULL, '&nbsp;د دې دپاره شاهى اصُول مقرر وُو چې قبيلې به هره ورځ د خُدائ پاک د کور په موسيقۍ کښې مشرى څنګه کوى.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah011_verse_023.mp3', NULL, 1761760676, 1761760676),
