(11654, 'Nehemiah 11:25', 'Nehemiah', 11, 25, '&nbsp;ډېر خلق د خپلو پټو سره نزدې په کلو کښې اوسېدل. څۀ کسان چې د يهوداه د قبيلې وُو نو هغوئ په قِريَت‌اربع، ديبون، يقبضى‌اېل او د دې ښارونو سره نزدې کلو کښې اوسېدل.', NULL, '&nbsp;ډېر خلق د خپلو پټو سره نزدې په کلو کښې اوسېدل. څۀ کسان چې د يهوداه د قبيلې وُو نو هغوئ په قِريَت‌اربع، ديبون، يقبضى‌اېل او د دې ښارونو سره نزدې کلو کښې اوسېدل.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah011_verse_025.mp3', NULL, 1761760676, 1761760676),
