(11656, 'Nehemiah 11:27', 'Nehemiah', 11, 27, '&nbsp;او داسې په حصارسعول، بيرسبع او د دې نه ګېرچاپېره کلو کښې هم اوسېدل.', NULL, '&nbsp;او داسې په حصارسعول، بيرسبع او د دې نه ګېرچاپېره کلو کښې هم اوسېدل.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah011_verse_027.mp3', NULL, 1761760676, 1761760676),
