(11659, 'Nehemiah 11:30', 'Nehemiah', 11, 30, '&nbsp;په زنوح، عدولام او نزدې کلو کښې اوسېدل. هغوئ په لکيس او په نزدې پټو کښې او په عزيقه او د دې په کلو کښې اوسېدل. نو د يهوداه خلق د بيرسبع نه واخله د هنوم وادۍ پورې اوسېدل.', NULL, '&nbsp;په زنوح، عدولام او نزدې کلو کښې اوسېدل. هغوئ په لکيس او په نزدې پټو کښې او په عزيقه او د دې په کلو کښې اوسېدل. نو د يهوداه خلق د بيرسبع نه واخله د هنوم وادۍ پورې اوسېدل.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah011_verse_030.mp3', NULL, 1761760676, 1761760676),
(11660, 'Nehemiah 11:31', 'Nehemiah', 11, 31, '&nbsp;د بنيامين قبيلې خلق په دې ځايونو کښې اوسېدل، جبعه، مِکماس، عياه، بيت‌ايل او د دې نزدې کلو کښې،', NULL, '&nbsp;د بنيامين قبيلې خلق په دې ځايونو کښې اوسېدل، جبعه، مِکماس، عياه، بيت‌ايل او د دې نزدې کلو کښې،', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah011_verse_031.mp3', NULL, 1761760676, 1761760676),
