(11664, 'Nehemiah 11:35', 'Nehemiah', 11, 35, '&nbsp;لد، اونو او په هغه وادۍ کښې چې چرته کاريګر اوسېدل.', NULL, '&nbsp;لد، اونو او په هغه وادۍ کښې چې چرته کاريګر اوسېدل.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah011_verse_035.mp3', NULL, 1761760676, 1761760676),
(11665, 'Nehemiah 11:36', 'Nehemiah', 11, 36, '&nbsp;د ليويانو څۀ قبيلې کومې چې د يهوداه په علاقه کښې اوسېدلې وې هغوئ د بنيامين د خلقو سره اوسېدو دپاره ولېږل شول.', NULL, '&nbsp;د ليويانو څۀ قبيلې کومې چې د يهوداه په علاقه کښې اوسېدلې وې هغوئ د بنيامين د خلقو سره اوسېدو دپاره ولېږل شول.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah011_verse_036.mp3', NULL, 1761760676, 1761760676),
(11666, 'Nehemiah 12:1', 'Nehemiah', 12, 1, '&nbsp;دا د هغه اِمامانو او ليويانو تفصيل دے کوم چې د شلتى‌اېل زوئ زرُبابل او د مشر اِمام يشوَع سره د جلاوطنۍ نه راواپس شول.', NULL, '&nbsp;دا د هغه اِمامانو او ليويانو تفصيل دے کوم چې د شلتى‌اېل زوئ زرُبابل او د مشر اِمام يشوَع سره د جلاوطنۍ نه راواپس شول.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah012_verse_001.mp3', NULL, 1761760676, 1761760676),
(11667, 'Nehemiah 12:8', 'Nehemiah', 12, 8, '&nbsp;ليويان: دا کسان د شُکر ګزارۍ حمد‌و‌ثناء مشران وُو، يشوَع، بِنوئى، قدمى‌اېل، سربياه، يهوداه او متنياه.', NULL, '&nbsp;ليويان: دا کسان د شُکر ګزارۍ حمد‌و‌ثناء مشران وُو، يشوَع، بِنوئى، قدمى‌اېل، سربياه، يهوداه او متنياه.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah012_verse_008.mp3', NULL, 1761760676, 1761760676),
(11668, 'Nehemiah 12:9', 'Nehemiah', 12, 9, '&nbsp;دې کسانو ورسره آواز نيولو، بقبوقياه، عُنى او د هغوئ ملګرو ليويانو.', NULL, '&nbsp;دې کسانو ورسره آواز نيولو، بقبوقياه، عُنى او د هغوئ ملګرو ليويانو.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah012_verse_009.mp3', NULL, 1761760676, 1761760676),
(11669, 'Nehemiah 12:10', 'Nehemiah', 12, 10, '&nbsp;يشوَع د يويقيم پلار وو، يويقيم د اِلياسب پلار وو، اِلياسب د يويدع پلار وو،', NULL, '&nbsp;يشوَع د يويقيم پلار وو، يويقيم د اِلياسب پلار وو، اِلياسب د يويدع پلار وو،', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah012_verse_010.mp3', NULL, 1761760676, 1761760676),
(11670, 'Nehemiah 12:11', 'Nehemiah', 12, 11, '&nbsp;يويدع د يونتن پلار وو، او يونتن د يدوع پلار وو.', NULL, '&nbsp;يويدع د يونتن پلار وو، او يونتن د يدوع پلار وو.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah012_verse_011.mp3', NULL, 1761760676, 1761760676),
(11671, 'Nehemiah 12:22', 'Nehemiah', 12, 22, '&nbsp;کله چې اِلياسب، يويدع، يوحانان او يدوع مشران اِمامان وُو نو د ليويانو د مشرانو فهرست تيار شو او هم داسې د فارس بادشاه داريوس په زمانه کښې د اِمامانو د کورَنو د مشرانو حِساب کِتاب ساتلے شوے وو.', NULL, '&nbsp;کله چې اِلياسب، يويدع، يوحانان او يدوع مشران اِمامان وُو نو د ليويانو د مشرانو فهرست تيار شو او هم داسې د فارس بادشاه داريوس په زمانه کښې د اِمامانو د کورَنو د مشرانو حِساب کِتاب ساتلے شوے وو.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah012_verse_022.mp3', NULL, 1761760676, 1761760676),
(11672, 'Nehemiah 12:23', 'Nehemiah', 12, 23, '&nbsp;د اِلياسب نمسى د يوحانان وخت پورې د ليويانو د کورَنو مشرانو حِساب کِتاب د تاريخ په کِتاب کښې ليکلے شو.', NULL, '&nbsp;د اِلياسب نمسى د يوحانان وخت پورې د ليويانو د کورَنو مشرانو حِساب کِتاب د تاريخ په کِتاب کښې ليکلے شو.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah012_verse_023.mp3', NULL, 1761760676, 1761760676),
(11673, 'Nehemiah 12:24', 'Nehemiah', 12, 24, '&nbsp;دا د ليويانو د کورَنو مشران دى: حسبياه، سربياه، يشوَع، بِنوئى، قدمى‌اېل. په هغه وخت کښې به دوو ډلو يو بل ته مخامخ نمبر په نمبر د خُدائ پاک ثناء صِفت کولو او د هغۀ شُکر به يې ادا کولو. دا به يې د هغه اصُولو په مطابق کول کوم چې د خُدائ پاک خِدمت کوونکى داؤد بادشاه ورته ښودلى وُو.', NULL, '&nbsp;دا د ليويانو د کورَنو مشران دى: حسبياه، سربياه، يشوَع، بِنوئى، قدمى‌اېل. په هغه وخت کښې به دوو ډلو يو بل ته مخامخ نمبر په نمبر د خُدائ پاک ثناء صِفت کولو او د هغۀ شُکر به يې ادا کولو. دا به يې د هغه اصُولو په مطابق کول کوم چې د خُدائ پاک خِدمت کوونکى داؤد بادشاه ورته ښودلى وُو.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah012_verse_024.mp3', NULL, 1761760676, 1761760676),
(11674, 'Nehemiah 12:25', 'Nehemiah', 12, 25, '&nbsp;د خُدائ پاک د کور دا څوکيداران د خُدائ پاک د کور د دروازو سره د ګودامونو مشران وُو: متنياه، بقبوقياه، عبدياه، مسلام، طلمون او عقوب.', NULL, '&nbsp;د خُدائ پاک د کور دا څوکيداران د خُدائ پاک د کور د دروازو سره د ګودامونو مشران وُو: متنياه، بقبوقياه، عبدياه، مسلام، طلمون او عقوب.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah012_verse_025.mp3', NULL, 1761760676, 1761760676),
(11675, 'Nehemiah 12:26', 'Nehemiah', 12, 26, '&nbsp;دا خلق د يوصدق نمسى او د يشوَع زوئ يويقيم په وخت کښې هلته اوسېدل او د نحمياه حکمران په وخت کښې او د عزرا په وخت کښې چې اِمام او د شريعت عالِم وو.', NULL, '&nbsp;دا خلق د يوصدق نمسى او د يشوَع زوئ يويقيم په وخت کښې هلته اوسېدل او د نحمياه حکمران په وخت کښې او د عزرا په وخت کښې چې اِمام او د شريعت عالِم وو.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah012_verse_026.mp3', NULL, 1761760676, 1761760676),
(11676, 'Nehemiah 12:27', 'Nehemiah', 12, 27, '&nbsp;کله چې د يروشلم د ښار دېوال وقف کېدلو، نو ليويان د هغه ټولو ځايونو نه راوستلے شول چرته چې هغوئ اوسېدل، هغوئ د دې دپاره راوستلے شول چې د وقف کېدو په جشن کښې د شُکر ګزارۍ د سندرو سره او د چمټو او بينجو د موسيقۍ سره شريک شى.', NULL, '&nbsp;کله چې د يروشلم د ښار دېوال وقف کېدلو، نو ليويان د هغه ټولو ځايونو نه راوستلے شول چرته چې هغوئ اوسېدل، هغوئ د دې دپاره راوستلے شول چې د وقف کېدو په جشن کښې د شُکر ګزارۍ د سندرو سره او د چمټو او بينجو د موسيقۍ سره شريک شى.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah012_verse_027.mp3', NULL, 1761760676, 1761760676),
(11677, 'Nehemiah 12:28', 'Nehemiah', 12, 28, '&nbsp;د ليويانو کورَنو سندرغاړى د هغه علاقې نه راغونډ شول چرته چې هغوئ اوسېدل. هغوئ د يروشلم ګېرچاپېره علاقې نه او د نطوفه نه ګېرچاپېره د وړو ښارونو نه،', NULL, '&nbsp;د ليويانو کورَنو سندرغاړى د هغه علاقې نه راغونډ شول چرته چې هغوئ اوسېدل. هغوئ د يروشلم ګېرچاپېره علاقې نه او د نطوفه نه ګېرچاپېره د وړو ښارونو نه،', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah012_verse_028.mp3', NULL, 1761760676, 1761760676),
(11678, 'Nehemiah 12:29', 'Nehemiah', 12, 29, '&nbsp;او د بيت‌جِلجال، جبعه او عزماوت نه راغلل.', NULL, '&nbsp;او د بيت‌جِلجال، جبعه او عزماوت نه راغلل.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah012_verse_029.mp3', NULL, 1761760676, 1761760676),
(11679, 'Nehemiah 12:30', 'Nehemiah', 12, 30, '&nbsp;اِمامانو او ليويانو د خپلو ځانونو، خلقو، د دروازو او د ښار د دېوال دپاره د پاکوالى رسم ادا کړو.', NULL, '&nbsp;اِمامانو او ليويانو د خپلو ځانونو، خلقو، د دروازو او د ښار د دېوال دپاره د پاکوالى رسم ادا کړو.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah012_verse_030.mp3', NULL, 1761760676, 1761760676),
(11680, 'Nehemiah 12:31', 'Nehemiah', 12, 31, '&nbsp;ما د دېوال دپاسه د يهوداه مشران راغونډ کړل او هغوئ مې د دوو لويو ډلو مشران مقرر کړل چې د ښار نه ګېرچاپېره روان شى او د خُدائ پاک شُکر ادا کوى. اوله ډله د دېوال دپاسه ښى طرف ته د ډېران دروازې طرف ته لاړه.', NULL, '&nbsp;ما د دېوال دپاسه د يهوداه مشران راغونډ کړل او هغوئ مې د دوو لويو ډلو مشران مقرر کړل چې د ښار نه ګېرچاپېره روان شى او د خُدائ پاک شُکر ادا کوى. اوله ډله د دېوال دپاسه ښى طرف ته د ډېران دروازې طرف ته لاړه.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah012_verse_031.mp3', NULL, 1761760676, 1761760676),
(11681, 'Nehemiah 12:32', 'Nehemiah', 12, 32, '&nbsp;هوسعياه د سندرغاړو نه وروستو روان شو، چې د يهوداه نيم مشران ورپسې وُو.', NULL, '&nbsp;هوسعياه د سندرغاړو نه وروستو روان شو، چې د يهوداه نيم مشران ورپسې وُو.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761760676, 1761760676),
(11682, 'Nehemiah 12:36', 'Nehemiah', 12, 36, '&nbsp;په هغۀ پسې د هغۀ د قبيلې نور کسان وُو: سمعياه، عزراېل، مِللى، جِللى، ماعى، نتنى‌ايل، يهوداه او حنانى. هغوئ ټولو د موسيقۍ هغه شان څيزونه روان کړى وُو کوم چې د خُدائ پاک خِدمت کوونکى داؤد بادشاه غږول. عزرا عالِم د دې جلوس نه وړاندې روان وو.', NULL, '&nbsp;په هغۀ پسې د هغۀ د قبيلې نور کسان وُو: سمعياه، عزراېل، مِللى، جِللى، ماعى، نتنى‌ايل، يهوداه او حنانى. هغوئ ټولو د موسيقۍ هغه شان څيزونه روان کړى وُو کوم چې د خُدائ پاک خِدمت کوونکى داؤد بادشاه غږول. عزرا عالِم د دې جلوس نه وړاندې روان وو.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761760676, 1761760676),
(11683, 'Nehemiah 12:37', 'Nehemiah', 12, 37, '&nbsp;د فوارې د دروازې سره هغوئ په هغه پوړو باندې وختل کومې چې د داؤد ښار ته تلې وې، د داؤد د محل نه تېر شول او د ښار نمرخاتۀ طرف ته د اوبو دروازې سره دېوال ته واپس شول.', NULL, '&nbsp;د فوارې د دروازې سره هغوئ په هغه پوړو باندې وختل کومې چې د داؤد ښار ته تلې وې، د داؤد د محل نه تېر شول او د ښار نمرخاتۀ طرف ته د اوبو دروازې سره دېوال ته واپس شول.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761760676, 1761760676),
(11684, 'Nehemiah 12:38', 'Nehemiah', 12, 38, '&nbsp;د هغه کسانو بله ډله کومو چې شکريه ادا کوله د دېوال د سر سره ګس طرف ته لاړل او نيم خلق ما سره ورپسې روان وُو. مونږ د تنور د مينارې نه تېر شُو او پلن دېوال ته لاړُو،', NULL, '&nbsp;د هغه کسانو بله ډله کومو چې شکريه ادا کوله د دېوال د سر سره ګس طرف ته لاړل او نيم خلق ما سره ورپسې روان وُو. مونږ د تنور د مينارې نه تېر شُو او پلن دېوال ته لاړُو،', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761760676, 1761760676),
(11685, 'Nehemiah 12:39', 'Nehemiah', 12, 39, '&nbsp;او د هغه ځائ نه مونږ د اِفرائيم دروازې نه، يسانه دروازې نه، د کبانو دروازې نه، د حنن‌ايل مينارې او د سلو مينارې نه روان وُو او د ګډو دروازې ته لاړُو. او مونږ خپل تګ د خُدائ پاک د کور دروازې سره نزدې بس کړو.', NULL, '&nbsp;او د هغه ځائ نه مونږ د اِفرائيم دروازې نه، يسانه دروازې نه، د کبانو دروازې نه، د حنن‌ايل مينارې او د سلو مينارې نه روان وُو او د ګډو دروازې ته لاړُو. او مونږ خپل تګ د خُدائ پاک د کور دروازې سره نزدې بس کړو.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761760676, 1761760676),
(11686, 'Nehemiah 12:40', 'Nehemiah', 12, 40, '&nbsp;هغه دواړه ډلو کومو چې د خُدائ پاک شُکر ادا کولو هغه د خُدائ پاک د کور علاقې ته ورسېدلې. زۀ هم د مشرانو نيمې قبيلې سره وم،', NULL, '&nbsp;هغه دواړه ډلو کومو چې د خُدائ پاک شُکر ادا کولو هغه د خُدائ پاک د کور علاقې ته ورسېدلې. زۀ هم د مشرانو نيمې قبيلې سره وم،', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761760676, 1761760676),
(11687, 'Nehemiah 12:41', 'Nehemiah', 12, 41, '&nbsp;زما په ډله کښې دا اِمامان شامل وُو، چې هغوئ بيګلې غږولې: اِلياقيم، معسياه، مينامين، ميکاياه، اليوعينى، زکرياه او حننياه.', NULL, '&nbsp;زما په ډله کښې دا اِمامان شامل وُو، چې هغوئ بيګلې غږولې: اِلياقيم، معسياه، مينامين، ميکاياه، اليوعينى، زکرياه او حننياه.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761760676, 1761760676),
(11688, 'Nehemiah 12:42', 'Nehemiah', 12, 42, '&nbsp;او په هغوئ پسې معسياه، سمعياه، اِلى‌عزر، عُزى، يهوحنان، مُلکياه، عيلام او ايصر روان وُو. د دې حمد ويوونکو مشرى ازرخياه کوله او په اوچت آواز يې سندرې وئيلې.', NULL, '&nbsp;او په هغوئ پسې معسياه، سمعياه، اِلى‌عزر، عُزى، يهوحنان، مُلکياه، عيلام او ايصر روان وُو. د دې حمد ويوونکو مشرى ازرخياه کوله او په اوچت آواز يې سندرې وئيلې.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761760676, 1761760676),
(11689, 'Nehemiah 12:43', 'Nehemiah', 12, 43, '&nbsp;په هغه ورځ باندې ډېرې نذرانې پېش کړے شوې او د خلقو زړونه د خوشحالۍ نه ډک وُو ځکه چې خُدائ پاک هغوئ ډېر خوشحاله کړى وُو. ښځې او ماشومان په دې جشن کښې شريک وُو او چې هغوئ کوم شور جوړ کړے وو نو هغه تر لرې لرې پورې اورېدے شو.', NULL, '&nbsp;په هغه ورځ باندې ډېرې نذرانې پېش کړے شوې او د خلقو زړونه د خوشحالۍ نه ډک وُو ځکه چې خُدائ پاک هغوئ ډېر خوشحاله کړى وُو. ښځې او ماشومان په دې جشن کښې شريک وُو او چې هغوئ کوم شور جوړ کړے وو نو هغه تر لرې لرې پورې اورېدے شو.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761760676, 1761760676),
(11690, 'Nehemiah 12:44', 'Nehemiah', 12, 44, '&nbsp;په هغه وخت کښې څۀ سړى د هغه ګودامونو مشران مقرر شوى وُو، چرته چې د خُدائ پاک د کور دپاره څيزونه کېښودلے شول، په دې کښې نذرانه، وړومبے پېدا شوې غله او لسمه حِصه. دا سړى د مختلفو ښارونو سره نزدې پټو نه د برخو راغونډولو ذمه وار وُو. دا برخې د قانون په مطابق د اِمامانو او ليويانو دپاره وې. د يهوداه ټول خلق د اِمامانو او ليويانو نه خوشحاله وُو.', NULL, '&nbsp;په هغه وخت کښې څۀ سړى د هغه ګودامونو مشران مقرر شوى وُو، چرته چې د خُدائ پاک د کور دپاره څيزونه کېښودلے شول، په دې کښې نذرانه، وړومبے پېدا شوې غله او لسمه حِصه. دا سړى د مختلفو ښارونو سره نزدې پټو نه د برخو راغونډولو ذمه وار وُو. دا برخې د قانون په مطابق د اِمامانو او ليويانو دپاره وې. د يهوداه ټول خلق د اِمامانو او ليويانو نه خوشحاله وُو.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761760676, 1761760676),
(11691, 'Nehemiah 12:45', 'Nehemiah', 12, 45, '&nbsp;هغوئ د پاکوالى رسمونه او هغه نور رسمونه ادا کول د کومو چې خُدائ پاک حُکم ورکړے وو. د خُدائ پاک د کور موسيقارانو او څوکيدارانو هم خپله ذمه وارى د هغه اصُولو په مطابق سر ته رسوله کوم چې داؤد بادشاه او د هغۀ زوئ سليمان جوړ کړى وُو.', NULL, '&nbsp;هغوئ د پاکوالى رسمونه او هغه نور رسمونه ادا کول د کومو چې خُدائ پاک حُکم ورکړے وو. د خُدائ پاک د کور موسيقارانو او څوکيدارانو هم خپله ذمه وارى د هغه اصُولو په مطابق سر ته رسوله کوم چې داؤد بادشاه او د هغۀ زوئ سليمان جوړ کړى وُو.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761760676, 1761760676),
(11692, 'Nehemiah 12:46', 'Nehemiah', 12, 46, '&nbsp;ډېر وخت مخکښې د داؤد بادشاه او آسف موسيقار د وخت، موسيقارانو د خُدائ پاک د ثناء صِفت کولو او د شُکر ګزارۍ مشرى کړې وه.', NULL, '&nbsp;ډېر وخت مخکښې د داؤد بادشاه او آسف موسيقار د وخت، موسيقارانو د خُدائ پاک د ثناء صِفت کولو او د شُکر ګزارۍ مشرى کړې وه.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761760676, 1761760676),
(11693, 'Nehemiah 12:47', 'Nehemiah', 12, 47, '&nbsp;د زرُبابل او نحمياه په زمانه کښې به ټولو بنى اِسرائيلو هره ورځ د خُدائ د کور د سندرغاړو او څوکيدارانو ضرورتونه پوره کول. ليويانو ته به هغه برخه ورکولے کېدله کومه چې هغوئ دپاره مقرر وه او ليويانو به د هغې نه اِمامانو له هغه برخه ورکوله کومه چې د هغوئ دپاره مقرر وه.', NULL, '&nbsp;د زرُبابل او نحمياه په زمانه کښې به ټولو بنى اِسرائيلو هره ورځ د خُدائ د کور د سندرغاړو او څوکيدارانو ضرورتونه پوره کول. ليويانو ته به هغه برخه ورکولے کېدله کومه چې هغوئ دپاره مقرر وه او ليويانو به د هغې نه اِمامانو له هغه برخه ورکوله کومه چې د هغوئ دپاره مقرر وه.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761760676, 1761760676),
(11694, 'Nehemiah 13:1', 'Nehemiah', 13, 1, '&nbsp;کله چې د موسىٰ شريعت خلقو ته په اوچت آواز لوستلے شو، نو هغوئ دې آياتونو ته راغلل چې وائ، يو عمونى او موآبى ته به هم دا اجازت نۀ وى چې د خُدائ پاک په ډله کښې داخل شى.', NULL, '&nbsp;کله چې د موسىٰ شريعت خلقو ته په اوچت آواز لوستلے شو، نو هغوئ دې آياتونو ته راغلل چې وائ، يو عمونى او موآبى ته به هم دا اجازت نۀ وى چې د خُدائ پاک په ډله کښې داخل شى.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah013_verse_001.mp3', NULL, 1761760676, 1761760676),
(11695, 'Nehemiah 13:2', 'Nehemiah', 13, 2, '&nbsp;دا د هغې په وجه کله چې بنى اِسرائيل د مِصر نه بهر په لار روان وُو نو عمونيانو او موآبيانو هغوئ له اوبۀ او روټۍ نۀ وه ورکړې. او د دې په ځائ بلعام له يې پېسې ورکړې چې په بنى اِسرائيلو باندې لعنت ووائى، خو زمونږ خُدائ پاک هغه لعنت په برکت بدل کړو.', NULL, '&nbsp;دا د هغې په وجه کله چې بنى اِسرائيل د مِصر نه بهر په لار روان وُو نو عمونيانو او موآبيانو هغوئ له اوبۀ او روټۍ نۀ وه ورکړې. او د دې په ځائ بلعام له يې پېسې ورکړې چې په بنى اِسرائيلو باندې لعنت ووائى، خو زمونږ خُدائ پاک هغه لعنت په برکت بدل کړو.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah013_verse_002.mp3', NULL, 1761760676, 1761760676),
(11696, 'Nehemiah 13:3', 'Nehemiah', 13, 3, '&nbsp;کله چې بنى اِسرائيلو دا حُکم واورېدو نو هغوئ د قوم نه د پردى مُلک ټول خلق وويستل.', NULL, '&nbsp;کله چې بنى اِسرائيلو دا حُکم واورېدو نو هغوئ د قوم نه د پردى مُلک ټول خلق وويستل.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah013_verse_003.mp3', NULL, 1761760676, 1761760676),
(11697, 'Nehemiah 13:4', 'Nehemiah', 13, 4, '&nbsp;اِلياسب اِمام کوم چې د خُدائ پاک د ګودامونو مشر وو، هغه د ډېرې مودې نه د طوبياه ملګرے وو.', NULL, '&nbsp;اِلياسب اِمام کوم چې د خُدائ پاک د ګودامونو مشر وو، هغه د ډېرې مودې نه د طوبياه ملګرے وو.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah013_verse_004.mp3', NULL, 1761760676, 1761760676),
(11698, 'Nehemiah 13:5', 'Nehemiah', 13, 5, '&nbsp;هغۀ طوبياه له دا اجازت ورکړو چې يوه لويه کوټه استعمالوى چې به مخکښې په کښې د غلې نذرانو او خوشبويۍ نذرانو د جمع کولو او د خُدائ پاک په کور کښې د استعمالېدونکى سامان دپاره، د اِمامانو د نذرانو دپاره، د غلې د لسمې حصې، د ميو او د زيتُونو هغه تېلو دپاره مخصوصه وه کومه به چې ليويانو، د خُدائ پاک د کور موسيقارانو او د خُدائ پاک د کور څوکيدارانو دپاره وه.', NULL, '&nbsp;هغۀ طوبياه له دا اجازت ورکړو چې يوه لويه کوټه استعمالوى چې به مخکښې په کښې د غلې نذرانو او خوشبويۍ نذرانو د جمع کولو او د خُدائ پاک په کور کښې د استعمالېدونکى سامان دپاره، د اِمامانو د نذرانو دپاره، د غلې د لسمې حصې، د ميو او د زيتُونو هغه تېلو دپاره مخصوصه وه کومه به چې ليويانو، د خُدائ پاک د کور موسيقارانو او د خُدائ پاک د کور څوکيدارانو دپاره وه.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah013_verse_005.mp3', NULL, 1761760676, 1761760676),
(11699, 'Nehemiah 13:6', 'Nehemiah', 13, 6, '&nbsp;کله چې داسې کېدل، نو زۀ په يروشلم کښې نۀ وم، ځکه چې د بابل بادشاه ارتخششتا د بادشاهۍ په دوه دېرشم کال زۀ هغۀ له واپس ورغلے وم چې خبر ورورسوم. څۀ وخت وروستو ما ته د هغۀ نه اجازت مِلاو شو چې واپس يروشلم ته تلے شى.', NULL, '&nbsp;کله چې داسې کېدل، نو زۀ په يروشلم کښې نۀ وم، ځکه چې د بابل بادشاه ارتخششتا د بادشاهۍ په دوه دېرشم کال زۀ هغۀ له واپس ورغلے وم چې خبر ورورسوم. څۀ وخت وروستو ما ته د هغۀ نه اجازت مِلاو شو چې واپس يروشلم ته تلے شى.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah013_verse_006.mp3', NULL, 1761760676, 1761760676),
