(11702, 'Nehemiah 13:9', 'Nehemiah', 13, 9, '&nbsp;ما حُکم ورکړو چې د کوټو د پاکوالى رسم دې ادا کړے شى او د خُدائ پاک د کور د سامان، د غلې نذرانې او خوشبوئى دې بيا واپس په خپل ځائ باندې کېښودلے شى.', NULL, '&nbsp;ما حُکم ورکړو چې د کوټو د پاکوالى رسم دې ادا کړے شى او د خُدائ پاک د کور د سامان، د غلې نذرانې او خوشبوئى دې بيا واپس په خپل ځائ باندې کېښودلے شى.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah013_verse_009.mp3', NULL, 1761760676, 1761760676),
(11703, 'Nehemiah 13:10', 'Nehemiah', 13, 10, '&nbsp;ما ته دا پته هم ولګېده چې د خُدائ پاک د کور موسيقاران او نور ليويان د يروشلم نه تلى دى او خپلو پټو ته واپس شوى دى، دا ځکه چې خلقو هغوئ له دومره خوراک ورکولے نۀ شو چې ګزاره ورباندې کېدله.', NULL, '&nbsp;ما ته دا پته هم ولګېده چې د خُدائ پاک د کور موسيقاران او نور ليويان د يروشلم نه تلى دى او خپلو پټو ته واپس شوى دى، دا ځکه چې خلقو هغوئ له دومره خوراک ورکولے نۀ شو چې ګزاره ورباندې کېدله.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah013_verse_010.mp3', NULL, 1761760676, 1761760676),
(11704, 'Nehemiah 13:11', 'Nehemiah', 13, 11, '&nbsp;ما آفسران ورټل او ورته مې ووئيل چې د خُدائ پاک د کور خيال ولې نۀ دے ساتلے شوے. او ما ليويان او موسيقاران واپس د خُدائ پاک کور ته راوستل او بيا مې په کار لګيا کړل.', NULL, '&nbsp;ما آفسران ورټل او ورته مې ووئيل چې د خُدائ پاک د کور خيال ولې نۀ دے ساتلے شوے. او ما ليويان او موسيقاران واپس د خُدائ پاک کور ته راوستل او بيا مې په کار لګيا کړل.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah013_verse_011.mp3', NULL, 1761760676, 1761760676),
(11705, 'Nehemiah 13:12', 'Nehemiah', 13, 12, '&nbsp;بيا ټول بنى اِسرائيليان يو ځل بيا شروع شول چې د خُدائ پاک د کور ګودامونو ته خپل د غلې لسمه حِصه، مے او د زيتُونو تېل راوړى.', NULL, '&nbsp;بيا ټول بنى اِسرائيليان يو ځل بيا شروع شول چې د خُدائ پاک د کور ګودامونو ته خپل د غلې لسمه حِصه، مے او د زيتُونو تېل راوړى.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah013_verse_012.mp3', NULL, 1761760676, 1761760676),
(11706, 'Nehemiah 13:13', 'Nehemiah', 13, 13, '&nbsp;ما دا سړى د ګودامونو مشران مقرر کړل: شلمياه، چې يو اِمام وو، صدوق، چې د شريعت يو عالِم وو، او فداياه ليوے. د متنياه نمسے او د زکور زوئ حنان د هغوئ مددګار وو. دا اعتبارى کسان وُو، او د هغوئ دا ذمه وارى وه چې په ليويانو باندې د سامان په تقسيمولو کښې د ايماندارۍ نه کار واخلى.', NULL, '&nbsp;ما دا سړى د ګودامونو مشران مقرر کړل: شلمياه، چې يو اِمام وو، صدوق، چې د شريعت يو عالِم وو، او فداياه ليوے. د متنياه نمسے او د زکور زوئ حنان د هغوئ مددګار وو. دا اعتبارى کسان وُو، او د هغوئ دا ذمه وارى وه چې په ليويانو باندې د سامان په تقسيمولو کښې د ايماندارۍ نه کار واخلى.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah013_verse_013.mp3', NULL, 1761760676, 1761760676),
(11707, 'Nehemiah 13:14', 'Nehemiah', 13, 14, '&nbsp;زما خُدايه پاکه، ياد ساته دا هر څۀ چې ما ستا د کور او د دې د عبادت دپاره کړى دى او دا مۀ هېروه.', NULL, '&nbsp;زما خُدايه پاکه، ياد ساته دا هر څۀ چې ما ستا د کور او د دې د عبادت دپاره کړى دى او دا مۀ هېروه.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah013_verse_014.mp3', NULL, 1761760676, 1761760676),
(11708, 'Nehemiah 13:15', 'Nehemiah', 13, 15, '&nbsp;په هغه وخت کښې ما وليدل چې په يهوداه کښې خلقو د سبت په ورځ د انګورو لنګرۍ استعمالوله. او نورو په خپلو خرونو باندې غله، مے، انګور، اينځر او نور څيزونه بار کول او يروشلم ته يې وړل، ما هغوئ له خبردارے ورکړو چې د سبت په ورځ دې هيڅ نۀ خرڅوى.', NULL, '&nbsp;په هغه وخت کښې ما وليدل چې په يهوداه کښې خلقو د سبت په ورځ د انګورو لنګرۍ استعمالوله. او نورو په خپلو خرونو باندې غله، مے، انګور، اينځر او نور څيزونه بار کول او يروشلم ته يې وړل، ما هغوئ له خبردارے ورکړو چې د سبت په ورځ دې هيڅ نۀ خرڅوى.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah013_verse_015.mp3', NULL, 1761760676, 1761760676),
(11709, 'Nehemiah 13:16', 'Nehemiah', 13, 16, '&nbsp;د صور ښار څۀ خلق په يروشلم کښې اوسېدل او هغوئ کبان او د هر قِسم سامان ښار ته د دې دپاره راوړو چې د سبت په ورځ يې زمونږ په خلقو باندې خرڅ کړى.', NULL, '&nbsp;د صور ښار څۀ خلق په يروشلم کښې اوسېدل او هغوئ کبان او د هر قِسم سامان ښار ته د دې دپاره راوړو چې د سبت په ورځ يې زمونږ په خلقو باندې خرڅ کړى.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah013_verse_016.mp3', NULL, 1761760676, 1761760676),
(11710, 'Nehemiah 13:17', 'Nehemiah', 13, 17, '&nbsp;ما د يهوداه مشران ورټل او ورته مې ووئيل، ”تاسو خپل دې بد عمل ته وګورئ. تاسو د سبت د ورځې سپکاوے کوئ.', NULL, '&nbsp;ما د يهوداه مشران ورټل او ورته مې ووئيل، ”تاسو خپل دې بد عمل ته وګورئ. تاسو د سبت د ورځې سپکاوے کوئ.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah013_verse_017.mp3', NULL, 1761760676, 1761760676),
(11711, 'Nehemiah 13:18', 'Nehemiah', 13, 18, '&nbsp;دا بلکل هم هغه کار دے چې خُدائ پاک پرې ستاسو پلار نيکۀ له سزا ورکړه چې کله هغۀ په ښار باندې تباهى راوسته. او تاسو نور زور هم کوئ چې د بنى اِسرائيلو په مُلک باندې د خُدائ پاک نور قهر هم نازل شى ځکه چې د سبت د ورځې سپکاوے کيږى.“', NULL, '&nbsp;دا بلکل هم هغه کار دے چې خُدائ پاک پرې ستاسو پلار نيکۀ له سزا ورکړه چې کله هغۀ په ښار باندې تباهى راوسته. او تاسو نور زور هم کوئ چې د بنى اِسرائيلو په مُلک باندې د خُدائ پاک نور قهر هم نازل شى ځکه چې د سبت د ورځې سپکاوے کيږى.“', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah013_verse_018.mp3', NULL, 1761760676, 1761760676),
(11712, 'Nehemiah 13:19', 'Nehemiah', 13, 19, '&nbsp;نو ما حُکم ورکړو چې د هر سبت د شروع کېدو نه وړاندې د ښار دروازې په ماښامى کښې بندولے شى او د سبت د ورځې د ختمېدو نه وړاندې دې نۀ شى کولاولے. ما خپل يو څو سړى په دروازو باندې د دې دپاره ودرول چې دا خبره يقينى شى چې د سبت په ورځ به ښار ته هيڅ هم نۀ شى راوړلے.', NULL, '&nbsp;نو ما حُکم ورکړو چې د هر سبت د شروع کېدو نه وړاندې د ښار دروازې په ماښامى کښې بندولے شى او د سبت د ورځې د ختمېدو نه وړاندې دې نۀ شى کولاولے. ما خپل يو څو سړى په دروازو باندې د دې دپاره ودرول چې دا خبره يقينى شى چې د سبت په ورځ به ښار ته هيڅ هم نۀ شى راوړلے.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah013_verse_019.mp3', NULL, 1761760676, 1761760676),
(11713, 'Nehemiah 13:20', 'Nehemiah', 13, 20, '&nbsp;يو يا دوه ځل سامان خرڅوونکو او سوداګرو د خالى شپه د ښار د دېوالونو نه بهر تېره کړه.', NULL, '&nbsp;يو يا دوه ځل سامان خرڅوونکو او سوداګرو د خالى شپه د ښار د دېوالونو نه بهر تېره کړه.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah013_verse_020.mp3', NULL, 1761760676, 1761760676),
(11714, 'Nehemiah 13:21', 'Nehemiah', 13, 21, '&nbsp;ما هغوئ له خبردارے ورکړو، ”تاسو د دې دېوال سره شپه ولې تېروئ کۀ تاسو بيا داسې وکړل، نو زۀ به تاسو خراب‌تُراب کړم.“ نو د دې نه پس هغوئ د سبت په ورځ بيا رانۀ غلل.', NULL, '&nbsp;ما هغوئ له خبردارے ورکړو، ”تاسو د دې دېوال سره شپه ولې تېروئ کۀ تاسو بيا داسې وکړل، نو زۀ به تاسو خراب‌تُراب کړم.“ نو د دې نه پس هغوئ د سبت په ورځ بيا رانۀ غلل.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah013_verse_021.mp3', NULL, 1761760676, 1761760676),
(11715, 'Nehemiah 13:22', 'Nehemiah', 13, 22, '&nbsp;ما ليويانو له حُکم ورکړو چې خپل ځانونه پاک کړئ او لاړ شئ او د دروازو څوکيدارى وکړئ چې د سبت ورځ مقدسه پاتې شى. خُدايه پاکه، ما د دې دپاره هم ياد ساته او د خپلې لوئې مينې په وجه مې بچ کړه.', NULL, '&nbsp;ما ليويانو له حُکم ورکړو چې خپل ځانونه پاک کړئ او لاړ شئ او د دروازو څوکيدارى وکړئ چې د سبت ورځ مقدسه پاتې شى. خُدايه پاکه، ما د دې دپاره هم ياد ساته او د خپلې لوئې مينې په وجه مې بچ کړه.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah013_verse_022.mp3', NULL, 1761760676, 1761760676),
(11716, 'Nehemiah 13:23', 'Nehemiah', 13, 23, '&nbsp;په هغه وخت کښې ما ته دا پته هم ولګېده چې څۀ يهودى سړو د اشدود، عمون او د موآب د ښځو سره ودونه کړى دى.', NULL, '&nbsp;په هغه وخت کښې ما ته دا پته هم ولګېده چې څۀ يهودى سړو د اشدود، عمون او د موآب د ښځو سره ودونه کړى دى.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah013_verse_023.mp3', NULL, 1761760676, 1761760676),
(11717, 'Nehemiah 13:24', 'Nehemiah', 13, 24, '&nbsp;د هغوئ نيم اولاد د اشدود ژبه او يا څۀ بله ژبه وئيله او هغوئ زمونږ ژبه نۀ شوه وئيلے.', NULL, '&nbsp;د هغوئ نيم اولاد د اشدود ژبه او يا څۀ بله ژبه وئيله او هغوئ زمونږ ژبه نۀ شوه وئيلے.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah013_verse_024.mp3', NULL, 1761760676, 1761760676),
(11718, 'Nehemiah 13:25', 'Nehemiah', 13, 25, '&nbsp;ما هغه سړو له خبردارے ورکړو، په هغوئ مې لعنت ووئيلو، ومې وهل او وېښتۀ مې ترې نه وويستل. بيا مې ترې نه د خُدائ پاک په نوم باندې دا قسم واخستو چې هغوئ او د هغوئ بچى به هيڅکله د پردى مُلک د خلقو سره ودونه نۀ کوى.', NULL, '&nbsp;ما هغه سړو له خبردارے ورکړو، په هغوئ مې لعنت ووئيلو، ومې وهل او وېښتۀ مې ترې نه وويستل. بيا مې ترې نه د خُدائ پاک په نوم باندې دا قسم واخستو چې هغوئ او د هغوئ بچى به هيڅکله د پردى مُلک د خلقو سره ودونه نۀ کوى.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah013_verse_025.mp3', NULL, 1761760676, 1761760676),
(11719, 'Nehemiah 13:26', 'Nehemiah', 13, 26, '&nbsp;ما ورته ووئيل، ”سليمان د پردى مُلک د ښځو په وجه ګناه وکړه. هغه داسې سړے وو چې هغه د نورو قومونو د هر يو بادشاه نه لوئ وو. خُدائ پاک د هغۀ سره مينه کوله او هغه يې د بنى اِسرائيلو په ټول مُلک باندې بادشاه جوړ کړے وو، خو بيا هم هغه د پردى مُلک ښځو په ګناه باندې اخته کړو.', NULL, '&nbsp;ما ورته ووئيل، ”سليمان د پردى مُلک د ښځو په وجه ګناه وکړه. هغه داسې سړے وو چې هغه د نورو قومونو د هر يو بادشاه نه لوئ وو. خُدائ پاک د هغۀ سره مينه کوله او هغه يې د بنى اِسرائيلو په ټول مُلک باندې بادشاه جوړ کړے وو، خو بيا هم هغه د پردى مُلک ښځو په ګناه باندې اخته کړو.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah013_verse_026.mp3', NULL, 1761760676, 1761760676),
(11720, 'Nehemiah 13:27', 'Nehemiah', 13, 27, '&nbsp;نو مونږ به بيا د ګناهِ کبيره داسې عمل څنګه وکړُو چې د خُدائ پاک سره بې‌وفائى وکړُو او د پردى مُلک ښځو سره ودونه وکړُو؟“', NULL, '&nbsp;نو مونږ به بيا د ګناهِ کبيره داسې عمل څنګه وکړُو چې د خُدائ پاک سره بې‌وفائى وکړُو او د پردى مُلک ښځو سره ودونه وکړُو؟“', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah013_verse_027.mp3', NULL, 1761760676, 1761760676),
(11721, 'Nehemiah 13:28', 'Nehemiah', 13, 28, '&nbsp;يويدع د مشر اِمام اِلياسب زوئ وو، خو د يويدع يو زوئ د بيت‌حورون د ښار د سنبلط د لور سره وادۀ وکړو، نو ما يويدع دې ته مجبور کړو چې يروشلم پرېږدى.', NULL, '&nbsp;يويدع د مشر اِمام اِلياسب زوئ وو، خو د يويدع يو زوئ د بيت‌حورون د ښار د سنبلط د لور سره وادۀ وکړو، نو ما يويدع دې ته مجبور کړو چې يروشلم پرېږدى.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah013_verse_028.mp3', NULL, 1761760676, 1761760676),
(11722, 'Nehemiah 13:29', 'Nehemiah', 13, 29, '&nbsp;خُدايه پاکه، هغه راپه ياد کړه چې دې خلقو د اِمامت او د هغه لوظ سپکاوے څنګه وکړو چې کوم لوظ تا د اِمامانو او ليويانو سره کړے وو.', NULL, '&nbsp;خُدايه پاکه، هغه راپه ياد کړه چې دې خلقو د اِمامت او د هغه لوظ سپکاوے څنګه وکړو چې کوم لوظ تا د اِمامانو او ليويانو سره کړے وو.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah013_verse_029.mp3', NULL, 1761760676, 1761760676),
(11723, 'Nehemiah 13:30', 'Nehemiah', 13, 30, '&nbsp;نو ما خلق د پردى مُلک د هر يو څيز نه صفا کړل، ما د اِمامانو او ليويانو دپاره اصُول ځکه جوړ کړل چې هر يو کس خپله خپله ذمه وارى وپېژنى،', NULL, '&nbsp;نو ما خلق د پردى مُلک د هر يو څيز نه صفا کړل، ما د اِمامانو او ليويانو دپاره اصُول ځکه جوړ کړل چې هر يو کس خپله خپله ذمه وارى وپېژنى،', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah013_verse_030.mp3', NULL, 1761760676, 1761760676),
(11724, 'Nehemiah 13:31', 'Nehemiah', 13, 31, '&nbsp;ما د لرګو بندوبست وکړو چې هغه به د هغه نذرانو په سوزولو کښې استعمالېدل چې کومې نذرانې به په صحيح وخت راوړلے شوې، دا کار مې هم وکړو چې خلق د خپلې وړومبۍ غلې او خپلې وړومبۍ پخې شوې مېوې راوړى. خُدايه پاکه، دا هر څۀ مۀ هېروه او را ياد کړه.', NULL, '&nbsp;ما د لرګو بندوبست وکړو چې هغه به د هغه نذرانو په سوزولو کښې استعمالېدل چې کومې نذرانې به په صحيح وخت راوړلے شوې، دا کار مې هم وکړو چې خلق د خپلې وړومبۍ غلې او خپلې وړومبۍ پخې شوې مېوې راوړى. خُدايه پاکه، دا هر څۀ مۀ هېروه او را ياد کړه.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_nehemiah013_verse_031.mp3', NULL, 1761760676, 1761760676),
(11725, 'Esther 1:3', 'Esther', 1, 3, '&nbsp;د هغۀ د بادشاهۍ په درېم کال هغۀ خپلو ټولو آفسرانو او وزيرانو له يوه لويه مېلمستيا وکړه. د فارس او د مادى فوجى آفسران هم موجود وُو او داسې د صُوبو حکمرانان او عزتمند سړى هم موجود وُو.', NULL, '&nbsp;د هغۀ د بادشاهۍ په درېم کال هغۀ خپلو ټولو آفسرانو او وزيرانو له يوه لويه مېلمستيا وکړه. د فارس او د مادى فوجى آفسران هم موجود وُو او داسې د صُوبو حکمرانان او عزتمند سړى هم موجود وُو.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_esther001_verse_003.mp3', NULL, 1761760676, 1761760676),
(11726, 'Esther 1:4', 'Esther', 1, 4, '&nbsp;په پوره شپږو مياشتو کښې هغۀ د شان او شوکت او عظمت سره د شاهى دربار د ټول دولت نمائش وکړو.', NULL, '&nbsp;په پوره شپږو مياشتو کښې هغۀ د شان او شوکت او عظمت سره د شاهى دربار د ټول دولت نمائش وکړو.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_esther001_verse_004.mp3', NULL, 1761760676, 1761760676),
(11727, 'Esther 1:5', 'Esther', 1, 5, '&nbsp;د هغې نه پس، بادشاه ټولو خلقو ته د سوسه په مرکزى ښار کښې يوه لويه مېلمستيا وکړه، چې مالداره او غريبانان په کښې يو شان شامل وُو. دا مېلمستيا پوره يوه هفته جارى وه او دا د شاهى محل په باغونو کښې شوې وه.', NULL, '&nbsp;د هغې نه پس، بادشاه ټولو خلقو ته د سوسه په مرکزى ښار کښې يوه لويه مېلمستيا وکړه، چې مالداره او غريبانان په کښې يو شان شامل وُو. دا مېلمستيا پوره يوه هفته جارى وه او دا د شاهى محل په باغونو کښې شوې وه.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_esther001_verse_005.mp3', NULL, 1761760676, 1761760676),
(11728, 'Esther 1:6', 'Esther', 1, 6, '&nbsp;دربار د آسمانى رنګ او د سپين رنګ د مالوچو جوړو شوو پړدو باندې ښائسته کړے شوے وو، د سنګِ مرمرو په ستنو باندې د سپينو زرو د کَړو سره د کاسنى رنګ د ښې لټې د مزو سره تړلے شوې وې. د سرو زرو او سپينو زرو کټُونه په دربار کښې اېښودے شوى وُو، د دربار فرش د سپين سنګِ مرمر، سور قيمتى کاڼى، د ځلېدونکې ملغلرو او د آسمانى رنګ د فيروزو نه جوړ شوے وو.', NULL, '&nbsp;دربار د آسمانى رنګ او د سپين رنګ د مالوچو جوړو شوو پړدو باندې ښائسته کړے شوے وو، د سنګِ مرمرو په ستنو باندې د سپينو زرو د کَړو سره د کاسنى رنګ د ښې لټې د مزو سره تړلے شوې وې. د سرو زرو او سپينو زرو کټُونه په دربار کښې اېښودے شوى وُو، د دربار فرش د سپين سنګِ مرمر، سور قيمتى کاڼى، د ځلېدونکې ملغلرو او د آسمانى رنګ د فيروزو نه جوړ شوے وو.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_esther001_verse_006.mp3', NULL, 1761760676, 1761760676),
(11729, 'Esther 1:7', 'Esther', 1, 7, '&nbsp;د سرو زرو په پيالو کښې شراب ورکول چې هره يوه پيالۍ به د بلې په شان نۀ وه او بادشاه به په شاهى ميو کښې د سخاوت نه کار اخستلو.', NULL, '&nbsp;د سرو زرو په پيالو کښې شراب ورکول چې هره يوه پيالۍ به د بلې په شان نۀ وه او بادشاه به په شاهى ميو کښې د سخاوت نه کار اخستلو.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_esther001_verse_007.mp3', NULL, 1761760676, 1761760676),
(11730, 'Esther 1:8', 'Esther', 1, 8, '&nbsp;د شرابو په څښلو کښې حد مقرر نۀ وو، بادشاه د محل نوکرانو له حُکم ورکړے وو چې د هر چا زړۀ چې څومره غواړى نو هغه څښلے شى.', NULL, '&nbsp;د شرابو په څښلو کښې حد مقرر نۀ وو، بادشاه د محل نوکرانو له حُکم ورکړے وو چې د هر چا زړۀ چې څومره غواړى نو هغه څښلے شى.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_esther001_verse_008.mp3', NULL, 1761760676, 1761760676),
(11731, 'Esther 1:9', 'Esther', 1, 9, '&nbsp;هم په دې دوران کښې، د شاهى محل دننه مَلِکه وشتى د ښځو دپاره مېلمستيا کړې وه.', NULL, '&nbsp;هم په دې دوران کښې، د شاهى محل دننه مَلِکه وشتى د ښځو دپاره مېلمستيا کړې وه.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_esther001_verse_009.mp3', NULL, 1761760676, 1761760676),
(11732, 'Esther 1:10', 'Esther', 1, 10, '&nbsp;د خپلې مېلمستيا په اوومه ورځ باندې بادشاه په نشه کښې وو او ښۀ په سور کښې وو، نو هغۀ اووۀ خصيان راوغوښتل کوم چې د هغۀ ذاتى خِدمتګاران وُو، مهُومان، بِزتا، خربونا، بِګتا، ابګتا، زتار او کرکس.', NULL, '&nbsp;د خپلې مېلمستيا په اوومه ورځ باندې بادشاه په نشه کښې وو او ښۀ په سور کښې وو، نو هغۀ اووۀ خصيان راوغوښتل کوم چې د هغۀ ذاتى خِدمتګاران وُو، مهُومان، بِزتا، خربونا، بِګتا، ابګتا، زتار او کرکس.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_esther001_verse_010.mp3', NULL, 1761760676, 1761760676),
(11733, 'Esther 1:11', 'Esther', 1, 11, '&nbsp;بادشاه هغوئ ته حُکم وکړو چې مَلِکه وشتى دننه راولئ چې شاهى تاج يې په سر وى. مَلِکه يوه ښائسته ښځه وه او بادشاه غوښتل چې د هغې حُسن آفسرانو او خپلو ټولو مېلمنو ته وښائى.', NULL, '&nbsp;بادشاه هغوئ ته حُکم وکړو چې مَلِکه وشتى دننه راولئ چې شاهى تاج يې په سر وى. مَلِکه يوه ښائسته ښځه وه او بادشاه غوښتل چې د هغې حُسن آفسرانو او خپلو ټولو مېلمنو ته وښائى.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_esther001_verse_011.mp3', NULL, 1761760676, 1761760676),
(11734, 'Esther 1:12', 'Esther', 1, 12, '&nbsp;خو کله چې خِدمتګارانو مَلِکه وشتى ته د بادشاه د حُکم په حقله ووئيل، نو هغې د راتلو نه اِنکار وکړو. نو په دې باندې بادشاه د غصې نه تک سور شو.', NULL, '&nbsp;خو کله چې خِدمتګارانو مَلِکه وشتى ته د بادشاه د حُکم په حقله ووئيل، نو هغې د راتلو نه اِنکار وکړو. نو په دې باندې بادشاه د غصې نه تک سور شو.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_esther001_verse_012.mp3', NULL, 1761760676, 1761760676),
(11735, 'Esther 1:13', 'Esther', 1, 13, '&nbsp;نو دا د بادشاهانو رِواج وو چې د قانون او حُکمونو د سوالونو په حقله يې د ماهِرانو رايې معلوموله، نو هغۀ خپل هغه مشيران راوغوښتل، چې هغوئ ته به پته وه چې څۀ کول په کار دى.', NULL, '&nbsp;نو دا د بادشاهانو رِواج وو چې د قانون او حُکمونو د سوالونو په حقله يې د ماهِرانو رايې معلوموله، نو هغۀ خپل هغه مشيران راوغوښتل، چې هغوئ ته به پته وه چې څۀ کول په کار دى.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_esther001_verse_013.mp3', NULL, 1761760676, 1761760676),
(11736, 'Esther 1:14', 'Esther', 1, 14, '&nbsp;کوم مشيران به چې بادشاه له ورتلل نو هغه کارشينا، شتر، ادماتا، ترسيس، مرس، مرسنا او مموکان وُو، دا اووۀ د فارس او مادى هغه آفسران وُو چې په بادشاهۍ کښې يې د ټولو نه اوچتې مرتبې لرلې.', NULL, '&nbsp;کوم مشيران به چې بادشاه له ورتلل نو هغه کارشينا، شتر، ادماتا، ترسيس، مرس، مرسنا او مموکان وُو، دا اووۀ د فارس او مادى هغه آفسران وُو چې په بادشاهۍ کښې يې د ټولو نه اوچتې مرتبې لرلې.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_esther001_verse_014.mp3', NULL, 1761760676, 1761760676),
(11737, 'Esther 1:15', 'Esther', 1, 15, '&nbsp;بادشاه دې سړو ته ووئيل، ”ما، يعنې اخسويرس بادشاه، خپل خصيان د يو حُکم سره مَلِکه وشتى ته ولېږل او هغې د دې حُکم د منلو نه اِنکار وکړو. قانون د دې په حقله څۀ وائى چې مونږ د هغې سره څۀ وکړُو؟“', NULL, '&nbsp;بادشاه دې سړو ته ووئيل، ”ما، يعنې اخسويرس بادشاه، خپل خصيان د يو حُکم سره مَلِکه وشتى ته ولېږل او هغې د دې حُکم د منلو نه اِنکار وکړو. قانون د دې په حقله څۀ وائى چې مونږ د هغې سره څۀ وکړُو؟“', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_esther001_verse_015.mp3', NULL, 1761760676, 1761760676),
(11738, 'Esther 1:16', 'Esther', 1, 16, '&nbsp;نو مموکان بادشاه او د هغۀ آفسرانو ته ووئيل، ”مَلِکه وشتى نۀ صِرف د بادشاه بې‌عزتى کړې ده بلکې هغې د آفسرانو او د ټول قوم بې‌عزتى يې کړې ده.', NULL, '&nbsp;نو مموکان بادشاه او د هغۀ آفسرانو ته ووئيل، ”مَلِکه وشتى نۀ صِرف د بادشاه بې‌عزتى کړې ده بلکې هغې د آفسرانو او د ټول قوم بې‌عزتى يې کړې ده.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_esther001_verse_016.mp3', NULL, 1761760676, 1761760676),
(11739, 'Esther 1:17', 'Esther', 1, 17, '&nbsp;د بادشاهۍ هره يوه ښځه چې خبر شى چې مَلِکه څۀ کړى دى نو هغه به خپل خاوند ته سپک کتل شروع کړى. هغوئ به وائى چې اخسويرس بادشاه مَلِکه وشتى له حُکم ورکړو چې راشه، خو هغې اِنکار وکړو.', NULL, '&nbsp;د بادشاهۍ هره يوه ښځه چې خبر شى چې مَلِکه څۀ کړى دى نو هغه به خپل خاوند ته سپک کتل شروع کړى. هغوئ به وائى چې اخسويرس بادشاه مَلِکه وشتى له حُکم ورکړو چې راشه، خو هغې اِنکار وکړو.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_esther001_verse_017.mp3', NULL, 1761760676, 1761760676),
(11740, 'Esther 1:18', 'Esther', 1, 18, '&nbsp;نن چې د فارس او مادى د شاهى آفسرانو ښځې د مَلِکه د دې کار نه خبر شى نو هغوئ به هم د خپلو خاوندانو سره هم دغه شان د بې‌عزتۍ سلوک کوى او داسې به دا معامله ډېره خرابه شى.', NULL, '&nbsp;نن چې د فارس او مادى د شاهى آفسرانو ښځې د مَلِکه د دې کار نه خبر شى نو هغوئ به هم د خپلو خاوندانو سره هم دغه شان د بې‌عزتۍ سلوک کوى او داسې به دا معامله ډېره خرابه شى.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_esther001_verse_018.mp3', NULL, 1761760676, 1761760676),
(11741, 'Esther 1:19', 'Esther', 1, 19, '&nbsp;بادشاه سلامت، کۀ ستا رضا وى، نو شاهى فرمان جارى کړه چې وشتى دې بيا هيڅکله د بادشاه په مخکښې نۀ حاضريږى. دا حُکم وکړه چې دا د فارس او مادى په قانون کښې وليکلے شى، نو داسې به هيڅوک هم دا نۀ شى بدلولے. بيا د هغې د مَلِکه عهده د هغې نه زياتې حقدارې ښځې له ورکړه.', NULL, '&nbsp;بادشاه سلامت، کۀ ستا رضا وى، نو شاهى فرمان جارى کړه چې وشتى دې بيا هيڅکله د بادشاه په مخکښې نۀ حاضريږى. دا حُکم وکړه چې دا د فارس او مادى په قانون کښې وليکلے شى، نو داسې به هيڅوک هم دا نۀ شى بدلولے. بيا د هغې د مَلِکه عهده د هغې نه زياتې حقدارې ښځې له ورکړه.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_esther001_verse_019.mp3', NULL, 1761760676, 1761760676),
(11742, 'Esther 1:20', 'Esther', 1, 20, '&nbsp;کله چې ستا د دې فرمان پته په دې لويه بادشاهۍ کښې ولګى، نو هره ښځه به د خپل خاوند ښۀ عزت کوى، کۀ هغه مالداره وى او کۀ غريب وى.“', NULL, '&nbsp;کله چې ستا د دې فرمان پته په دې لويه بادشاهۍ کښې ولګى، نو هره ښځه به د خپل خاوند ښۀ عزت کوى، کۀ هغه مالداره وى او کۀ غريب وى.“', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_esther001_verse_020.mp3', NULL, 1761760676, 1761760676),
(11743, 'Esther 1:21', 'Esther', 1, 21, '&nbsp;د بادشاه او د هغۀ د وزيرانو دا خبره خوښه شوه او مموکان چې کومه مشوره ورکړې وه نو بادشاه هم هغه شان وکړل.', NULL, '&nbsp;د بادشاه او د هغۀ د وزيرانو دا خبره خوښه شوه او مموکان چې کومه مشوره ورکړې وه نو بادشاه هم هغه شان وکړل.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_esther001_verse_021.mp3', NULL, 1761760676, 1761760676),
(11744, 'Esther 1:22', 'Esther', 1, 22, '&nbsp;هغۀ هرې شاهى صُوبې ته د هغه صُوبې په ژبه او رسم‌الخط کښې يو پېغام ولېږلو، چې په کښې وئيلے شوى وُو چې هر يو خاوند به د خپل کور مشرى کوى.', NULL, '&nbsp;هغۀ هرې شاهى صُوبې ته د هغه صُوبې په ژبه او رسم‌الخط کښې يو پېغام ولېږلو، چې په کښې وئيلے شوى وُو چې هر يو خاوند به د خپل کور مشرى کوى.', 'OT', 'yousafzai2019', 'yousafzai', '[]', NULL, NULL, 1761760676, 1761760676),
(11745, 'Esther 2:1', 'Esther', 2, 1, '&nbsp;وروستو، کله چې د بادشاه غصه سړه شوې وه، نو هغۀ بيا هم د وشتى د عمل او د هغې خِلاف د فرمان په حقله سوچ کولو.', NULL, '&nbsp;وروستو، کله چې د بادشاه غصه سړه شوې وه، نو هغۀ بيا هم د وشتى د عمل او د هغې خِلاف د فرمان په حقله سوچ کولو.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_esther002_verse_001.mp3', NULL, 1761760676, 1761760676),
(11746, 'Esther 2:2', 'Esther', 2, 2, '&nbsp;نو د بادشاه خادِمانو هغۀ له مشوره ورکړه، ”مونږ به ستا دپاره يو څو ښائسته ناوادۀ شوې پېغلې ولټوُو.', NULL, '&nbsp;نو د بادشاه خادِمانو هغۀ له مشوره ورکړه، ”مونږ به ستا دپاره يو څو ښائسته ناوادۀ شوې پېغلې ولټوُو.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_esther002_verse_002.mp3', NULL, 1761760676, 1761760676),
(11747, 'Esther 2:3', 'Esther', 2, 3, '&nbsp;تۀ د بادشاهۍ په هره يوه صُوبه کښې آفسران مقرر کړه او هغوئ له حُکم ورکړه چې هغوئ ټولې ښائسته پېغلې په مرکزى ښار سوسه کښې ستا د زناناؤ ځائ ته راولى. هيجا څوک چې د بادشاه د زناناؤ مشر دے او خصى دے هغه به د هغوئ خيال ساتى او د هغوئ د سنګار بندوبست به کوى.', NULL, '&nbsp;تۀ د بادشاهۍ په هره يوه صُوبه کښې آفسران مقرر کړه او هغوئ له حُکم ورکړه چې هغوئ ټولې ښائسته پېغلې په مرکزى ښار سوسه کښې ستا د زناناؤ ځائ ته راولى. هيجا څوک چې د بادشاه د زناناؤ مشر دے او خصى دے هغه به د هغوئ خيال ساتى او د هغوئ د سنګار بندوبست به کوى.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_esther002_verse_003.mp3', NULL, 1761760676, 1761760676),
(11748, 'Esther 2:4', 'Esther', 2, 4, '&nbsp;نو چې کومه پېغله ستا ډېره خوښه شى نو هغه بوځه او د وشتى په ځائ يې خپله مَلِکه جوړه کړه.“ نو بادشاه ووئيل چې دا يوه ښۀ مشوره ده، نو هغۀ په دې خبره باندې عمل وکړو.', NULL, '&nbsp;نو چې کومه پېغله ستا ډېره خوښه شى نو هغه بوځه او د وشتى په ځائ يې خپله مَلِکه جوړه کړه.“ نو بادشاه ووئيل چې دا يوه ښۀ مشوره ده، نو هغۀ په دې خبره باندې عمل وکړو.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_esther002_verse_004.mp3', NULL, 1761760676, 1761760676),
(11749, 'Esther 2:5', 'Esther', 2, 5, '&nbsp;په هغه وخت کښې هلته په سوسه کښې يو يهودى اوسېدو چې نوم يې مردکى وو او هغه د يائير زوئ وو، هغه د بنيامين د قبيلې وو او د قيس او سِمعى د اولاد نه وو.', NULL, '&nbsp;په هغه وخت کښې هلته په سوسه کښې يو يهودى اوسېدو چې نوم يې مردکى وو او هغه د يائير زوئ وو، هغه د بنيامين د قبيلې وو او د قيس او سِمعى د اولاد نه وو.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_esther002_verse_005.mp3', NULL, 1761760676, 1761760676),
(11750, 'Esther 2:6', 'Esther', 2, 6, '&nbsp;کله چې د بابل بادشاه نبوکدنضر د يهوداه بادشاه يهوياکين د يروشلم نه بابل مُلک ته بوتلو، د قېديانو يوه ډله هم ورسره وه، او مردکى هم په هغوئ کښې وو.', NULL, '&nbsp;کله چې د بابل بادشاه نبوکدنضر د يهوداه بادشاه يهوياکين د يروشلم نه بابل مُلک ته بوتلو، د قېديانو يوه ډله هم ورسره وه، او مردکى هم په هغوئ کښې وو.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_esther002_verse_006.mp3', NULL, 1761760676, 1761760676),
(11751, 'Esther 2:7', 'Esther', 2, 7, '&nbsp;د هغۀ يوه د ترۀ لور اِستَر وه، چې د هغې عبرانے نوم هدسا وو، هغه يوه ښائسته پېغله وه او ښۀ کړۀ‌وړۀ يې وُو. د هغې د مور او پلار د مرګ نه پس، مردکى هغه اخستې وه او د خپلې لور په توګه يې راوستې وه.', NULL, '&nbsp;د هغۀ يوه د ترۀ لور اِستَر وه، چې د هغې عبرانے نوم هدسا وو، هغه يوه ښائسته پېغله وه او ښۀ کړۀ‌وړۀ يې وُو. د هغې د مور او پلار د مرګ نه پس، مردکى هغه اخستې وه او د خپلې لور په توګه يې راوستې وه.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_esther002_verse_007.mp3', NULL, 1761760676, 1761760676),
(11752, 'Esther 2:8', 'Esther', 2, 8, '&nbsp;کله چې بادشاه خپل نوے فرمان جارى کړو او ډيرې پېغلې سوسه ته راوستلے شوې، نو اِستَر هم په هغوئ کښې وه. هغه هم په شاهى محل کښې هيجا ته حواله شوه، کوم چې د بادشاه د زناناؤ د ځائ مشر وو.', NULL, '&nbsp;کله چې بادشاه خپل نوے فرمان جارى کړو او ډيرې پېغلې سوسه ته راوستلے شوې، نو اِستَر هم په هغوئ کښې وه. هغه هم په شاهى محل کښې هيجا ته حواله شوه، کوم چې د بادشاه د زناناؤ د ځائ مشر وو.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_esther002_verse_008.mp3', NULL, 1761760676, 1761760676),
(11753, 'Esther 2:9', 'Esther', 2, 9, '&nbsp;د هيجا اِستَر خوښه شوه او هغه پرې مِهربانه شو. هغۀ سمدستى د هغې د سنګار او د خاص خوراک بندوبست وکړو. هغۀ ورله د بادشاه د زناناؤ په ځائ کښې د ټولو نه ښۀ ځائ ورکړو او د هغې د خِدمت دپاره يې اووۀ پېغلې مقررې کړې چې د شاهى محل نه په خصوصى توګه خوښې کړې شوې وې.', NULL, '&nbsp;د هيجا اِستَر خوښه شوه او هغه پرې مِهربانه شو. هغۀ سمدستى د هغې د سنګار او د خاص خوراک بندوبست وکړو. هغۀ ورله د بادشاه د زناناؤ په ځائ کښې د ټولو نه ښۀ ځائ ورکړو او د هغې د خِدمت دپاره يې اووۀ پېغلې مقررې کړې چې د شاهى محل نه په خصوصى توګه خوښې کړې شوې وې.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_esther002_verse_009.mp3', NULL, 1761760676, 1761760676),
(11754, 'Esther 2:10', 'Esther', 2, 10, '&nbsp;نو د مردکى د نصيحت په وجه، اِستَر خپل قوم او خاندان پټ ساتلے وو.', NULL, '&nbsp;نو د مردکى د نصيحت په وجه، اِستَر خپل قوم او خاندان پټ ساتلے وو.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_esther002_verse_010.mp3', NULL, 1761760676, 1761760676),
