(11759, 'Esther 2:15', 'Esther', 2, 15, '&nbsp;نو هغه وخت راغلو چې اِستَر بادشاه له لاړه شى. اِستَر د ابى‌خېل لور او د مردکى د ترۀ لور وه، چې مردکى هغه د خپلې لور په توګه اخستې وه. کله چې د هغې وار راغلو، نو هغې هم هغه جامې اغوستې وې د کومو مشوره چې د بادشاه د ښځو د کور مشر هيجا نومې خصى له ورکړې وه، اِستَر چې چا هم ليدله نو د هغۀ به خوښېدله.', NULL, '&nbsp;نو هغه وخت راغلو چې اِستَر بادشاه له لاړه شى. اِستَر د ابى‌خېل لور او د مردکى د ترۀ لور وه، چې مردکى هغه د خپلې لور په توګه اخستې وه. کله چې د هغې وار راغلو، نو هغې هم هغه جامې اغوستې وې د کومو مشوره چې د بادشاه د ښځو د کور مشر هيجا نومې خصى له ورکړې وه، اِستَر چې چا هم ليدله نو د هغۀ به خوښېدله.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_esther002_verse_015.mp3', NULL, 1761760676, 1761760676),
(11760, 'Esther 2:16', 'Esther', 2, 16, '&nbsp;نو د اخسويرس د بادشاهۍ په اوؤم کال، په لسمه مياشت يعنې د طيبت په مياشت کښې، اِستَر شاهى محل ته اخسويرس بادشاه ته راوستلے شوه.', NULL, '&nbsp;نو د اخسويرس د بادشاهۍ په اوؤم کال، په لسمه مياشت يعنې د طيبت په مياشت کښې، اِستَر شاهى محل ته اخسويرس بادشاه ته راوستلے شوه.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_esther002_verse_016.mp3', NULL, 1761760676, 1761760676),
(11761, 'Esther 2:17', 'Esther', 2, 17, '&nbsp;اِستَر د بادشاه د نورو ټولو پېغلو نه زياته خوښه شوه، نو ځکه يې هغې له زړۀ او مينه ورکړه. هغۀ شاهى تاج ور په سر کړو او د وشتى په ځائ يې مَلِکه جوړه کړه.', NULL, '&nbsp;اِستَر د بادشاه د نورو ټولو پېغلو نه زياته خوښه شوه، نو ځکه يې هغې له زړۀ او مينه ورکړه. هغۀ شاهى تاج ور په سر کړو او د وشتى په ځائ يې مَلِکه جوړه کړه.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_esther002_verse_017.mp3', NULL, 1761760676, 1761760676),
(11762, 'Esther 2:18', 'Esther', 2, 18, '&nbsp;بيا بادشاه د اِستَر د درناوى دپاره يوه لويه مېلمستيا وکړه او خپلو ټولو آفسرانو او وزيرانو له يې دعوت ورکړو. هغۀ د ټولې بادشاهۍ دپاره په هغه ورځ د چُهټۍ اِعلان وکړو او هر چا له يې قيمتى تُحفې ورکړې.', NULL, '&nbsp;بيا بادشاه د اِستَر د درناوى دپاره يوه لويه مېلمستيا وکړه او خپلو ټولو آفسرانو او وزيرانو له يې دعوت ورکړو. هغۀ د ټولې بادشاهۍ دپاره په هغه ورځ د چُهټۍ اِعلان وکړو او هر چا له يې قيمتى تُحفې ورکړې.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_esther002_verse_018.mp3', NULL, 1761760676, 1761760676),
(11763, 'Esther 2:19', 'Esther', 2, 19, '&nbsp;په دې دوران کښې بادشاه مردکى د محل آفسر مقرر کړے وو.', NULL, '&nbsp;په دې دوران کښې بادشاه مردکى د محل آفسر مقرر کړے وو.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_esther002_verse_019.mp3', NULL, 1761760676, 1761760676),
(11764, 'Esther 2:20', 'Esther', 2, 20, '&nbsp;اِستَر تر اوسه پورې خپل قوم او خاندان پټ ساتلے وو، لکه څنګه چې مردکى ورته وئيلى وُو. او څنګه چې هغې په ماشوموالى کښې د مردکى خبره منله اوس يې هم منله.', NULL, '&nbsp;اِستَر تر اوسه پورې خپل قوم او خاندان پټ ساتلے وو، لکه څنګه چې مردکى ورته وئيلى وُو. او څنګه چې هغې په ماشوموالى کښې د مردکى خبره منله اوس يې هم منله.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_esther002_verse_020.mp3', NULL, 1761760676, 1761760676),
(11765, 'Esther 2:21', 'Esther', 2, 21, '&nbsp;په هغه وخت کښې چې مردکى په محل کښې دفتر ونيولو، بِګتان او ترش، د محل دوه هغه خصيانو کومو چې د اخسويرس بادشاه کوټو ته د ننوتلو د ځائ څوکيدارى کوله، هغوئ د بادشاه خِلاف شول او د هغۀ د وژلو منصوبه يې جوړه کړه.', NULL, '&nbsp;په هغه وخت کښې چې مردکى په محل کښې دفتر ونيولو، بِګتان او ترش، د محل دوه هغه خصيانو کومو چې د اخسويرس بادشاه کوټو ته د ننوتلو د ځائ څوکيدارى کوله، هغوئ د بادشاه خِلاف شول او د هغۀ د وژلو منصوبه يې جوړه کړه.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_esther002_verse_021.mp3', NULL, 1761760676, 1761760676),
(11766, 'Esther 2:22', 'Esther', 2, 22, '&nbsp;خو مردکى د دې منصوبې نه خبر شو او دا خبر يې مَلِکه اِستَر ته ورسولو. بيا هغې بادشاه ته ووئيل چې مردکى زۀ د دې نه خبر کړې يم.', NULL, '&nbsp;خو مردکى د دې منصوبې نه خبر شو او دا خبر يې مَلِکه اِستَر ته ورسولو. بيا هغې بادشاه ته ووئيل چې مردکى زۀ د دې نه خبر کړې يم.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_esther002_verse_022.mp3', NULL, 1761760676, 1761760676),
(11767, 'Esther 2:23', 'Esther', 2, 23, '&nbsp;کله چې د منصوبې تفتيش وشو او پته ولګېده چې هغه خبر رښتيا وو، نو هغوئ په دار باندې ځوړند کړے شول. بادشاه حُکم وکړو چې دا واقعه دې د شاهى تاريخ په کِتاب کښې وليکلے شى.', NULL, '&nbsp;کله چې د منصوبې تفتيش وشو او پته ولګېده چې هغه خبر رښتيا وو، نو هغوئ په دار باندې ځوړند کړے شول. بادشاه حُکم وکړو چې دا واقعه دې د شاهى تاريخ په کِتاب کښې وليکلے شى.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_esther002_verse_023.mp3', NULL, 1761760676, 1761760676),
(11768, 'Esther 3:1', 'Esther', 3, 1, '&nbsp;څۀ موده وروستو اخسويرس بادشاه همان نومې سړى له ترقى ورکړه او د وزيرانو مشر يې جوړ کړو. همان د اجاج د قوم همداتا زوئ وو.', NULL, '&nbsp;څۀ موده وروستو اخسويرس بادشاه همان نومې سړى له ترقى ورکړه او د وزيرانو مشر يې جوړ کړو. همان د اجاج د قوم همداتا زوئ وو.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_esther003_verse_001.mp3', NULL, 1761760676, 1761760676),
(11769, 'Esther 3:2', 'Esther', 3, 2, '&nbsp;بادشاه خپلو ټولو آفسرانو له حُکم ورکړو چې همان ته د عزت نه ټيټېږئ، خو مردکى يې عزت نۀ کولو او نۀ ورته ټيټېدو.', NULL, '&nbsp;بادشاه خپلو ټولو آفسرانو له حُکم ورکړو چې همان ته د عزت نه ټيټېږئ، خو مردکى يې عزت نۀ کولو او نۀ ورته ټيټېدو.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_esther003_verse_002.mp3', NULL, 1761760676, 1761760676),
(11770, 'Esther 3:3', 'Esther', 3, 3, '&nbsp;نورو شاهى آفسرانو د هغۀ نه تپوس وکړو چې، ”تۀ د بادشاه د حُکم نافرمانى ولې کوې؟“', NULL, '&nbsp;نورو شاهى آفسرانو د هغۀ نه تپوس وکړو چې، ”تۀ د بادشاه د حُکم نافرمانى ولې کوې؟“', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_esther003_verse_003.mp3', NULL, 1761760676, 1761760676),
(11771, 'Esther 3:4', 'Esther', 3, 4, '&nbsp;هغوئ به هره ورځ ورته وئيل، خو هغۀ به ورته غوږ نۀ نيولو. هغۀ به وئيل، ”زۀ همان ته نۀ شم ټيټېدلے ځکه چې زۀ يهودى يم.“ نو هغوئ همان د دې نه خبر کړو، هغوئ غوښتل چې وګورى چې هغه به د مردکى دا رويه برداشت کړى کۀ نه.', NULL, '&nbsp;هغوئ به هره ورځ ورته وئيل، خو هغۀ به ورته غوږ نۀ نيولو. هغۀ به وئيل، ”زۀ همان ته نۀ شم ټيټېدلے ځکه چې زۀ يهودى يم.“ نو هغوئ همان د دې نه خبر کړو، هغوئ غوښتل چې وګورى چې هغه به د مردکى دا رويه برداشت کړى کۀ نه.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_esther003_verse_004.mp3', NULL, 1761760676, 1761760676),
(11772, 'Esther 3:5', 'Esther', 3, 5, '&nbsp;کله چې همان ته پته ولګېده چې مردکے هغۀ ته د عزت نه نۀ ټيټيږى نو همان سخت غصه شو،', NULL, '&nbsp;کله چې همان ته پته ولګېده چې مردکے هغۀ ته د عزت نه نۀ ټيټيږى نو همان سخت غصه شو،', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_esther003_verse_005.mp3', NULL, 1761760676, 1761760676),
(11773, 'Esther 3:6', 'Esther', 3, 6, '&nbsp;او کله چې خبر شو چې مردکے يهودى دے، نو همان دا فېصله وکړه چې هغه به نۀ صرف مردکى له سزا ورکوى بلکې هغۀ دا منصوبه هم جوړه کړه چې د فارس په بادشاهۍ کښې هر يو يهودى ووژنى.', NULL, '&nbsp;او کله چې خبر شو چې مردکے يهودى دے، نو همان دا فېصله وکړه چې هغه به نۀ صرف مردکى له سزا ورکوى بلکې هغۀ دا منصوبه هم جوړه کړه چې د فارس په بادشاهۍ کښې هر يو يهودى ووژنى.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_esther003_verse_006.mp3', NULL, 1761760676, 1761760676),
(11774, 'Esther 3:7', 'Esther', 3, 7, '&nbsp;د اخسويرس بادشاه د حکومت په دولسم کال، په وړومبۍ مياشت يعنې د نسان په مياشت، همان حُکم وکړو چې پوريم يعنې پچه دې واچولے شى چې دا معلومه کړى چې د دې منصوبې دپاره صحيح مياشت کومه يوه ده. نو د دولسمې مياشتې يعنې د ادر مياشتې ديارلسمه ورځ خوښه کړے شوه.', NULL, '&nbsp;د اخسويرس بادشاه د حکومت په دولسم کال، په وړومبۍ مياشت يعنې د نسان په مياشت، همان حُکم وکړو چې پوريم يعنې پچه دې واچولے شى چې دا معلومه کړى چې د دې منصوبې دپاره صحيح مياشت کومه يوه ده. نو د دولسمې مياشتې يعنې د ادر مياشتې ديارلسمه ورځ خوښه کړے شوه.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_esther003_verse_007.mp3', NULL, 1761760676, 1761760676),
(11775, 'Esther 3:8', 'Esther', 3, 8, '&nbsp;نو همان د بادشاه په مخکښې حاضر شو او ورته يې ووئيل، ”ستا په ټوله بادشاهۍ کښې د خلقو يو قِسم نسل خور دے او دا په هره صُوبه کښې موندلے شى. هغوئ داسې رِواجونه کوى چې هغه د نورو ټولو خلقو په شان نۀ دى. د دې نه علاوه، هغوئ د بادشاهۍ قانون هم نۀ منى، نو دا ستا دپاره د فائدې خبره نۀ ده چې هغوئ برداشت کړې.', NULL, '&nbsp;نو همان د بادشاه په مخکښې حاضر شو او ورته يې ووئيل، ”ستا په ټوله بادشاهۍ کښې د خلقو يو قِسم نسل خور دے او دا په هره صُوبه کښې موندلے شى. هغوئ داسې رِواجونه کوى چې هغه د نورو ټولو خلقو په شان نۀ دى. د دې نه علاوه، هغوئ د بادشاهۍ قانون هم نۀ منى، نو دا ستا دپاره د فائدې خبره نۀ ده چې هغوئ برداشت کړې.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_esther003_verse_008.mp3', NULL, 1761760676, 1761760676),
(11776, 'Esther 3:9', 'Esther', 3, 9, '&nbsp;بادشاه سلامت، کۀ ستا رضا وى، نو يو فرمان جارى کړه چې هغوئ دې ووژلے شى. کۀ تا داسې وکړل، نو زۀ به د بادشاهۍ د اِنتظام دپاره د درې لاکه او څلوېښتو زرو کېلو نه زيات سپين زر په شاهى خزانه کښې کېږدم.“', NULL, '&nbsp;بادشاه سلامت، کۀ ستا رضا وى، نو يو فرمان جارى کړه چې هغوئ دې ووژلے شى. کۀ تا داسې وکړل، نو زۀ به د بادشاهۍ د اِنتظام دپاره د درې لاکه او څلوېښتو زرو کېلو نه زيات سپين زر په شاهى خزانه کښې کېږدم.“', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_esther003_verse_009.mp3', NULL, 1761760676, 1761760676),
(11777, 'Esther 3:10', 'Esther', 3, 10, '&nbsp;بادشاه خپله هغه ګوتمه وويستله، چې هغه به په سرکارى فرمان باندې د مهر لګولو دپاره استعمالېدله او دا يې د يهوديانو دشمن د همداتا زوئ همان له ورکړه چې دے د اجاج د اولاد نه وو.', NULL, '&nbsp;بادشاه خپله هغه ګوتمه وويستله، چې هغه به په سرکارى فرمان باندې د مهر لګولو دپاره استعمالېدله او دا يې د يهوديانو دشمن د همداتا زوئ همان له ورکړه چې دے د اجاج د اولاد نه وو.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_esther003_verse_010.mp3', NULL, 1761760676, 1761760676),
(11778, 'Esther 3:11', 'Esther', 3, 11, '&nbsp;بادشاه همان ته ووئيل، ”سپين زر ځان سره کړه او د خلقو سره هم هغسې وکړه څنګه چې دې زړۀ غواړى.“', NULL, '&nbsp;بادشاه همان ته ووئيل، ”سپين زر ځان سره کړه او د خلقو سره هم هغسې وکړه څنګه چې دې زړۀ غواړى.“', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_esther003_verse_011.mp3', NULL, 1761760676, 1761760676),
(11779, 'Esther 3:12', 'Esther', 3, 12, '&nbsp;نو د وړومبۍ مياشتې په ديارلسمه ورځ باندې همان د بادشاه منشيان راوغوښتل او يو فرمان يې جارى کړو چې د هرې صُوبې په ژبه او رسم‌الخط کښې دې د دې ترجمه وشى او ټولو حکمرانانو، حاکِمانو او آفسرانو ته دې ولېږلے شى. دا فرمان د اخسويرس بادشاه په نوم جارى شو او د هغۀ د ګوتمې مهر ورباندې لګېدلے وو.', NULL, '&nbsp;نو د وړومبۍ مياشتې په ديارلسمه ورځ باندې همان د بادشاه منشيان راوغوښتل او يو فرمان يې جارى کړو چې د هرې صُوبې په ژبه او رسم‌الخط کښې دې د دې ترجمه وشى او ټولو حکمرانانو، حاکِمانو او آفسرانو ته دې ولېږلے شى. دا فرمان د اخسويرس بادشاه په نوم جارى شو او د هغۀ د ګوتمې مهر ورباندې لګېدلے وو.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_esther003_verse_012.mp3', NULL, 1761760676, 1761760676),
(11780, 'Esther 3:13', 'Esther', 3, 13, '&nbsp;پېغام رسونکو دا فرمان د بادشاهۍ هرې صُوبې ته يوړو. په دې کښې دا خبرې ليکلے شوې وې چې صِرف په هغه ورځ يعنې د ادر مياشتې په ديارلسمه ورځ باندې دې ټول يهوديان، ځوانان، بوډاګان، ښځې او ماشومان ووژلے شى. هغوئ دې د بې‌رحمۍ سره حلال کړے شى او چې هغوئ څۀ لرى نو هغه ترې نه واخلئ.', NULL, '&nbsp;پېغام رسونکو دا فرمان د بادشاهۍ هرې صُوبې ته يوړو. په دې کښې دا خبرې ليکلے شوې وې چې صِرف په هغه ورځ يعنې د ادر مياشتې په ديارلسمه ورځ باندې دې ټول يهوديان، ځوانان، بوډاګان، ښځې او ماشومان ووژلے شى. هغوئ دې د بې‌رحمۍ سره حلال کړے شى او چې هغوئ څۀ لرى نو هغه ترې نه واخلئ.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_esther003_verse_013.mp3', NULL, 1761760676, 1761760676),
(11781, 'Esther 3:14', 'Esther', 3, 14, '&nbsp;د دې فرمان د خبرو نه د هرې صُوبې خلق ځکه خبرول په کار وُو، چې کله هغه ورځ راشى نو چې هر يو کس ورته تيار وى.', NULL, '&nbsp;د دې فرمان د خبرو نه د هرې صُوبې خلق ځکه خبرول په کار وُو، چې کله هغه ورځ راشى نو چې هر يو کس ورته تيار وى.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_esther003_verse_014.mp3', NULL, 1761760676, 1761760676),
(11782, 'Esther 3:15', 'Esther', 3, 15, '&nbsp;د بادشاه د حُکم په مطابق هغه فرمان د سوسه په مرکزى ښار کښې خلقو ته ورسولے شو او پېغام رسونکو دا خبر نورو صُوبو ته يوړو. په کوم وخت کښې چې د سوسه ښار په ګډوډۍ کښې اچولے شو نو بادشاه او همان شرابو څښلو ته ناست وُو.', NULL, '&nbsp;د بادشاه د حُکم په مطابق هغه فرمان د سوسه په مرکزى ښار کښې خلقو ته ورسولے شو او پېغام رسونکو دا خبر نورو صُوبو ته يوړو. په کوم وخت کښې چې د سوسه ښار په ګډوډۍ کښې اچولے شو نو بادشاه او همان شرابو څښلو ته ناست وُو.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_esther003_verse_015.mp3', NULL, 1761760676, 1761760676),
(11783, 'Esther 4:1', 'Esther', 4, 1, '&nbsp;کله چې مردکے د هغه هر څۀ نه خبر شو چې څۀ شوى وُو، نو هغۀ د خفګان نه خپلې جامې وشلولې. بيا هغۀ د ټاټ جامې واغوستلې، سر يې په ايرو پټ کړو، په ښار کښې روان شو او تر هغې پورې يې په چغو چغو او بد بد ژړل،', NULL, '&nbsp;کله چې مردکے د هغه هر څۀ نه خبر شو چې څۀ شوى وُو، نو هغۀ د خفګان نه خپلې جامې وشلولې. بيا هغۀ د ټاټ جامې واغوستلې، سر يې په ايرو پټ کړو، په ښار کښې روان شو او تر هغې پورې يې په چغو چغو او بد بد ژړل،', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_esther004_verse_001.mp3', NULL, 1761760676, 1761760676),
(11784, 'Esther 4:2', 'Esther', 4, 2, '&nbsp;چې د محل دروازې ته ورسېدو. هغه دننه ځکه لا نۀ ړو چې د ټاټ په جامو کښې دننه د تلو اجازت نۀ وو.', NULL, '&nbsp;چې د محل دروازې ته ورسېدو. هغه دننه ځکه لا نۀ ړو چې د ټاټ په جامو کښې دننه د تلو اجازت نۀ وو.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_esther004_verse_002.mp3', NULL, 1761760676, 1761760676),
(11785, 'Esther 4:3', 'Esther', 4, 3, '&nbsp;په ټولو صُوبو کښې، چرته هم چې د بادشاه د فرمان پته لګېدلې وه، نو هلته يهوديانو په چغو چغو ژړل. هغوئ روژه ونيوله، ژړا او وير يې کولو او ډېرو کسانو د ټاټ جامې اغوستې وې او سر يې په ايرو پټ کړے وو.', NULL, '&nbsp;په ټولو صُوبو کښې، چرته هم چې د بادشاه د فرمان پته لګېدلې وه، نو هلته يهوديانو په چغو چغو ژړل. هغوئ روژه ونيوله، ژړا او وير يې کولو او ډېرو کسانو د ټاټ جامې اغوستې وې او سر يې په ايرو پټ کړے وو.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_esther004_verse_003.mp3', NULL, 1761760676, 1761760676),
(11786, 'Esther 4:4', 'Esther', 4, 4, '&nbsp;کله چې د اِستَر ښځو خِدمتګارانو او خصيانو اِستَر ته ووئيل چې مردکى څۀ کول، نو هغه سخته پرېشانه شوه. نو هغې مردکى له څۀ جامې ولېږلې چې د ټاټ جامو په ځائ يې واغوندى، خو هغۀ به نۀ اخستلې.', NULL, '&nbsp;کله چې د اِستَر ښځو خِدمتګارانو او خصيانو اِستَر ته ووئيل چې مردکى څۀ کول، نو هغه سخته پرېشانه شوه. نو هغې مردکى له څۀ جامې ولېږلې چې د ټاټ جامو په ځائ يې واغوندى، خو هغۀ به نۀ اخستلې.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_esther004_verse_004.mp3', NULL, 1761760676, 1761760676),
(11787, 'Esther 4:5', 'Esther', 4, 5, '&nbsp;بيا هغې هتاک راوغوښتلو، هغه يو خصى وو چې بادشاه د هغې نوکر کړے وو او هغې هغۀ ته وفرمائيل چې مردکى له لاړ شه او د دې پته ولګوه چې څۀ مسئله ده چې هغه دومره غمژن دے.', NULL, '&nbsp;بيا هغې هتاک راوغوښتلو، هغه يو خصى وو چې بادشاه د هغې نوکر کړے وو او هغې هغۀ ته وفرمائيل چې مردکى له لاړ شه او د دې پته ولګوه چې څۀ مسئله ده چې هغه دومره غمژن دے.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_esther004_verse_005.mp3', NULL, 1761760676, 1761760676),
