(11790, 'Esther 4:8', 'Esther', 4, 8, '&nbsp;هغۀ هتاک له د هغه فرمان يو نقل ورکړو چې کوم په سوسه کښې جارى شوے وو، چې په هغې کښې د يهوديانو د تباهۍ حُکم وو. مردکى هتاک ته ووئيل چې دا اِستَر له يوسه او اِستَر د حالاتو نه خبر کړه او هغې ته ووايه چې لاړه شى او بادشاه ته دا سوال زارى وکړى چې د هغې په خلقو رحم وکړى.', NULL, '&nbsp;هغۀ هتاک له د هغه فرمان يو نقل ورکړو چې کوم په سوسه کښې جارى شوے وو، چې په هغې کښې د يهوديانو د تباهۍ حُکم وو. مردکى هتاک ته ووئيل چې دا اِستَر له يوسه او اِستَر د حالاتو نه خبر کړه او هغې ته ووايه چې لاړه شى او بادشاه ته دا سوال زارى وکړى چې د هغې په خلقو رحم وکړى.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_esther004_verse_008.mp3', NULL, 1761760676, 1761760676),
