(11794, 'Esther 4:12', 'Esther', 4, 12, '&nbsp;کله چې مردکى ته د اِستَر پېغام مِلاو شو،', NULL, '&nbsp;کله چې مردکى ته د اِستَر پېغام مِلاو شو،', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_esther004_verse_012.mp3', NULL, 1761760676, 1761760676),
(11795, 'Esther 4:13', 'Esther', 4, 13, '&nbsp;نو هغۀ اِستَر ته دا پېغام ولېږلو، ”داسې مۀ وايه چې په ټولو يهوديانو کښې به صرف تۀ بچ شې ولې چې تۀ په شاهى محل کښې يې.', NULL, '&nbsp;نو هغۀ اِستَر ته دا پېغام ولېږلو، ”داسې مۀ وايه چې په ټولو يهوديانو کښې به صرف تۀ بچ شې ولې چې تۀ په شاهى محل کښې يې.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_esther004_verse_013.mp3', NULL, 1761760676, 1761760676),
