(11797, 'Esther 4:15', 'Esther', 4, 15, '&nbsp;اِستَر مردکى له دا جواب ولېږلو،', NULL, '&nbsp;اِستَر مردکى له دا جواب ولېږلو،', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_esther004_verse_015.mp3', NULL, 1761760676, 1761760676),
(11798, 'Esther 4:16', 'Esther', 4, 16, '&nbsp;”لاړ شه او په سوسه کښې ټول يهوديان په يو ځائ راغونډ کړه، روژه ونيسئ او زما دپاره دُعا وکړئ. درې ورځې او درې شپې هيڅ خوراک څښاک مۀ کوئ. زۀ او زما خِدمتګارې به هم ستاسو په شان روژه ونيسو. د هغې نه پس به بيا زۀ بادشاه له لاړه شم، اګر چې دا د قانون خِلاف ورزى ده. خو کۀ د داسې کولو په وجه زۀ مرم، نو مړه دې شم.“', NULL, '&nbsp;”لاړ شه او په سوسه کښې ټول يهوديان په يو ځائ راغونډ کړه، روژه ونيسئ او زما دپاره دُعا وکړئ. درې ورځې او درې شپې هيڅ خوراک څښاک مۀ کوئ. زۀ او زما خِدمتګارې به هم ستاسو په شان روژه ونيسو. د هغې نه پس به بيا زۀ بادشاه له لاړه شم، اګر چې دا د قانون خِلاف ورزى ده. خو کۀ د داسې کولو په وجه زۀ مرم، نو مړه دې شم.“', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_esther004_verse_016.mp3', NULL, 1761760676, 1761760676),
(11799, 'Esther 4:17', 'Esther', 4, 17, '&nbsp;نو بيا مردکى لاړو او هغه هر څۀ يې وکړل چې اِستَر ورته وئيلى وُو.', NULL, '&nbsp;نو بيا مردکى لاړو او هغه هر څۀ يې وکړل چې اِستَر ورته وئيلى وُو.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_esther004_verse_017.mp3', NULL, 1761760676, 1761760676),
