(11801, 'Esther 5:2', 'Esther', 5, 2, '&nbsp;کله چې بادشاه وکتل چې مَلِکه اِستَر دننه په دربار کښې ولاړه وه، نو بادشاه په هغې باندې مِهربانه شو او هغۀ خپله د سرو زرو امسا وراوږده کړه. بيا اِستَر ورنزدې شوه او د امسا سر له يې لاس وروړو.', NULL, '&nbsp;کله چې بادشاه وکتل چې مَلِکه اِستَر دننه په دربار کښې ولاړه وه، نو بادشاه په هغې باندې مِهربانه شو او هغۀ خپله د سرو زرو امسا وراوږده کړه. بيا اِستَر ورنزدې شوه او د امسا سر له يې لاس وروړو.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_esther005_verse_002.mp3', NULL, 1761760676, 1761760676),
