(11804, 'Esther 5:5', 'Esther', 5, 5, '&nbsp;بادشاه همان له حُکم ورکړو چې زر راشى، نو چې داسې دوئ د اِستَر مېلمانۀ شى. نو بادشاه او همان د اِستَر مېلمستيا له لاړل.', NULL, '&nbsp;بادشاه همان له حُکم ورکړو چې زر راشى، نو چې داسې دوئ د اِستَر مېلمانۀ شى. نو بادشاه او همان د اِستَر مېلمستيا له لاړل.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_esther005_verse_005.mp3', NULL, 1761760676, 1761760676),
(11805, 'Esther 5:6', 'Esther', 5, 6, '&nbsp;د ميو څښلو په وخت بادشاه د هغې نه تپوس وکړو، ”ما ته ووايه چې تۀ څۀ غواړې، نو تا ته به هغه مِلاو شى. زۀ به ستا درخواست منظور کړم، تر دې پورې کۀ تۀ زما نيمه بادشاهى هم وغواړې.“', NULL, '&nbsp;د ميو څښلو په وخت بادشاه د هغې نه تپوس وکړو، ”ما ته ووايه چې تۀ څۀ غواړې، نو تا ته به هغه مِلاو شى. زۀ به ستا درخواست منظور کړم، تر دې پورې کۀ تۀ زما نيمه بادشاهى هم وغواړې.“', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_esther005_verse_006.mp3', NULL, 1761760676, 1761760676),
