(11824, 'Esther 6:13', 'Esther', 6, 13, '&nbsp;هغۀ خپلې ښځې او ټولو دوستانو ته هغه هر څۀ ووئيل چې څۀ شوى وُو. بيا هغې او د هغۀ هوښيارو ملګرو هغۀ ته ووئيل، ”په مردکى باندې ستا هيڅ زور نۀ رسى. هغه يو يهودى دے او ځکه تۀ په هغۀ باندې برے نۀ شې موندلے. هغه به خامخا تا له شکست درکړى.“', NULL, '&nbsp;هغۀ خپلې ښځې او ټولو دوستانو ته هغه هر څۀ ووئيل چې څۀ شوى وُو. بيا هغې او د هغۀ هوښيارو ملګرو هغۀ ته ووئيل، ”په مردکى باندې ستا هيڅ زور نۀ رسى. هغه يو يهودى دے او ځکه تۀ په هغۀ باندې برے نۀ شې موندلے. هغه به خامخا تا له شکست درکړى.“', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_esther006_verse_013.mp3', NULL, 1761760676, 1761760676),
