(11838, 'Esther 8:3', 'Esther', 8, 3, '&nbsp;نو اِستَر بادشاه له بيا لاړه او د هغۀ په پښو پرېوته، وې ژړل او مِنت زارى يې ورته وکړه چې د هغه خرابې منصوبې خِلاف څۀ وکړى کومه چې د اجاج اولاد همان د يهوديانو خِلاف جوړه کړې ده.', NULL, '&nbsp;نو اِستَر بادشاه له بيا لاړه او د هغۀ په پښو پرېوته، وې ژړل او مِنت زارى يې ورته وکړه چې د هغه خرابې منصوبې خِلاف څۀ وکړى کومه چې د اجاج اولاد همان د يهوديانو خِلاف جوړه کړې ده.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_esther008_verse_003.mp3', NULL, 1761760676, 1761760676),
(11839, 'Esther 8:4', 'Esther', 8, 4, '&nbsp;بادشاه هغې ته خپله د سرو زرو امسا بيا وراُږده کړه، نو هغه ودرېده او وې فرمائيل،', NULL, '&nbsp;بادشاه هغې ته خپله د سرو زرو امسا بيا وراُږده کړه، نو هغه ودرېده او وې فرمائيل،', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_esther008_verse_004.mp3', NULL, 1761760676, 1761760676),
(11840, 'Esther 8:5', 'Esther', 8, 5, '&nbsp;”بادشاه سلامت، کۀ ستا رضا وى او کۀ تا سره زما فکر وى او دا تا ته ښۀ ښکارى، نو مِهربانى وکړه چې دا فرمان جارى کړه چې د همان په حُکم باندې دې عمل نۀ کيږى، دا هغه حُکم وو چې د اجاج قبيلې د همداتا زوئ همان د ټولو يهوديانو د وژلو دپاره ورکړے وو.', NULL, '&nbsp;”بادشاه سلامت، کۀ ستا رضا وى او کۀ تا سره زما فکر وى او دا تا ته ښۀ ښکارى، نو مِهربانى وکړه چې دا فرمان جارى کړه چې د همان په حُکم باندې دې عمل نۀ کيږى، دا هغه حُکم وو چې د اجاج قبيلې د همداتا زوئ همان د ټولو يهوديانو د وژلو دپاره ورکړے وو.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_esther008_verse_005.mp3', NULL, 1761760676, 1761760676),
(11841, 'Esther 8:6', 'Esther', 8, 6, '&nbsp;کۀ دا افت زما په خلقو باندې راشى او چې زما خپلوان ووژلے شى نو بيا زۀ دا څنګه برداشت کولے شم؟“', NULL, '&nbsp;کۀ دا افت زما په خلقو باندې راشى او چې زما خپلوان ووژلے شى نو بيا زۀ دا څنګه برداشت کولے شم؟“', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_esther008_verse_006.mp3', NULL, 1761760676, 1761760676),
(11842, 'Esther 8:7', 'Esther', 8, 7, '&nbsp;بيا اخسويرس بادشاه مَلِکه اِستَر او مردکى يهودى ته ووئيل، ”ګورئ، ما همان د يهوديانو خِلاف د منصوبې په وجه پهانسى کړے دے او ما اِستَر له د هغۀ جائيداد هم ورکړے دے.', NULL, '&nbsp;بيا اخسويرس بادشاه مَلِکه اِستَر او مردکى يهودى ته ووئيل، ”ګورئ، ما همان د يهوديانو خِلاف د منصوبې په وجه پهانسى کړے دے او ما اِستَر له د هغۀ جائيداد هم ورکړے دے.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_esther008_verse_007.mp3', NULL, 1761760676, 1761760676),
(11843, 'Esther 8:8', 'Esther', 8, 8, '&nbsp;خو د بادشاه په نوم چې کوم فرمان جارى شوے وى او په هغې باندې شاهى مهر لګولے شوے وى نو هغه نۀ واپس کيږى. خو يهوديانو ته هغه څۀ ليکلے شئ څۀ چې ستاسو زړۀ غواړى، او دا زما په نوم ليکلے شئ او شاهى مهر ورباندې ولګولے شئ.“', NULL, '&nbsp;خو د بادشاه په نوم چې کوم فرمان جارى شوے وى او په هغې باندې شاهى مهر لګولے شوے وى نو هغه نۀ واپس کيږى. خو يهوديانو ته هغه څۀ ليکلے شئ څۀ چې ستاسو زړۀ غواړى، او دا زما په نوم ليکلے شئ او شاهى مهر ورباندې ولګولے شئ.“', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_esther008_verse_008.mp3', NULL, 1761760676, 1761760676),
(11844, 'Esther 8:9', 'Esther', 8, 9, '&nbsp;نو د درېمې مياشتې يعنې د سيوان د مياشتې په درويشتمه ورځ داسې وشول. مردکى د بادشاه منشيان راوغوښتل او يهوديانو، حکمرانانو، وزيرانو او د هِندوستان نه واخله تر ايتهوپيا پورې د يو سل او اوويشتو صُوبو آفسرانو ته يې خطونه وليکل. خطونه هرې صُوبې ته په خپله ژبه او رسم‌الخط کښې او يهوديانو ته په خپله ژبه او رسم‌الخط کښې ليکلے شوى وُو.', NULL, '&nbsp;نو د درېمې مياشتې يعنې د سيوان د مياشتې په درويشتمه ورځ داسې وشول. مردکى د بادشاه منشيان راوغوښتل او يهوديانو، حکمرانانو، وزيرانو او د هِندوستان نه واخله تر ايتهوپيا پورې د يو سل او اوويشتو صُوبو آفسرانو ته يې خطونه وليکل. خطونه هرې صُوبې ته په خپله ژبه او رسم‌الخط کښې او يهوديانو ته په خپله ژبه او رسم‌الخط کښې ليکلے شوى وُو.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_esther008_verse_009.mp3', NULL, 1761760676, 1761760676),
(11845, 'Esther 8:10', 'Esther', 8, 10, '&nbsp;مردکى خطونه د اخسويرس بادشاه د طرف نه ليکلى وُو او په دې باندې يې شاهى مهر لګولے وو. دا په هغه تېزو آسونو باندې سوارو کسانو په ذريعه رسولے شوى وُو چې کوم آسونه د بادشاه دپاره ساتلے شوى وُو.', NULL, '&nbsp;مردکى خطونه د اخسويرس بادشاه د طرف نه ليکلى وُو او په دې باندې يې شاهى مهر لګولے وو. دا په هغه تېزو آسونو باندې سوارو کسانو په ذريعه رسولے شوى وُو چې کوم آسونه د بادشاه دپاره ساتلے شوى وُو.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_esther008_verse_010.mp3', NULL, 1761760676, 1761760676),
(11846, 'Esther 8:11', 'Esther', 8, 11, '&nbsp;په دې خطونو کښې دا تفصيل وو چې بادشاه به په هر ښار کښې يهوديانو له دا اجازت ورکړى چې د خپلو ځانونو د حِفاظت دپاره متحد شى. کۀ د يو قوم فوجيان په هره يوه صُوبه کښې په يهودى سړو باندې، د هغوئ بچو او ښځو باندې حمله وکړى، نو يهوديان به هم ورباندې حمله کوى او حمله کوونکى به تباه کړى، هغوئ دې تر آخرى کس پورې ووژنى او د هغوئ هر څۀ دې لوټ کړى.', NULL, '&nbsp;په دې خطونو کښې دا تفصيل وو چې بادشاه به په هر ښار کښې يهوديانو له دا اجازت ورکړى چې د خپلو ځانونو د حِفاظت دپاره متحد شى. کۀ د يو قوم فوجيان په هره يوه صُوبه کښې په يهودى سړو باندې، د هغوئ بچو او ښځو باندې حمله وکړى، نو يهوديان به هم ورباندې حمله کوى او حمله کوونکى به تباه کړى، هغوئ دې تر آخرى کس پورې ووژنى او د هغوئ هر څۀ دې لوټ کړى.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_esther008_verse_011.mp3', NULL, 1761760676, 1761760676),
(11847, 'Esther 8:12', 'Esther', 8, 12, '&nbsp;دا فرمان د فارس په ټول سلطنت کښې په هغه ورځ عملى کولے شو چې کومه د يهوديانو د وژلو دپاره مقرره وه، دا د دولسمې يعنې د ادر مياشتې ديارلسمه ورځ وه.', NULL, '&nbsp;دا فرمان د فارس په ټول سلطنت کښې په هغه ورځ عملى کولے شو چې کومه د يهوديانو د وژلو دپاره مقرره وه، دا د دولسمې يعنې د ادر مياشتې ديارلسمه ورځ وه.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_esther008_verse_012.mp3', NULL, 1761760676, 1761760676),
(11848, 'Esther 8:13', 'Esther', 8, 13, '&nbsp;د دې قانونى اِعلان شوے وو او په هره صُوبه کښې هر څوک د دې نه خبر وُو، نو چې کله هغه ورځ راشى نو يهوديان به د دشمن نه د بدل اخستلو دپاره تيار وى.', NULL, '&nbsp;د دې قانونى اِعلان شوے وو او په هره صُوبه کښې هر څوک د دې نه خبر وُو، نو چې کله هغه ورځ راشى نو يهوديان به د دشمن نه د بدل اخستلو دپاره تيار وى.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_esther008_verse_013.mp3', NULL, 1761760676, 1761760676),
(11849, 'Esther 8:14', 'Esther', 8, 14, '&nbsp;د بادشاه په حُکم په شاهى آسونو سوارۀ پېغام وړُونکى تېز لاړل. هغه فرمان په مرکزى ښار سوسه کښې هم جارى شوے وو.', NULL, '&nbsp;د بادشاه په حُکم په شاهى آسونو سوارۀ پېغام وړُونکى تېز لاړل. هغه فرمان په مرکزى ښار سوسه کښې هم جارى شوے وو.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_esther008_verse_014.mp3', NULL, 1761760676, 1761760676),
(11850, 'Esther 8:15', 'Esther', 8, 15, '&nbsp;مردکے د محل نه لاړو چې شاهى لِباس يعنې آسمانى او سپين رنګ جامې، د کاسنى رنګ د مهينې لټې يوه چُوغه يې اغوستې وه او د سرو زرو يو زبردست تاج يې په سر وو. بيا د سوسه کوڅې د لاسونو د پړقارى او د خوشحالۍ د چغو نه ډکې شوې.', NULL, '&nbsp;مردکے د محل نه لاړو چې شاهى لِباس يعنې آسمانى او سپين رنګ جامې، د کاسنى رنګ د مهينې لټې يوه چُوغه يې اغوستې وه او د سرو زرو يو زبردست تاج يې په سر وو. بيا د سوسه کوڅې د لاسونو د پړقارى او د خوشحالۍ د چغو نه ډکې شوې.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_esther008_verse_015.mp3', NULL, 1761760676, 1761760676),
(11851, 'Esther 8:16', 'Esther', 8, 16, '&nbsp;يهوديانو خوشحالى، راحت، خندا او عزت محسوسولو.', NULL, '&nbsp;يهوديانو خوشحالى، راحت، خندا او عزت محسوسولو.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_esther008_verse_016.mp3', NULL, 1761760676, 1761760676),
(11852, 'Esther 8:17', 'Esther', 8, 17, '&nbsp;هر ښار او هرې صُوبې ته هم چې د بادشاه فرمان ورسېدو، نو يهوديان خوشحاله وُو. هغوئ مېلمستيا او جشن وکړو. او په هغوئ کښې نور ډېر خلق په دې وجه يهوديان شول، ځکه چې د يهوديانو نه يرېدل.', NULL, '&nbsp;هر ښار او هرې صُوبې ته هم چې د بادشاه فرمان ورسېدو، نو يهوديان خوشحاله وُو. هغوئ مېلمستيا او جشن وکړو. او په هغوئ کښې نور ډېر خلق په دې وجه يهوديان شول، ځکه چې د يهوديانو نه يرېدل.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_esther008_verse_017.mp3', NULL, 1761760676, 1761760676),
(11853, 'Esther 9:1', 'Esther', 9, 1, '&nbsp;د ادر مياشتې ديارلسمه ورځ راغله، دا هغه ورځ وه چې په دې باندې شاهى فرمان عملى کول وُو، هغه ورځ چې د يهوديانو دشمنانو دا اُميد لرلو چې يهوديان به د خپل طاقت لاندې راولى. خو يهوديانو ورباندې فتح وموندله.', NULL, '&nbsp;د ادر مياشتې ديارلسمه ورځ راغله، دا هغه ورځ وه چې په دې باندې شاهى فرمان عملى کول وُو، هغه ورځ چې د يهوديانو دشمنانو دا اُميد لرلو چې يهوديان به د خپل طاقت لاندې راولى. خو يهوديانو ورباندې فتح وموندله.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_esther009_verse_001.mp3', NULL, 1761760676, 1761760676),
(11854, 'Esther 9:2', 'Esther', 9, 2, '&nbsp;د اخسويرس په ټوله بادشاهۍ کښې يهوديان په خپلو ښارونو کښې د هغه چا خِلاف يو شول چا چې په هغوئ د حملې کوشش کولو. د هر ځائ خلق د هغوئ نه يرېدل او هيچا د هغوئ مقابله نۀ شوه کولے.', NULL, '&nbsp;د اخسويرس په ټوله بادشاهۍ کښې يهوديان په خپلو ښارونو کښې د هغه چا خِلاف يو شول چا چې په هغوئ د حملې کوشش کولو. د هر ځائ خلق د هغوئ نه يرېدل او هيچا د هغوئ مقابله نۀ شوه کولے.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_esther009_verse_002.mp3', NULL, 1761760676, 1761760676),
(11855, 'Esther 9:3', 'Esther', 9, 3, '&nbsp;د صُوبو ټولو آفسرانو، حکمرانانو، وزيرانو او شاهى نمائندګانو د يهوديانو مدد په دې وجه وکړو چې هغوئ د مردکى نه يرېدل.', NULL, '&nbsp;د صُوبو ټولو آفسرانو، حکمرانانو، وزيرانو او شاهى نمائندګانو د يهوديانو مدد په دې وجه وکړو چې هغوئ د مردکى نه يرېدل.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_esther009_verse_003.mp3', NULL, 1761760676, 1761760676),
(11856, 'Esther 9:4', 'Esther', 9, 4, '&nbsp;په ټوله بادشاهۍ کښې دا ښۀ مشهوره وه چې مردکى اوس په محل کښې يو تکړه سړے وو او نور هم تکړه کېدو.', NULL, '&nbsp;په ټوله بادشاهۍ کښې دا ښۀ مشهوره وه چې مردکى اوس په محل کښې يو تکړه سړے وو او نور هم تکړه کېدو.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_esther009_verse_004.mp3', NULL, 1761760676, 1761760676),
(11857, 'Esther 9:5', 'Esther', 9, 5, '&nbsp;نو په هغه ورځو کښې يهوديانو خپل دشمنان په تُورو ووژل او نيست او نابود يې کړل. او چا چې د يهوديانو نه نفرت کولو د هغوئ سره يې د خپلې مرضى په مطابق عمل وکړو.', NULL, '&nbsp;نو په هغه ورځو کښې يهوديانو خپل دشمنان په تُورو ووژل او نيست او نابود يې کړل. او چا چې د يهوديانو نه نفرت کولو د هغوئ سره يې د خپلې مرضى په مطابق عمل وکړو.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_esther009_verse_005.mp3', NULL, 1761760676, 1761760676),
(11858, 'Esther 9:6', 'Esther', 9, 6, '&nbsp;د سوسه په مرکزى ښار کښې يهوديانو پينځۀ سوه کسان ووژل.', NULL, '&nbsp;د سوسه په مرکزى ښار کښې يهوديانو پينځۀ سوه کسان ووژل.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_esther009_verse_006.mp3', NULL, 1761760676, 1761760676),
(11859, 'Esther 9:11', 'Esther', 9, 11, '&nbsp;هم په هغه ورځ بادشاه خبر کړے شو چې په سوسه کښې څومره کسان وژلے شوى دى.', NULL, '&nbsp;هم په هغه ورځ بادشاه خبر کړے شو چې په سوسه کښې څومره کسان وژلے شوى دى.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_esther009_verse_011.mp3', NULL, 1761760676, 1761760676),
(11860, 'Esther 9:12', 'Esther', 9, 12, '&nbsp;بيا بادشاه مَلِکه اِستَر ته ووئيل، ”صِرف د سوسه په قلعه کښې يهوديانو پينځۀ سوه کسان وژلى دى، چې په دې کښې د همان زامن هم شامل دى. چې دلته دومره زيات وژلے شوى دى نو په صُوبو کښې به څۀ شوى وى. اوس تۀ څۀ غواړې؟ تۀ ووايه کۀ نور څۀ هم غواړې نو در به کړے شى.“', NULL, '&nbsp;بيا بادشاه مَلِکه اِستَر ته ووئيل، ”صِرف د سوسه په قلعه کښې يهوديانو پينځۀ سوه کسان وژلى دى، چې په دې کښې د همان زامن هم شامل دى. چې دلته دومره زيات وژلے شوى دى نو په صُوبو کښې به څۀ شوى وى. اوس تۀ څۀ غواړې؟ تۀ ووايه کۀ نور څۀ هم غواړې نو در به کړے شى.“', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_esther009_verse_012.mp3', NULL, 1761760676, 1761760676),
(11861, 'Esther 9:13', 'Esther', 9, 13, '&nbsp;اِستَر ورته په جواب کښې وفرمائيل، ”بادشاه سلامت، کۀ ستا رضا وى، نو يهوديانو له سبا په سوسه کښې يو ځل بيا د نن په شان اجازت ورکړه. او دا حُکم ورکړه چې د همان د لسو زامنو لاشونه په دار باندې ځوړند کړے شى.“', NULL, '&nbsp;اِستَر ورته په جواب کښې وفرمائيل، ”بادشاه سلامت، کۀ ستا رضا وى، نو يهوديانو له سبا په سوسه کښې يو ځل بيا د نن په شان اجازت ورکړه. او دا حُکم ورکړه چې د همان د لسو زامنو لاشونه په دار باندې ځوړند کړے شى.“', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_esther009_verse_013.mp3', NULL, 1761760676, 1761760676),
(11862, 'Esther 9:14', 'Esther', 9, 14, '&nbsp;نو بادشاه حُکم وکړو چې داسې دې وشى او په سوسه کښې دا فرمان جارى شو. د همان د لسو زامنو لاشونه په دار راځوړند کړے شول.', NULL, '&nbsp;نو بادشاه حُکم وکړو چې داسې دې وشى او په سوسه کښې دا فرمان جارى شو. د همان د لسو زامنو لاشونه په دار راځوړند کړے شول.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_esther009_verse_014.mp3', NULL, 1761760676, 1761760676),
(11863, 'Esther 9:15', 'Esther', 9, 15, '&nbsp;د ادر مياشتې په څوارلسمه ورځ د سوسه يهوديان يو ځل بيا يو ځائ شول او په ښار کښې يې درې سوه نور کسان ووژل. خو هغوئ بيا هم څۀ لوټ مار ونۀ کړو.', NULL, '&nbsp;د ادر مياشتې په څوارلسمه ورځ د سوسه يهوديان يو ځل بيا يو ځائ شول او په ښار کښې يې درې سوه نور کسان ووژل. خو هغوئ بيا هم څۀ لوټ مار ونۀ کړو.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_esther009_verse_015.mp3', NULL, 1761760676, 1761760676),
(11864, 'Esther 9:16', 'Esther', 9, 16, '&nbsp;يهوديان په صُوبو کښې هم د خپلو ځانونو د حِفاظت دپاره راغونډ شول. هغوئ د خپلو دشمنانو نه داسې ځانونه خلاص کړل چې پينځۀ اويا زره يې هغه کسان ووژل چا چې د هغوئ نه نفرت کولو. خو هغوئ لوټ مار ونۀ کړو.', NULL, '&nbsp;يهوديان په صُوبو کښې هم د خپلو ځانونو د حِفاظت دپاره راغونډ شول. هغوئ د خپلو دشمنانو نه داسې ځانونه خلاص کړل چې پينځۀ اويا زره يې هغه کسان ووژل چا چې د هغوئ نه نفرت کولو. خو هغوئ لوټ مار ونۀ کړو.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_esther009_verse_016.mp3', NULL, 1761760676, 1761760676),
(11865, 'Esther 9:17', 'Esther', 9, 17, '&nbsp;دا د ادر د مياشتې په ديارلسمه ورځ باندې وشول. په ورپسې ورځ يعنې په څوارلسمه ورځ باندې نور قتلونه ونۀ شول او هغوئ په دې ورځ د خوشحالۍ نه يې مېلمستيا وکړه.', NULL, '&nbsp;دا د ادر د مياشتې په ديارلسمه ورځ باندې وشول. په ورپسې ورځ يعنې په څوارلسمه ورځ باندې نور قتلونه ونۀ شول او هغوئ په دې ورځ د خوشحالۍ نه يې مېلمستيا وکړه.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_esther009_verse_017.mp3', NULL, 1761760676, 1761760676),
(11866, 'Esther 9:18', 'Esther', 9, 18, '&nbsp;خو د سوسه يهوديانو پينځلسمه ورځ د چُهټۍ ورځ وګرځوله، ځکه چې هغوئ په ديارلسمه او څوارلسمه ورځ باندې خپل دشمنان وژلى وُو او په پينځلسمه ورځ يې وژل بس کړى وُو.', NULL, '&nbsp;خو د سوسه يهوديانو پينځلسمه ورځ د چُهټۍ ورځ وګرځوله، ځکه چې هغوئ په ديارلسمه او څوارلسمه ورځ باندې خپل دشمنان وژلى وُو او په پينځلسمه ورځ يې وژل بس کړى وُو.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_esther009_verse_018.mp3', NULL, 1761760676, 1761760676),
(11867, 'Esther 9:19', 'Esther', 9, 19, '&nbsp;نو په دې وجه هغه يهوديان کوم چې په کلو کښې اوسيږى هغوئ د ادر د مياشتې په څوارلسمه ورځ د خوشحالۍ چُهټى کوى، په دې وخت باندې هغوئ مېلمستيا کوى او يو بل له د خوراک دپاره تُحفې ورکوى.', NULL, '&nbsp;نو په دې وجه هغه يهوديان کوم چې په کلو کښې اوسيږى هغوئ د ادر د مياشتې په څوارلسمه ورځ د خوشحالۍ چُهټى کوى، په دې وخت باندې هغوئ مېلمستيا کوى او يو بل له د خوراک دپاره تُحفې ورکوى.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_esther009_verse_019.mp3', NULL, 1761760676, 1761760676),
(11868, 'Esther 9:20', 'Esther', 9, 20, '&nbsp;مردکى دا واقعې ليکلې وې او د فارس په ټول سلطنت کښې نزدې او لرې ټولو يهوديانو له يې خطونه لېږلى وُو،', NULL, '&nbsp;مردکى دا واقعې ليکلې وې او د فارس په ټول سلطنت کښې نزدې او لرې ټولو يهوديانو له يې خطونه لېږلى وُو،', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_esther009_verse_020.mp3', NULL, 1761760676, 1761760676),
(11869, 'Esther 9:21', 'Esther', 9, 21, '&nbsp;هغوئ ته يې وئيلى وُو چې هر کال د ادر مياشتې په څوارلسمه او پينځلسمه ورځ اختر کوئ.', NULL, '&nbsp;هغوئ ته يې وئيلى وُو چې هر کال د ادر مياشتې په څوارلسمه او پينځلسمه ورځ اختر کوئ.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_esther009_verse_021.mp3', NULL, 1761760676, 1761760676),
(11870, 'Esther 9:22', 'Esther', 9, 22, '&nbsp;دا هغه ورځې وې چې په هغې باندې يهوديانو د خپلو دشمنانو نه ځانونه خلاص کړل، دا هغه مياشت وه چې د غم او د خفګان وخت نه په خندا او خوشحالۍ باندې بدله شوې وه. هغوئ ته وئيلے شوى وُو چې په دې ورځو باندې خوشحالى او مېلمستيا وکړئ او يو بل او غريبانانو له د خوراک دپاره تُحفې ورکړئ.', NULL, '&nbsp;دا هغه ورځې وې چې په هغې باندې يهوديانو د خپلو دشمنانو نه ځانونه خلاص کړل، دا هغه مياشت وه چې د غم او د خفګان وخت نه په خندا او خوشحالۍ باندې بدله شوې وه. هغوئ ته وئيلے شوى وُو چې په دې ورځو باندې خوشحالى او مېلمستيا وکړئ او يو بل او غريبانانو له د خوراک دپاره تُحفې ورکړئ.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_esther009_verse_022.mp3', NULL, 1761760676, 1761760676),
(11871, 'Esther 9:23', 'Esther', 9, 23, '&nbsp;نو يهوديانو د مردکى په اصُولو باندې عمل وکړو او دا اختر د هر کال رِواج جوړ شو.', NULL, '&nbsp;نو يهوديانو د مردکى په اصُولو باندې عمل وکړو او دا اختر د هر کال رِواج جوړ شو.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_esther009_verse_023.mp3', NULL, 1761760676, 1761760676),
(11872, 'Esther 9:24', 'Esther', 9, 24, '&nbsp;د همداتا زوئ همان چې د اجاج د اولاد نه وو او د يهوديانو دشمن وو، هغۀ پچه واچوله چې دا پوريم بللے شوه، دا د دې دپاره وه چې د يهوديانو د تباهۍ ورځ معلومه کړى، هغۀ دا منصوبه جوړه کړې وه چې هغوئ صفا ختم کړى.', NULL, '&nbsp;د همداتا زوئ همان چې د اجاج د اولاد نه وو او د يهوديانو دشمن وو، هغۀ پچه واچوله چې دا پوريم بللے شوه، دا د دې دپاره وه چې د يهوديانو د تباهۍ ورځ معلومه کړى، هغۀ دا منصوبه جوړه کړې وه چې هغوئ صفا ختم کړى.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_esther009_verse_024.mp3', NULL, 1761760676, 1761760676),
(11873, 'Esther 9:25', 'Esther', 9, 25, '&nbsp;خو اِستَر بادشاه له لاړه او بادشاه د دې نتيجې سره يو ليکلے فرمان جارى کړو چې همان د يهوديانو دپاره کومه منصوبه جوړه کړې وه نو هغه ورته اولټه راوګرځېده او هغه او د هغۀ زامن په دار باندې پهانسى کړے شول.', NULL, '&nbsp;خو اِستَر بادشاه له لاړه او بادشاه د دې نتيجې سره يو ليکلے فرمان جارى کړو چې همان د يهوديانو دپاره کومه منصوبه جوړه کړې وه نو هغه ورته اولټه راوګرځېده او هغه او د هغۀ زامن په دار باندې پهانسى کړے شول.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_esther009_verse_025.mp3', NULL, 1761760676, 1761760676),
(11874, 'Esther 9:26', 'Esther', 9, 26, '&nbsp;نو ځکه هغې ته د پوريم اختر وائى، پخوا زمانه کښې به دا لفظ د پچى اچولو دپاره استعمالېدو. د مردکى د خطونو په وجه او د هغه هر څۀ په وجه چې په هغوئ شوى وُو،', NULL, '&nbsp;نو ځکه هغې ته د پوريم اختر وائى، پخوا زمانه کښې به دا لفظ د پچى اچولو دپاره استعمالېدو. د مردکى د خطونو په وجه او د هغه هر څۀ په وجه چې په هغوئ شوى وُو،', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_esther009_verse_026.mp3', NULL, 1761760676, 1761760676),
(11875, 'Esther 9:27', 'Esther', 9, 27, '&nbsp;يهوديانو د خپلو ځانونو، د خپل اولاد او د هغه چا دپاره دا اصُول جوړ کړو چې څوک يهودى شى، نو هر کال به په صحيح وخت باندې دا دوه ورځې په باقاعدګۍ سره د مردکى د اصُولو په مطابق مناووى.', NULL, '&nbsp;يهوديانو د خپلو ځانونو، د خپل اولاد او د هغه چا دپاره دا اصُول جوړ کړو چې څوک يهودى شى، نو هر کال به په صحيح وخت باندې دا دوه ورځې په باقاعدګۍ سره د مردکى د اصُولو په مطابق مناووى.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_esther009_verse_027.mp3', NULL, 1761760676, 1761760676),
(11876, 'Esther 9:28', 'Esther', 9, 28, '&nbsp;دا فېصله شوې وه چې د يهوديانو د خاندان راتلونکے هر يو نسل چې په هره صُوبه يا ښار کښې وى په راتلونکى ټولو وختونو کښې به د پوريم دا ورځې يادې ساتى او دا ورځې به مناووى.', NULL, '&nbsp;دا فېصله شوې وه چې د يهوديانو د خاندان راتلونکے هر يو نسل چې په هره صُوبه يا ښار کښې وى په راتلونکى ټولو وختونو کښې به د پوريم دا ورځې يادې ساتى او دا ورځې به مناووى.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_esther009_verse_028.mp3', NULL, 1761760676, 1761760676),
