(11888, 'Job 1:5', 'Job', 1, 5, '&nbsp;او کله به چې د مېلمستيا ورځ تېره شوه، نو ايُوب به سحر وختى پاڅېدو او د هر يو بچى دپاره يې د ګناه نه د پاکوالى سوزېدونکې نذرانه پېش کوله، ايُوب به همېشه دا کار د دې دپاره کولو چې د هغۀ خيال وو چې کېدے شى چې زما بچو ګناه کړې وى او په خپلو زړُونو کښې يې خُدائ پاک ته بدرد وئيلى وى.', NULL, '&nbsp;او کله به چې د مېلمستيا ورځ تېره شوه، نو ايُوب به سحر وختى پاڅېدو او د هر يو بچى دپاره يې د ګناه نه د پاکوالى سوزېدونکې نذرانه پېش کوله، ايُوب به همېشه دا کار د دې دپاره کولو چې د هغۀ خيال وو چې کېدے شى چې زما بچو ګناه کړې وى او په خپلو زړُونو کښې يې خُدائ پاک ته بدرد وئيلى وى.', 'OT', 'yousafzai2019', 'yousafzai', '[]', 'yousafzai/ot/yousafzai_job001_verse_005.mp3', NULL, 1761760676, 1761760676),
